    <!-- الدستور الثاني (Constitution 2): هندسة المرشد الذكي، الصوت الرجالي، عدم تكرار الافتتاحية، والمحاكاة الحية للشاشات الوليدة -->
    <!-- ══════════════════════════════════════════════════════════════════════════════ -->
    <script id="mcp-constitution-2-smart-guide-engine">
    (function () {
        'use strict';

        // قفل تثبيت القوائم المنسدلة أثناء المحاكاة الحية للمرشد الذكي حتى لا تُغلق تلقائياً بحدث onblur
        window.__mcpC5PinDropdownList = null;

        // دالة مساعدة للحصول على معرّف أول كتلة حساب فرعي نشطة في الشاشة ديناميكياً
        window.getFirstActiveMcpBlockId = function () {
            const firstBlock = document.querySelector('#accounts-blocks-container .account-block');
            return (firstBlock && firstBlock.getAttribute('data-block-id')) || '1';
        };

        // فتح القائمة المنسدلة للحسابات حياً مع إظهار كافة الخيارات دون فلترة مسبقة وتثبيتها أمام عين المستخدم
        window.openGuideAccountDropdownLive = function (type) {
            if (!type) return;
            const listId = type + '-dropdown-list';
            window.__mcpC5PinDropdownList = listId;
            const searchEl = document.getElementById(type + '-search');
            const savedVal = searchEl ? searchEl.value : '';
            try {
                if (searchEl) searchEl.value = '';
                if (typeof window.showAccountDropdown === 'function') {
                    window.showAccountDropdown(type);
                }
            } catch (e) {} finally {
                if (searchEl) searchEl.value = savedVal;
            }
            const listEl = document.getElementById(listId);
            if (listEl) {
                listEl.classList.add('show');
                listEl.style.display = 'block';
            }
        };

        // فتح القائمة المنسدلة لمراكز التكلفة والمشاريع حياً مع إظهار كافة الخيارات وتثبيتها
        window.openGuideCostCenterDropdownLive = function (blockId) {
            const bid = blockId || window.getFirstActiveMcpBlockId();
            const listId = 'cost-center-' + bid + '-dropdown-list';
            window.__mcpC5PinDropdownList = listId;
            const inputEl = document.getElementById('cost-center-' + bid);
            const savedVal = inputEl ? inputEl.value : '';
            try {
                if (inputEl) inputEl.value = '';
                if (typeof window.showCostCenterDropdown === 'function') {
                    window.showCostCenterDropdown(bid);
                }
            } catch (e) {} finally {
                if (inputEl) inputEl.value = savedVal;
            }
            const listEl = document.getElementById(listId);
            if (listEl) {
                listEl.classList.add('show');
                listEl.style.display = 'block';
            }
        };

        // فتح نافذة كمبيالات وإشعارات الواتساب حياً أثناء الشرح حتى لو لم يكتب المستخدم مبالغ بعد
        window.openGuideWhatsAppModalLive = function () {
            const modal = document.getElementById('wa-voucher-modal');
            if (!modal) return;
            const bid = window.getFirstActiveMcpBlockId();
            const blockIdInput = document.getElementById('wa-modal-block-id');
            if (blockIdInput) blockIdInput.value = bid;
            modal.style.display = 'flex';
            try {
                if (typeof window.setWATargetMode === 'function') window.setWATargetMode('both');
                if (typeof window.setWAFormatType === 'function') window.setWAFormatType('promissory_note');
                if (typeof window.renderPromissoryNotePreview === 'function') window.renderPromissoryNotePreview('debtor');
            } catch (e) {}
        };

