        }

        /* توحيد ارتفاعات ومقاسات الخانات والـ Padding والـ Margin في الشاشة الرئيسية والشاشات الوليدة */
        .main-container input.form-input:not(#amount-local-hdr):not(#amount-foreign),
        .main-container input.form-control,
