            border-color: #fef08a !important;
            color: #fef08a !important;
            box-shadow: 0 0 22px rgba(239, 68, 68, 0.9), 0 8px 20px rgba(185, 28, 28, 0.75) !important;
            animation: mcpDeleteConfirmPulse 0.75s infinite alternate ease-in-out !important;
        }
        @keyframes mcpDeleteConfirmPulse {
            0% { transform: scale(1.01); box-shadow: 0 0 14px rgba(239, 68, 68, 0.75); }
            100% { transform: scale(1.04); box-shadow: 0 0 26px rgba(254, 240, 138, 0.85), 0 10px 24px rgba(239, 68, 68, 0.8); }
        }

        /* شارات اختصارات لوحة المفاتيح الأنيقة والمصغرة على الأزرار (Shortcut Badges) */
        kbd.shortcut-kbd {
            display: inline-flex !important;
            align-items: center !important;
            justify-content: center !important;
            padding: 1px 6px !important;
            font-size: 0.72rem !important;
            font-weight: 900 !important;
            font-family: var(--mcp-font-mono) !important;
            line-height: 1.25 !important;
            color: #fef08a !important;
            background: rgba(9, 13, 22, 0.65) !important;
            border: 1.5px solid rgba(255, 255, 255, 0.28) !important;
            border-radius: 6px !important;
            box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.45) !important;
            margin-inline-start: 4px !important;
            letter-spacing: 0.3px !important;
            pointer-events: none !important;
        }

        /* 3. الإيماءات الحركية والضوئية والاهتزازية للأزرار (Micro-Scale 1.03, Border Glow, Bottom Under-Glow & Tactile Pulse — Directive 3) */
        .btn,
        .crystal-btn,
        .btn-dock-btn,
        .voucher-type-btn,
        .btn-add-account-block,
        .btn-quick-add-acc,
        .btn-quick-add-cc,
        .btn-duplicate-block,
        .btn-statement-glow {
            --btn-edge-glow: rgba(56, 189, 248, 0.85);
            --btn-underglow: rgba(56, 189, 248, 0.55);
            position: relative !important;
            transition: transform 0.18s cubic-bezier(0.22, 1, 0.36, 1), border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease !important;
            will-change: transform, box-shadow;
        }

        /* إضاءة سفلية تحت الزر (Bottom Under-Glow) تمنحه عمقاً وفخامة بصرية عند المرور */
        .footer-actions.unified-footer-bar .btn::after,
        .btn-dock-btn::after,
        .btn-add-account-block::after {
            content: '' !important;
            position: absolute !important;
            bottom: -5px !important;
            left: 14% !important;
            right: 14% !important;
            height: 7px !important;
            border-radius: 50% !important;
            background: var(--btn-edge-glow, var(--tab-border-color, #38bdf8)) !important;
            filter: blur(6px) !important;
            opacity: 0 !important;
            transform: scaleX(0.7) !important;
            transition: opacity 0.2s ease, transform 0.2s ease !important;
            pointer-events: none !important;
            z-index: -1 !important;
        }

        /* تكبير انسيابي خفيف (scale(1.03)) دون إزاحة أو هز العناصر المجاورة + إنارة الحواف + الإضاءة السفلية */
        .footer-actions.unified-footer-bar .btn:hover:not(:disabled),
        .crystal-btn:hover:not(:disabled),
        .btn-dock-btn:hover:not(:disabled),
        .voucher-type-btn:hover:not(:disabled),
        .btn-add-account-block:hover:not(:disabled),
        .btn-quick-add-acc:hover:not(:disabled),
        .btn-quick-add-cc:hover:not(:disabled),
        .btn-duplicate-block:hover:not(:disabled),
        .btn-statement-glow:hover:not(:disabled) {
            transform: scale(1.03) !important;
            box-shadow:
                0 10px 20px -4px var(--btn-underglow, var(--tab-glow-color, rgba(56, 189, 248, 0.55))),
                0 0 14px var(--btn-edge-glow, var(--tab-border-color, rgba(56, 189, 248, 0.8))),
                inset 0 1px 2px rgba(255, 255, 255, 0.35) !important;
            z-index: 12 !important;
        }

        .footer-actions.unified-footer-bar .btn:hover::after,
        .btn-dock-btn:hover::after,
        .btn-add-account-block:hover::after {
            opacity: 0.85 !important;
            transform: scaleX(1.05) !important;
        }

        /* نبضة الضغط التفاعلية (Tactile Active Press & Pulse) */
        .footer-actions.unified-footer-bar .btn:active:not(:disabled),
        .crystal-btn:active:not(:disabled),
        .btn-dock-btn:active:not(:disabled),
        .voucher-type-btn:active:not(:disabled),
        .btn-add-account-block:active:not(:disabled),
        .btn-quick-add-acc:active:not(:disabled),
        .btn-quick-add-cc:active:not(:disabled),
        .btn-duplicate-block:active:not(:disabled) {
            transform: scale(0.97) !important;
            transition: transform 0.06s ease !important;
        }

        @keyframes mcpBtnTactilePulse {
            0% { box-shadow: 0 0 0 0 rgba(52, 211, 153, 0.75); }
            70% { box-shadow: 0 0 0 12px rgba(52, 211, 153, 0); }
            100% { box-shadow: 0 0 0 0 rgba(52, 211, 153, 0); }
        }
        .mcp-tactile-pulse {
            animation: mcpBtnTactilePulse 0.42s cubic-bezier(0.16, 1, 0.3, 1) !important;
        }

        /* 4. اللمعات الضوئية المتحركة الزجاجية على أسطح البرنامج بخفة الريشة (0ms Pure GPU Glassmorphism Sheen — Directive 4) */
        @keyframes mcpGpuGlassSheen {
            0% {
                transform: translate3d(-140%, 0, 0) skewX(-25deg);
                opacity: 0;
            }
            12% {
                opacity: 0.65;
            }
            28% {
                transform: translate3d(240%, 0, 0) skewX(-25deg);
                opacity: 0;
            }
            100% {
                transform: translate3d(240%, 0, 0) skewX(-25deg);
                opacity: 0;
            }
        }

        #primary-inputs-container,
        .account-block,
        #mcp-world-summary-bar,
        #payment-methods-row {
            position: relative !important;
            overflow: visible !important;
        }

        /* طبقة اللمعة الزجاجية المسرّعة عبر GPU فقط (transform + opacity) بلا أي استهلاك للذاكرة */
        #primary-inputs-container::before,
        .account-block::before,
        #mcp-world-summary-bar::before {
            content: '' !important;
            position: absolute !important;
            top: 0 !important;
            left: 0 !important;
            width: 42% !important;
            height: 100% !important;
            background: linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.09) 50%, rgba(255,255,255,0) 100%) !important;
            transform: translate3d(-140%, 0, 0) skewX(-25deg) !important;
            pointer-events: none !important;
            will-change: transform, opacity !important;
            animation: mcpGpuGlassSheen 9s ease-in-out infinite !important;
            z-index: 1 !important;
            border-radius: inherit !important;
        }

        /* 5. الدستور الموحد للرسائل التحذيرية والإشعارات الطائرة (Standardized Floating Toasts — Directive 5) */
        #toast-container.toast-container {
            position: fixed !important;
            top: 18px !important;
            left: 50% !important;
            transform: translateX(-50%) !important;
            z-index: 9999999 !important;
            display: flex !important;
            flex-direction: column !important;
            align-items: center !important;
            gap: 10px !important;
            pointer-events: none !important;
            max-width: 92vw !important;
        }

        #toast-container .toast {
            position: relative !important;
            overflow: hidden !important;
            min-width: 290px !important;
            max-width: 560px !important;
            padding: 12px 20px 15px 20px !important;
            border-radius: 14px !important;
            font-family: var(--mcp-font-sans) !important;
            font-weight: 900 !important;
            font-size: 0.98rem !important;
            display: flex !important;
            align-items: center !important;
            gap: 10px !important;
            pointer-events: auto !important;
            cursor: pointer !important;
            backdrop-filter: blur(18px) !important;
            -webkit-backdrop-filter: blur(18px) !important;
            direction: rtl !important;
            letter-spacing: 0.2px !important;
            animation: toastIn 0.28s cubic-bezier(0.16, 1, 0.3, 1) both !important;
        }

        /* رسائل النجاح (حفظ/مزامنة): أخضر زمردي مضيء */
        #toast-container .toast.success {
            background: linear-gradient(135deg, rgba(6, 78, 59, 0.96), rgba(4, 120, 87, 0.96)) !important;
            border: 2.2px solid #10b981 !important;
            color: #ecfdf5 !important;
            box-shadow: 0 12px 32px rgba(0, 0, 0, 0.65), 0 0 22px rgba(16, 185, 129, 0.55) !important;
        }

        /* رسائل التنبيه الاستباقي: كهرماني/ذهبي واضح */
        #toast-container .toast.warning,
        #toast-container .toast.info {
            background: linear-gradient(135deg, rgba(120, 53, 15, 0.96), rgba(180, 83, 9, 0.96)) !important;
            border: 2.2px solid #fbbf24 !important;
            color: #fef3c7 !important;
            box-shadow: 0 12px 32px rgba(0, 0, 0, 0.65), 0 0 22px rgba(245, 158, 11, 0.55) !important;
        }

        /* الرسائل التحذيرية والأمنية وأخطاء الإدخال: أحمر صريح مميز */
        #toast-container .toast.error {
            background: linear-gradient(135deg, rgba(127, 29, 29, 0.97), rgba(185, 28, 28, 0.97)) !important;
            border: 2.2px solid #f87171 !important;
            color: #fef2f2 !important;
            box-shadow: 0 12px 32px rgba(0, 0, 0, 0.7), 0 0 26px rgba(239, 68, 68, 0.7) !important;
        }

        /* شريط التقدم الزمني الذكي أسفل الرسالة الطائرة */
        .toast-progress-bar {
            position: absolute !important;
            bottom: 0 !important;
            right: 0 !important;
            height: 3.5px !important;
            width: 100% !important;
            background: rgba(255, 255, 255, 0.75) !important;
            transform-origin: right center !important;
            animation: mcpToastProgress linear forwards !important;
        }
        @keyframes mcpToastProgress {
            from { transform: scaleX(1); }
            to { transform: scaleX(0); }
        }
    </style>

    <!-- ══════════════════════════════════════════════════════════════════════════════ -->
    <!-- الدستور الرابع (Constitution 4 of 14): دستور "المرشد الذكي" (1) — الصوت الرجالي الفخيم، الكبسولة المصغرة غير الحاجبة (Micro-HUD)، الافتتاحية الصافية مرة واحدة، الملخص العام (الوظيفة + المدخلات + المخرجات)، القاعدة الذهبية، وخريطة الترابط الثلاثية (3-Stage Pure SVG 0ms) -->
    <!-- ══════════════════════════════════════════════════════════════════════════════ -->
    <style id="mcp-constitution-4-smart-guide-styles">
        /* 1. كبسولة التحكم المصغرة فائقة الأناقة غير الحاجبة للرؤية (Micro-HUD Capsule — Directive 2) */
        #mcpC4SmartGuideMicroHud {
            display: none;
            position: fixed;
            bottom: 66px;
            left: 50%;
            transform: translateX(-50%);
            z-index: 2147483645;
            width: min(880px, 95vw);
            border-radius: 16px;
            padding: 8px 12px;
            border: 2.4px solid #38bdf8 !important;
            background: rgba(15, 23, 42, 0.96) !important;
            color: #ffffff !important;
            box-shadow: 0 16px 40px rgba(0, 0, 0, 0.65), 0 0 20px rgba(56, 189, 248, 0.3) !important;
            backdrop-filter: blur(16px);
            -webkit-backdrop-filter: blur(16px);
            direction: rtl;
            font-family: var(--mcp-font-sans, 'Tajawal', 'Cairo', sans-serif) !important;
            transition: top 0.2s ease, bottom 0.2s ease, box-shadow 0.2s ease;
        }
        #mcpC4SmartGuideMicroHud.active {
            display: flex !important;
            flex-direction: column !important;
            gap: 6px !important;
        }
        #mcpC4SmartGuideMicroHud.docked-top {
            bottom: auto !important;
            top: 64px !important;
        }
        #mcpC4SmartGuideMicroHud.minimized-pill {
            width: auto !important;
            max-width: 92vw !important;
            padding: 6px 12px !important;
        }
        #mcpC4SmartGuideMicroHud.minimized-pill #mcpC4SvgImpactMapWrap,
        #mcpC4SmartGuideMicroHud.minimized-pill #mcpC4GoldenRuleStrip,
        #mcpC4SmartGuideMicroHud.minimized-pill #mcpC4HudSpeechText {
            display: none !important;
        }

        /* سريان السمة الفاتحة على كبسولة المرشد المصغرة مع تباين صارم (#000000 على خلفية فاتحة) وسُمك (+2) */
        html.light-theme #mcpC4SmartGuideMicroHud {
            background: rgba(255, 255, 255, 0.98) !important;
            color: #000000 !important;
            border: 2.4px solid #0284c7 !important;
            box-shadow: 0 14px 36px rgba(15, 23, 42, 0.22), 0 0 16px rgba(2, 132, 199, 0.2) !important;
        }

        #mcpC4SmartGuideMicroHud .mcp-c4-hud-top {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 6px;
            flex-wrap: wrap;
        }
        #mcpC4SmartGuideMicroHud .mcp-c4-hud-controls {
            display: flex;
            align-items: center;
            gap: 5px;
            flex-wrap: wrap;
        }
        #mcpC4SmartGuideMicroHud .mcp-c4-hud-btn {
            height: 31px !important;
            min-height: 31px !important;
            padding: 0 9px !important;
            border-radius: 8px !important;
            border: 2px solid #38bdf8 !important;
            background: #1e293b !important;
            color: #ffffff !important;
            font-size: 0.78rem !important;
            font-weight: 900 !important;
            cursor: pointer !important;
            display: inline-flex !important;
            align-items: center !important;
            gap: 4px !important;
            transition: transform 0.14s ease, box-shadow 0.14s ease, border-color 0.14s ease !important;
        }
        html.light-theme #mcpC4SmartGuideMicroHud .mcp-c4-hud-btn {
            background: #f8fafc !important;
            color: #000000 !important;
            border: 2px solid #0284c7 !important;
        }
        #mcpC4SmartGuideMicroHud .mcp-c4-hud-btn:hover {
            transform: scale(1.03) !important;
            box-shadow: 0 0 12px rgba(56, 189, 248, 0.45) !important;
        }
        #mcpC4SmartGuideMicroHud .mcp-c4-hud-btn.active-mode {
            border-color: #10b981 !important;
            background: rgba(16, 185, 129, 0.22) !important;
            box-shadow: 0 0 10px rgba(16, 185, 129, 0.5) !important;
        }

        /* شريط النص المنطوق المتزامن (Live Subtitle Strip) */
        #mcpC4SmartGuideMicroHud .mcp-c4-hud-speech {
            font-size: 0.89rem !important;
            font-weight: 800 !important;
            line-height: 1.52 !important;
            padding: 6px 10px !important;
            border-radius: 10px !important;
            border: 2px solid #334155 !important;
            background: rgba(2, 6, 23, 0.78) !important;
            color: #ffffff !important;
            max-height: 76px !important;
            overflow-y: auto !important;
        }
        html.light-theme #mcpC4SmartGuideMicroHud .mcp-c4-hud-speech {
            background: #f8fafc !important;
            color: #000000 !important;
            border: 2px solid #94a3b8 !important;
        }

        /* شريط القاعدة الذهبية ورسالة الطمأنينة النفسية المدمج (Directive 5 & World-Class Addition 3) */
        #mcpC4GoldenRuleStrip {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 8px;
            flex-wrap: wrap;
            padding: 5px 10px;
            border-radius: 10px;
            border: 2px solid #f59e0b !important;
            background: rgba(245, 158, 11, 0.14) !important;
            color: #ffffff !important;
            font-size: 0.8rem !important;
            font-weight: 900 !important;
            cursor: pointer;
        }
        html.light-theme #mcpC4GoldenRuleStrip {
            background: #fffbeb !important;
            color: #000000 !important;
            border: 2px solid #d97706 !important;
        }

        /* خريطة الترابط البصرية الثلاثية خفيفة الريشة (0ms Pure SVG 3-Stage Impact Map — Directive 6) */
        #mcpC4SvgImpactMapWrap {
            display: none;
            padding: 6px 8px;
            border-radius: 12px;
            border: 2px dashed #38bdf8;
            background: rgba(2, 6, 23, 0.65);
        }
        html.light-theme #mcpC4SvgImpactMapWrap {
            background: #f1f5f9;
            border-color: #0284c7;
        }
        #mcpC4SvgImpactMapWrap.show {
            display: block !important;
        }
        .mcp-c4-svg-stage {
            transition: opacity 0.22s ease, filter 0.22s ease, transform 0.22s ease;
            opacity: 0.45;
            cursor: pointer;
        }
        .mcp-c4-svg-stage.active-stage {
            opacity: 1 !important;
            filter: drop-shadow(0 0 10px rgba(56, 189, 248, 0.88));
        }
        @keyframes mcpC4SvgArrowFlow {
            from { stroke-dashoffset: 20; }
            to { stroke-dashoffset: 0; }
        }
        #mcpC4SvgArrow1 path,
        #mcpC4SvgArrow2 path {
            stroke-dasharray: 6 4;
            animation: mcpC4SvgArrowFlow 0.85s linear infinite;
        }

        /* إطار التركيز البصري المتزامن مع شرح الحقول والأزرار (Live Element Spotlight) */
        .mcp-c4-guide-spotlight {
            outline: 3.5px solid #f59e0b !important;
            outline-offset: 3px !important;
            box-shadow: 0 0 22px rgba(245, 158, 11, 0.78) !important;
            position: relative !important;
            z-index: 60 !important;
        }

        @media print {
            #mcpC4SmartGuideMicroHud {
                display: none !important;
            }
        }
    </style>

    <!-- كبسولة المرشد الذكي المصغرة غير الحاجبة (Micro-HUD Capsule) + خريطة الترابط الثلاثية (Pure SVG 0ms) -->
    <div id="mcpC4SmartGuideMicroHud" role="region" aria-label="كبسولة المرشد الذكي المصغرة لشاشة الحركة المالية المجمعة">
        <div class="mcp-c4-hud-top">
            <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
                <span id="mcpC4VoiceWaveBadge" style="font-weight:900;font-size:0.84rem;color:#38bdf8;">🎙️ المرشد الذكي (صوت رجالي فخيم)</span>
                <span id="mcpC4StepCounterBadge" style="padding:1px 8px;border-radius:999px;border:1.8px solid currentColor;font-size:0.74rem;font-weight:900;">1 / 19</span>
