    <script id="mcp-constitution-4-smart-guide-engine">
    (function () {
        'use strict';
        if (window.McpDesktopConstitution4) return;

        // البسملة والصلاة على النبي ﷺ تُنطق مرة واحدة فقط في البداية بدون أي تكرار وبدون عبارة "شرح من الألف إلى الياء"
        const OPENING_SALAWAT_ONCE = 'اللهم صل وسلم على نبينا محمد.';

        const McpDesktopConstitution4 = {
            // قفل برمجي صارم يمنع تكرار الصلاة على النبي ﷺ بين الخانات أو الخطوات نهائياً ولو استمر الشرح 10 ساعات (Directive 1)
            hasPlayedOpeningInvocation: false,
            isActive: false,
            isPaused: false,
            pickElementMode: false,
            currentStepIndex: 0,
            speechRate: 1.0,
            selectedMaleVoice: null,
            activeUtterance: null,
            activeAudioEl: null,
            stepAdvanceTimer: null,
            stageSyncTimers: [],
            keepAliveInterval: null,

            // خطوات الشرح المعزولة حصرياً لشاشة الحركة المالية المجمعة (خالية تماماً من عبارة "شرح من الألف إلى الياء")
            steps: [
                {
                    id: 'overview-purpose',
                    title: '1️⃣ الشرح العام الشامل للصفحة (الوظيفة • المدخلات • المخرجات • القاعدة الذهبية)',
                    svgStage: 'input',
                    autoCycleSvgStages: true,
                    showMap: true,
                    selector: '#payment-methods-row, #primary-inputs-container',
                    goldenRule: 'القاعدة الذهبية للشاشة: اختر الحساب الرئيسي بالأعلى أولاً ثم وزّع الأطراف الفرعية بالأسفل يتوازن قيدك المزدوج تلقائياً 100%.',
                    action: () => { if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups(); },
                    text: 'أهلاً بحضرتك في شاشة الحركة المالية المجمعة، لصرف واستلام النقدية والبنوك المتعددة. أولاً: وظيفة هذه الشاشة وأهميتها أنها تختصر عشرات السندات الفردية في سند مالي مجمع واحد متوازن ذرياً؛ فإما صرف من حساب رئيسي واحد بالأعلى كالخزينة أو البنك لعدة مستفيدين ومصروفات بالأسفل، وإما استلام من عدة عملاء بالأسفل وإيداعها دفعة واحدة في الحساب الرئيسي بالأعلى. ثانياً: من أي شاشة تأتي المعلومات إلى هذه الصفحة؟ تتغذى تلقائياً من شاشة البيانات الأساسية وشجرة الحسابات للعملاء والموردين والموظفين، وشاشة الخزائن والبنوك وأرصدتها الحية، وشاشة العملات وأسعار الصرف ومراكز التكلفة، ودرج إشعارات بنكك واللصق الذكي من إكسل. ثالثاً: أين تُسمّع وفي أي تقرير وشاشة تؤثر؟ فور حفظها باختصار إف عشرة تُسمّع لحظياً في خمس جهات: أرصدة الخزائن والبنوك بالنقص عند الصرف والزيادة عند الاستلام، وكشوف حسابات الأطراف ودفتر الأستاذ العام، ودفتر اليومية العامة وميزان المراجعة، وحافظة الشيكات، وتقارير أرباح وتكاليف مراكز التكلفة والمشاريع. رابعاً: القاعدة الذهبية العامة لهذه الشاشة: حدّد اتجاه الحركة واختر الحساب الرئيسي بالأعلى أولاً ثم وزّع الأطراف الفرعية ومبالغها بالأسفل، يتوازن قيدك المزدوج تلقائياً بنسبة مئة بالمئة. واطمئن تماماً يا أخي المحاسب ولا تخشَ الخطأ أبداً؛ فالشاشة محمية بنظام الأمان الذكي وحفظ المسودة ومنع التكرار والتراجع الفوري.'
                },
                {
                    id: 'overview-inputs',
                    title: '2️⃣ من أي شاشة تأتي المعلومات إلى هذه الصفحة؟ (مصادر المدخلات)',
                    svgStage: 'input',
                    showMap: true,
                    selector: '#primary-inputs-container',
                    goldenRule: 'القاعدة الذهبية للمدخلات: كل حساب أو مركز تكلفة تؤسسه في البيانات الأساسية أو عبر زر (➕) يظهر هنا فوراً.',
                    action: () => { if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups(); },
                    text: 'من أي شاشة تأتي المعلومات إلى هذه الصفحة؟ تتغذى هذه الشاشة بالبيانات تلقائياً من خمس شاشات ومصادر رئيسية: أولاً شاشة البيانات الأساسية وشجرة الحسابات التي تغذيها بأسماء العملاء والموردين والموظفين وحسابات المصروفات والإيرادات، وثانياً شاشة الخزائن والبنوك والتطبيقات البنكية التي تغذي الحساب الرئيسي وأرصدته الحية، وثالثاً شاشة العملات وأسعار الصرف وشاشة مراكز التكلفة والمشاريع، ورابعاً درج إشعارات بنكك الواردة من الواتساب والماسح الضوئي الذكي للإشعارات، وخامساً أداة الاستيراد واللصق الذكي من جداول إكسل.'
                },
                {
                    id: 'overview-outputs',
                    title: '3️⃣ أين تُسمّع هذه الصفحة وفي أي تقرير وشاشة تؤثر؟ (المخرجات والأثر المحاسبي)',
                    svgStage: 'output',
                    showMap: true,
                    selector: '#mcp-world-summary-bar',
                    goldenRule: 'القاعدة الذهبية للتسميع: حفظ السند (F10) يرحّل القيد المزدوج لحظياً في 5 تقارير وشاشات بلا أي تدخل يدوي.',
                    action: () => { if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups(); },
                    text: 'أين تُسمّع هذه الصفحة وفي أي تقرير وشاشة ثانية تؤثر؟ بمجرد اعتماد وحفظ السند باختصار إف عشرة، يُسمّع القيد المحاسبي المزدوج لحظياً في خمس جهات وتقارير: أولاً في شاشة وتقارير الخزائن والبنوك حيث ينقص رصيد الخزينة أو البنك فوراً عند الصرف ويزيد فوراً عند الاستلام، وثانياً في كشوف حسابات العملاء والموردين والموظفين ودفتر الأستاذ العام حيث ينزل لكل طرف مبلغه المستقل وبيانه الخاص، وثالثاً في دفتر اليومية العامة وميزان المراجعة وقائمة الأرباح والخسائر، ورابعاً في حافظة الشيكات الصادرة والواردة وتقارير التحويلات البنكية، وخامساً في تقارير أرباح وتكاليف مراكز التكلفة والمشاريع والشاحنات.'
                },
                {
                    id: 'overview-golden-rule',
                    title: '4️⃣ القاعدة الذهبية العامة للشاشة + رسالة الطمأنينة النفسية للمحاسب',
                    svgStage: 'all',
                    showMap: true,
                    selector: '#main-form-panel',
                    goldenRule: 'القاعدة الذهبية للشاشة: حدّد اتجاه الحركة واختر الحساب الرئيسي بالأعلى أولاً ثم وزّع الأطراف الفرعية بالأسفل يتوازن قيدك تلقائياً 100%.',
                    action: () => { if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups(); },
                    text: 'القاعدة الذهبية العامة لهذه الشاشة: حدّد اتجاه الحركة أولاً بين صرف إلى مجموعة أو استلام من مجموعة، واختر الحساب الرئيسي في الأعلى، ثم وزّع الأطراف الفرعية ومبالغها وطرق دفعها في الأسفل؛ يتوازن قيدك المحاسبي المزدوج وأرصدة الخزينة وكشوف الحسابات تلقائياً بنسبة مئة بالمئة. واطمئن تماماً يا أخي المحاسب واعمل بكل ثقة وراحة نفسية ولا تخشَ الخطأ أبداً؛ فهذه الشاشة محمية بنظام الأمان الذكي، والحفظ التلقائي للمسودة ضد انقطاع الكهرباء أو الإنترنت، ودرع منع تكرار الإشعارات البنكية، وقفل الحفظ الذري لمنع الازدواجية، وقفل التأكيد المدمج للحذف، مع إمكانية التعديل أو التراجع الفوري في أي لحظة.'
                },
                {
                    id: 'step-header-bar',
                    title: '5️⃣ شريط القيادة العلوي: اتجاه الحركة (صرف 🔴 / استلام 🟢) ورقم السند والتاريخ',
                    svgStage: 'process',
                    showMap: false,
                    selector: '#payment-methods-row',
                    goldenRule: 'القاعدة الذهبية: زر (صرف إلى مجموعة 🔴) يجعل الحساب الرئيسي دائناً، وزر (استلام من مجموعة 🟢) يجعله مديناً.',
                    action: () => { if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups(); },
                    text: 'ننتقل الآن بسلاسة لشرح كل خانة وزر وقائمة وشاشة وليدة مع قاعدتها الذهبية: ففي هذا الشريط العلوي تحدد أولاً اتجاه الحركة بضغطة زر؛ إما صرف إلى مجموعة باللون الأحمر عندما تدفع من خزنتك أو بنكك لعدة جهات، أو استلام من مجموعة باللون الأخضر عندما تقبض من عدة عملاء وتودع في حسابك، وبجانبهما رقم السند التسلسلي وأسهم التنقل وتاريخ السند ورقم المرجع. القاعدة الذهبية لهذا الشريط: زر صرف إلى مجموعة يجعل الحساب الرئيسي دائناً ينقص رصيده، وزر استلام من مجموعة يجعله مديناً يزيد رصيده.'
                },
                {
                    id: 'step-inbound-bankak-drawer',
                    title: '6️⃣ المحاكاة الحية للشاشة الوليدة (1): درج إشعارات بنكك الواردة من الواتساب (📥)',
                    svgStage: 'input',
                    showMap: false,
                    selector: '#inbound-receipts-drawer, #btn-inbound-receipts-drawer',
                    goldenRule: 'القاعدة الذهبية: استورد الإشعار من درج الواتساب مباشرة بدلاً من النقل اليدوي لضمان دقة رقم العملية والمبلغ 100%.',
                    action: () => {
                        if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups();
                        const drawer = document.getElementById('inbound-receipts-drawer');
                        if (typeof window.toggleInboundReceiptsDrawer === 'function') {
                            try { window.toggleInboundReceiptsDrawer(true); } catch (e) { if (drawer) drawer.classList.add('open'); }
                        } else if (drawer) {
                            drawer.classList.add('open');
                        }
                    },
                    text: 'وعند الضغط على زر إشعارات بنكك، يفتح أمامك الآن حياً درج التحويلات البنكية الواردة من الواتساب؛ لتستعرض صور الإشعارات المستلمة وتضغط على أي إشعار لينزل مَبلغه ورقمه المرجعي في السند مباشرة. القاعدة الذهبية لهذا الدرج: استورد الإشعار من درج الواتساب مباشرة بدلاً من النقل اليدوي لضمان دقة رقم العملية والمبلغ وعدم تكرار الصرف.'
                },
                {
                    id: 'step-main-account',
                    title: '7️⃣ الحساب الرئيسي بالأعلى + المحاكاة الحية لفتح قائمة الخزائن والبنوك وكشف الرصيد',
                    svgStage: 'input',
                    showMap: false,
                    selector: '#main-account-search',
                    goldenRule: 'القاعدة الذهبية: راقب شريط الرصيد الحي أسفل الحساب الرئيسي لتعرف رصيد الخزينة أو البنك قبل السند وبعده فوراً.',
                    action: () => {
                        if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups();
                        if (typeof window.openGuideAccountDropdownLive === 'function') {
                            window.openGuideAccountDropdownLive('main-account');
                        }
                    },
                    text: 'هنا في الأعلى تختار الحساب الرئيسي كالخزينة أو البنك؛ ولاحظ كيف فتحت وانسدلت أمامك الآن القائمة المنسدلة للخزائن والبنوك حياً على الشاشة مع دعم البحث العربي الذكي المتسامح مع الهمزات والتاء المربوطة، ويظهر تحتها شريط الرصيد الحي وزر كشف الحساب. القاعدة الذهبية للحساب الرئيسي: اختر الخزينة أو البنك الفعلي وراقب شريط الرصيد الحي تحته للتأكد من كفاية الرصيد قبل الصرف.'
                },
                {
                    id: 'step-quick-add-account',
                    title: '8️⃣ المحاكاة الحية للشاشة الوليدة (2): الإضافة الفورية لحساب جديد (➕ Alt+N)',
                    svgStage: 'input',
                    showMap: false,
                    selector: '#mcp-quick-add-account-modal > div, .btn-quick-add-acc',
                    goldenRule: 'القاعدة الذهبية: لا تغادر السند لتأسيس حساب جديد؛ اضغط (➕) أو Alt+N وحدّد تصنيفه بدقة لينزل فوراً في الخانة.',
                    action: () => {
                        if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups();
                        if (typeof window.openQuickAddAccountModal === 'function') {
