            init() {
                this.removeSubGuideButtonsInsideScreen();
                this.initMaleVoiceEngine();
                this.bindHudControls();
                this.hijackTopGuideButtonForInstantStart();
                this.initPickElementExplainMode();
            },

            // 1. حذف أي أزرار فرعية للمرشد داخل الشاشة والاعتماد الحصري على زر "المرشد" العلوي فقط (Directive 1)
            removeSubGuideButtonsInsideScreen() {
                document.querySelectorAll('[id*="sub-guide"], .sub-guide-btn').forEach(el => {
                    if (!el.closest('#msg-universal-fixed-launcher') && !el.closest('#mcpC4SmartGuideMicroHud')) {
                        try { el.remove(); } catch (e) {}
                    }
                });
            },

            // 2. تهيئة وتثبيت الصوت الرجالي الفخيم الحصري (استبعاد الأصوات النسائية تماماً — Directive 3)
            initMaleVoiceEngine() {
                const self = this;
                if (!('speechSynthesis' in window)) return;

                const selectBestMaleArabicVoice = function () {
                    const voices = window.speechSynthesis.getVoices() || [];
                    if (!voices.length) return;

                    const femalePattern = /(salma|zariyah|laila|hoda|fatima|amira|mariam|noura|amany|female|woman|girl|سلمى|زارية|ليلى|هدى|فاطمة|أماني)/i;
                    const malePriorityPattern = /(hamed|shakir|naayf|tarik|maged|hamdan|omar|abdullah|ali|male|حامد|شاكر|نايف|طارق|ماجد|حمدان)/i;

                    const arabicVoices = voices.filter(v => /^ar/i.test(v.lang || '') || /arabic|عرب/i.test(v.name || ''));
                    const strictlyMaleArabic = arabicVoices.filter(v => !femalePattern.test(v.name || ''));

                    self.selectedMaleVoice = strictlyMaleArabic.find(v => malePriorityPattern.test(v.name || ''))
                        || strictlyMaleArabic[0]
                        || arabicVoices.find(v => !femalePattern.test(v.name || ''))
                        || arabicVoices[0]
                        || null;
                };

                selectBestMaleArabicVoice();
                if (typeof window.speechSynthesis.onvoiceschanged !== 'undefined') {
                    window.speechSynthesis.addEventListener('voiceschanged', selectBestMaleArabicVoice);
                }
            },

            // 3. ربط زر "المرشد" العلوي بالبدء الفوري (طوالي) داخل حدث الضغطة المباشر (onClick) لضمان خروج الصوت 100% (Directives 1, 2, 3)
            hijackTopGuideButtonForInstantStart() {
                const self = this;

                window.openSmartGuide = function () {
                    self.startImmediateGuideFromTopButton();
                };

                document.addEventListener('click', function (e) {
                    const guideBtn = e.target && e.target.closest('.msg-quartet-guide, [onclick*="openSmartGuide"]');
                    if (!guideBtn) return;
                    e.preventDefault();
                    e.stopPropagation();
                    e.stopImmediatePropagation();
                    self.startImmediateGuideFromTopButton();
                }, true);
            },

            suppressLegacyGuideModalsAndBars() {
                window.__MUTE_LEGACY_GUIDE_AUDIO__ = true;
                if (typeof window.stopLiveAutopilotSimulation === 'function') {
                    try { window.stopLiveAutopilotSimulation(); } catch (e) {}
                }
                ['msg-universal-modal', 'msg-live-coach-bar', 'msg-coach-svg-popover', 'msg-c5-impact-map-banner', 'msg-pinned-audio-dock'].forEach(id => {
                    const el = document.getElementById(id);
                    if (el) el.style.display = 'none';
                });
            },

            startImmediateGuideFromTopButton() {
                this.suppressLegacyGuideModalsAndBars();

                const hud = document.getElementById('mcpC4SmartGuideMicroHud');
                if (hud) {
                    hud.classList.remove('minimized-pill');
                    hud.classList.add('active');
                }

                this.isActive = true;
                this.isPaused = false;
                this.pickElementMode = false;
                const pickBtn = document.getElementById('mcpC4PickModeBtn');
                if (pickBtn) pickBtn.classList.remove('active-mode');

                this.currentStepIndex = 0;
                this.playStep(0, true);
            },

            clearStageSyncTimers() {
                this.stageSyncTimers.forEach(t => clearTimeout(t));
                this.stageSyncTimers = [];
            },

            // 4. تشغيل الخطوة مع تطبيق قفل عدم تكرار الصلاة على النبي ﷺ (hasPlayedOpeningInvocation — Directives 1, 4, 5, 6)
            playStep(index) {
                const self = this;
                clearTimeout(this.stepAdvanceTimer);
                this.clearStageSyncTimers();
                this.suppressLegacyGuideModalsAndBars();

                if (index < 0) index = 0;
                if (index >= this.steps.length) {
                    this.clearSpotlight();
                    if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups();
                    return;
                }

                this.currentStepIndex = index;
                const step = this.steps[index];

                // تحديث عداد الخطوات والقائمة المنسدلة في الكبسولة المصغرة
                const counterEl = document.getElementById('mcpC4StepCounterBadge');
                if (counterEl) counterEl.textContent = (index + 1) + ' / ' + this.steps.length;

                const selectEl = document.getElementById('mcpC4StageJumpSelect');
                if (selectEl) selectEl.value = String(index);

                // تحديث شريط القاعدة الذهبية المتزامن
                const grText = document.getElementById('mcpC4GoldenRuleText');
                if (grText && step.goldenRule) {
                    grText.innerHTML = '👑 <b style="color:#f59e0b;">' + step.goldenRule + '</b>';
                }

                // تحديث خريطة الترابط البصرية الثلاثية (3-Stage Pure SVG Impact Map) في نفس الثانية
                const mapWrap = document.getElementById('mcpC4SvgImpactMapWrap');
                const mapBtn = document.getElementById('mcpC4MapToggleBtn');
                if (mapWrap) {
                    if (step.showMap) {
                        mapWrap.classList.add('show');
                        if (mapBtn) mapBtn.classList.add('active-mode');
                    } else {
                        mapWrap.classList.remove('show');
                        if (mapBtn) mapBtn.classList.remove('active-mode');
                    }
                }
                this.highlightSvgStage(step.svgStage || 'process');
                if (step.autoCycleSvgStages) {
                    this.highlightSvgStage('process');
                    this.stageSyncTimers.push(setTimeout(() => { if (self.isActive && self.currentStepIndex === index) self.highlightSvgStage('input'); }, 9500));
                    this.stageSyncTimers.push(setTimeout(() => { if (self.isActive && self.currentStepIndex === index) self.highlightSvgStage('output'); }, 19500));
                    this.stageSyncTimers.push(setTimeout(() => { if (self.isActive && self.currentStepIndex === index) self.highlightSvgStage('all'); }, 29000));
                }

                // تنفيذ المحاكاة الحية للخطوة (فتح القوائم المنسدلة والشاشات الوليدة حياً)
                if (typeof step.action === 'function') {
                    try { step.action(); } catch (e) {}
                }

                // تسليط الإطار الضوئي على العنصر المشروح حالياً
                this.highlightScreenElement(step.selector);

                // بناء النص الصافي مع نطق "اللهم صل وسلم على نبينا محمد" مرة واحدة فقط في بداية التشغيل الأول (Directive 1)
                let spokenText = step.text;
                let displayHtml = '<strong>' + step.title + ':</strong> ' + step.text;

                if (!this.hasPlayedOpeningInvocation && !window.hasPlayedOpeningInvocation && !window.__mcpC4HasPlayedOpeningInvocation) {
                    this.hasPlayedOpeningInvocation = true;
                    window.hasPlayedOpeningInvocation = true;
                    window.__mcpC4HasPlayedOpeningInvocation = true;
                    window.__mgC4HasPlayedOpeningInvocation = true;
                    spokenText = OPENING_SALAWAT_ONCE + ' ' + step.text;
                    displayHtml = '<span style="color:#10b981;font-weight:900;">' + OPENING_SALAWAT_ONCE + '</span> — <strong>' + step.title + ':</strong> ' + step.text;
                }

                const speechBox = document.getElementById('mcpC4HudSpeechText');
                if (speechBox) speechBox.innerHTML = displayHtml;

                this.speakMaleVoiceNow(spokenText, () => {
                    if (!self.isActive || self.isPaused || self.pickElementMode) return;
                    if (self.currentStepIndex < self.steps.length - 1) {
                        self.stepAdvanceTimer = setTimeout(() => {
                            self.playStep(self.currentStepIndex + 1);
                        }, 420);
                    } else {
                        self.clearSpotlight();
                        if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups();
                    }
                });
            },

            stopActiveAudioEl() {
                if (this.activeAudioEl) {
                    try {
                        this.activeAudioEl.onended = null;
                        this.activeAudioEl.onerror = null;
                        this.activeAudioEl.pause();
                        this.activeAudioEl.src = '';
                    } catch (e) {}
                    this.activeAudioEl = null;
                }
            },

            // 5. محرك النطق الرجالي الفخيم المباشر (cancel -> resume -> speak) لضمان خروج الصوت فعلياً في كل المتصفحات (Directive 3)
            speakMaleVoiceNow(text, onComplete) {
                const self = this;
                const playPauseBtn = document.getElementById('mcpC4PlayPauseBtn');
                const waveBadge = document.getElementById('mcpC4VoiceWaveBadge');

                this.stopActiveAudioEl();
                if (this.keepAliveInterval) {
                    clearInterval(this.keepAliveInterval);
                    this.keepAliveInterval = null;
                }

                // تطهير النص من أي عبارات ممنوعة ("شرح من الألف إلى الياء") وضمان عدم تكرار الصلاة على النبي ﷺ في وسط الخطوات
                let cleanText = String(text || '')
                    .replace(/شرح\s+من\s+الألف\s+(إلى|ل)\s*الياء/g, '')
                    .replace(/من\s+الألف\s+(إلى|ل)\s*الياء/g, '')
                    .trim();

                let completedOnce = false;
                const finishOnce = function () {
                    if (completedOnce) return;
                    completedOnce = true;
                    if (self.keepAliveInterval) {
                        clearInterval(self.keepAliveInterval);
                        self.keepAliveInterval = null;
                    }
                    if (waveBadge) waveBadge.textContent = '🎙️ المرشد الذكي (صوت رجالي فخيم)';
                    if (typeof onComplete === 'function') onComplete();
                };

                const playServerMaleAudioFallback = function () {
                    if (completedOnce || !self.isActive) return;
                    try {
                        const audio = new Audio('api/tts_male.php?dialect=sudanese&text=' + encodeURIComponent(cleanText));
                        audio.playbackRate = self.speechRate || 1.0;
                        self.activeAudioEl = audio;
                        audio.onplay = function () {
                            self.isPaused = false;
                            if (playPauseBtn) playPauseBtn.innerHTML = '⏸ إيقاف';
                            if (waveBadge) waveBadge.textContent = '🔊 المرشد ينطق الآن (صوت رجالي فخيم)';
                        };
                        audio.onended = finishOnce;
                        audio.onerror = function () {
                            if (waveBadge) waveBadge.textContent = '🎙️ المرشد الذكي (صوت رجالي فخيم)';
                            setTimeout(finishOnce, 1200);
                        };
                        audio.play().catch(() => {
                            setTimeout(finishOnce, 1500);
                        });
                    } catch (err) {
                        setTimeout(finishOnce, 1500);
                    }
                };

                if (!('speechSynthesis' in window)) {
                    playServerMaleAudioFallback();
                    return;
                }

                try {
                    window.speechSynthesis.cancel();
                    window.speechSynthesis.resume();
                } catch (e) {}

                if (!this.selectedMaleVoice) {
                    this.initMaleVoiceEngine();
                }

                const utter = new SpeechSynthesisUtterance(cleanText);
                utter.lang = (this.selectedMaleVoice && this.selectedMaleVoice.lang) ? this.selectedMaleVoice.lang : 'ar-SA';
                if (this.selectedMaleVoice) {
                    utter.voice = this.selectedMaleVoice;
                }
                // ضبط خامة الصوت الرجالي الفخيم الهادئ المريح للأذن والنفس
                utter.pitch = 0.88;
                utter.rate = this.speechRate || 1.0;
                utter.volume = 1.0;

                let utterStarted = false;
                utter.onstart = function () {
                    utterStarted = true;
                    self.isPaused = false;
                    if (playPauseBtn) playPauseBtn.innerHTML = '⏸ إيقاف';
                    if (waveBadge) waveBadge.textContent = '🔊 المرشد ينطق الآن (صوت رجالي فخيم)';
                };

                utter.onend = finishOnce;
                utter.onerror = function () {
                    if (!utterStarted && !completedOnce) {
                        playServerMaleAudioFallback();
                        return;
                    }
                    finishOnce();
                };

                this.activeUtterance = utter;
                try {
                    window.speechSynthesis.speak(utter);
                    // حلقة تنشيط ذكية لمنع متصفحات Chromium من إيقاف الجمل العربية الطويلة
                    this.keepAliveInterval = setInterval(() => {
                        try {
                            if (!self.isActive || self.isPaused) return;
                            if (window.speechSynthesis.paused) {
                                window.speechSynthesis.resume();
                            }
                        } catch (_e) {}
                    }, 250);
                    setTimeout(() => {
                        try {
                            if (self.isActive && !self.isPaused && self.activeUtterance === utter) {
                                if (window.speechSynthesis.paused) {
                                    window.speechSynthesis.resume();
                                }
                                if (!window.speechSynthesis.speaking && !window.speechSynthesis.pending && !utterStarted && !completedOnce) {
                                    window.speechSynthesis.resume();
                                    window.speechSynthesis.speak(utter);
                                }
                            }
                        } catch (e) {}
                    }, 60);
                    // إذا لم يتوفر صوت عربي في نظام التشغيل المحلي خلال 450ms، يعمل الصوت الرجالي الفخيم الاحتياطي فوراً
                    if (!this.selectedMaleVoice) {
                        setTimeout(() => {
                            if (!utterStarted && !completedOnce && self.isActive && self.activeUtterance === utter) {
                                try { window.speechSynthesis.cancel(); } catch (e) {}
                                playServerMaleAudioFallback();
                            }
                        }, 450);
                    }
                } catch (e) {
                    playServerMaleAudioFallback();
                }
            },

            highlightSvgStage(stageKey) {
                const mapIds = {
                    input: 'mcpC4SvgStageInput',
                    process: 'mcpC4SvgStageProcess',
                    output: 'mcpC4SvgStageOutput'
                };
                Object.keys(mapIds).forEach(k => {
                    const el = document.getElementById(mapIds[k]);
                    if (el) {
                        el.classList.toggle('active-stage', stageKey === 'all' || k === stageKey);
                    }
                });
            },

            highlightScreenElement(selector) {
                this.clearSpotlight();
                if (!selector) return;
                const parts = String(selector).split(',').map(s => s.trim()).filter(Boolean);
                let el = null;
                for (const sel of parts) {
                    try {
                        const candidate = document.querySelector(sel);
                        if (candidate && candidate.offsetParent !== null) {
                            el = candidate;
                            break;
                        }
                    } catch (e) {}
                }
                if (!el && parts.length) {
                    try { el = document.querySelector(parts[0]); } catch (e) {}
                }
                if (!el) return;
                el.classList.add('mcp-c4-guide-spotlight');
                try {
                    el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                } catch (e) {}
            },

            clearSpotlight() {
                document.querySelectorAll('.mcp-c4-guide-spotlight').forEach(el => {
                    el.classList.remove('mcp-c4-guide-spotlight');
                });
            },

            // 6. ربط أزرار كبسولة التحكم المصغرة (Micro-HUD Controls)
            bindHudControls() {
                const self = this;

                const prevBtn = document.getElementById('mcpC4PrevBtn');
                const nextBtn = document.getElementById('mcpC4NextBtn');
                const playPauseBtn = document.getElementById('mcpC4PlayPauseBtn');
                const replayBtn = document.getElementById('mcpC4ReplayBtn');
                const speedBtn = document.getElementById('mcpC4SpeedBtn');
                const mapBtn = document.getElementById('mcpC4MapToggleBtn');
                const goldenBtn = document.getElementById('mcpC4GoldenRuleBtn');
                const pickBtn = document.getElementById('mcpC4PickModeBtn');
                const dockBtn = document.getElementById('mcpC4DockPosBtn');
                const minBtn = document.getElementById('mcpC4MinimizeBtn');
                const closeBtn = document.getElementById('mcpC4CloseHudBtn');
                const stageSelect = document.getElementById('mcpC4StageJumpSelect');

                if (prevBtn) {
                    prevBtn.addEventListener('click', () => {
                        self.pickElementMode = false;
                        if (pickBtn) pickBtn.classList.remove('active-mode');
                        self.playStep(Math.max(0, self.currentStepIndex - 1));
                    });
                }

                if (nextBtn) {
                    nextBtn.addEventListener('click', () => {
                        self.pickElementMode = false;
                        if (pickBtn) pickBtn.classList.remove('active-mode');
                        self.playStep(Math.min(self.steps.length - 1, self.currentStepIndex + 1));
                    });
                }

                if (replayBtn) {
                    replayBtn.addEventListener('click', () => {
                        self.playStep(self.currentStepIndex);
                    });
                }

                if (goldenBtn) {
                    goldenBtn.addEventListener('click', () => {
                        self.pickElementMode = false;
                        if (pickBtn) pickBtn.classList.remove('active-mode');
                        self.playStep(3);
                    });
                }

                if (playPauseBtn) {
                    playPauseBtn.addEventListener('click', () => {
                        if (self.activeAudioEl) {
                            if (!self.activeAudioEl.paused) {
                                self.isPaused = true;
                                clearTimeout(self.stepAdvanceTimer);
                                self.activeAudioEl.pause();
                                playPauseBtn.innerHTML = '▶️ استئناف';
                            } else {
                                self.isPaused = false;
                                self.activeAudioEl.play().catch(() => {});
                                playPauseBtn.innerHTML = '⏸ إيقاف';
                            }
                            return;
                        }
                        if (!('speechSynthesis' in window)) return;
                        if (window.speechSynthesis.speaking && !self.isPaused) {
                            self.isPaused = true;
                            clearTimeout(self.stepAdvanceTimer);
                            window.speechSynthesis.pause();
                            playPauseBtn.innerHTML = '▶️ استئناف';
                        } else if (self.isPaused) {
                            self.isPaused = false;
                            window.speechSynthesis.resume();
                            playPauseBtn.innerHTML = '⏸ إيقاف';
                        } else {
                            self.playStep(self.currentStepIndex);
                        }
                    });
                }

                if (speedBtn) {
                    const speeds = [0.9, 1.0, 1.15, 1.3];
                    speedBtn.addEventListener('click', () => {
                        const idx = speeds.indexOf(self.speechRate);
                        self.speechRate = speeds[(idx + 1) % speeds.length];
                        speedBtn.textContent = '⚡ ' + self.speechRate.toFixed(2).replace(/\.00$/, '.0') + 'x';
                        if (self.isActive && !self.isPaused) {
                            self.playStep(self.currentStepIndex);
                        }
                    });
                }

                if (mapBtn) {
                    mapBtn.addEventListener('click', () => {
                        const wrap = document.getElementById('mcpC4SvgImpactMapWrap');
                        if (wrap) {
                            const shown = wrap.classList.toggle('show');
                            mapBtn.classList.toggle('active-mode', shown);
                        }
                    });
                }

                if (dockBtn) {
                    dockBtn.addEventListener('click', () => {
                        const hud = document.getElementById('mcpC4SmartGuideMicroHud');
                        if (hud) {
                            const top = hud.classList.toggle('docked-top');
                            dockBtn.textContent = top ? '⬇️ للأسفل' : '⬆️ للأعلى';
                        }
                    });
                }

                if (minBtn) {
                    minBtn.addEventListener('click', () => {
                        const hud = document.getElementById('mcpC4SmartGuideMicroHud');
                        if (hud) {
                            const isMin = hud.classList.toggle('minimized-pill');
                            minBtn.textContent = isMin ? '🗖' : '🗕';
                        }
                    });
                }

                if (stageSelect) {
                    stageSelect.addEventListener('change', () => {
                        const targetIdx = parseInt(stageSelect.value, 10) || 0;
                        self.pickElementMode = false;
                        if (pickBtn) pickBtn.classList.remove('active-mode');
                        self.playStep(targetIdx);
                    });
                }

                if (closeBtn) {
                    closeBtn.addEventListener('click', () => self.stopAndCloseGuide());
                }

                document.addEventListener('keydown', (e) => {
                    if (e.key === 'Escape' && self.isActive) {
                        self.stopAndCloseGuide();
                    }
                });
            },

            // 7. وضع "👆 اشرح عنصراً" التفاعلي الفوري لشرح أي خانة أو زر بالضغط عليه (بدون تكرار الصلاة على النبي ﷺ)
            initPickElementExplainMode() {
                const self = this;
                const pickBtn = document.getElementById('mcpC4PickModeBtn');
                if (pickBtn) {
                    pickBtn.addEventListener('click', () => {
                        self.pickElementMode = !self.pickElementMode;
                        pickBtn.classList.toggle('active-mode', self.pickElementMode);
                        if (self.pickElementMode) {
                            clearTimeout(self.stepAdvanceTimer);
                            const speechBox = document.getElementById('mcpC4HudSpeechText');
                            const msg = 'وضع شرح العنصر المباشر نشط الآن: اضغط على أي خانة أو زر في الشاشة أو الشاشات الوليدة ليشرحه المرشد فوراً.';
                            if (speechBox) speechBox.innerHTML = '<strong>👆 وضع الشرح المباشر:</strong> ' + msg;
                            self.speakMaleVoiceNow(msg);
                        }
                    });
                }

                document.addEventListener('click', function (e) {
                    if (!self.isActive || !self.pickElementMode) return;
                    if (e.target.closest('#mcpC4SmartGuideMicroHud') || e.target.closest('#msg-universal-fixed-launcher')) return;

                    const el = e.target.closest('button, input, select, textarea, .account-block, #mcp-world-summary-bar, #grand-tafqeet-container, #payment-methods-row, #primary-inputs-container');
                    if (!el) return;

                    e.preventDefault();
                    e.stopPropagation();

                    self.clearSpotlight();
                    el.classList.add('mcp-c4-guide-spotlight');

                    const explanation = self.describeClickedElement(el);
                    const speechBox = document.getElementById('mcpC4HudSpeechText');
                    if (speechBox) {
                        speechBox.innerHTML = '<strong>🎯 ' + explanation.title + ':</strong> ' + explanation.desc;
                    }
                    self.speakMaleVoiceNow(explanation.title + '. ' + explanation.desc);
                }, true);
            },

            describeClickedElement(el) {
                if (typeof window.explainMultiCashPaymentDomElement === 'function') {
                    const found = window.explainMultiCashPaymentDomElement(el);
                    if (found) return found;
                }
                const labelTxt = (el.getAttribute('title') || el.getAttribute('placeholder') || el.innerText || 'عنصر في شاشة الحركة المالية المجمعة').replace(/\s+/g, ' ').trim().slice(0, 65);
                return {
                    title: labelTxt || 'عنصر تفاعلي في السند المجمع',
                    desc: 'هذا العنصر جزء من دورة عمل شاشة الحركة المالية المجمعة ويعمل بتكامل مباشر مع القيد المزدوج وتقارير الأستاذ العام والخزينة.'
                };
            },

            stopAndCloseGuide() {
                this.isActive = false;
                this.isPaused = false;
                this.pickElementMode = false;
                clearTimeout(this.stepAdvanceTimer);
                this.clearStageSyncTimers();
                if (this.keepAliveInterval) {
                    clearInterval(this.keepAliveInterval);
                    this.keepAliveInterval = null;
                }
                this.clearSpotlight();
                if (typeof window.cleanupMultiCashGuidePopups === 'function') {
                    try { window.cleanupMultiCashGuidePopups(); } catch (e) {}
                }
                this.stopActiveAudioEl();
                try {
                    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
                } catch (e) {}
                const hud = document.getElementById('mcpC4SmartGuideMicroHud');
                if (hud) hud.classList.remove('active');
            }
        };

        window.McpDesktopConstitution4 = McpDesktopConstitution4;
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => McpDesktopConstitution4.init());
        } else {
            McpDesktopConstitution4.init();
        }
    })();
    </script>

    <!-- ══════════════════════════════════════════════════════════════════════════════ -->
    <!-- الدستور الخامس (Constitution 5 of 14): دستور "المرشد الذكي" (2) — المحاكاة الحية للشاشات الوليدة والقوائم، القاعدة الذهبية لكل عنصر، البؤرة الضوئية والتأشير والقفز المباشر، التحديث الذاتي المستقبلي (MutationObserver)، ومراعاة الصلاحيات -->
    <!-- ══════════════════════════════════════════════════════════════════════════════ -->
    <style id="mcp-constitution-5-smart-guide-styles">
        /* 1. شريط القاعدة الذهبية الخاصة بالعنصر المشروح حالياً داخل كبسولة المرشد (World-Class Addition 1) */
        #mcpC5ElementGoldenRuleBar {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 8px;
            flex-wrap: wrap;
            padding: 5px 10px;
            border-radius: 10px;
            border: 2px solid #10b981 !important;
            background: rgba(16, 185, 129, 0.14) !important;
            color: #ffffff !important;
            font-size: 0.8rem !important;
            font-weight: 900 !important;
            cursor: pointer;
            transition: border-color 0.2s ease, background 0.2s ease;
        }
        html.light-theme #mcpC5ElementGoldenRuleBar {
            background: #ecfdf5 !important;
            color: #000000 !important;
            border: 2px solid #059669 !important;
        }
        #mcpC4SmartGuideMicroHud.minimized-pill #mcpC5ElementGoldenRuleBar {
            display: none !important;
        }

        /* 2. المؤشر البصري العائم للبؤرة الضوئية بتسارع GPU 0ms (World-Class Addition 2 — Directive 3) */
        #mcpC5LivePointerBadge {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            z-index: 2147483644;
            pointer-events: none;
            padding: 5px 11px;
            border-radius: 999px;
            border: 2.2px solid #f59e0b !important;
            background: rgba(15, 23, 42, 0.96) !important;
            color: #ffffff !important;
            font-family: var(--mcp-font-sans, 'Tajawal', 'Cairo', sans-serif) !important;
            font-size: 0.77rem !important;
            font-weight: 900 !important;
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.55), 0 0 16px rgba(245, 158, 11, 0.55) !important;
            white-space: nowrap;
            max-width: 90vw;
            overflow: hidden;
            text-overflow: ellipsis;
            direction: rtl;
            will-change: transform;
            transition: transform 0.16s cubic-bezier(0.22, 1, 0.36, 1);
        }
        html.light-theme #mcpC5LivePointerBadge {
            background: #fffbeb !important;
            color: #000000 !important;
            border: 2.2px solid #d97706 !important;
            box-shadow: 0 8px 20px rgba(15, 23, 42, 0.2), 0 0 12px rgba(217, 119, 6, 0.35) !important;
        }

        /* 3. نافذة المعاينة الحية لخيارات قوائم <select> المنسدلة (World-Class Addition 3 — Directive 2) */
        #mcpC5LiveSelectPreviewPopup {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            z-index: 2147483643;
            min-width: 220px;
            max-width: 340px;
            border-radius: 12px;
            padding: 8px 10px;
            border: 2.2px solid #38bdf8 !important;
            background: rgba(15, 23, 42, 0.97) !important;
            color: #ffffff !important;
            box-shadow: 0 16px 36px rgba(0, 0, 0, 0.65), 0 0 18px rgba(56, 189, 248, 0.4) !important;
            direction: rtl;
            font-family: var(--mcp-font-sans, 'Tajawal', 'Cairo', sans-serif) !important;
            pointer-events: none;
        }
        html.light-theme #mcpC5LiveSelectPreviewPopup {
            background: #ffffff !important;
            color: #000000 !important;
            border: 2.2px solid #0284c7 !important;
            box-shadow: 0 12px 28px rgba(15, 23, 42, 0.22) !important;
        }
        #mcpC5LiveSelectPreviewPopup .mcp-c5-sel-hdr {
            font-size: 0.76rem;
            font-weight: 900;
            color: #38bdf8;
            margin-bottom: 5px;
            padding-bottom: 4px;
            border-bottom: 1.5px solid rgba(56, 189, 248, 0.35);
        }
        html.light-theme #mcpC5LiveSelectPreviewPopup .mcp-c5-sel-hdr {
            color: #0284c7;
            border-bottom-color: rgba(2, 132, 199, 0.3);
        }
        #mcpC5LiveSelectPreviewPopup .mcp-c5-sel-opt {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 6px;
            padding: 4px 8px;
            border-radius: 7px;
            font-size: 0.78rem;
            font-weight: 800;
            margin-bottom: 2px;
        }
        #mcpC5LiveSelectPreviewPopup .mcp-c5-sel-opt.is-selected {
            background: rgba(16, 185, 129, 0.22);
            border: 1.5px solid #10b981;
        }
        html.light-theme #mcpC5LiveSelectPreviewPopup .mcp-c5-sel-opt.is-selected {
            background: #d1fae5;
            border-color: #059669;
            color: #000000;
        }

        /* 4. البؤرة الضوئية المركزة وتهدئة الخلفية غير النشطة أثناء الشرح (Spotlight Focus — Directive 3) */
        .mcp-c4-guide-spotlight {
            outline: 3.5px solid #f59e0b !important;
            outline-offset: 3px !important;
            box-shadow: 0 0 0 4px rgba(245, 158, 11, 0.28), 0 0 26px rgba(245, 158, 11, 0.85) !important;
            border-radius: 8px;
            transition: outline 0.15s ease, box-shadow 0.15s ease !important;
        }

        /* 5. إخفاء وقفل العناصر غير المصرح بها حسب صلاحيات المستخدم (Role-Aware UI — Directive 5) */
        [data-mcp-role-hidden="1"] {
            display: none !important;
            pointer-events: none !important;
        }

        @media print {
            #mcpC5LivePointerBadge,
            #mcpC5LiveSelectPreviewPopup {
                display: none !important;
            }
        }
    </style>

    <!-- المؤشر البصري العائم للبؤرة الضوئية (GPU Spotlight Pointer Badge) -->
    <div id="mcpC5LivePointerBadge" aria-hidden="true">🎯 العنصر النشط</div>

    <!-- نافذة المعاينة الحية لخيارات قوائم <select> المنسدلة (Live Native Select Mirror) -->
    <div id="mcpC5LiveSelectPreviewPopup" aria-hidden="true"></div>

    <script id="mcp-constitution-5-smart-guide-engine">
    (function () {
        'use strict';
        if (window.McpDesktopConstitution5) return;

        // دالة عالمية لعرض خيارات أي قائمة <select> منسدلة حياً أمام عين المستخدم أثناء الشرح (Directive 2)
        window.showLiveSelectOptionsMirror = function (selectEl, _unused, customTitle) {
            const popup = document.getElementById('mcpC5LiveSelectPreviewPopup');
            if (!popup || !selectEl || !selectEl.options) return;
            const rect = selectEl.getBoundingClientRect();
            if (rect.width === 0 && rect.height === 0) return;

            const title = customTitle || selectEl.getAttribute('title') || '📂 خيارات القائمة المنسدلة الحية';
            let html = '<div class="mcp-c5-sel-hdr">' + title + ' (منسدلة حياً أمامك)</div>';
            Array.from(selectEl.options).slice(0, 8).forEach(opt => {
                const isSel = opt.selected;
                html += '<div class="mcp-c5-sel-opt ' + (isSel ? 'is-selected' : '') + '">' +
                    '<span>' + (isSel ? '✅ ' : '• ') + (opt.text || opt.value) + '</span>' +
                    (isSel ? '<span style="font-size:0.7rem;color:#10b981;font-weight:900;">مختار</span>' : '') +
                    '</div>';
            });
            popup.innerHTML = html;
            popup.style.display = 'block';

            const topPos = Math.min(window.innerHeight - popup.offsetHeight - 14, Math.max(12, rect.bottom + 6));
            const leftPos = Math.min(window.innerWidth - popup.offsetWidth - 14, Math.max(12, rect.left));
            popup.style.top = topPos + 'px';
            popup.style.left = leftPos + 'px';
        };

        window.hideLiveSelectOptionsMirror = function () {
            const popup = document.getElementById('mcpC5LiveSelectPreviewPopup');
            if (popup) popup.style.display = 'none';
        };

        const McpDesktopConstitution5 = {
            hoverExplainEnabled: true,
            hoverDebounceTimer: null,
            lastHoveredElement: null,
            mutationObserver: null,
            dynamicElementsMap: new WeakMap(),
            dynamicRegisteredSelectors: new Set(),

            init() {
                this.patchDropdownDelayedHiders();
                this.injectConstitution5HudControlsAndBars();
                this.upgradeConstitution4EngineForC5();
                this.bindHoverAndClickToJump();
                this.enforceRolePermissionsAndFilterGuide();
                this.initSelfUpdatingMutationObserver();
            },

            // 1. حماية القوائم المنسدلة المفتوحة بواسطة المرشد الذكي من الإغلاق التلقائي بحدث onblur (Directive 2)
            patchDropdownDelayedHiders() {
                const origHideAcc = window.hideAccountDropdownDelayed;
                if (typeof origHideAcc === 'function' && !origHideAcc.__mcpC5Patched) {
                    const wrappedAcc = function (type) {
                        const listId = type + '-dropdown-list';
                        if (window.__mcpC5PinDropdownList === listId) return;
                        return origHideAcc.apply(this, arguments);
                    };
                    wrappedAcc.__mcpC5Patched = true;
                    window.hideAccountDropdownDelayed = wrappedAcc;
                }

                const origHideCC = window.hideCostCenterDropdownDelayed;
                if (typeof origHideCC === 'function' && !origHideCC.__mcpC5Patched) {
                    const wrappedCC = function (blockId) {
                        const listId = 'cost-center-' + blockId + '-dropdown-list';
                        if (window.__mcpC5PinDropdownList === listId) return;
                        return origHideCC.apply(this, arguments);
                    };
                    wrappedCC.__mcpC5Patched = true;
                    window.hideCostCenterDropdownDelayed = wrappedCC;
                }
            },

            // 2. حقن شريط القاعدة الذهبية الخاصة بالعنصر وأزرار التأشير والاستشعار الذاتي داخل كبسولة المرشد (Additions 1, 4, 5)
            injectConstitution5HudControlsAndBars() {
                const self = this;
                const hud = document.getElementById('mcpC4SmartGuideMicroHud');
                if (!hud) return;

                const controls = hud.querySelector('.mcp-c4-hud-controls');
                const pickBtn = document.getElementById('mcpC4PickModeBtn');
                if (controls && !document.getElementById('mcpC5HoverToggleBtn')) {
                    const hoverBtn = document.createElement('button');
                    hoverBtn.type = 'button';
                    hoverBtn.id = 'mcpC5HoverToggleBtn';
                    hoverBtn.className = 'mcp-c4-hud-btn active-mode';
                    hoverBtn.title = 'تفعيل/إيقاف الشرح الفوري والقاعدة الذهبية عند التأشير بالماوس أو الضغط المباشر (Hover & Click-to-Jump)';
                    hoverBtn.innerHTML = '🖱️ تأشير وقفز';
                    hoverBtn.addEventListener('click', () => {
                        self.hoverExplainEnabled = !self.hoverExplainEnabled;
                        hoverBtn.classList.toggle('active-mode', self.hoverExplainEnabled);
                    });
                    if (pickBtn && pickBtn.nextSibling) {
                        controls.insertBefore(hoverBtn, pickBtn.nextSibling);
                    } else {
                        controls.appendChild(hoverBtn);
                    }
                }

                const topLeftGroup = hud.querySelector('.mcp-c4-hud-top > div:first-child');
                if (topLeftGroup && !document.getElementById('mcpC5SelfUpdateBadge')) {
                    const selfBadge = document.createElement('span');
                    selfBadge.id = 'mcpC5SelfUpdateBadge';
                    selfBadge.style.cssText = 'padding:1px 7px;border-radius:999px;border:1.6px solid #10b981;color:#10b981;font-size:0.71rem;font-weight:900;';
                    selfBadge.title = 'محرك الاستشعار الحي (MutationObserver) نشط ويكتشف تلقائياً أي زر أو خانة تضاف للشاشة';
                    selfBadge.textContent = '🔄 استشعار ذاتي 100%';
                    topLeftGroup.appendChild(selfBadge);
                }

                const generalGoldenStrip = document.getElementById('mcpC4GoldenRuleStrip');
                if (generalGoldenStrip && !document.getElementById('mcpC5ElementGoldenRuleBar')) {
                    const elemBar = document.createElement('div');
                    elemBar.id = 'mcpC5ElementGoldenRuleBar';
                    elemBar.title = 'اضغط لسماع القاعدة الذهبية الخاصة بهذا العنصر بالصوت الرجالي الفخيم';
                    elemBar.innerHTML = '<span id="mcpC5ElementGoldenRuleText">💎 <b style="color:#10b981;">القاعدة الذهبية للعنصر الحالي:</b> أشر بالماوس أو اضغط على أي خانة أو زر لسماع شرحه العميق وقاعدته الذهبية فوراً.</span>' +
                        '<span style="font-size:0.74rem;opacity:0.92;">🎯 محاكاة حية + صلاحيات ذكية 🔊</span>';
                    elemBar.addEventListener('click', () => {
                        const c4 = window.McpDesktopConstitution4;
                        const txtEl = document.getElementById('mcpC5ElementGoldenRuleText');
                        if (c4 && txtEl) {
                            c4.speakMaleVoiceNow(txtEl.textContent.replace(/[💎🔊🎯]/g, '').trim());
                        }
                    });
                    generalGoldenStrip.insertAdjacentElement('afterend', elemBar);
                }
            },

            // 3. ترقية محرك الدستور الرابع ليدعم البؤرة الضوئية العائمة، وتحديث شريط القاعدة الذهبية للعنصر، وتخطي العناصر المقيدة بالصلاحيات
            upgradeConstitution4EngineForC5() {
                const self = this;
                const c4 = window.McpDesktopConstitution4;
                if (!c4 || c4.__mcpC5Upgraded) return;
                c4.__mcpC5Upgraded = true;

                const origHighlight = c4.highlightScreenElement.bind(c4);
                c4.highlightScreenElement = function (selector, customBadgeTitle) {
                    origHighlight(selector);
                    const activeEl = document.querySelector('.mcp-c4-guide-spotlight');
                    if (activeEl) {
                        const info = (typeof window.explainMultiCashPaymentDomElement === 'function' && window.explainMultiCashPaymentDomElement(activeEl)) || null;
                        const step = c4.steps[c4.currentStepIndex] || {};
                        const badgeTitle = customBadgeTitle || (info && info.title) || step.title || 'العنصر المشروح حالياً';
                        const goldenRule = (info && info.goldenRule) || step.goldenRule || '';
                        self.positionPointerBadgeOnElement(activeEl, badgeTitle);
                        self.updateElementGoldenRuleBar(badgeTitle, goldenRule);
                    }
                };

                const origClearSpotlight = c4.clearSpotlight.bind(c4);
                c4.clearSpotlight = function () {
                    origClearSpotlight();
                    self.hidePointerBadge();
                };

                const origPlayStep = c4.playStep.bind(c4);
                c4.playStep = function (index) {
                    // تخطي أي خطوة لا يملك المستخدم الحالي صلاحية رؤيتها تلقائياً (Directive 5)
                    let targetIdx = index;
                    const dir = (index >= c4.currentStepIndex) ? 1 : -1;
                    while (targetIdx >= 0 && targetIdx < c4.steps.length) {
                        if (self.isStepPermitted(c4.steps[targetIdx])) break;
                        targetIdx += dir;
                    }
                    if (targetIdx < 0) targetIdx = 0;
                    return origPlayStep(targetIdx);
                };

                const origStop = c4.stopAndCloseGuide.bind(c4);
                c4.stopAndCloseGuide = function () {
                    clearTimeout(self.hoverDebounceTimer);
                    self.hidePointerBadge();
                    window.hideLiveSelectOptionsMirror();
                    origStop();
                };
            },

            positionPointerBadgeOnElement(el, labelText) {
                const badge = document.getElementById('mcpC5LivePointerBadge');
                if (!badge || !el) return;
                const rect = el.getBoundingClientRect();
                if (rect.width === 0 && rect.height === 0) {
                    badge.style.display = 'none';
                    return;
                }
                badge.textContent = '🎯 ' + String(labelText || '').replace(/\s+/g, ' ').trim().slice(0, 72);
                badge.style.display = 'block';

                const badgeW = badge.offsetWidth || 220;
                const badgeH = badge.offsetHeight || 32;
                let top = rect.top - badgeH - 8;
                if (top < 8) top = Math.min(window.innerHeight - badgeH - 8, rect.bottom + 8);
                let left = rect.right - badgeW;
                left = Math.max(10, Math.min(window.innerWidth - badgeW - 10, left));

                badge.style.transform = 'translate3d(' + Math.round(left) + 'px, ' + Math.round(top) + 'px, 0)';
            },

            hidePointerBadge() {
                const badge = document.getElementById('mcpC5LivePointerBadge');
                if (badge) badge.style.display = 'none';
            },

            updateElementGoldenRuleBar(title, goldenRule) {
                const elText = document.getElementById('mcpC5ElementGoldenRuleText');
                if (!elText) return;
                const cleanRule = goldenRule || 'القاعدة الذهبية: راجع دقة البيانات في هذا العنصر لضمان سلامة الترحيل المحاسبي.';
                elText.innerHTML = '💎 <b style="color:#10b981;">' + (title ? title + ' — ' : '') + '</b><span>' + cleanRule + '</span>';
            },

            // 4. المحاكاة الحية الفورية عند شرح أي عنصر (فتح القوائم المنسدلة أو الشاشات الوليدة المرتبطة به — Directive 2)
            triggerElementLiveSimulation(el, info) {
                if (!el || !info) return;
                // الحفاظ على أي شاشة وليدة مفتوحة إذا كان العنصر بداخلها!
                if (typeof window.cleanupMultiCashGuidePopups === 'function') {
                    window.cleanupMultiCashGuidePopups(el);
                }

                const simType = info.simType;
                if (!simType) {
                    if (el.tagName === 'SELECT') {
                        window.showLiveSelectOptionsMirror(el, null, info.title);
                    }
                    return;
                }

                if (simType === 'select-preview') {
                    const selEl = (info.simTarget && document.querySelector(info.simTarget)) || (el.tagName === 'SELECT' ? el : null);
                    if (selEl) window.showLiveSelectOptionsMirror(selEl, null, info.title);
                } else if (simType === 'dropdown-main-account') {
                    if (typeof window.openGuideAccountDropdownLive === 'function') {
                        window.openGuideAccountDropdownLive('main-account');
                    }
                } else if (simType === 'dropdown-sub-account') {
                    const block = el.closest('.account-block');
                    const bid = (block && block.getAttribute('data-block-id')) || window.getFirstActiveMcpBlockId();
                    if (typeof window.openGuideAccountDropdownLive === 'function') {
                        window.openGuideAccountDropdownLive('account-' + bid);
                    }
                } else if (simType === 'dropdown-cost-center') {
                    const block = el.closest('.account-block');
                    const bid = (block && block.getAttribute('data-block-id')) || window.getFirstActiveMcpBlockId();
                    if (typeof window.openGuideCostCenterDropdownLive === 'function') {
                        window.openGuideCostCenterDropdownLive(bid);
                    }
                } else if (simType === 'dropdown-auto-send') {
                    const menu = document.getElementById('auto-send-dropdown-menu');
                    if (menu) menu.style.display = 'block';
                } else if (simType === 'expand-bank') {
                    const block = el.closest('.account-block');
                    const bid = (block && block.getAttribute('data-block-id')) || window.getFirstActiveMcpBlockId();
                    const bankBtn = document.getElementById('pm-bank-' + bid);
                    const bankDet = document.getElementById('bank-details-' + bid);
                    if (bankDet && bankDet.style.display === 'none' && bankBtn) {
                        try { bankBtn.click(); } catch (e) {}
                    }
                } else if (simType === 'expand-cheque') {
                    const block = el.closest('.account-block');
                    const bid = (block && block.getAttribute('data-block-id')) || window.getFirstActiveMcpBlockId();
                    const chqBtn = document.getElementById('pm-cheque-' + bid);
                    const chqDet = document.getElementById('cheque-details-' + bid);
                    if (chqDet && chqDet.style.display === 'none' && chqBtn) {
                        try { chqBtn.click(); } catch (e) {}
                    }
                } else if (simType === 'modal-quick-add-acc') {
                    const modal = document.getElementById('mcp-quick-add-account-modal');
                    if (modal && modal.style.display !== 'flex' && typeof window.openQuickAddAccountModal === 'function') {
                        try { window.openQuickAddAccountModal('main-account'); } catch (e) {}
                    }
                } else if (simType === 'modal-quick-add-cc') {
                    const modal = document.getElementById('mcp-quick-add-cc-modal');
                    const bid = window.getFirstActiveMcpBlockId();
                    if (modal && modal.style.display !== 'flex' && typeof window.openQuickAddCostCenterModal === 'function') {
                        try { window.openQuickAddCostCenterModal(bid); } catch (e) {}
                    }
                } else if (simType === 'modal-split') {
                    const modal = document.getElementById('mcp-split-modal');
                    if (modal && modal.style.display !== 'flex' && typeof window.openEqualSplitModal === 'function') {
                        try { window.openEqualSplitModal(); } catch (e) {}
                    }
                } else if (simType === 'modal-excel') {
                    const modal = document.getElementById('mcp-excel-modal');
                    if (modal && modal.style.display !== 'flex' && typeof window.openExcelPasteModal === 'function') {
                        try { window.openExcelPasteModal(); } catch (e) {}
                    }
                } else if (simType === 'modal-templates') {
                    const modal = document.getElementById('mcp-templates-modal');
                    if (modal && modal.style.display !== 'flex' && typeof window.openBatchTemplatesModal === 'function') {
                        try { window.openBatchTemplatesModal(); } catch (e) {}
                    }
                } else if (simType === 'drawer-inbound') {
                    const drawer = document.getElementById('inbound-receipts-drawer');
                    if (drawer && !drawer.classList.contains('open')) {
                        if (typeof window.toggleInboundReceiptsDrawer === 'function') {
                            try { window.toggleInboundReceiptsDrawer(true); } catch (e) { drawer.classList.add('open'); }
                        } else {
                            drawer.classList.add('open');
                        }
                    }
                } else if (simType === 'modal-whatsapp') {
                    const modal = document.getElementById('wa-voucher-modal');
                    if (modal && modal.style.display !== 'flex' && typeof window.openGuideWhatsAppModalLive === 'function') {
                        window.openGuideWhatsAppModalLive();
                    }
                } else if (simType === 'modal-print-preview') {
                    const modal = document.getElementById('print-preview-modal');
                    if (modal && modal.style.display !== 'flex' && typeof window.printVoucher === 'function') {
                        try { window.printVoucher(); } catch (e) {}
                    }
                } else if (simType === 'modal-c9-inspection') {
                    if (window.McpDesktopConstitution9 && typeof window.McpDesktopConstitution9.openInspectionModal === 'function') {
                        window.McpDesktopConstitution9.openInspectionModal();
                        const uSel = document.getElementById('mcpC9UnitSelect');
                        if (uSel) window.showLiveSelectOptionsMirror(uSel, null, '3️⃣ وحدات القياس المترابطة والتحويل اللحظي');
                    }
                } else if (simType === 'modal-c10-commercial') {
                    if (window.McpDesktopConstitution10 && typeof window.McpDesktopConstitution10.openCommercialModal === 'function') {
                        window.McpDesktopConstitution10.openCommercialModal();
                        const tSel = document.getElementById('mcpC10PricingTierSelect');
                        if (tSel) window.showLiveSelectOptionsMirror(tSel, null, '2️⃣ شرائح الأسعار الذكية (جملة / نصف جملة / قطاعي / سعر خاص / آخر سعر)');
                    }
                } else if (simType === 'modal-c11-portfolio') {
                    if (window.McpDesktopConstitution11 && typeof window.McpDesktopConstitution11.openPortfolioModal === 'function') {
                        window.McpDesktopConstitution11.openPortfolioModal();
                        const dSel = document.getElementById('mcpC11NewChqDirection');
                        if (dSel) window.showLiveSelectOptionsMirror(dSel, null, '1️⃣ نوع الشيك في الحافظة (صادر لمورد / وارد من عميل قابل للتظهير)');
                    }
                } else if (simType === 'modal-c12-security') {
                    if (window.McpDesktopConstitution12 && typeof window.McpDesktopConstitution12.openSecurityModal === 'function') {
                        window.McpDesktopConstitution12.openSecurityModal();
                    }
                } else if (simType === 'modal-c13-cyber') {
                    if (window.McpDesktopConstitution13 && typeof window.McpDesktopConstitution13.openCyberModal === 'function') {
                        window.McpDesktopConstitution13.openCyberModal();
                    }
                } else if (simType === 'modal-c14-reports') {
                    if (window.McpDesktopConstitution14 && typeof window.McpDesktopConstitution14.openReportsModal === 'function') {
                        window.McpDesktopConstitution14.openReportsModal();
                    }
                } else if (simType === 'modal-c15-master') {
                    if (window.McpDesktopConstitution15 && typeof window.McpDesktopConstitution15.openMasterGateModal === 'function') {
                        window.McpDesktopConstitution15.openMasterGateModal();
                    }
                } else if (simType === 'modal-fc1-ai') {
                    if (window.McpFinalConstitution1AI && typeof window.McpFinalConstitution1AI.openAiSupremeModal === 'function') {
                        window.McpFinalConstitution1AI.openAiSupremeModal();
                    }
                } else if (simType === 'modal-fc2-analytical') {
                    if (window.McpFinalConstitution2AnalyticalSecurityAI && typeof window.McpFinalConstitution2AnalyticalSecurityAI.openAnalyticalModal === 'function') {
                        window.McpFinalConstitution2AnalyticalSecurityAI.openAnalyticalModal();
                    }
                }
            },

            // 5. شرح أي عنصر فوراً عند التأشير عليه (Hover) أو الضغط عليه مباشرة (Click-to-Jump — Directive 3)
            explainInteractiveElementNow(el, triggerLiveModals) {
                const c4 = window.McpDesktopConstitution4;
                if (!c4 || !c4.isActive || !el) return;
                if (!this.isElementPermittedForCurrentUser(el)) return;

                const info = (typeof window.explainMultiCashPaymentDomElement === 'function' && window.explainMultiCashPaymentDomElement(el))
                    || this.resolveDynamicElementInfo(el);
                if (!info) return;

                clearTimeout(c4.stepAdvanceTimer);
                c4.clearStageSyncTimers();
                c4.clearSpotlight();
                el.classList.add('mcp-c4-guide-spotlight');

                const ruleText = info.goldenRule || 'القاعدة الذهبية: راجع دقة البيانات في هذا العنصر لضمان سلامة الترحيل المحاسبي.';
                this.positionPointerBadgeOnElement(el, info.title);
                this.updateElementGoldenRuleBar(info.title, ruleText);

                const grStripText = document.getElementById('mcpC4GoldenRuleText');
                if (grStripText) {
                    grStripText.innerHTML = '👑 <b style="color:#f59e0b;">' + ruleText + '</b>';
                }

                // تنفيذ المحاكاة الحية للقوائم المنسدلة أو الشاشات الوليدة
                if (triggerLiveModals || (info.simType && !info.simType.startsWith('modal-'))) {
                    this.triggerElementLiveSimulation(el, info);
                } else if (el.tagName === 'SELECT') {
                    window.showLiveSelectOptionsMirror(el, null, info.title);
                }

                const speechBox = document.getElementById('mcpC4HudSpeechText');
                if (speechBox) {
                    speechBox.innerHTML = '<strong>🎯 ' + info.title + ':</strong> ' + info.desc +
                        ' <span style="color:#fcd34d;font-weight:900;">(' + ruleText + ')</span>';
                }

                c4.speakMaleVoiceNow(info.title + '. ' + info.desc + ' ' + ruleText);
            },

            bindHoverAndClickToJump() {
                const self = this;
                const interactiveSelector = 'button, input, select, textarea, .btn-statement-glow, #mcp-world-summary-bar, #grand-tafqeet-container, #mcp-2g-resilience-badge';

                // الشرح السلس عند التأشير بالماوس (Hover-to-Explain) أثناء تفعيل المرشد
                document.addEventListener('mouseover', function (e) {
                    const c4 = window.McpDesktopConstitution4;
                    if (!c4 || !c4.isActive || !self.hoverExplainEnabled) return;
                    if (e.target.closest('#mcpC4SmartGuideMicroHud') || e.target.closest('#msg-universal-fixed-launcher')) return;

                    const el = e.target.closest(interactiveSelector);
                    if (!el || el === self.lastHoveredElement) return;
                    if (!self.isElementPermittedForCurrentUser(el)) return;

                    self.lastHoveredElement = el;
                    clearTimeout(self.hoverDebounceTimer);
                    self.hoverDebounceTimer = setTimeout(() => {
                        if (!c4.isActive || !self.hoverExplainEnabled) return;
                        self.explainInteractiveElementNow(el, false);
                    }, 460);
                }, { passive: true });

                // القفز المباشر بالضغط (Click-to-Jump) على أي خانة أو زر أثناء تفعيل المرشد الذكي
                document.addEventListener('click', function (e) {
                    const c4 = window.McpDesktopConstitution4;
                    if (!c4 || !c4.isActive) return;
                    if (e.target.closest('#mcpC4SmartGuideMicroHud') || e.target.closest('#msg-universal-fixed-launcher')) return;

                    const el = e.target.closest(interactiveSelector);
                    if (!el) return;
                    if (!self.isElementPermittedForCurrentUser(el)) return;

                    // إذا كان وضع "👆 اشرح عنصراً" مفعلاً، نمنع السلوك الافتراضي ونفتح المحاكاة الحية للشاشة الوليدة أو القائمة
                    if (c4.pickElementMode) {
                        e.preventDefault();
                        e.stopPropagation();
                        e.stopImmediatePropagation();
                        self.explainInteractiveElementNow(el, true);
                        return;
                    }

                    // حتى بدون وضع "اشرح عنصراً"، عند الضغط المباشر على أي خانة أو زر أثناء عمل المرشد ينتقل المرشد فوراً لشرحه مع قاعدته الذهبية!
                    if (self.hoverExplainEnabled) {
                        setTimeout(() => {
                            self.explainInteractiveElementNow(el, false);
                        }, 40);
                    }
                }, true);
            },

            // 6. الاستشعار الحي والتحديث الذاتي للمرشد الذكي عند إضافة أي زر أو خانة مستقبلاً (MutationObserver & Live DOM Scanner — Directive 4)
            resolveDynamicElementInfo(el) {
                if (!el) return null;
                if (this.dynamicElementsMap.has(el)) {
                    return this.dynamicElementsMap.get(el);
                }
                return this.synthesizeDynamicGoldenRule(el);
            },

            synthesizeDynamicGoldenRule(el) {
                if (!el) return null;
                const explicitTitle = el.getAttribute('data-guide-title') || el.getAttribute('aria-label') || el.getAttribute('title') || '';
                const explicitDesc = el.getAttribute('data-guide-desc') || '';
                const explicitRule = el.getAttribute('data-golden-rule') || '';

                let labelText = explicitTitle;
                if (!labelText && el.id) {
                    const lbl = document.querySelector('label[for="' + el.id + '"]');
                    if (lbl) labelText = lbl.textContent;
                }
                if (!labelText) {
                    labelText = el.getAttribute('placeholder') || el.textContent || el.value || 'عنصر تفاعلي في الشاشة';
                }
                labelText = String(labelText).replace(/\s+/g, ' ').trim().slice(0, 68);
                if (!labelText) return null;

                const tag = (el.tagName || '').toUpperCase();
                let desc = explicitDesc;
                let goldenRule = explicitRule;

                if (!desc) {
                    if (tag === 'BUTTON' || el.classList.contains('btn')) {
                        desc = 'زر إجرائي ذكي لتنفيذ أمر (' + labelText + ') مباشرة ضمن دورة عمل شاشة الحركة المالية المجمعة دون مغادرة الصفحة.';
                    } else if (tag === 'SELECT') {
                        desc = 'قائمة اختيار منسدلة لتحديد (' + labelText + ') وضبط تأثيره المحاسبي آلياً في السند.';
                    } else {
                        desc = 'خانة إدخال مخصصة لتسجيل (' + labelText + ') وترحيلها بدقة ضمن القيد المزدوج وتقارير الأستاذ العام.';
                    }
                }

                if (!goldenRule) {
                    if (tag === 'BUTTON' || el.classList.contains('btn')) {
                        goldenRule = 'القاعدة الذهبية: تحقق من اكتمال بيانات السطر قبل تنفيذ (' + labelText + ') لضمان دقة الترحيل 100%.';
                    } else if (tag === 'SELECT') {
                        goldenRule = 'القاعدة الذهبية: اختر الخيار المطابق لطبيعة المستند من قائمة (' + labelText + ') لتوجيه القيد للتقرير الصحيح.';
                    } else {
                        goldenRule = 'القاعدة الذهبية: دوّن (' + labelText + ') بدقة ووضوح ليظهر بشكل سليم في كشوف الحسابات والطباعة.';
                    }
                }

                const info = {
                    title: '✨ ' + labelText,
                    desc: desc,
                    goldenRule: goldenRule,
                    simType: tag === 'SELECT' ? 'select-preview' : null
                };
                this.dynamicElementsMap.set(el, info);
                return info;
            },

            scanAndRegisterNewDomElements(rootNode) {
                const self = this;
                const root = (rootNode && rootNode.querySelectorAll) ? rootNode : document;
                const c4 = window.McpDesktopConstitution4;
                const selectEl = document.getElementById('mcpC4StageJumpSelect');

                const candidates = root.querySelectorAll('button, input:not([type="hidden"]), select, textarea, [data-guide-title]');
                candidates.forEach(el => {
                    if (el.closest('#mcpC4SmartGuideMicroHud') || el.closest('#msg-universal-fixed-launcher')) return;
                    if (!self.dynamicElementsMap.has(el)) {
                        self.synthesizeDynamicGoldenRule(el);
                    }

                    // إذا أُضيف زر أو عنصر جديد يحمل data-guide-title أو data-auto-guide-step، يُدرج تلقائياً في خطوات المرشد وقائمة القفز!
                    const customGuideTitle = el.getAttribute('data-guide-title');
                    if (customGuideTitle && c4 && Array.isArray(c4.steps)) {
                        const selKey = el.id ? ('#' + el.id) : ('[data-guide-title="' + customGuideTitle.replace(/"/g, '\\"') + '"]');
                        if (!self.dynamicRegisteredSelectors.has(selKey)) {
                            self.dynamicRegisteredSelectors.add(selKey);
                            const info = self.synthesizeDynamicGoldenRule(el);
                            const newStepIdx = c4.steps.length;
                            c4.steps.push({
                                id: 'dyn-step-' + newStepIdx,
                                title: (newStepIdx + 1) + '️⃣ ' + info.title,
                                svgStage: 'process',
                                showMap: false,
                                selector: selKey,
                                goldenRule: info.goldenRule,
                                action: () => {
                                    if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups(el);
                                    if (el.tagName === 'SELECT') window.showLiveSelectOptionsMirror(el, null, info.title);
                                },
                                text: info.title + '. ' + info.desc + ' ' + info.goldenRule
                            });
                            if (selectEl) {
                                const opt = document.createElement('option');
                                opt.value = String(newStepIdx);
                                opt.textContent = (newStepIdx + 1) + '️⃣ ' + info.title;
                                selectEl.appendChild(opt);
                            }
                            const counterEl = document.getElementById('mcpC4StepCounterBadge');
                            if (counterEl) {
                                counterEl.textContent = (c4.currentStepIndex + 1) + ' / ' + c4.steps.length;
                            }
                        }
                    }
                });
            },

            initSelfUpdatingMutationObserver() {
                const self = this;
                this.scanAndRegisterNewDomElements(document);
                if (typeof MutationObserver === 'undefined' || !document.body) return;

                let scanTimer = null;
                this.mutationObserver = new MutationObserver((mutations) => {
                    let hasNewNodes = false;
                    for (const m of mutations) {
                        if (m.addedNodes && m.addedNodes.length > 0) {
                            hasNewNodes = true;
                            break;
                        }
                    }
                    if (!hasNewNodes) return;
                    clearTimeout(scanTimer);
                    scanTimer = setTimeout(() => {
                        self.scanAndRegisterNewDomElements(document);
                        self.enforceRolePermissionsAndFilterGuide();
                    }, 120);
                });

                this.mutationObserver.observe(document.body, {
                    childList: true,
                    subtree: true
                });
            },

            // 7. التكيّف الذكي للشاشة والكيرسر والمرشد مع صلاحيات المستخدم (Role-Aware UI, Cursor & Guide — Directive 5)
            getCurrentUserPermissions() {
                let perms = {};
                let role = 'admin';
                try {
                    const u = JSON.parse(localStorage.getItem('erp_currentUser') || localStorage.getItem('user') || '{}');
                    if (u && u.role) role = String(u.role).toLowerCase();
                    if (u && u.permissions && typeof u.permissions === 'object') {
                        perms = Object.assign({}, perms, u.permissions);
                    }
                } catch (e) {}
                try {
                    const storedPerms = JSON.parse(localStorage.getItem('erp_user_permissions') || '{}');
                    if (storedPerms && typeof storedPerms === 'object') {
                        perms = Object.assign({}, perms, storedPerms);
                    }
                } catch (e) {}
                if (window.MagaieesPermissions && typeof window.MagaieesPermissions === 'object') {
                    perms = Object.assign({}, perms, window.MagaieesPermissions);
                }
                return { role, perms };
            },

            isElementPermittedForCurrentUser(el) {
                if (!el) return false;
                if (el.getAttribute('data-mcp-role-hidden') === '1' || el.getAttribute('data-role-hidden') === 'true') {
                    return false;
                }
                if (el.classList.contains('restricted-by-role') || el.classList.contains('permission-locked')) {
                    return false;
                }

                const reqPerm = el.getAttribute('data-required-permission') || el.getAttribute('data-permission');
                if (reqPerm) {
                    const { role, perms } = this.getCurrentUserPermissions();
                    if (perms[reqPerm] === false || perms[reqPerm] === 0 || perms[reqPerm] === '0') {
                        return false;
                    }
                    if (role !== 'admin' && role !== 'superadmin' && Object.keys(perms).length > 0 && !(reqPerm in perms)) {
                        return false;
                    }
                }
                return true;
            },

            isStepPermitted(step) {
                if (!step || !step.selector) return true;
                const parts = String(step.selector).split(',').map(s => s.trim()).filter(Boolean);
                let foundAnyInDom = false;
                for (const sel of parts) {
                    try {
                        const el = document.querySelector(sel);
                        if (el) {
                            foundAnyInDom = true;
                            if (this.isElementPermittedForCurrentUser(el)) {
                                return true;
                            }
                        }
                    } catch (e) {}
                }
                return !foundAnyInDom ? true : false;
            },

            enforceRolePermissionsAndFilterGuide() {
                const self = this;
                // 1. فحص أي عناصر مقيدة بالصلاحيات وإخفاؤها وقفلها برمجياً وتخطيها بالكيرسر (tabIndex = -1)
                document.querySelectorAll('[data-required-permission], [data-permission], .restricted-by-role, .permission-locked, [data-role-hidden="true"]').forEach(el => {
                    if (!self.isElementPermittedForCurrentUser(el)) {
                        el.setAttribute('data-mcp-role-hidden', '1');
                        el.setAttribute('aria-hidden', 'true');
                        el.tabIndex = -1;
                        if ('disabled' in el) el.disabled = true;
                    } else {
                        el.removeAttribute('data-mcp-role-hidden');
                        el.removeAttribute('aria-hidden');
                    }
                });

                // 2. تحديث قائمة خطوات المرشد الذكي لإخفاء أي خطوة تخص عنصراً خارج صلاحيات المستخدم الحالي
                const c4 = window.McpDesktopConstitution4;
                const selectEl = document.getElementById('mcpC4StageJumpSelect');
                if (c4 && selectEl && Array.isArray(c4.steps)) {
                    Array.from(selectEl.options).forEach(opt => {
                        const idx = parseInt(opt.value, 10);
                        const step = c4.steps[idx];
                        const permitted = self.isStepPermitted(step);
                        opt.hidden = !permitted;
                        opt.disabled = !permitted;
                    });
                }
            }
        };

        window.McpDesktopConstitution5 = McpDesktopConstitution5;
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => McpDesktopConstitution5.init());
        } else {
            McpDesktopConstitution5.init();
        }
    })();
    </script>

    <!-- ══════════════════════════════════════════════════════════════════════════════ -->
    <!-- الدستور السادس (Constitution 6 of 14): دستور التزامن الصاروخي في كسر من الثانية (جوال ↔ لابتوب ↔ أوفلاين)، منع التضارب (CRDT)، الحارس الفولاذي ضد انطفاء الجهاز (IndexedDB)، الذرية المحاسبية 100%، وثبات السرعة مع 100 ألف سجل -->
    <!-- ══════════════════════════════════════════════════════════════════════════════ -->
    <style id="mcp-constitution-6-flash-sync-crdt-styles">
        /* 1. كبسولة التزامن الصاروخي بالمللي ثانية ومنع التضارب (CRDT Flash Sync Capsule — World-Class Addition 1) */
        #mcpC6FlashSyncBadge {
            display: inline-flex;
            align-items: center;
            gap: 6px;
            height: 36px;
            padding: 0 11px;
            border-radius: 999px;
            font-size: 0.76rem;
            font-weight: 900;
            cursor: pointer;
            user-select: none;
            white-space: nowrap;
            border: 2px solid #10b981 !important;
            background: rgba(6, 78, 59, 0.45) !important;
            color: #ffffff !important;
            box-shadow: 0 4px 12px rgba(16, 185, 129, 0.25);
            transition: transform 0.14s ease, border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
        }
        html.light-theme #mcpC6FlashSyncBadge {
            background: #ecfdf5 !important;
            color: #000000 !important;
            border: 2px solid #059669 !important;
            box-shadow: 0 3px 10px rgba(5, 150, 105, 0.16);
        }
        #mcpC6FlashSyncBadge:hover {
            transform: translateY(-1px) scale(1.02);
            box-shadow: 0 0 14px rgba(16, 185, 129, 0.55);
        }
        #mcpC6FlashSyncBadge[data-sync-state="syncing"] {
            border-color: #38bdf8 !important;
            background: rgba(3, 105, 161, 0.48) !important;
            color: #ffffff !important;
        }
        html.light-theme #mcpC6FlashSyncBadge[data-sync-state="syncing"] {
            background: #e0f2fe !important;
            color: #000000 !important;
            border-color: #0284c7 !important;
        }
        #mcpC6FlashSyncBadge[data-sync-state="offline"] {
            border-color: #f59e0b !important;
            background: rgba(120, 53, 15, 0.52) !important;
            color: #ffffff !important;
        }
        html.light-theme #mcpC6FlashSyncBadge[data-sync-state="offline"] {
            background: #fffbeb !important;
            color: #000000 !important;
            border-color: #d97706 !important;
        }
        #mcpC6FlashSyncDot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: #10b981;
            box-shadow: 0 0 8px #10b981;
            flex-shrink: 0;
        }
        #mcpC6FlashSyncBadge[data-sync-state="syncing"] #mcpC6FlashSyncDot {
            background: #38bdf8;
            box-shadow: 0 0 10px #38bdf8;
        }
        #mcpC6FlashSyncBadge[data-sync-state="offline"] #mcpC6FlashSyncDot {
            background: #f59e0b;
            box-shadow: 0 0 10px #f59e0b;
        }

        /* 2. شريط الحارس الفولاذي لاستعادة المسودة بعد انقطاع الكهرباء أو نفاد البطارية (Persistent Crash Guard — Directive 4) */
        #mcpC6CrashRestoreBar {
            position: fixed;
            bottom: 68px;
            right: 16px;
            z-index: 2147483638;
            display: none;
            align-items: center;
            gap: 9px;
            flex-wrap: wrap;
            padding: 9px 14px;
            border-radius: 14px;
            border: 2.3px solid #f59e0b !important;
            background: rgba(15, 23, 42, 0.97) !important;
            color: #ffffff !important;
            font-family: var(--mcp-font-sans, 'Tajawal', 'Cairo', sans-serif) !important;
            font-size: 0.82rem !important;
            font-weight: 900 !important;
            box-shadow: 0 14px 34px rgba(0, 0, 0, 0.65), 0 0 18px rgba(245, 158, 11, 0.35) !important;
            direction: rtl;
        }
        html.light-theme #mcpC6CrashRestoreBar {
            background: #fffbeb !important;
            color: #000000 !important;
            border: 2.3px solid #d97706 !important;
            box-shadow: 0 12px 28px rgba(15, 23, 42, 0.22) !important;
        }
        #mcpC6CrashRestoreBar.mcp-c6-visible {
            display: inline-flex !important;
        }
        #mcpC6CrashRestoreBar .mcp-c6-restore-btn {
            padding: 4px 11px;
            border-radius: 8px;
            border: 2px solid #10b981 !important;
            background: #059669 !important;
            color: #ffffff !important;
            font-weight: 900;
            font-size: 0.78rem;
            cursor: pointer;
        }
        #mcpC6CrashRestoreBar .mcp-c6-dismiss-btn {
            padding: 4px 9px;
            border-radius: 8px;
            border: 1.8px solid #64748b !important;
            background: transparent !important;
            color: inherit !important;
            font-weight: 800;
            font-size: 0.76rem;
            cursor: pointer;
        }

        @media print {
            #mcpC6FlashSyncBadge,
            #mcpC6CrashRestoreBar {
                display: none !important;
            }
        }
    </style>

    <script id="mcp-constitution-6-flash-sync-crdt-engine">
    (function () {
        'use strict';
        if (window.McpDesktopConstitution6) return;

        const McpDesktopConstitution6 = {
            initialized: false,
            deviceNodeId: '',
            hlcCounter: 0,
            lastHlcWallMs: 0,
            lastServerDigest: '',
            syncInFlight: false,
            syncTimer: null,
            broadcastChannel: null,
            idbPromise: null,
            IDB_NAME: 'McpErpCrashGuardDB_v6',
            IDB_VERSION: 1,
            CRDT_QUEUE_KEY: 'mcp_c6_crdt_nano_queue_v1',
            CRASH_DRAFT_KEY: 'mcp_c6_crash_guard_draft_v1',
            DEVICE_NODE_KEY: 'mcp_c6_device_node_id_v1',
            VIRTUAL_WINDOW_SIZE: 45,
            accountHashIndex: new Map(),
            voucherHashIndex: new Map(),
            lastIndexedAccountCount: -1,
            lastIndexedVoucherCount: -1,

            init() {
                if (this.initialized) return;
                this.initialized = true;

                this.initDeviceNodeId();
                this.initIndexedDBVault();
                this.injectFlashSyncHudBadge();
                this.bridgeMicroSyncEngineToCrdt();
                this.initBroadcastAndNetworkListeners();
                this.initCrashGuardKeystrokeMirror();
                this.init100kVirtualScrollerAndIndex();
                this.initAtomicDoubleEntryGuard();
                this.registerWithSmartGuide();

                // استعادة المسودة المحمية في حال انطفاء الجهاز المفاجئ بسبب الكهرباء أو البطارية
                setTimeout(() => this.checkAndRestoreCrashDraft(), 200);
                // إطلاق أول نبضة تزامن صاروخي بالمللي ثانية فور فتح الشاشة
                setTimeout(() => this.triggerFlashDeltaSync('boot'), 380);
            },

            // 1. توليد هوية عقدة الجهاز + ساعة منطقية هجينة (HLC) + UUIDv4 لمنع تضارب الأوفلاين (CRDT — Directive 2)
            initDeviceNodeId() {
                try {
                    let saved = localStorage.getItem(this.DEVICE_NODE_KEY);
                    if (!saved) {
                        const isMob = /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent || '');
                        saved = (isMob ? 'MOB_' : 'LAP_') + Math.random().toString(36).substring(2, 8).toUpperCase();
                        localStorage.setItem(this.DEVICE_NODE_KEY, saved);
                    }
                    this.deviceNodeId = saved;
                } catch (_) {
                    this.deviceNodeId = 'NODE_' + Math.floor(Math.random() * 99999);
                }
            },

            generateUUIDv4() {
                if (window.crypto && typeof window.crypto.randomUUID === 'function') {
                    return window.crypto.randomUUID();
                }
                return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
                    const r = (Math.random() * 16) | 0;
                    const v = c === 'x' ? r : (r & 0x3) | 0x8;
                    return v.toString(16);
                });
            },

            nextHlcTimestamp() {
                const now = Date.now();
                if (now > this.lastHlcWallMs) {
                    this.lastHlcWallMs = now;
                    this.hlcCounter = 0;
                } else {
                    this.hlcCounter += 1;
                }
                const padCounter = String(this.hlcCounter).padStart(4, '0');
                return this.lastHlcWallMs + '-' + padCounter + '-' + this.deviceNodeId;
            },

            // 2. الحارس الفولاذي ضد انقطاع الكهرباء والبطارية (IndexedDB + LocalStorage Dual Vault — Directive 4)
            initIndexedDBVault() {
                if (!window.indexedDB) return Promise.resolve(null);
                if (this.idbPromise) return this.idbPromise;
                this.idbPromise = new Promise((resolve) => {
                    try {
                        const req = window.indexedDB.open(this.IDB_NAME, this.IDB_VERSION);
                        req.onupgradeneeded = (ev) => {
                            const db = ev.target.result;
                            if (!db.objectStoreNames.contains('crashGuardStore')) {
                                db.createObjectStore('crashGuardStore', { keyPath: 'key' });
                            }
                            if (!db.objectStoreNames.contains('crdtOfflineQueue')) {
                                db.createObjectStore('crdtOfflineQueue', { keyPath: 'idempotencyKey' });
                            }
                        };
                        req.onsuccess = (ev) => resolve(ev.target.result);
                        req.onerror = () => resolve(null);
                    } catch (_) {
                        resolve(null);
                    }
                });
                return this.idbPromise;
            },

            async saveToIdbStore(storeName, obj) {
                try {
                    const db = await this.initIndexedDBVault();
                    if (!db) return false;
                    return new Promise((resolve) => {
                        try {
                            const tx = db.transaction([storeName], 'readwrite');
                            tx.objectStore(storeName).put(obj);
                            tx.oncomplete = () => resolve(true);
                            tx.onerror = () => resolve(false);
                        } catch (_) {
                            resolve(false);
                        }
                    });
                } catch (_) {
                    return false;
                }
            },

            async readFromIdbStore(storeName, key) {
                try {
                    const db = await this.initIndexedDBVault();
                    if (!db) return null;
                    return new Promise((resolve) => {
                        try {
                            const tx = db.transaction([storeName], 'readonly');
                            const req = tx.objectStore(storeName).get(key);
                            req.onsuccess = () => resolve(req.result || null);
                            req.onerror = () => resolve(null);
                        } catch (_) {
                            resolve(null);
                        }
                    });
                } catch (_) {
                    return null;
                }
            },

            captureFullBatchDraftSnapshot() {
                try {
                    const type = document.getElementById('voucher-type')?.value || 'payment';
                    const vDate = document.getElementById('voucher-date')?.value || '';
                    const vRef = document.getElementById('voucher-ref')?.value || '';
                    const mainAcc = document.getElementById('main-account')?.getAttribute('data-id') || document.getElementById('main-account')?.value || '';
                    const mainAccName = document.getElementById('main-account-search')?.value.trim() || '';
                    const desc = document.getElementById('voucher-desc')?.value.trim() || '';
                    const currency = document.getElementById('currency')?.value || 'SDG';
                    const exRate = document.getElementById('exchange-rate')?.value || '';

                    const blocksData = [];
                    let hasMeaningfulData = false;
                    const parseAmt = (v) => parseFloat(String(v || '0').replace(/,/g, '')) || 0;

                    document.querySelectorAll('.account-block').forEach(block => {
                        const bid = block.getAttribute('data-block-id');
                        const accName = document.getElementById('account-' + bid + '-search')?.value.trim() || '';
                        const accId = document.getElementById('account-' + bid + '-id')?.value || '';
                        const stmt = document.getElementById('statement-' + bid)?.value.trim() || '';
                        const cc = document.getElementById('cost-center-' + bid)?.value.trim() || '';
                        const ccId = document.getElementById('cost-center-' + bid + '-id')?.value.trim() || '';
                        const cashAmt = parseAmt(block.querySelector('.block-cash-amount')?.value);
                        const cashDesc = block.querySelector('.block-cash-desc-input')?.value.trim() || '';

                        const bankRows = [];
                        block.querySelectorAll('.bank-row').forEach(r => {
                            const bAmt = parseAmt(r.querySelector('.block-bank-amount')?.value);
                            const bName = r.querySelector('.block-bank-name-input')?.value.trim() || '';
                            const bTr = r.querySelector('.block-transfer-no-input')?.value.trim() || '';
                            const bDesc = r.querySelector('.block-bank-desc-input')?.value.trim() || '';
                            if (bAmt > 0 || bName || bTr) bankRows.push({ amount: bAmt, bankName: bName, transferNo: bTr, desc: bDesc });
                        });

                        const chequeRows = [];
                        block.querySelectorAll('.cheque-row').forEach(r => {
                            const cAmt = parseAmt(r.querySelector('.block-cheque-amount')?.value);
                            const cBank = r.querySelector('.block-cheque-bank-input')?.value.trim() || '';
                            const cNo = r.querySelector('.block-cheque-no-input')?.value.trim() || '';
                            const cDate = r.querySelector('.block-cheque-date-input')?.value || '';
                            const cDesc = r.querySelector('.block-cheque-desc-input')?.value.trim() || '';
                            if (cAmt > 0 || cBank || cNo) chequeRows.push({ amount: cAmt, bank: cBank, no: cNo, date: cDate, desc: cDesc });
                        });

                        if (accName || cashAmt > 0 || bankRows.length > 0 || chequeRows.length > 0 || stmt) {
                            hasMeaningfulData = true;
                            blocksData.push({
                                accountName: accName,
                                accountId: accId,
                                statement: stmt,
                                costCenter: cc,
                                costCenterId: ccId,
                                cashAmount: cashAmt,
                                cashDesc: cashDesc,
                                bankRows: bankRows,
                                chequeRows: chequeRows
                            });
                        }
                    });

                    if (!hasMeaningfulData && !desc) return null;

                    const snapshot = {
                        key: 'active_multi_cash_payment_draft',
                        savedAt: Date.now(),
                        updatedAtMs: Date.now(),
                        hlcTimestamp: this.nextHlcTimestamp(),
                        deviceNodeId: this.deviceNodeId,
                        type: type,
                        voucherDate: vDate,
                        voucherRef: vRef,
                        mainAccount: mainAcc,
                        mainAccountName: mainAccName,
                        description: desc,
                        currency: currency,
                        exchangeRate: exRate,
                        blocks: blocksData
                    };

                    localStorage.setItem(this.CRASH_DRAFT_KEY, JSON.stringify(snapshot));
                    const baseDraftKey = (typeof window.getTenantKey === 'function') ? window.getTenantKey('erp_mcp_active_draft_v1') : 'erp_mcp_active_draft_v1';
                    localStorage.setItem(baseDraftKey, JSON.stringify(snapshot));
                    this.saveToIdbStore('crashGuardStore', snapshot);
                    return snapshot;
                } catch (_) {
                    return null;
                }
            },

            initCrashGuardKeystrokeMirror() {
                const self = this;
                let debounceTimer = null;

                const scheduleMirror = () => {
                    clearTimeout(debounceTimer);
                    debounceTimer = setTimeout(() => {
                        self.captureFullBatchDraftSnapshot();
                    }, 320);
                };

                document.addEventListener('input', (e) => {
                    if (!e.target || e.target.closest('#mcpC4SmartGuideMicroHud')) return;
                    scheduleMirror();
                }, { capture: true, passive: true });

                document.addEventListener('change', (e) => {
                    if (!e.target || e.target.closest('#mcpC4SmartGuideMicroHud')) return;
                    scheduleMirror();
                }, true);

                window.addEventListener('pagehide', () => {
                    self.captureFullBatchDraftSnapshot();
                    self.flushBeaconOnUnload();
                });

                const btnSave = document.getElementById('btn-save');
                const btnNew = document.querySelector('.btn-new');
                if (btnSave) {
                    btnSave.addEventListener('click', () => {
                        setTimeout(() => {
                            const hdrAmt = parseFloat(String(document.getElementById('amount-local-hdr')?.value || '0').replace(/,/g, '')) || 0;
                            if (hdrAmt === 0 || (typeof formDirty !== 'undefined' && !formDirty)) {
                                self.clearCrashDraft();
                            }
                        }, 450);
                    });
                }
                if (btnNew) {
                    btnNew.addEventListener('click', () => self.clearCrashDraft());
                }
            },

            clearCrashDraft() {
                try {
                    localStorage.removeItem(this.CRASH_DRAFT_KEY);
                    this.saveToIdbStore('crashGuardStore', {
                        key: 'active_multi_cash_payment_draft',
                        cleared: true,
                        updatedAtMs: Date.now()
                    });
                    const bar = document.getElementById('mcpC6CrashRestoreBar');
                    if (bar) bar.classList.remove('mcp-c6-visible');
                } catch (_) {}
            },

            async checkAndRestoreCrashDraft() {
                try {
                    let snap = null;
                    const rawLs = localStorage.getItem(this.CRASH_DRAFT_KEY);
                    if (rawLs) {
                        try { snap = JSON.parse(rawLs); } catch (_) {}
                    }
                    if (!snap || snap.cleared || !Array.isArray(snap.blocks) || snap.blocks.length === 0) {
                        const idbSnap = await this.readFromIdbStore('crashGuardStore', 'active_multi_cash_payment_draft');
                        if (idbSnap && !idbSnap.cleared && Array.isArray(idbSnap.blocks) && idbSnap.blocks.length > 0) {
                            snap = idbSnap;
                        }
                    }
                    if (!snap || snap.cleared || !Array.isArray(snap.blocks) || snap.blocks.length === 0) return;

                    if (Date.now() - (snap.updatedAtMs || snap.savedAt || 0) > 86400000) {
                        this.clearCrashDraft();
                        return;
                    }

                    // مزامنة المسودة المستردة من IndexedDB مع محرك المسودة المحلي لضمان عمل زر الاسترجاع
                    const baseDraftKey = (typeof window.getTenantKey === 'function') ? window.getTenantKey('erp_mcp_active_draft_v1') : 'erp_mcp_active_draft_v1';
                    localStorage.setItem(baseDraftKey, JSON.stringify(snap));
                    const topRestoreBtn = document.getElementById('btn-mcp-draft-restore');
                    if (topRestoreBtn) {
                        topRestoreBtn.style.display = 'inline-flex';
                        topRestoreBtn.title = 'استرجاع مسودة محمية ضد الانقطاع (' + snap.blocks.length + ' حساب)';
                    }

                    const currentHdrAmt = parseFloat(String(document.getElementById('amount-local-hdr')?.value || '0').replace(/,/g, '')) || 0;
                    if (currentHdrAmt > 0) return;

                    this.showCrashRestoreBanner(snap);
                } catch (_) {}
            },

            showCrashRestoreBanner(snap) {
                let bar = document.getElementById('mcpC6CrashRestoreBar');
                if (!bar) {
                    bar = document.createElement('div');
                    bar.id = 'mcpC6CrashRestoreBar';
                    bar.setAttribute('data-guide-title', '🛡️ شريط الحارس الفولاذي ضد انطفاء الجهاز المفاجئ');
                    bar.setAttribute('data-golden-rule', 'القاعدة الذهبية: اضغط (استعادة فورية ⚡) لاسترجاع كافة كتل ومبالغ السند المجمع المحفوظة في خزنة IndexedDB.');
                    bar.innerHTML = '<span>🛡️ الحارس الفولاذي: وُجدت مسودة سند مجمع غير محفوظة (' + (snap.blocks ? snap.blocks.length : 1) + ' حساب) قبل انقطاع الجلسة</span>' +
                        '<button type="button" class="mcp-c6-restore-btn" id="mcpC6RestoreDraftNowBtn">استعادة فورية ⚡</button>' +
                        '<button type="button" class="mcp-c6-dismiss-btn" id="mcpC6DismissDraftBtn">تجاهل</button>';
                    document.body.appendChild(bar);
                }
                bar.classList.add('mcp-c6-visible');

                const restoreBtn = document.getElementById('mcpC6RestoreDraftNowBtn');
                const dismissBtn = document.getElementById('mcpC6DismissDraftBtn');
                if (restoreBtn) {
                    restoreBtn.onclick = () => {
                        try {
                            if (window.McpAutoDraftEngine && typeof window.McpAutoDraftEngine.restore === 'function') {
                                window.McpAutoDraftEngine.restore();
                            }
                            if (snap.voucherDate && document.getElementById('voucher-date')) {
                                document.getElementById('voucher-date').value = snap.voucherDate;
                            }
                            if (snap.voucherRef && document.getElementById('voucher-ref')) {
                                document.getElementById('voucher-ref').value = snap.voucherRef;
                            }
                            bar.classList.remove('mcp-c6-visible');
                            if (typeof window.showToast === 'function') {
                                window.showToast('🛡️ تم استعادة مسودة السند المجمع بالكامل عبر الحارس الفولاذي (IndexedDB)!', 'success');
                            }
                        } catch (_) {}
                    };
                }
                if (dismissBtn) {
                    dismissBtn.onclick = () => this.clearCrashDraft();
                }
            },

            // 3. اقتناص شرارة الإنترنت في كسر من الثانية والتزامن اللحظي (جوال ↔ لابتوب ↔ أوفلاين) + منع التضارب (CRDT — Directives 1 & 2)
            injectFlashSyncHudBadge() {
                if (document.getElementById('mcpC6FlashSyncBadge')) return;
                const badge2g = document.getElementById('mcp-2g-resilience-badge');
                const topRow = document.getElementById('payment-methods-row') || document.body;

                const badge = document.createElement('div');
                badge.id = 'mcpC6FlashSyncBadge';
                badge.setAttribute('data-sync-state', navigator.onLine ? 'online' : 'offline');
                badge.setAttribute('data-guide-title', '⚡ كبسولة التزامن الصاروخي بالمللي ثانية ومنع التضارب (CRDT: جوال ↔ لابتوب ↔ أوفلاين)');
                badge.setAttribute('data-golden-rule', 'القاعدة الذهبية: اعمل في الجوال أو اللابتوب حتى بدون إنترنت؛ فبمجرد لمس الشبكة لكسر من الثانية تندمج حركات الجهازين معاً بدقة 100%.');
                badge.setAttribute('title', 'التزامن الصاروخي في كسر من الثانية (جوال ↔ لابتوب ↔ أوفلاين) بنظام CRDT — اضغط للمزامنة الفورية الآن');
                badge.innerHTML = '<span id="mcpC6FlashSyncDot"></span>' +
                    '<span id="mcpC6FlashSyncText">' + (navigator.onLine ? 'تزامن صاروخي CRDT ⚡' : 'أوفلاين محمي 🛡️') + '</span>';

                badge.addEventListener('click', () => {
                    this.triggerFlashDeltaSync('manual_click', true);
                });

                if (badge2g && badge2g.parentElement) {
                    badge2g.insertAdjacentElement('afterend', badge);
                } else if (topRow && topRow !== document.body) {
                    topRow.appendChild(badge);
                }
            },

            updateFlashSyncBadge(state, labelText) {
                const badge = document.getElementById('mcpC6FlashSyncBadge');
                const txt = document.getElementById('mcpC6FlashSyncText');
                if (!badge || !txt) return;
                badge.setAttribute('data-sync-state', state);
                const q = this.getCrdtOfflineQueue();
                if (q.length > 0 && state === 'offline') {
                    txt.textContent = 'أوفلاين محمي (' + q.length + ') 🛡️';
                } else {
                    txt.textContent = labelText || (state === 'online' ? 'تزامن صاروخي CRDT ⚡' : state === 'syncing' ? 'نبض صاروخي...' : 'أوفلاين محمي 🛡️');
                }
            },

            getCrdtOfflineQueue() {
                try {
                    const raw = localStorage.getItem(this.CRDT_QUEUE_KEY);
                    const parsed = raw ? JSON.parse(raw) : [];
                    return Array.isArray(parsed) ? parsed : [];
                } catch (_) {
                    return [];
                }
            },

            saveCrdtOfflineQueue(queue) {
                try {
                    const clean = Array.isArray(queue) ? queue : [];
                    localStorage.setItem(this.CRDT_QUEUE_KEY, JSON.stringify(clean));
                    clean.forEach((item) => {
                        if (item && item.idempotencyKey) {
                            this.saveToIdbStore('crdtOfflineQueue', item);
                        }
                    });
                } catch (_) {}
            },

            bridgeMicroSyncEngineToCrdt() {
                const self = this;
                if (window.McpMicroSyncEngine && !window.McpMicroSyncEngine.__mcpC6Bridged) {
                    const origEnqueue = window.McpMicroSyncEngine.enqueue;
                    window.McpMicroSyncEngine.enqueue = function (voucher) {
                        if (typeof origEnqueue === 'function') {
                            try { origEnqueue.apply(this, arguments); } catch (_) {}
                        }
                        self.enqueueCrdtNanoPacket(voucher, 'UPSERT');
                    };
                    window.McpMicroSyncEngine.__mcpC6Bridged = true;
                }
            },

            enqueueCrdtNanoPacket(voucherRecord, operation = 'UPSERT') {
                if (!voucherRecord || typeof voucherRecord !== 'object') return;
                const vId = String(voucherRecord.voucherNo || voucherRecord.id || '').trim();
                if (!vId) return;

                const hlc = this.nextHlcTimestamp();
                const nowMs = Date.now();
                const idemKey = voucherRecord.idempotencyKey || ('crdt_mcp_' + vId + '_' + this.deviceNodeId);

                voucherRecord.id = vId;
                voucherRecord.voucherNo = vId;
                voucherRecord.isGrouped = true;
                voucherRecord.idempotencyKey = idemKey;
                voucherRecord.hlcTimestamp = hlc;
                voucherRecord.updatedAtMs = nowMs;
                voucherRecord.originNodeId = this.deviceNodeId;

                const queue = this.getCrdtOfflineQueue();
                const existingIdx = queue.findIndex((q) => q && (q.id === vId || q.idempotencyKey === idemKey));
                const nanoPacket = {
                    id: vId,
                    voucherNo: vId,
                    type: voucherRecord.type || 'payment',
                    idempotencyKey: idemKey,
                    hlcTimestamp: hlc,
                    updatedAtMs: nowMs,
                    originNodeId: this.deviceNodeId,
                    operation: operation,
                    record: Object.assign({}, voucherRecord)
                };

                if (existingIdx >= 0) {
                    nanoPacket.record = Object.assign({}, queue[existingIdx].record || {}, voucherRecord);
                    queue[existingIdx] = nanoPacket;
                } else {
                    queue.push(nanoPacket);
                }

                this.saveCrdtOfflineQueue(queue);
                this.broadcastCrossTabCrdt(nanoPacket);

                if (navigator.onLine) {
                    this.triggerFlashDeltaSync('crdt_enqueue');
                } else {
                    this.updateFlashSyncBadge('offline');
                }
            },

            // دمج سندات الصرف والقبض المجمعة ذرياً بدون تضارب (Zero-Conflict CRDT Merge — Directive 2)
            mergeCrdtBatchVouchersAndBalances(remotePayments, remoteReceipts) {
                let totalAdded = 0;
                let totalUpdated = 0;

                const mergeSingleTable = (remoteList, baseStorageKey, serverGlobalProp) => {
                    if (!Array.isArray(remoteList) || remoteList.length === 0) return;
                    const tenantKey = (typeof window.getTenantKey === 'function') ? window.getTenantKey(baseStorageKey) : baseStorageKey;
                    let localList = [];
                    try {
                        localList = JSON.parse(localStorage.getItem(tenantKey) || localStorage.getItem(baseStorageKey) || '[]');
                        if (!Array.isArray(localList)) localList = [];
                    } catch (_) {
                        localList = [];
                    }

                    const byId = new Map();
                    localList.forEach((item) => {
                        const k = String(item?.voucherNo || item?.id || '').trim();
                        if (k) byId.set(k, item);
                    });

                    let tableChanged = false;
                    remoteList.forEach((rem) => {
                        if (!rem || typeof rem !== 'object') return;
                        const idKey = String(rem.voucherNo || rem.id || '').trim();
                        if (!idKey) return;
                        const loc = byId.get(idKey);
                        if (!loc) {
                            byId.set(idKey, rem);
                            localList.push(rem);
                            totalAdded++;
                            tableChanged = true;
                        } else {
                            const remTs = Number(rem.updatedAtMs || 0);
                            const locTs = Number(loc.updatedAtMs || 0);
                            const remHlc = String(rem.hlcTimestamp || '');
                            const locHlc = String(loc.hlcTimestamp || '');
                            const remAmt = Number(rem.totalAmount || rem.amountLocal || 0);
                            const locAmt = Number(loc.totalAmount || loc.amountLocal || 0);

                            if (remTs > locTs || (remTs === locTs && remHlc > locHlc) || (remTs === 0 && remAmt !== locAmt)) {
                                const merged = Object.assign({}, loc, rem);
                                const idx = localList.findIndex((x) => String(x?.voucherNo || x?.id || '').trim() === idKey);
                                if (idx >= 0) localList[idx] = merged;
                                byId.set(idKey, merged);
                                totalUpdated++;
                                tableChanged = true;
                            }
                        }
                    });

                    if (tableChanged) {
                        try {
                            const jsonStr = JSON.stringify(localList);
                            localStorage.setItem(baseStorageKey, jsonStr);
                            if (tenantKey !== baseStorageKey) {
                                localStorage.setItem(tenantKey, jsonStr);
                            }
                            window[serverGlobalProp] = localList;
                        } catch (_) {}
                    }
                };

                mergeSingleTable(remotePayments, 'erp_payments_v1', 'SERVER_PAYMENTS');
                mergeSingleTable(remoteReceipts, 'erp_receipts_v1', 'SERVER_RECEIPTS');

                if (totalAdded > 0 || totalUpdated > 0) {
                    try {
                        if (typeof window.rebuildGLFromAllTables === 'function') {
                            window.rebuildGLFromAllTables(false);
                        }
                        if (typeof window.updateAllLiveBalances === 'function') {
                            window.updateAllLiveBalances();
                        }
                        this.rebuild100kHashIndex(true);
                    } catch (_) {}
                }

                return { added: totalAdded, updated: totalUpdated };
            },

            async triggerFlashDeltaSync(reason = 'auto', showToastOnManual = false) {
                if (!navigator.onLine) {
                    this.updateFlashSyncBadge('offline');
                    if (showToastOnManual && typeof window.showToast === 'function') {
                        window.showToast('🛡️ الجهاز يعمل في وضع الأوفلاين الفولاذي؛ جميع الحركات المجمعة محفوظة في خزنة IndexedDB وستندفع في أول كسر من الثانية لتوفر الإنترنت.', 'info');
                    }
                    return;
                }
                if (this.syncInFlight) return;
                this.syncInFlight = true;
                this.updateFlashSyncBadge('syncing', 'نبض صاروخي...');

                const queue = this.getCrdtOfflineQueue();
                const payload = {
                    deviceNodeId: this.deviceNodeId,
                    hlcTimestamp: this.nextHlcTimestamp(),
                    clientDigest: this.lastServerDigest,
                    reason: reason,
                    crdtQueue: queue
                };

                try {
                    const resp = await fetch('multi-cash-payment.php?api=flash_delta_sync', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(payload),
                        keepalive: true,
                        cache: 'no-store'
                    });

                    if (resp.ok) {
                        const data = await resp.json();
                        if (data && data.success) {
                            if (Array.isArray(data.pushedIds) && data.pushedIds.length > 0) {
                                const pushedSet = new Set(data.pushedIds.map(String));
                                const remaining = this.getCrdtOfflineQueue().filter((q) => !pushedSet.has(String(q.voucherNo || q.id)));
                                this.saveCrdtOfflineQueue(remaining);
                            }

                            if (data.digest) {
                                this.lastServerDigest = data.digest;
                            }

                            let mergeStats = { added: 0, updated: 0 };
                            if (data.hasChanges) {
                                mergeStats = this.mergeCrdtBatchVouchersAndBalances(data.payments || [], data.receipts || []);
                            }

                            this.updateFlashSyncBadge('online', 'تزامن صاروخي CRDT ⚡');
                            if (showToastOnManual && typeof window.showToast === 'function') {
                                const msg = (mergeStats.added || mergeStats.updated)
                                    ? '⚡ اكتمل التزامن الصاروخي: تم دمج (' + mergeStats.added + ' جديد / ' + mergeStats.updated + ' محدث) بين الجوال واللابتوب في كسر من الثانية!'
                                    : '⚡ التزامن الصاروخي (CRDT) مكتمل 100% بين الجوال واللابتوب والقاعدة السحابية!';
                                window.showToast(msg, 'success');
                            }
                        } else {
                            this.updateFlashSyncBadge('online', 'تزامن صاروخي CRDT ⚡');
                        }
                    } else {
                        this.updateFlashSyncBadge(navigator.onLine ? 'online' : 'offline');
                    }
                } catch (_) {
                    this.updateFlashSyncBadge(navigator.onLine ? 'online' : 'offline');
                } finally {
                    this.syncInFlight = false;
                }
            },

            broadcastCrossTabCrdt(packet) {
                try {
                    if (this.broadcastChannel) {
                        this.broadcastChannel.postMessage({ type: 'MCP_C6_CRDT_DELTA', packet: packet });
                    }
                } catch (_) {}
            },

            initBroadcastAndNetworkListeners() {
                const self = this;
                // 1. قناة التزامن الفوري بين التبويبات والنوافذ المفتوحة (0ms BroadcastChannel)
                try {
                    if (typeof BroadcastChannel !== 'undefined') {
                        this.broadcastChannel = new BroadcastChannel('mcp_erp_crdt_sync_v6');
                        this.broadcastChannel.onmessage = (ev) => {
                            if (ev && ev.data && ev.data.type === 'MCP_C6_CRDT_DELTA' && ev.data.packet && ev.data.packet.record) {
                                const rec = ev.data.packet.record;
                                if (rec.type === 'receipt') {
                                    self.mergeCrdtBatchVouchersAndBalances([], [rec]);
                                } else {
                                    self.mergeCrdtBatchVouchersAndBalances([rec], []);
                                }
                            }
                        };
                    }
                } catch (_) {}

                // 2. اقتناص شرارة الإنترنت في أول مللي ثانية (Spark-of-Internet Listener — Directive 1)
                window.addEventListener('online', () => {
                    self.updateFlashSyncBadge('syncing', 'اقتناص الشبكة ⚡');
                    self.triggerFlashDeltaSync('spark_online');
                    if (window.McpMicroSyncEngine && typeof window.McpMicroSyncEngine.flushNow === 'function') {
                        try { window.McpMicroSyncEngine.flushNow(); } catch (_) {}
                    }
                });

                window.addEventListener('offline', () => {
                    self.updateFlashSyncBadge('offline');
                });

                if (navigator.connection && typeof navigator.connection.addEventListener === 'function') {
                    navigator.connection.addEventListener('change', () => {
                        if (navigator.onLine) {
                            self.triggerFlashDeltaSync('connection_change');
                        }
                    });
                }

                // 3. المزامنة الفورية عند عودة التركيز للشاشة أو التبديل بين الجوال واللابتوب
                document.addEventListener('visibilitychange', () => {
                    if (document.visibilityState === 'visible' && navigator.onLine) {
                        self.triggerFlashDeltaSync('visibility_resume');
                    } else if (document.visibilityState === 'hidden') {
                        self.flushBeaconOnUnload();
                    }
                });

                window.addEventListener('focus', () => {
                    if (navigator.onLine) {
                        self.triggerFlashDeltaSync('window_focus');
                    }
                });

                // 4. نبض تزامن حي خفيف كالريشة يلتقط أي سند أُدخل من الجوال أو اللابتوب دون تحديث الصفحة
                this.syncTimer = setInterval(() => {
                    if (navigator.onLine && document.visibilityState === 'visible') {
                        self.triggerFlashDeltaSync('heartbeat');
                    }
                }, 22000);
            },

            flushBeaconOnUnload() {
                try {
                    if (!navigator.onLine || typeof navigator.sendBeacon !== 'function') return;
                    const queue = this.getCrdtOfflineQueue();
                    if (queue.length === 0) return;
                    const blob = new Blob([JSON.stringify({
                        deviceNodeId: this.deviceNodeId,
                        hlcTimestamp: this.nextHlcTimestamp(),
                        reason: 'unload_beacon',
                        crdtQueue: queue
                    })], { type: 'application/json' });
                    navigator.sendBeacon('multi-cash-payment.php?api=flash_delta_sync', blob);
                } catch (_) {}
            },

            // 4. ثبات السرعة الخارقة مع تضخم البيانات إلى 100 ألف سجل (Big-Data Virtualization & O(1) Hash Indexing — Directive 3)
            normalizeForHash(str) {
                if (!str) return '';
                return String(str)
                    .toLowerCase()
                    .replace(/[\u064B-\u065F\u0670\u0640]/g, '')
                    .replace(/[أإآٱ]/g, 'ا')
                    .replace(/ة/g, 'ه')
                    .replace(/[ىئ]/g, 'ي')
                    .replace(/ؤ/g, 'و')
                    .replace(/\s+/g, ' ')
                    .trim();
            },

            rebuild100kHashIndex(force = false) {
                try {
                    const getTKey = (typeof window.getTenantKey === 'function') ? window.getTenantKey : ((k) => k);
                    const payList = JSON.parse(localStorage.getItem(getTKey('erp_payments_v1')) || localStorage.getItem('erp_payments_v1') || '[]');
                    const recList = JSON.parse(localStorage.getItem(getTKey('erp_receipts_v1')) || localStorage.getItem('erp_receipts_v1') || '[]');
                    const totalVouchers = (Array.isArray(payList) ? payList.length : 0) + (Array.isArray(recList) ? recList.length : 0);

                    if (force || totalVouchers !== this.lastIndexedVoucherCount) {
                        this.voucherHashIndex.clear();
                        if (Array.isArray(payList)) {
                            for (let i = 0; i < payList.length; i++) {
                                const v = payList[i];
                                const k = String(v?.voucherNo || v?.id || '').toUpperCase();
                                if (k) this.voucherHashIndex.set(k, { type: 'payment', index: i, record: v });
                            }
                        }
                        if (Array.isArray(recList)) {
                            for (let i = 0; i < recList.length; i++) {
                                const v = recList[i];
                                const k = String(v?.voucherNo || v?.id || '').toUpperCase();
                                if (k) this.voucherHashIndex.set(k, { type: 'receipt', index: i, record: v });
                            }
                        }
                        this.lastIndexedVoucherCount = totalVouchers;
                    }
                } catch (_) {}
            },

            applyDropdownVirtualWindowing(listEl) {
                if (!listEl || listEl.dataset.mcpC6Virtualized === '1') return;
                listEl.dataset.mcpC6Virtualized = '1';
                const self = this;
                let isEnforcing = false;

                const enforceWindowLimit = () => {
                    if (isEnforcing) return;
                    const items = listEl.children;
                    if (!items || items.length <= self.VIRTUAL_WINDOW_SIZE) return;
                    isEnforcing = true;
                    try {
                        const maxShow = self.VIRTUAL_WINDOW_SIZE;
                        let shownCount = 0;
                        for (let i = 0; i < items.length; i++) {
                            const child = items[i];
                            if (child.style.display !== 'none') {
                                shownCount++;
                                if (shownCount > maxShow && !child.dataset.mcpC6Expanded) {
                                    child.style.display = 'none';
                                    child.dataset.mcpC6VirtualHidden = '1';
                                }
                            }
                        }
                    } finally {
                        isEnforcing = false;
                    }
                };

                listEl.addEventListener('scroll', () => {
                    if (listEl.scrollTop + listEl.clientHeight >= listEl.scrollHeight - 65) {
                        const hiddenItems = listEl.querySelectorAll('[data-mcp-c6-virtual-hidden="1"]');
                        const batch = Math.min(hiddenItems.length, 35);
                        if (batch <= 0) return;
                        isEnforcing = true;
                        try {
                            for (let i = 0; i < batch; i++) {
                                hiddenItems[i].style.display = '';
                                hiddenItems[i].dataset.mcpC6Expanded = '1';
                                hiddenItems[i].removeAttribute('data-mcp-c6-virtual-hidden');
                            }
                        } finally {
                            isEnforcing = false;
                        }
                    }
                }, { passive: true });

                const obs = new MutationObserver(() => enforceWindowLimit());
                obs.observe(listEl, { childList: true });
            },

            init100kVirtualScrollerAndIndex() {
                const self = this;
                setTimeout(() => this.rebuild100kHashIndex(true), 500);

                const bindAllCurrentDropdowns = () => {
                    document.querySelectorAll('.custom-dropdown-list, [id$="-dropdown-list"], #inbound-receipts-list').forEach(el => {
                        self.applyDropdownVirtualWindowing(el);
                    });
                };
                bindAllCurrentDropdowns();

                // مراقبة أي كتلة حساب فرعي جديدة تُضاف للسند لتفعيل التمرير الافتراضي (Virtual Scrolling) عليها تلقائياً
                const container = document.getElementById('accounts-blocks-container');
                if (container && typeof MutationObserver !== 'undefined') {
                    const blockObs = new MutationObserver(() => bindAllCurrentDropdowns());
                    blockObs.observe(container, { childList: true, subtree: true });
                }
            },

            // 5. الربط المحاسبي الشامل والتسميع الذري في كل الشاشات والتقارير (100% Atomic Double-Entry Checkpoint — Directive 5)
            initAtomicDoubleEntryGuard() {
                const self = this;
                const getTKey = (typeof window.getTenantKey === 'function') ? window.getTenantKey : ((k) => k);
                const BASE_KEYS = [
                    'erp_payments_v1',
                    'erp_receipts_v1',
                    'erp_safes_v1',
                    'erp_banks_v1',
                    'erp_customers_v1',
                    'erp_suppliers_v1',
                    'erp_accounts_v1',
                    'erp_journal_entries_v1',
                    'erp_cost_centers_v1'
                ];

                const captureAtomicSnapshot = () => {
                    const snap = {};
                    BASE_KEYS.forEach((k) => {
                        try {
                            snap[k] = localStorage.getItem(k);
                            const tk = getTKey(k);
                            if (tk !== k) snap[tk] = localStorage.getItem(tk);
                        } catch (_) {}
                    });
                    return snap;
                };

                const rollbackAtomicSnapshot = (snap) => {
                    if (!snap) return;
                    Object.keys(snap).forEach((k) => {
                        try {
                            if (snap[k] === null || snap[k] === undefined) {
                                localStorage.removeItem(k);
                            } else {
                                localStorage.setItem(k, snap[k]);
                            }
                        } catch (_) {}
                    });
                };

                const btnSave = document.getElementById('btn-save');
                if (btnSave && !btnSave.dataset.mcpC6AtomicBound) {
                    btnSave.dataset.mcpC6AtomicBound = '1';
                    btnSave.addEventListener('click', () => {
                        const preSnapshot = captureAtomicSnapshot();
                        setTimeout(() => {
                            try {
                                const vType = document.getElementById('voucher-type')?.value || 'payment';
                                const baseKey = (vType === 'receipt') ? 'erp_receipts_v1' : 'erp_payments_v1';
                                const tenantKey = getTKey(baseKey);
                                const list = JSON.parse(localStorage.getItem(tenantKey) || localStorage.getItem(baseKey) || '[]');
                                if (!Array.isArray(list) || list.length === 0) return;

                                const rec = list[list.length - 1];
                                if (!rec || (!rec.voucherNo && !rec.id)) return;

                                const totalAmt = Number(rec.totalAmount || rec.amountLocal || 0);
                                const itemsSum = Array.isArray(rec.items)
                                    ? rec.items.reduce((acc, it) => acc + (Number(it?.amount || 0)), 0)
                                    : totalAmt;

                                // فحص التوازن الذري المزدوج: إجمالي الحساب الرئيسي === مجموع الحسابات الفرعية بنسبة خطأ 0%
                                if (totalAmt <= 0 || Math.abs(totalAmt - itemsSum) > 0.05) {
                                    rollbackAtomicSnapshot(preSnapshot);
                                    return;
                                }

                                rec.atomicDoubleEntryVerified = true;
                                rec.atomicMainEqualSubs = totalAmt;
                                rec.hlcTimestamp = self.nextHlcTimestamp();
                                rec.updatedAtMs = Date.now();
                                rec.originNodeId = self.deviceNodeId;

                                const jsonStr = JSON.stringify(list);
                                localStorage.setItem(baseKey, jsonStr);
                                if (tenantKey !== baseKey) localStorage.setItem(tenantKey, jsonStr);

                                self.enqueueCrdtNanoPacket(rec, 'UPSERT');
                                self.clearCrashDraft();
                            } catch (_) {
                                rollbackAtomicSnapshot(preSnapshot);
                            }
                        }, 220);
                    });
                }
            },

            // 6. ربط الدستور السادس وإضافاته العالمية الخمس بالمرشد الذكي (Directive 6)
            registerWithSmartGuide() {
                window.MCP_DESKTOP_CONSTITUTION6_GUIDE = {
                    constitutionNumber: 6,
                    title: 'الدستور السادس: التزامن الصاروخي بالمللي ثانية (CRDT)، الحارس الفولاذي، وثبات 100 ألف سجل',
                    goldenRule: 'القاعدة الذهبية للتزامن والذرية: أي سند مجمع تحفظه في الجوال أو اللابتوب — حتى في أضعف شبكة أو أوفلاين — يُختم ببصمة زمنية ذرية (CRDT + HLC) ويُدمج في كسر من الثانية فور لمس الإنترنت دون أن يمسح جهاز عمل الجهاز الآخر أبداً، وبقيد مزدوج متوازن 100%.'
                };

                const c4 = window.McpDesktopConstitution4;
                const selectEl = document.getElementById('mcpC4StageJumpSelect');
                if (c4 && Array.isArray(c4.steps) && !c4.steps.some(s => s.id === 'step-c6-flash-sync-crdt')) {
                    const stepIdx = c4.steps.length;
                    const c6Step = {
                        id: 'step-c6-flash-sync-crdt',
                        title: '2️⃣0️⃣ التزامن الصاروخي بالمللي ثانية (CRDT)، الحارس الفولاذي، وثبات 100 ألف سجل',
                        svgStage: 'output',
                        showMap: false,
                        selector: '#mcpC6FlashSyncBadge, #mcp-2g-resilience-badge',
                        goldenRule: 'القاعدة الذهبية للتزامن والذرية: اعمل في الجوال أو اللابتوب حتى أوفلاين؛ فبمجرد لمس الإنترنت لكسر من الثانية تندمج حركات الجهازين ذرياً بنظام (CRDT) دون ضياع قرش واحد.',
                        action: () => {
                            if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups();
                        },
                        text: 'وبجوار شارة الخفة القصوى تظهر كبسولة التزامن الصاروخي بالمللي ثانية بنظام سي آر دي تي؛ فهي تقتنص أول شرارة إنترنت في كسر من الثانية لتدفع الحزم النانوية بين الجوال واللابتوب وتدمج حركات الأوفلاين ذرياً بدون أي تضارب، مع الحارس الفولاذي المزدوج الذي يحمي مسودتك ضد انطفاء الجهاز المفاجئ، والفهرسة الافتراضية التي تحافظ على سرعة صفر مللي ثانية حتى مع مئة ألف سجل. القاعدة الذهبية للتزامن: اعمل في الجوال أو اللابتوب بأمان تام؛ فكل حرف محمي في خزنة الجهاز وتندمج حركات الجهازين معاً بدقة مئة بالمئة.'
                    };
                    c4.steps.push(c6Step);
                    if (selectEl) {
                        const opt = document.createElement('option');
                        opt.value = String(stepIdx);
                        opt.textContent = '2️⃣0️⃣ التزامن الصاروخي (CRDT) والحارس الفولاذي و100 ألف سجل';
                        selectEl.appendChild(opt);
                    }
                    const counterEl = document.getElementById('mcpC4StepCounterBadge');
                    if (counterEl) {
                        counterEl.textContent = (c4.currentStepIndex + 1) + ' / ' + c4.steps.length;
                    }
                }
            }
        };

        window.McpDesktopConstitution6 = McpDesktopConstitution6;
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => McpDesktopConstitution6.init());
        } else {
            McpDesktopConstitution6.init();
        }
    })();
    </script>

    <!-- ══════════════════════════════════════════════════════════════════════════════ -->
    <!-- الدستور السابع (Constitution 7 of 14): دستور الأبجديات البرمجية التحتية، توحيد الأرقام والفاصلة العشرية، تنظيف المسافات واللصق الذكي، التراجع الفوري (Ctrl+Z)، الباركود، والطب البصري لراحة العين ومنع الزغللة وانزلاق النظر (Zebra Striping + Tabular Numerals) -->
    <!-- ══════════════════════════════════════════════════════════════════════════════ -->
    <style id="mcp-constitution-7-ophthalmic-ergonomics-styles">
        /* 1. الطب البصري (2): المحاذاة الهندسية العمودية للأرقام بالمسطرة (Tabular Numerals) ومنع الارتعاش (Directive 5) */
        #voucher-no-display,
        #voucher-ref,
        #exchange-rate,
        #amount-local-hdr,
        #amount-foreign,
        .block-sub-amount,
        .block-cash-amount,
        .block-bank-amount,
        .block-cheque-amount,
        .block-transfer-no-input,
        .block-cheque-no-input,
        .account-total-input,
        #mcp-split-total,
        #mcp-split-count,
        #mcp-qa-phone,
        #wa-both-debtor-phone,
        #wa-both-creditor-phone,
        #mcp-world-summary-bar span,
        #main-account-live-bal span,
        .block-live-balance-row span {
            font-variant-numeric: tabular-nums lining-nums !important;
            font-feature-settings: "tnum" 1, "lnum" 1, "zero" 1 !important;
            letter-spacing: 0.02em;
            backface-visibility: hidden;
            -webkit-font-smoothing: antialiased;
        }

        /* 2. الطب البصري (1): التدرج البصري التبادلي الهادي (Zebra Striping) لمنع انزلاق العين الأفقي (Directive 4) */
        #accounts-blocks-container .account-block:nth-child(odd) {
            background-color: rgba(15, 23, 42, 0.72);
        }
        #accounts-blocks-container .account-block:nth-child(even) {
            background-color: rgba(30, 41, 59, 0.76);
        }
        html.light-theme #accounts-blocks-container .account-block:nth-child(odd) {
            background-color: #ffffff !important;
        }
        html.light-theme #accounts-blocks-container .account-block:nth-child(even) {
            background-color: #f8fafc !important;
        }

        .bank-row:nth-child(even),
        .cheque-row:nth-child(even),
        .custom-dropdown-list .custom-dropdown-item:nth-child(even),
        table tbody tr:nth-child(even) {
            background-color: rgba(30, 41, 59, 0.36);
        }
        html.light-theme .bank-row:nth-child(even),
        html.light-theme .cheque-row:nth-child(even),
        html.light-theme .custom-dropdown-list .custom-dropdown-item:nth-child(even),
        html.light-theme table tbody tr:nth-child(even) {
            background-color: rgba(241, 245, 249, 0.88);
