            box-shadow: 0 4px 12px rgba(56, 189, 248, 0.22);
            transition: transform 0.14s ease, box-shadow 0.18s ease;
        }
        html.light-theme #mcpC7UndoBtn {
            background: #f0f9ff !important;
            color: #000000 !important;
            border: 2px solid #0284c7 !important;
        }
        #mcpC7UndoBtn:hover {
            transform: translateY(-1px) scale(1.02);
            box-shadow: 0 0 14px rgba(56, 189, 248, 0.5);
        }
        #mcpC7UndoCountBadge {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-width: 19px;
            height: 19px;
            padding: 0 5px;
            border-radius: 999px;
            background: #0284c7;
            color: #ffffff !important;
            font-size: 0.71rem;
            font-weight: 900;
            font-variant-numeric: tabular-nums;
        }

        @media print {
            #mcpC7UndoBtn {
                display: none !important;
            }
        }
    </style>

    <script id="mcp-constitution-7-ophthalmic-ergonomics-engine">
    (function () {
        'use strict';
        if (window.McpDesktopConstitution7) return;

        const McpDesktopConstitution7 = {
            initialized: false,
            undoStack: [],
            MAX_UNDO_STACK: 35,
            isRestoringUndo: false,
            barcodeBuffer: '',
            lastBarcodeKeyTime: 0,
            BARCODE_MAX_GAP_MS: 35,

            NUMERIC_SELECTORS: '#exchange-rate, #amount-local-hdr, #amount-foreign, .block-sub-amount, .block-cash-amount, .block-bank-amount, .block-cheque-amount, .account-total-input, #mcp-split-total, #mcp-split-count',
            PHONE_SELECTORS: '#mcp-qa-phone, #wa-both-debtor-phone, #wa-both-creditor-phone, #wa-modal-phone',

            init() {
                if (this.initialized) return;
                this.initialized = true;

                this.initUniversalNumeralAndDecimalNormalizer();
                this.initAutoTrimAndSmartCleanPaste();
                this.initMultiLevelUndoAndBlockRecovery();
                this.initFullKeyboardAndBarcodeScanner();
                this.initMedicalAntiEyeSlipActiveRowLock();
                this.registerWithSmartGuide();
            },

            // 1. أبجدية توحيد الأرقام العربية/الإنجليزية والفاصلة العشرية تلقائياً في 0ms (Directive 1)
            convertEasternDigitsToAscii(raw) {
                if (typeof raw !== 'string' || !raw) return '';
                return raw
                    .replace(/[\u0660-\u0669]/g, (d) => String(d.charCodeAt(0) - 0x0660))
                    .replace(/[\u06F0-\u06F9]/g, (d) => String(d.charCodeAt(0) - 0x06F0));
            },

            isNumericTarget(el) {
                if (!el || !el.tagName) return false;
                if (el.matches && el.matches(this.NUMERIC_SELECTORS)) return true;
                const type = (el.getAttribute('type') || '').toLowerCase();
                const inputMode = (el.getAttribute('inputmode') || '').toLowerCase();
                const id = el.id || '';
                return (
                    type === 'number' ||
                    inputMode === 'decimal' ||
                    inputMode === 'numeric' ||
                    el.dataset.numeric === 'true' ||
                    /amount|rate|price|total|balance|qty|split/i.test(id)
                );
            },

            isPhoneTarget(el) {
                if (!el || !el.tagName) return false;
                if (el.matches && el.matches(this.PHONE_SELECTORS)) return true;
                return (el.getAttribute('type') || '').toLowerCase() === 'tel' || /phone|mobile|whatsapp/i.test(el.id || '');
            },

            normalizeNumericValue(val, allowNegative = false) {
                if (typeof val !== 'string') val = String(val ?? '');
                let s = this.convertEasternDigitsToAscii(val);
                // تحويل حرف الفاصلة بالكيبورد العربي (و / ، / ٫ / ז) إلى نقطة عشرية قياسية (.)
                s = s.replace(/[و،٫ז]/g, '.');
                const hasMinus = allowNegative && s.trim().startsWith('-');
                // إذا كان الحقل يحتوي على تعبير حسابي (مثل 1500+2500) نحافظ على العمليات الحسابية وندمج أي نقطتين متتاليتين
                if (/[+\-*/()]/.test(s)) {
                    return s.replace(/\.{2,}/g, '.');
                }
                const parts = s.split('.');
                if (parts.length > 2) {
                    s = parts[0] + '.' + parts.slice(1).join('');
                }
                return (hasMinus ? '-' : '') + s;
            },

            initUniversalNumeralAndDecimalNormalizer() {
                const self = this;

                // اعتراض ضغطة الفاصلة العشرية بالكيبورد العربي (و / ، / ٫ / ז) داخل خانات المبالغ وسعر الصرف وتحويلها فوراً إلى (.)
                document.addEventListener('keydown', (e) => {
                    const el = e.target;
                    if (!el || !self.isNumericTarget(el) || el.readOnly || el.disabled) return;
                    if (e.ctrlKey || e.altKey || e.metaKey) return;

                    const decimalAliasKeys = new Set(['و', '،', '٫', 'ז', 'Decimal']);
                    if (decimalAliasKeys.has(e.key)) {
                        e.preventDefault();
                        const curVal = String(el.value || '');
                        const start = typeof el.selectionStart === 'number' ? el.selectionStart : curVal.length;
                        const end = typeof el.selectionEnd === 'number' ? el.selectionEnd : curVal.length;
                        // التحقق من عدم وجود نقطة عشرية في الرقم الحالي (أو بعد آخر علامة حسابية)
                        const beforeCursor = curVal.slice(0, start);
                        const lastToken = beforeCursor.split(/[+\-*/()]/).pop() || '';
                        if (lastToken.includes('.')) return;

                        const prefix = beforeCursor || '0';
                        const nextVal = prefix + '.' + curVal.slice(end);
                        el.value = nextVal;
                        try {
                            el.setSelectionRange(prefix.length + 1, prefix.length + 1);
                        } catch (_) {}
                        el.dispatchEvent(new Event('input', { bubbles: true }));
                    }
                }, true);

                // توحيد الأرقام المشرقية والفارسية في كافة الخانات في نفس جزء الثانية (0ms)
                document.addEventListener('input', (e) => {
                    const el = e.target;
                    if (!el || (el.tagName !== 'INPUT' && el.tagName !== 'TEXTAREA') || el.readOnly || el.disabled) return;
                    const orig = el.value;
                    if (!orig) return;
                    if (!/[\u0660-\u0669\u06F0-\u06F9و،٫ז]/.test(orig) && orig.indexOf('..') === -1) return;

                    let normalized = self.convertEasternDigitsToAscii(orig);
                    if (self.isNumericTarget(el)) {
                        normalized = self.normalizeNumericValue(normalized, false);
                    }

                    if (normalized !== orig) {
                        const pos = typeof el.selectionStart === 'number' ? el.selectionStart : normalized.length;
                        el.value = normalized;
                        try {
                            el.setSelectionRange(pos, pos);
                        } catch (_) {}
                    }
                }, { capture: true, passive: true });
            },

            // 2. أبجدية تنظيف المسافات الوهمية (Auto-Trim) وخاصية اللصق النظيف الذكي (Smart Clean Paste — Directive 2)
            cleanInvisibleAndDuplicateSpaces(str, trimEdges = true) {
                if (typeof str !== 'string') return '';
                const cleaned = this.convertEasternDigitsToAscii(str)
                    .replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g, '')
                    .replace(/\u00A0/g, ' ')
                    .replace(/[ \t]{2,}/g, ' ');
                return trimEdges ? cleaned.trim() : cleaned;
            },

            smartExtractNumericPaste(rawText) {
                if (typeof rawText !== 'string') return '';
                let s = this.convertEasternDigitsToAscii(rawText)
                    .replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g, '')
                    .replace(/[٫]/g, '.')
                    .trim();

                // معالجة المبالغ المنسوخة من الواتساب أو الإكسل مثل "125,000،50 ج.س" أو "المبلغ: 45,000.75"
                s = s.replace(/(\d)[،و](\d{1,4})(?!\d)/g, '$1.$2');
                s = s.replace(/,/g, '');
                const match = s.match(/-?\d+(?:\.\d+)?/);
                return match ? match[0] : '';
            },

            smartExtractPhonePaste(rawText) {
                if (typeof rawText !== 'string') return '';
                const s = this.convertEasternDigitsToAscii(rawText)
                    .replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g, '')
                    .trim();
                const hasPlus = s.startsWith('+');
                const digits = s.replace(/\D+/g, '');
                return digits ? ((hasPlus ? '+' : '') + digits) : '';
            },

            initAutoTrimAndSmartCleanPaste() {
                const self = this;

                // 1. تنظيف المسافات الوهمية تلقائياً عند الخروج من الحقل (blur) لمنع تكرار نفس العميل أو الحساب بسبب مسافة غير مرئية
                document.addEventListener('blur', (e) => {
                    const el = e.target;
                    if (!el || (el.tagName !== 'INPUT' && el.tagName !== 'TEXTAREA') || el.readOnly || el.disabled) return;
                    if (el.type === 'password' || el.type === 'file' || el.id === 'mcp-excel-paste-area') return;

                    const orig = el.value;
                    if (!orig) return;

                    let cleaned = self.cleanInvisibleAndDuplicateSpaces(orig, true);
                    if (self.isPhoneTarget(el)) {
                        cleaned = self.smartExtractPhonePaste(cleaned);
                    }
                    if (cleaned !== orig) {
                        el.value = cleaned;
                        el.dispatchEvent(new Event('input', { bubbles: true }));
                        el.dispatchEvent(new Event('change', { bubbles: true }));
                    }
                }, true);

                // 2. اللصق النظيف الذكي (Smart Clean Paste Ctrl+V) من الواتساب أو الإكسل
                document.addEventListener('paste', (e) => {
                    const el = e.target;
                    if (!el || (el.tagName !== 'INPUT' && el.tagName !== 'TEXTAREA') || el.readOnly || el.disabled) return;
                    // نترك منطقة لصق جدول الإكسل المجمع متعددة الأسطر مع تنظيف الأرقام العربية والمحارف الخفية فقط
                    const clip = e.clipboardData || window.clipboardData;
                    if (!clip) return;
                    const rawText = clip.getData('text/plain') || clip.getData('Text') || '';
                    if (!rawText) return;

                    if (el.id === 'mcp-excel-paste-area') {
                        const cleanMultiLine = self.convertEasternDigitsToAscii(rawText)
                            .replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g, '');
                        if (cleanMultiLine !== rawText) {
                            e.preventDefault();
                            el.value = cleanMultiLine;
                            el.dispatchEvent(new Event('input', { bubbles: true }));
                        }
                        return;
                    }

                    let cleanPaste = '';
                    if (self.isNumericTarget(el)) {
                        cleanPaste = self.smartExtractNumericPaste(rawText);
                    } else if (self.isPhoneTarget(el)) {
                        cleanPaste = self.smartExtractPhonePaste(rawText);
                    } else if (el.classList.contains('block-transfer-no-input') || el.classList.contains('block-cheque-no-input')) {
                        cleanPaste = self.cleanInvisibleAndDuplicateSpaces(rawText, true).replace(/[^\w\-/]/g, '');
                    } else {
                        cleanPaste = self.cleanInvisibleAndDuplicateSpaces(rawText.replace(/[\r\n]+/g, ' '), true);
                    }

                    if (cleanPaste && cleanPaste !== rawText) {
                        e.preventDefault();
                        const curVal = String(el.value || '');
                        const start = typeof el.selectionStart === 'number' ? el.selectionStart : 0;
                        const end = typeof el.selectionEnd === 'number' ? el.selectionEnd : curVal.length;

                        const finalVal = self.isNumericTarget(el)
                            ? cleanPaste
                            : self.cleanInvisibleAndDuplicateSpaces(curVal.slice(0, start) + cleanPaste + curVal.slice(end), true);

                        el.value = finalVal;
                        el.dispatchEvent(new Event('input', { bubbles: true }));
                        el.dispatchEvent(new Event('change', { bubbles: true }));
                        if (typeof window.showToast === 'function' && self.isNumericTarget(el)) {
                            window.showToast('✨ لصق ذكي نظيف: ' + finalVal, 'info', 1400);
                        }
                    }
                }, true);
            },

            // 3. أبجدية التراجع الفوري متعدد المستويات (Ctrl+Z) لاستعادة أي سطر أو كتلة أو تحويلة أو شيك حُذف بالخطأ (Directive 3)
            captureFullMultiVoucherState(reasonLabel = 'تعديل') {
                const parseAmt = (v) => parseFloat(String(v || '0').replace(/,/g, '')) || 0;
                const blocks = [];
                let nonEmptyCount = 0;

                const header = {
                    type: document.getElementById('voucher-type')?.value || 'payment',
                    date: document.getElementById('voucher-date')?.value || '',
                    ref: document.getElementById('voucher-ref')?.value || '',
                    mainAccountId: document.getElementById('main-account')?.getAttribute('data-id') || document.getElementById('main-account')?.value || '',
                    mainAccountName: document.getElementById('main-account-search')?.value || '',
                    currency: document.getElementById('currency')?.value || 'SDG',
                    exchangeRate: document.getElementById('exchange-rate')?.value || '',
                    desc: document.getElementById('voucher-desc')?.value || ''
                };
                if (header.desc.trim() || header.ref.trim()) nonEmptyCount++;

                document.querySelectorAll('.account-block').forEach(block => {
                    const bid = block.getAttribute('data-block-id');
                    const accName = document.getElementById('account-' + bid + '-search')?.value || '';
                    const accId = document.getElementById('account-' + bid + '-id')?.value || '';
                    const stmt = document.getElementById('statement-' + bid)?.value || '';
                    const cc = document.getElementById('cost-center-' + bid)?.value || '';
                    const ccId = document.getElementById('cost-center-' + bid + '-id')?.value || '';
                    const cashRaw = block.querySelector('.block-cash-amount')?.value || '';
                    const cashDesc = block.querySelector('.block-cash-desc-input')?.value || '';
                    const cashActive = document.getElementById('pm-cash-' + bid)?.classList.contains('active') || false;
                    const bankActive = document.getElementById('pm-bank-' + bid)?.classList.contains('active') || false;
                    const chequeActive = document.getElementById('pm-cheque-' + bid)?.classList.contains('active') || false;

                    const bankRows = [];
                    block.querySelectorAll('.bank-row').forEach(r => {
                        const bAmt = r.querySelector('.block-bank-amount')?.value || '';
                        const bName = r.querySelector('.block-bank-name-input')?.value || '';
                        const bTr = r.querySelector('.block-transfer-no-input')?.value || '';
                        const bDesc = r.querySelector('.block-bank-desc-input')?.value || '';
                        bankRows.push({ amountRaw: bAmt, bankName: bName, transferNo: bTr, desc: bDesc });
                        if (parseAmt(bAmt) > 0 || bName.trim() || bTr.trim()) nonEmptyCount++;
                    });

                    const chequeRows = [];
                    block.querySelectorAll('.cheque-row').forEach(r => {
                        const cAmt = r.querySelector('.block-cheque-amount')?.value || '';
                        const cBank = r.querySelector('.block-cheque-bank-input')?.value || '';
                        const cNo = r.querySelector('.block-cheque-no-input')?.value || '';
                        const cDate = r.querySelector('.block-cheque-date-input')?.value || '';
                        const cDesc = r.querySelector('.block-cheque-desc-input')?.value || '';
                        chequeRows.push({ amountRaw: cAmt, bank: cBank, no: cNo, date: cDate, desc: cDesc });
                        if (parseAmt(cAmt) > 0 || cBank.trim() || cNo.trim()) nonEmptyCount++;
                    });

                    if (accName.trim() || stmt.trim() || cc.trim() || parseAmt(cashRaw) > 0) nonEmptyCount++;

                    blocks.push({
                        accountName: accName,
                        accountId: accId,
                        statement: stmt,
                        costCenter: cc,
                        costCenterId: ccId,
                        cashActive: cashActive,
                        cashRaw: cashRaw,
                        cashDesc: cashDesc,
                        bankActive: bankActive,
                        bankRows: bankRows,
                        chequeActive: chequeActive,
                        chequeRows: chequeRows
                    });
                });

                return {
                    timestamp: Date.now(),
                    reasonLabel: reasonLabel,
                    nonEmptyCount: nonEmptyCount,
                    signature: JSON.stringify({ header, blocks }),
                    header: header,
                    blocks: blocks
                };
            },

            pushUndoSnapshot(reasonLabel = 'تعديل سطر') {
                if (this.isRestoringUndo) return;
                const snap = this.captureFullMultiVoucherState(reasonLabel);
                if (snap.nonEmptyCount === 0 && snap.blocks.length <= 1) return;

                const top = this.undoStack[this.undoStack.length - 1];
                if (top && top.signature === snap.signature) return;

                this.undoStack.push(snap);
                if (this.undoStack.length > this.MAX_UNDO_STACK) {
                    this.undoStack.shift();
                }
                this.updateUndoBadgeCount();
            },

            applyMultiVoucherSnapshot(snap) {
                if (!snap || !snap.header || !Array.isArray(snap.blocks)) return;
                const h = snap.header;

                if (typeof window.executeSetVoucherType === 'function' && h.type) {
                    const curType = document.getElementById('voucher-type')?.value || 'payment';
                    if (curType !== h.type) window.executeSetVoucherType(h.type);
                }
                if (document.getElementById('voucher-date') && h.date) document.getElementById('voucher-date').value = h.date;
                if (document.getElementById('voucher-ref')) document.getElementById('voucher-ref').value = h.ref || '';
                if (document.getElementById('main-account')) {
                    document.getElementById('main-account').value = h.mainAccountName || '';
                    document.getElementById('main-account').setAttribute('data-id', h.mainAccountId || '');
                }
                if (document.getElementById('main-account-search')) document.getElementById('main-account-search').value = h.mainAccountName || '';
                if (document.getElementById('currency') && h.currency) document.getElementById('currency').value = h.currency;
                if (document.getElementById('exchange-rate') && h.exchangeRate) document.getElementById('exchange-rate').value = h.exchangeRate;
                if (document.getElementById('voucher-desc')) document.getElementById('voucher-desc').value = h.desc || '';

                const container = document.getElementById('accounts-blocks-container');
                if (container && typeof window.addAccountBlock === 'function') {
                    container.innerHTML = '';
                    if (typeof window.blockCounter !== 'undefined') window.blockCounter = 0;

                    snap.blocks.forEach((b) => {
                        window.addAccountBlock();
                        const allBlocks = container.querySelectorAll('.account-block');
                        const lastBlock = allBlocks[allBlocks.length - 1];
                        if (!lastBlock) return;
                        const bid = lastBlock.getAttribute('data-block-id');

                        const sEl = document.getElementById('account-' + bid + '-search');
                        if (sEl) sEl.value = b.accountName || '';
                        const idEl = document.getElementById('account-' + bid + '-id');
                        if (idEl) idEl.value = b.accountId || '';
                        const hiddenAcc = document.getElementById('account-' + bid);
                        if (hiddenAcc) {
                            hiddenAcc.value = b.accountName || '';
                            hiddenAcc.setAttribute('data-id', b.accountId || '');
                        }
                        const stEl = document.getElementById('statement-' + bid);
                        if (stEl) stEl.value = b.statement || '';
                        const ccEl = document.getElementById('cost-center-' + bid);
                        if (ccEl) ccEl.value = b.costCenter || '';
                        const ccIdEl = document.getElementById('cost-center-' + bid + '-id');
                        if (ccIdEl) ccIdEl.value = b.costCenterId || '';

                        // استعادة حالة ومبالغ النقدي
                        const cashBtn = document.getElementById('pm-cash-' + bid);
                        const cashDet = document.getElementById('cash-details-' + bid);
                        if (cashBtn && cashDet) {
                            cashBtn.classList.toggle('active', !!b.cashActive);
                            cashDet.style.display = b.cashActive ? 'block' : 'none';
                        }
                        const cashInp = lastBlock.querySelector('.block-cash-amount');
                        if (cashInp) cashInp.value = b.cashRaw || '';
                        const cashDescInp = lastBlock.querySelector('.block-cash-desc-input');
                        if (cashDescInp) cashDescInp.value = b.cashDesc || '';

                        // استعادة حالة وأسطر التحويلات البنكية
                        const bankBtn = document.getElementById('pm-bank-' + bid);
                        const bankDet = document.getElementById('bank-details-' + bid);
                        const bankRowsBox = document.getElementById('bank-rows-' + bid);
                        if (bankBtn && bankDet) {
                            bankBtn.classList.toggle('active', !!b.bankActive);
                            bankDet.style.display = b.bankActive ? 'block' : 'none';
                        }
                        if (bankRowsBox && Array.isArray(b.bankRows) && b.bankRows.length > 0) {
                            bankRowsBox.innerHTML = '';
                            b.bankRows.forEach((br) => {
                                if (typeof window.addBankRow === 'function') window.addBankRow(bid);
                                const rows = bankRowsBox.querySelectorAll('.bank-row');
                                const r = rows[rows.length - 1];
                                if (r) {
                                    const a = r.querySelector('.block-bank-amount'); if (a) a.value = br.amountRaw || '';
                                    const n = r.querySelector('.block-bank-name-input'); if (n) n.value = br.bankName || '';
                                    const t = r.querySelector('.block-transfer-no-input'); if (t) t.value = br.transferNo || '';
                                    const d = r.querySelector('.block-bank-desc-input'); if (d) d.value = br.desc || '';
                                }
                            });
                        }

                        // استعادة حالة وأسطر الشيكات
                        const chqBtn = document.getElementById('pm-cheque-' + bid);
                        const chqDet = document.getElementById('cheque-details-' + bid);
                        const chqRowsBox = document.getElementById('cheque-rows-' + bid);
                        if (chqBtn && chqDet) {
                            chqBtn.classList.toggle('active', !!b.chequeActive);
                            chqDet.style.display = b.chequeActive ? 'block' : 'none';
                        }
                        if (chqRowsBox && Array.isArray(b.chequeRows) && b.chequeRows.length > 0) {
                            chqRowsBox.innerHTML = '';
                            b.chequeRows.forEach((cr) => {
                                if (typeof window.addChequeRow === 'function') window.addChequeRow(bid);
                                const rows = chqRowsBox.querySelectorAll('.cheque-row');
                                const r = rows[rows.length - 1];
                                if (r) {
                                    const a = r.querySelector('.block-cheque-amount'); if (a) a.value = cr.amountRaw || '';
                                    const n = r.querySelector('.block-cheque-bank-input'); if (n) n.value = cr.bank || '';
                                    const no = r.querySelector('.block-cheque-no-input'); if (no) no.value = cr.no || '';
                                    const dt = r.querySelector('.block-cheque-date-input'); if (dt) dt.value = cr.date || '';
                                    const d = r.querySelector('.block-cheque-desc-input'); if (d) d.value = cr.desc || '';
                                }
                            });
                        }

                        if (typeof window.recalcBlockTotal === 'function') {
                            try { window.recalcBlockTotal(bid); } catch (_) {}
                        }
                    });

                    if (typeof window.calcTotal === 'function') {
                        try { window.calcTotal(); } catch (_) {}
                    }
                    if (typeof window.updateAllLiveBalances === 'function') {
                        try { window.updateAllLiveBalances(); } catch (_) {}
                    }
                }
            },

            restoreLastUndoSnapshot() {
                if (this.undoStack.length === 0) {
                    if (typeof window.showToast === 'function') {
                        window.showToast('ℹ️ لا توجد خطوة سابقة في سجل التراجع الفوري (Ctrl+Z).', 'info');
                    }
                    return false;
                }

                const currentSnap = this.captureFullMultiVoucherState('Current');
                let targetSnap = this.undoStack.pop();
                if (targetSnap && this.undoStack.length > 0 && targetSnap.signature === currentSnap.signature) {
                    targetSnap = this.undoStack.pop();
                }
                if (!targetSnap) return false;

                this.isRestoringUndo = true;
                try {
                    this.applyMultiVoucherSnapshot(targetSnap);
                    this.updateUndoBadgeCount();
                    if (typeof window.showToast === 'function') {
                        window.showToast('↩️ تم التراجع الفوري واستعادة السطر والبيانات بنجاح (' + targetSnap.reasonLabel + ')!', 'success');
                    }
                } finally {
                    setTimeout(() => { this.isRestoringUndo = false; }, 100);
                }
                return true;
            },

            injectUndoTopButton() {
                if (document.getElementById('mcpC7UndoBtn')) return;
                const anchor = document.getElementById('mcpC6FlashSyncBadge') || document.getElementById('mcp-2g-resilience-badge');
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.id = 'mcpC7UndoBtn';
                btn.setAttribute('data-guide-title', '↩️ زر التراجع الفوري متعدد المستويات (Ctrl+Z — استعادة الأسطر والكتل والخانات)');
                btn.setAttribute('data-golden-rule', 'القاعدة الذهبية: لا تقلق أبداً إذا حذفت سطراً فرعياً أو ضغطت (جديد) بالخطأ؛ ضغطة واحدة على (Ctrl+Z) أو زر (↩️ تراجع) تعيد السطر والمبلغ كما كان 100%.');
                btn.title = 'التراجع الفوري الآمن (Ctrl+Z) لاستعادة أي كتلة حساب فرعي أو تحويلة أو شيك أو بيان حُذف بالخطأ';
                btn.innerHTML = '<span>↩️ تراجع</span><span id="mcpC7UndoCountBadge">0</span>';
                btn.addEventListener('click', () => this.restoreLastUndoSnapshot());

                if (anchor && anchor.parentElement) {
                    anchor.insertAdjacentElement('afterend', btn);
                }
            },

            updateUndoBadgeCount() {
                const badge = document.getElementById('mcpC7UndoCountBadge');
                if (badge) {
                    badge.textContent = String(this.undoStack.length);
                }
            },

            initMultiLevelUndoAndBlockRecovery() {
                const self = this;
                this.injectUndoTopButton();

                // 1. حفظ لقطة تراجع تلقائية قبل حذف أي كتلة حساب فرعي (removeAccountBlock)
                if (typeof window.removeAccountBlock === 'function' && !window.removeAccountBlock.__mcpC7Wrapped) {
                    const origRemoveBlock = window.removeAccountBlock;
                    const wrappedRemoveBlock = function (id) {
                        self.pushUndoSnapshot('قبل حذف كتلة حساب فرعي');
                        return origRemoveBlock.apply(this, arguments);
                    };
                    wrappedRemoveBlock.__mcpC7Wrapped = true;
                    window.removeAccountBlock = wrappedRemoveBlock;
                }

                // 2. حفظ لقطة تراجع تلقائية قبل حذف أي سطر تحويلة بنكية (removeBankRow)
                if (typeof window.removeBankRow === 'function' && !window.removeBankRow.__mcpC7Wrapped) {
                    const origRemoveBank = window.removeBankRow;
                    const wrappedRemoveBank = function (btn, blockId) {
                        self.pushUndoSnapshot('قبل حذف سطر تحويلة بنكية');
                        return origRemoveBank.apply(this, arguments);
                    };
                    wrappedRemoveBank.__mcpC7Wrapped = true;
                    window.removeBankRow = wrappedRemoveBank;
                }

                // 3. حفظ لقطة تراجع تلقائية قبل حذف أي سطر شيك (removeChequeRow)
                if (typeof window.removeChequeRow === 'function' && !window.removeChequeRow.__mcpC7Wrapped) {
                    const origRemoveCheque = window.removeChequeRow;
                    const wrappedRemoveCheque = function (btn, blockId) {
                        self.pushUndoSnapshot('قبل حذف سطر شيك');
                        return origRemoveCheque.apply(this, arguments);
                    };
                    wrappedRemoveCheque.__mcpC7Wrapped = true;
                    window.removeChequeRow = wrappedRemoveCheque;
                }

                // 4. حفظ لقطة تراجع تلقائية قبل تصفير الشاشة بزر (جديد F2 / resetVoucher)
                if (typeof window.resetVoucher === 'function' && !window.resetVoucher.__mcpC7Wrapped) {
                    const origReset = window.resetVoucher;
                    const wrappedReset = function () {
                        self.pushUndoSnapshot('قبل تصفير السند (جديد)');
                        return origReset.apply(this, arguments);
                    };
                    wrappedReset.__mcpC7Wrapped = true;
                    window.resetVoucher = wrappedReset;
                }

                const btnNew = document.querySelector('.btn-new');
                if (btnNew && !btnNew.dataset.mcpC7Protected) {
                    btnNew.dataset.mcpC7Protected = '1';
                    btnNew.addEventListener('mousedown', () => {
                        self.pushUndoSnapshot('قبل تصفير السند (جديد)');
                    }, true);
                }

                // 4.b التقاط ضغطة حذف كتلة أو سطر بنكي أو شيك في مرحلة الالتقاط (Capture Phase) قبل الحذف الفعلي
                document.addEventListener('mousedown', (e) => {
                    const btn = e.target && e.target.closest
                        ? e.target.closest('[data-action="remove-block"], [data-action="remove-bank-row"], [data-action="remove-cheque-row"], .btn-remove-block')
                        : null;
                    if (!btn) return;
                    const act = btn.getAttribute('data-action') || 'remove-block';
                    const label = act === 'remove-bank-row'
                        ? 'قبل حذف سطر تحويلة بنكية'
                        : (act === 'remove-cheque-row' ? 'قبل حذف سطر شيك' : 'قبل حذف كتلة حساب فرعي');
                    self.pushUndoSnapshot(label);
                }, true);

                // 5. التقاط لقطة تراجع عند تعديل الخانات
                let undoChangeTimer = null;
                document.addEventListener('change', (e) => {
                    const el = e.target;
                    if (!el || el.closest('#mcpC4SmartGuideMicroHud')) return;
                    if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.tagName === 'SELECT') {
                        clearTimeout(undoChangeTimer);
                        undoChangeTimer = setTimeout(() => self.pushUndoSnapshot('تعديل خانة'), 380);
                    }
                }, { capture: true, passive: true });
            },

            // 4. العمل الكامل بالكيبورد 100% ودعم قارئ الباركود اللحظي (Hardware Barcode Wedge Scanner — Directive 3)
            initFullKeyboardAndBarcodeScanner() {
                const self = this;
                document.addEventListener('keydown', (e) => {
                    // اختصار التراجع الفوري الشامل (Ctrl+Z)
                    if ((e.ctrlKey || e.metaKey) && !e.shiftKey && (e.key === 'z' || e.key === 'Z' || e.key === 'ئ')) {
                        if (self.undoStack.length > 0) {
                            e.preventDefault();
                            self.restoreLastUndoSnapshot();
                            return;
                        }
                    }

                    // قارئ الباركود الليزري اللحظي (Hardware Barcode / QR Wedge Scanner)
                    if (!e.ctrlKey && !e.altKey && !e.metaKey) {
                        const now = performance.now();
                        if (e.key && e.key.length === 1) {
                            if (now - self.lastBarcodeKeyTime <= self.BARCODE_MAX_GAP_MS) {
                                self.barcodeBuffer += self.convertEasternDigitsToAscii(e.key);
                            } else {
                                self.barcodeBuffer = self.convertEasternDigitsToAscii(e.key);
                            }
                            self.lastBarcodeKeyTime = now;
                        } else if (e.key === 'Enter' && self.barcodeBuffer.length >= 4 && (now - self.lastBarcodeKeyTime <= 65)) {
                            const scannedCode = self.barcodeBuffer.trim();
                            self.barcodeBuffer = '';
                            self.handleScannedBarcode(scannedCode, e);
                        }
                    }
                }, true);
            },

            handleScannedBarcode(code, event) {
                if (!code) return;
                const cleanCode = this.cleanInvisibleAndDuplicateSpaces(code, true).toUpperCase();
                if (!cleanCode) return;

                const getTKey = (typeof window.getTenantKey === 'function') ? window.getTenantKey : ((k) => k);
                const payList = JSON.parse(localStorage.getItem(getTKey('erp_payments_v1')) || localStorage.getItem('erp_payments_v1') || '[]');
                const recList = JSON.parse(localStorage.getItem(getTKey('erp_receipts_v1')) || localStorage.getItem('erp_receipts_v1') || '[]');

                const matchesCode = (v) => {
                    if (!v) return false;
                    if (String(v.voucherNo || v.id || '').toUpperCase() === cleanCode) return true;
                    if (String(v.mobileTransferNo || '').toUpperCase() === cleanCode) return true;
                    if (Array.isArray(v.items)) {
                        return v.items.some(it => String(it?.transferNo || it?.checkNo || '').toUpperCase() === cleanCode);
                    }
                    return false;
                };

                let found = Array.isArray(payList) ? payList.find(matchesCode) : null;
                let foundType = 'payment';
                if (!found && Array.isArray(recList)) {
                    found = recList.find(matchesCode);
                    foundType = 'receipt';
                }

                if (found) {
                    if (event) event.preventDefault();
                    if (typeof window.executeSetVoucherType === 'function') {
                        window.executeSetVoucherType(foundType);
                    }
                    if (typeof window.loadVoucherIntoForm === 'function') {
                        window.loadVoucherIntoForm(found);
                    }
                    if (typeof window.showToast === 'function') {
                        window.showToast('🔫 تم قراءة الباركود وفتح السند المجمع (' + (found.voucherNo || found.id) + ') في 0ms!', 'success');
                    }
                }
            },

            // 5. الطب البصري: إضاءة السطر والكتلة النشطة التي يقف عليها الكيرسر لمنع انزلاق النظر (Directive 4)
            initMedicalAntiEyeSlipActiveRowLock() {
                let prevBlock = null;
                let prevRow = null;

                document.addEventListener('focusin', (e) => {
                    if (prevBlock) { prevBlock.classList.remove('mcp-c7-active-block'); prevBlock = null; }
                    if (prevRow) { prevRow.classList.remove('mcp-c7-active-row'); prevRow = null; }

                    const el = e.target;
                    if (!el || !el.closest) return;

                    const block = el.closest('.account-block');
                    if (block) {
                        block.classList.add('mcp-c7-active-block');
                        prevBlock = block;
                    }

                    const row = el.closest('.bank-row, .cheque-row, .block-cash-details, tr');
                    if (row) {
                        row.classList.add('mcp-c7-active-row');
                        prevRow = row;
                    }
                }, { capture: true, passive: true });
            },

            // 6. ربط الدستور السابع وإضافاته العالمية الخمس بالمرشد الذكي (Directives 6 & 7)
            registerWithSmartGuide() {
                window.MCP_DESKTOP_CONSTITUTION7_GUIDE = {
                    constitutionNumber: 7,
                    title: 'الدستور السابع: الأبجديات البرمجية التحتية، التراجع الفوري (Ctrl+Z)، اللصق الذكي، والطب البصري لراحة العين',
                    goldenRule: 'القاعدة الذهبية للأبجديات والطب البصري: اكتب بأي كيبورد عربي أو إنجليزي أو الصق مباشرة من الواتساب والإكسل؛ النظام يوحد الأرقام والفاصلة العشرية وينظف المسافات الوهمية في 0ms، ويحمي عينك بالمسطرة العمودية للأرقام وتظليل الكتلة النشطة، مع تراجع فوري آمن (Ctrl+Z) عن أي حذف أو تصفير.'
                };

                const c4 = window.McpDesktopConstitution4;
                const selectEl = document.getElementById('mcpC4StageJumpSelect');
                if (c4 && Array.isArray(c4.steps) && !c4.steps.some(s => s.id === 'step-c7-ophthalmic-ergonomics')) {
                    const stepIdx = c4.steps.length;
                    const c7Step = {
                        id: 'step-c7-ophthalmic-ergonomics',
                        title: '2️⃣1️⃣ الأبجديات البرمجية، التراجع الفوري (Ctrl+Z)، اللصق الذكي، والطب البصري لراحة العين',
                        svgStage: 'process',
                        showMap: false,
                        selector: '#mcpC7UndoBtn, #accounts-blocks-container .account-block:first-child',
                        goldenRule: 'القاعدة الذهبية للأبجديات والطب البصري: اكتب بأي كيبورد عربي أو إنجليزي أو الصق من الواتساب؛ النظام يوحد الأرقام والفاصلة العشرية تلقائياً، وزر (↩️ تراجع Ctrl+Z) يعيد أي سطر حذفته بالخطأ فوراً.',
                        action: () => {
                            if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups();
                        },
                        text: 'وهنا في الشريط العلوي يظهر زر التراجع الفوري متعدد المستويات مع اختصار كنترول زد؛ فإذا حذفت أي كتلة حساب فرعي أو تحويلة بنكية أو شيك أو ضغطت على زر جديد بالخطأ، ضغطة واحدة تعيد السطر والمبلغ كما كان في صفر ثانية. كما تعمل الشاشة بأبجديات توحيد الأرقام العربية والإنجليزية وتحويل الفاصلة العشرية العربية لنقطة تلقائياً، واللصق النظيف الذكي من الواتساب والإكسل، مع درع الطب البصري الذي يرتب الأرقام عمودياً بالمسطرة ويضيء الكتلة النشطة لمنع انزلاق النظر. القاعدة الذهبية: اعمل بأقصى سرعة؛ فكل فاصلة ورقم يُضبط تلقائياً، واختصار كنترول زد يحميك من أي حذف غير مقصود.'
                    };
                    c4.steps.push(c7Step);
                    if (selectEl) {
                        const opt = document.createElement('option');
                        opt.value = String(stepIdx);
                        opt.textContent = '2️⃣1️⃣ الأبجديات والتراجع (Ctrl+Z) والطب البصري لراحة العين';
                        selectEl.appendChild(opt);
                    }
                    const counterEl = document.getElementById('mcpC4StepCounterBadge');
                    if (counterEl) {
                        counterEl.textContent = (c4.currentStepIndex + 1) + ' / ' + c4.steps.length;
                    }
                }
            }
        };

        window.McpDesktopConstitution7 = McpDesktopConstitution7;
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => McpDesktopConstitution7.init());
        } else {
            McpDesktopConstitution7.init();
        }
    })();
    </script>

