    <script id="mcp-constitution-8-cognitive-ergonomics-engine">
    (function () {
        'use strict';
        if (window.McpDesktopConstitution8) return;

        const McpDesktopConstitution8 = {
            initialized: false,
            PARK_STORAGE_KEY: 'erp_mcp_parked_vouchers_v1',
            FOCUS_TUNNEL_KEY: 'erp_mcp_c8_focus_tunnel_v1',
            mathHistory: [],
            dismissedAnomalies: new Set(),
            dismissedDuplicates: new Set(),
            bypassDuplicateCheckOnce: false,
            historicalStatsCache: null,
            lastHistoricalCacheTime: 0,

            init() {
                if (this.initialized) return;
                this.initialized = true;

                this.initInlineMathCalculatorAndPreview();
                this.initInstantTafqeetAndZeroScaleRadar();
                this.initFatFingerAnomalyGuard();
                this.initOneClickParkAndResumeSystem();
                this.initAntiDuplicateTransactionGuard();
                this.initMuscleMemoryBalanceAndFocusTunnel();
                this.registerWithSmartGuide();
            },

            getTenantStorageKey(baseKey) {
                return (typeof window.getTenantKey === 'function') ? window.getTenantKey(baseKey) : baseKey;
            },

            cleanNumber(val) {
                if (typeof val === 'number') return isFinite(val) ? val : 0;
                const s = String(val || '')
                    .replace(/[\u0660-\u0669]/g, d => String(d.charCodeAt(0) - 0x0660))
                    .replace(/[\u06F0-\u06F9]/g, d => String(d.charCodeAt(0) - 0x06F0))
                    .replace(/,/g, '')
                    .trim();
                const n = parseFloat(s);
                return isFinite(n) ? n : 0;
            },

            formatCleanNumber(num, decimals = null) {
                if (typeof window.fmtNum === 'function') {
                    return window.fmtNum(num, decimals, true);
                }
                const n = Number(num) || 0;
                const dec = (decimals !== null && decimals !== undefined) ? decimals : (n % 1 !== 0 ? 2 : 0);
                const parts = n.toFixed(dec).split('.');
                parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
                return parts.join('.');
            },

            // ═══════════════════════════════════════════════════════════════════════════
            // 1. الآلة الحاسبة المدمجة داخل الخانات الرقمية + شريط المعادلة الحية (Directive 1 & Addition 1)
            // ═══════════════════════════════════════════════════════════════════════════
            normalizeMathExpression(rawStr) {
                if (typeof rawStr !== 'string') return '';
                let s = rawStr
                    .replace(/[\u0660-\u0669]/g, d => String(d.charCodeAt(0) - 0x0660))
                    .replace(/[\u06F0-\u06F9]/g, d => String(d.charCodeAt(0) - 0x06F0))
                    .replace(/[×✕xX]/g, '*')
                    .replace(/[÷]/g, '/')
                    .replace(/[و،٫ז]/g, '.')
                    .replace(/,/g, '')
                    .replace(/=/g, '')
                    .trim();

                // معالجة النسبة المئوية داخل المعادلة مثل 10000-10% أو 5000+15% أو 5000*15%
                s = s.replace(/(\d+(?:\.\d+)?)\s*([+\-])\s*(\d+(?:\.\d+)?)%/g, '($1 $2 ($1 * $3 / 100))');
                s = s.replace(/(\d+(?:\.\d+)?)%/g, '($1 / 100)');
                return s;
            },

            hasMathOperator(rawStr) {
                if (typeof rawStr !== 'string' || !rawStr) return false;
                const s = rawStr
                    .replace(/[\u0660-\u0669]/g, d => String(d.charCodeAt(0) - 0x0660))
                    .replace(/[\u06F0-\u06F9]/g, d => String(d.charCodeAt(0) - 0x06F0))
                    .replace(/,/g, '')
                    .trim();
                return /[+*/×÷%()]/.test(s) || /\d\s*-\s*\d*/.test(s);
            },

            computeSafeMathResult(rawStr) {
                if (!this.hasMathOperator(rawStr)) return null;
                const expr = this.normalizeMathExpression(rawStr);
                if (!expr) return null;
                // لازم ينتهي برقم أو قوس مغلق حتى تكون المعادلة مكتملة
                if (!/[\d)]$/.test(expr)) return null;
                if (!/^[0-9.+\-*/()\s]+$/.test(expr)) return null;
                // يجب وجود عملية حسابية فعلية بين رقمين
                if (!(/[+*/]/.test(expr) || /\d\s*-\s*\d/.test(expr))) return null;

                try {
                    const val = Function('"use strict"; return (' + expr + ')')();
                    if (typeof val === 'number' && isFinite(val) && val >= 0) {
                        return Math.round(val * 100) / 100;
                    }
                } catch (_) {}
                return null;
            },

            ensureMathPreviewPill() {
                let pill = document.getElementById('mcpC8MathPreviewPill');
                if (!pill) {
                    pill = document.createElement('div');
                    pill.id = 'mcpC8MathPreviewPill';
                    document.body.appendChild(pill);
                }
                return pill;
            },

            updateMathPreviewPill(inputEl) {
                const pill = this.ensureMathPreviewPill();
                if (!inputEl || !document.body.contains(inputEl)) {
                    pill.style.display = 'none';
                    return;
                }
                const raw = String(inputEl.value || '').trim();
                if (!this.hasMathOperator(raw)) {
                    pill.style.display = 'none';
                    return;
                }

                const result = this.computeSafeMathResult(raw);
                const prettyExpr = raw.replace(/\*/g, ' × ').replace(/\//g, ' ÷ ');
                const rect = inputEl.getBoundingClientRect();

                pill.innerHTML = result !== null
                    ? `<span>🧮 معادلة حية:</span> <b style="color:#fbbf24;direction:ltr;display:inline-block;">${prettyExpr}</b> <span>=</span> <b style="color:#34d399;font-size:0.95rem;">${this.formatCleanNumber(result)}</b> <button type="button" id="mcpC8ApplyMathNowBtn" style="background:#10b981;color:#fff;border:none;border-radius:6px;padding:2px 8px;font-size:0.74rem;font-weight:900;cursor:pointer;">تثبيت (Enter)</button>`
                    : `<span>🧮 جاري كتابة معادلة:</span> <b style="color:#fbbf24;direction:ltr;display:inline-block;">${prettyExpr}</b> <span style="color:#94a3b8;font-size:0.75rem;">(أكمل الرقم ثم اضغط Enter)</span>`;

                pill.style.display = 'inline-flex';
                const topPos = Math.max(8, rect.top - 42);
                const leftPos = Math.max(10, Math.min(window.innerWidth - 320, rect.left));
                pill.style.top = topPos + 'px';
                pill.style.left = leftPos + 'px';

                const applyBtn = pill.querySelector('#mcpC8ApplyMathNowBtn');
                if (applyBtn) {
                    applyBtn.onmousedown = (ev) => {
                        ev.preventDefault();
                        this.evaluateInlineMathOnInput(inputEl, true);
                    };
                }
            },

            evaluateInlineMathOnInput(inputEl, showFeedback = true) {
                if (!inputEl || inputEl.readOnly || inputEl.disabled) return false;
                const raw = String(inputEl.value || '').trim();
                const result = this.computeSafeMathResult(raw);
                if (result === null) return false;

                if (window.McpDesktopConstitution7 && typeof window.McpDesktopConstitution7.pushUndoSnapshot === 'function') {
                    window.McpDesktopConstitution7.pushUndoSnapshot('حاسبة مدمجة (' + raw + ')');
                }

                const formatted = this.formatCleanNumber(result);
                inputEl.value = formatted;
                inputEl.dataset.lastMathExpr = `${raw} = ${formatted}`;
                this.mathHistory.unshift({ expr: raw, result: formatted, at: new Date().toLocaleTimeString('en-GB') });
                if (this.mathHistory.length > 8) this.mathHistory.pop();

                const pill = document.getElementById('mcpC8MathPreviewPill');
                if (pill) pill.style.display = 'none';

                const block = inputEl.closest('.account-block');
                if (block) {
                    const bid = block.getAttribute('data-block-id');
                    if (typeof window.recalcBlockTotal === 'function') window.recalcBlockTotal(bid);
                    if (typeof window.updateBlockTafqeetAndTier === 'function') window.updateBlockTafqeetAndTier(bid);
                }
                if (typeof window.calcTotal === 'function') window.calcTotal();
                inputEl.dispatchEvent(new Event('change', { bubbles: true }));

                if (showFeedback && typeof window.showToast === 'function') {
                    window.showToast(`🧮 الحاسبة المدمجة: ${raw} = ${formatted}`, 'info', 1700);
                }
                return true;
            },

            initInlineMathCalculatorAndPreview() {
                const self = this;
                const mathSelector = '.block-cash-amount, .block-bank-amount, .block-cheque-amount, .block-sub-amount, .transfer-amount, .cheque-amount, #mcp-split-total-input, #exchange-rate';

                // ترقية window.formatWhileTyping حتى لا يحذف إشارة الطرح (-) أو الضرب (*) أو القسمة (/) أو الأقواس أثناء كتابة المعادلة
                if (typeof window.formatWhileTyping === 'function' && !window.formatWhileTyping.__mcpC8Wrapped) {
                    const origFormatWhileTyping = window.formatWhileTyping;
                    const wrappedFormat = function (input) {
                        if (!input) return;
                        const raw = String(input.value || '');
                        if (self.hasMathOperator(raw)) {
                            const cleaned = raw
                                .replace(/[\u0660-\u0669]/g, d => String(d.charCodeAt(0) - 0x0660))
                                .replace(/[\u06F0-\u06F9]/g, d => String(d.charCodeAt(0) - 0x06F0))
                                .replace(/[×✕xX]/g, '*')
                                .replace(/[÷]/g, '/')
                                .replace(/[^0-9.,+\-*/%()\s]/g, '');
                            if (input.value !== cleaned) input.value = cleaned;
                            self.updateMathPreviewPill(input);
                            return;
                        }
                        return origFormatWhileTyping.apply(this, arguments);
                    };
                    wrappedFormat.__mcpC8Wrapped = true;
                    window.formatWhileTyping = wrappedFormat;
                }

                // ربط window.evaluateMcpInlineMath بالمحرك المطور
                window.evaluateMcpInlineMath = function (inputEl) {
                    return self.evaluateInlineMathOnInput(inputEl, true);
                };

                // تحديث شريط المعادلة الحية أثناء الكتابة
                document.addEventListener('input', (e) => {
                    const t = e.target;
                    if (t && t.matches && t.matches(mathSelector)) {
                        self.updateMathPreviewPill(t);
                    }
                }, true);

                // حساب المعادلة وتثبيت الناتج الصافي فور ضغط Enter أو Tab أو (=) في 0ms قبل انتقال الكيرسر للخانة التالية
                document.addEventListener('keydown', (e) => {
                    const t = e.target;
                    if (!t || !t.matches || !t.matches(mathSelector)) return;
                    if (e.key === 'Enter' || e.key === 'Tab' || e.key === '=') {
                        if (self.hasMathOperator(t.value)) {
                            const evaluated = self.evaluateInlineMathOnInput(t, true);
                            if (e.key === '=' && evaluated) {
                                e.preventDefault();
                            }
                        }
                    } else if (e.key === 'Escape') {
                        const pill = document.getElementById('mcpC8MathPreviewPill');
                        if (pill) pill.style.display = 'none';
                    }
                }, true);

                document.addEventListener('focusout', (e) => {
                    const t = e.target;
                    if (t && t.matches && t.matches(mathSelector)) {
                        self.evaluateInlineMathOnInput(t, true);
                        setTimeout(() => {
                            const pill = document.getElementById('mcpC8MathPreviewPill');
                            if (pill) pill.style.display = 'none';
                        }, 120);
                    }
                }, true);
            },

            // ═══════════════════════════════════════════════════════════════════════════
            // 2. التفقيط العربي اللحظي بالحروف + مقياس الأصفار لمنع خداع الأصفار (Directive 2 & Addition 2)
            // ═══════════════════════════════════════════════════════════════════════════
            describeZeroScale(amount) {
                const n = Math.floor(Math.abs(this.cleanNumber(amount)));
                if (n <= 0) return { text: '0 أصفار', tier: 'zero' };
                const digits = String(n).length - 1;
                let trailingZeros = 0;
                const s = String(n);
                for (let i = s.length - 1; i >= 0; i--) {
                    if (s[i] === '0') trailingZeros++;
                    else break;
                }
                let scaleName = 'آحاد/عشرات';
                if (digits === 2) scaleName = 'مئات';
                else if (digits === 3) scaleName = 'آلاف (1,000)';
                else if (digits === 4) scaleName = 'عشرات الآلاف (10,000)';
                else if (digits === 5) scaleName = 'مئات الآلاف (100,000)';
                else if (digits === 6) scaleName = 'ملايين (1,000,000)';
                else if (digits === 7) scaleName = 'عشرات الملايين (10M)';
                else if (digits === 8) scaleName = 'مئات الملايين (100M)';
                else if (digits >= 9) scaleName = 'مليارات (1B+)';

                return {
                    digits,
                    trailingZeros,
                    scaleName,
                    text: `🔢 ${trailingZeros > 0 ? trailingZeros + ' أصفار' : 'خانة ' + (digits + 1)} • ${scaleName}`
                };
            },

            updateAllZeroScaleBadges() {
                const curr = document.getElementById('currency')?.value || 'SDG';
                // 1. شارة الإجمالي الكلي للسند
                const grandContainer = document.getElementById('grand-tafqeet-container');
                const localHdr = document.getElementById('amount-local-hdr');
                const foreignHdr = document.getElementById('amount-foreign');
                const grandVal = curr === 'SDG'
                    ? this.cleanNumber(localHdr?.value || 0)
                    : this.cleanNumber(foreignHdr?.value || 0);

                if (grandContainer) {
                    let badge = document.getElementById('mcpC8GrandZeroScaleBadge');
                    if (!badge) {
                        badge = document.createElement('span');
                        badge.id = 'mcpC8GrandZeroScaleBadge';
                        badge.title = 'مقياس الأصفار والمرتبة الرقمية لمنع الخلط بين 100,000 و 1,000,000';
                        const firstDiv = grandContainer.querySelector('div');
                        if (firstDiv) firstDiv.appendChild(badge);
                        else grandContainer.appendChild(badge);
                    }
                    const info = this.describeZeroScale(grandVal);
                    badge.textContent = info.text;
                }

                // 2. شارة كل بطاقة حساب فرعي
                document.querySelectorAll('.account-block').forEach(block => {
                    const bid = block.getAttribute('data-block-id');
                    const rowEl = document.getElementById(`tafqeet-row-${bid}`);
                    const amtEl = document.getElementById(`amount-${bid}`);
                    if (!rowEl || !amtEl) return;
                    const val = this.cleanNumber(amtEl.value);
                    let bBadge = rowEl.querySelector('.mcp-c8-block-zero-scale');
                    if (!bBadge) {
                        bBadge = document.createElement('span');
                        bBadge.className = 'mcp-c8-block-zero-scale';
                        const leftBox = rowEl.querySelector('div');
                        if (leftBox) leftBox.appendChild(bBadge);
                    }
                    if (val > 0) {
                        bBadge.textContent = this.describeZeroScale(val).text;
                        bBadge.style.display = 'inline-flex';
                    } else {
                        bBadge.style.display = 'none';
                    }
                });
            },

            initInstantTafqeetAndZeroScaleRadar() {
                const self = this;

                // تحديث فوري لشارات الأصفار والتفقيط مع كل عملية حساب للإجمالي
                if (typeof window.calcTotal === 'function' && !window.calcTotal.__mcpC8TafqeetWrapped) {
                    const origCalcTotal = window.calcTotal;
                    const wrappedCalc = function () {
                        const res = origCalcTotal.apply(this, arguments);
                        self.updateAllZeroScaleBadges();
                        self.runSilentDoubleEntryBalanceCheck();
                        return res;
                    };
                    wrappedCalc.__mcpC8TafqeetWrapped = true;
                    window.calcTotal = wrappedCalc;
                }

                // دعم التفقيط اللحظي داخل الشاشات الوليدة (مثل نافذة توزيع مبلغ إجمالي #mcp-split-total-input) وتحديث شارات الأصفار والتوازن لحظياً
                let zeroScaleSyncTimer = null;
                document.addEventListener('input', (e) => {
                    const t = e.target;
                    if (!t) return;
                    if (t.id === 'mcp-split-total-input') {
                        let splitTafEl = document.getElementById('mcp-split-live-tafqeet');
                        if (!splitTafEl && t.parentElement) {
                            splitTafEl = document.createElement('div');
                            splitTafEl.id = 'mcp-split-live-tafqeet';
                            splitTafEl.style.cssText = 'margin-top:6px; padding:6px 10px; border-radius:8px; background:rgba(245,158,11,0.14); border:1.5px solid rgba(251,191,36,0.45); color:#fef08a; font-weight:800; font-size:0.86rem; display:flex; justify-content:space-between; align-items:center; gap:8px;';
                            t.parentElement.appendChild(splitTafEl);
                        }
                        if (splitTafEl && typeof window.formatArabicTafqeet === 'function') {
                            const v = self.cleanNumber(t.value);
                            const curr = document.getElementById('currency')?.value || 'SDG';
                            const scale = self.describeZeroScale(v);
                            splitTafEl.innerHTML = `<span>📜 ${window.formatArabicTafqeet(v, curr)}</span><span class="mcp-c8-block-zero-scale">${scale.text}</span>`;
                        }
                    }
                    clearTimeout(zeroScaleSyncTimer);
                    zeroScaleSyncTimer = setTimeout(() => {
                        self.updateAllZeroScaleBadges();
                        self.runSilentDoubleEntryBalanceCheck();
                    }, 30);
                }, true);

                document.addEventListener('change', () => {
                    setTimeout(() => {
                        self.updateAllZeroScaleBadges();
                        self.runSilentDoubleEntryBalanceCheck();
                    }, 30);
                }, true);

                setTimeout(() => this.updateAllZeroScaleBadges(), 180);
            },

            // ═══════════════════════════════════════════════════════════════════════════
            // 3. حارس الإرهاق الذكي لكشف الأرقام الشاذة وأخطاء الأصابع (Fat-Finger Anomaly Guard — Directive 3 & Addition 3)
            // ═══════════════════════════════════════════════════════════════════════════
            getHistoricalAccountStats() {
                const now = Date.now();
                if (this.historicalStatsCache && (now - this.lastHistoricalCacheTime < 15000)) {
                    return this.historicalStatsCache;
                }
                const stats = {};
                const addEntry = (accKey, amt) => {
                    if (!accKey || amt <= 0) return;
                    const k = String(accKey).trim().toLowerCase();
                    if (!stats[k]) stats[k] = { sum: 0, count: 0, max: 0, min: Infinity };
                    stats[k].sum += amt;
                    stats[k].count += 1;
                    if (amt > stats[k].max) stats[k].max = amt;
                    if (amt < stats[k].min) stats[k].min = amt;
                };

                ['erp_payments_v1', 'erp_receipts_v1'].forEach(baseKey => {
                    try {
                        const tKey = this.getTenantStorageKey(baseKey);
                        const arr = JSON.parse(localStorage.getItem(tKey) || localStorage.getItem(baseKey) || '[]');
                        if (!Array.isArray(arr)) return;
                        arr.forEach(v => {
                            if (!v || v.deleted) return;
                            if (Array.isArray(v.items)) {
                                v.items.forEach(it => {
                                    const a = this.cleanNumber(it?.amount || 0);
                                    addEntry(it?.accountId || it?.account, a);
                                    addEntry(it?.accountName, a);
                                });
                            }
                        });
                    } catch (_) {}
                });

                this.historicalStatsCache = stats;
                this.lastHistoricalCacheTime = now;
                return stats;
            },

            inspectInputForFatFingerAnomaly(inputEl) {
                if (!inputEl || !inputEl.classList) return;
                const val = this.cleanNumber(inputEl.value);

                // فحص خاص لسعر الصرف (#exchange-rate) إذا قفز لأضعاف السعر المرجعي أو هبط أقل بكثير من التكلفة/المعيار
                if (inputEl.id === 'exchange-rate') {
                    const sysRate = (typeof window.getSystemUsdRate === 'function' ? window.getSystemUsdRate() : 5999) || 5999;
                    if (val > 0 && (val >= sysRate * 2.5 || val <= sysRate * 0.4)) {
                        inputEl.classList.add('mcp-c8-amber-anomaly-pulse');
                        const grandAlert = document.getElementById('grand-fat-finger-alert');
                        if (grandAlert) {
                            grandAlert.style.display = 'inline-flex';
                            grandAlert.className = 'alert-badge-mega';
                            grandAlert.innerHTML = `⚠️ حارس الإرهاق: سعر الصرف (${this.formatCleanNumber(val)}) يختلف بشدة عن السعر المعتمد (${this.formatCleanNumber(sysRate)})`;
                        }
                    } else {
                        inputEl.classList.remove('mcp-c8-amber-anomaly-pulse');
                    }
                    return;
                }

                const block = inputEl.closest('.account-block');
                if (!block) return;
                const bid = block.getAttribute('data-block-id');
                const alertEl = document.getElementById(`tafqeet-alert-${bid}`);
                const rowEl = document.getElementById(`tafqeet-row-${bid}`);

                if (val <= 0) {
                    inputEl.classList.remove('mcp-c8-amber-anomaly-pulse');
                    return;
                }

                const accId = (document.getElementById(`account-${bid}-id`)?.value || '').trim().toLowerCase();
                const accName = (document.getElementById(`account-${bid}-search`)?.value || '').trim().toLowerCase();
                const dismissKey = `${bid}:${accId || accName}:${val}`;
                if (this.dismissedAnomalies.has(dismissKey)) {
                    inputEl.classList.remove('mcp-c8-amber-anomaly-pulse');
                    return;
                }

                const histMap = this.getHistoricalAccountStats();
                const hist = (accId && histMap[accId]) || (accName && histMap[accName]) || null;
                const curr = document.getElementById('currency')?.value || 'SDG';
                const megaThreshold = (curr === 'SDG') ? 1000000 : 1000;

                // حساب متوسط السطور الأخرى في نفس السند المجمع لكشف إذا زاد المحاسب صفراً في سطر واحد بالخطأ
                const peerAmounts = [];
                document.querySelectorAll('.account-block').forEach(b => {
                    const otherBid = b.getAttribute('data-block-id');
                    if (otherBid === bid) return;
                    const otherAmt = this.cleanNumber(document.getElementById(`amount-${otherBid}`)?.value || 0);
                    if (otherAmt > 0) peerAmounts.push(otherAmt);
                });
                const peerAvg = peerAmounts.length > 0
                    ? (peerAmounts.reduce((a, b) => a + b, 0) / peerAmounts.length)
                    : 0;

                let anomalyReason = '';
                if (hist && hist.count >= 1) {
                    const avg = Math.round(hist.sum / hist.count);
                    if (avg > 0 && val >= avg * 4) {
                        const mult = Math.round((val / avg) * 10) / 10;
                        anomalyReason = `⚠️ حارس الإرهاق: الرقم (${this.formatCleanNumber(val)}) يساوي ${mult}× المعدل التاريخي لهذا الحساب (${this.formatCleanNumber(avg)})`;
                    } else if (avg >= 1000 && val <= avg * 0.12) {
                        anomalyReason = `⚠️ حارس الإرهاق: الرقم (${this.formatCleanNumber(val)}) أقل بكثير من المعدل المعتاد لهذا الحساب (${this.formatCleanNumber(avg)})`;
                    }
                }
                if (!anomalyReason && peerAvg > 0 && val >= peerAvg * 7) {
                    anomalyReason = `⚠️ حارس الإرهاق: هذا السطر (${this.formatCleanNumber(val)}) أعلى بكثير من متوسط بقية سطور الدفعة (${this.formatCleanNumber(Math.round(peerAvg))})`;
                }
                if (!anomalyReason && val >= megaThreshold) {
                    anomalyReason = `👑 تنبيه أصفار: مبلغ كبير (${this.formatCleanNumber(val)} ${curr}) — راجع عدد الأصفار`;
                }

                if (anomalyReason) {
                    inputEl.classList.add('mcp-c8-amber-anomaly-pulse');
                    if (rowEl) rowEl.style.display = 'flex';
                    if (alertEl) {
                        alertEl.className = 'block-fat-finger-alert alert-badge-mega';
                        alertEl.style.display = 'inline-flex';
                        alertEl.innerHTML = `
                            <span>${anomalyReason}</span>
                            <button type="button" class="mcp-c8-div10-btn" style="background:#f59e0b;color:#0f172a;border:none;border-radius:5px;padding:1px 7px;font-size:0.74rem;font-weight:900;cursor:pointer;" title="حذف صفر زائد بالخطأ (القسمة على 10)">⚡ ÷10</button>
                            <button type="button" class="mcp-c8-ok-btn" style="background:rgba(16,185,129,0.25);color:#6ee7b7;border:1px solid #10b981;border-radius:5px;padding:1px 7px;font-size:0.74rem;font-weight:900;cursor:pointer;" title="تأكيد صحة الرقم وإخفاء الوميض الكهرماني">✓ صحيح</button>
                        `;
                        const div10Btn = alertEl.querySelector('.mcp-c8-div10-btn');
                        if (div10Btn) {
                            div10Btn.onclick = (ev) => {
                                ev.preventDefault();
                                ev.stopPropagation();
                                const corrected = Math.round((val / 10) * 100) / 100;
                                inputEl.value = this.formatCleanNumber(corrected);
                                inputEl.classList.remove('mcp-c8-amber-anomaly-pulse');
                                inputEl.dispatchEvent(new Event('input', { bubbles: true }));
                                if (typeof window.recalcBlockTotal === 'function') window.recalcBlockTotal(bid);
                                if (typeof window.calcTotal === 'function') window.calcTotal();
                                if (typeof window.showToast === 'function') {
                                    window.showToast(`⚡ تم تصحيح الصفر الزائد ليصبح: ${this.formatCleanNumber(corrected)}`, 'success', 1600);
                                }
                            };
                        }
                        const okBtn = alertEl.querySelector('.mcp-c8-ok-btn');
                        if (okBtn) {
                            okBtn.onclick = (ev) => {
                                ev.preventDefault();
                                ev.stopPropagation();
                                this.dismissedAnomalies.add(dismissKey);
                                inputEl.classList.remove('mcp-c8-amber-anomaly-pulse');
                                alertEl.style.display = 'none';
                            };
                        }
                    }
                } else {
                    inputEl.classList.remove('mcp-c8-amber-anomaly-pulse');
                }
            },

            initFatFingerAnomalyGuard() {
                const self = this;
                const amountSelector = '.block-cash-amount, .block-bank-amount, .block-cheque-amount, .block-sub-amount, #exchange-rate';

                document.addEventListener('input', (e) => {
                    const t = e.target;
                    if (t && t.matches && t.matches(amountSelector)) {
                        self.inspectInputForFatFingerAnomaly(t);
                    }
                }, true);

                document.addEventListener('change', (e) => {
                    const t = e.target;
                    if (t && t.matches && t.matches(amountSelector)) {
                        self.inspectInputForFatFingerAnomaly(t);
                    }
                }, true);
            },

            // ═══════════════════════════════════════════════════════════════════════════
            // 4. ميزة "تعليق الفاتورة/السند بضغطة زر" لمنع توتر الزحام (One-Click Park & Resume — Directive 4 & Addition 4)
            // ═══════════════════════════════════════════════════════════════════════════
            getParkedVouchersList() {
                try {
                    const key = this.getTenantStorageKey(this.PARK_STORAGE_KEY);
                    const raw = localStorage.getItem(key) || localStorage.getItem(this.PARK_STORAGE_KEY) || '[]';
                    const arr = JSON.parse(raw);
                    return Array.isArray(arr) ? arr : [];
                } catch (_) {
                    return [];
                }
            },

            saveParkedVouchersList(list) {
                try {
                    const key = this.getTenantStorageKey(this.PARK_STORAGE_KEY);
                    const json = JSON.stringify(Array.isArray(list) ? list : []);
                    localStorage.setItem(key, json);
                    localStorage.setItem(this.PARK_STORAGE_KEY, json);
                } catch (_) {}
            },

            ensureParkedBarAndButtons() {
                // 1. الشريط العلوي المصغر للسندات المعلقة (#mcpC8ParkedVouchersBar)
                const mainPanel = document.getElementById('main-form-panel');
                const topRow = document.getElementById('payment-methods-row');
                if (mainPanel && topRow && !document.getElementById('mcpC8ParkedVouchersBar')) {
                    const bar = document.createElement('div');
                    bar.id = 'mcpC8ParkedVouchersBar';
                    mainPanel.insertBefore(bar, topRow);
                }

                // 2. زر "⏸️ تعليق مؤقت" في شريط الإجراءات السفلي الموحد (#btn-mcp-park-voucher)
                const footerBar = document.querySelector('.footer-actions.unified-footer-bar');
                const btnNew = document.getElementById('btn-new');
                if (footerBar && !document.getElementById('btn-mcp-park-voucher')) {
                    const parkBtn = document.createElement('button');
                    parkBtn.type = 'button';
                    parkBtn.id = 'btn-mcp-park-voucher';
                    parkBtn.className = 'btn crystal-btn';
                    parkBtn.title = 'تعليق السند الحالي مؤقتاً في الشريط العلوي وتفريغ الشاشة لخدمة العميل المستعجل (F8 / Alt+P)';
                    parkBtn.setAttribute('data-guide-title', '⏸️ زر تعليق السند مؤقتاً بضغطة زر (One-Click Park & Resume — F8)');
                    parkBtn.setAttribute('data-golden-rule', 'القاعدة الذهبية: عند ازدحام الخزينة أو تأخر العميل، اضغط (⏸️ تعليق مؤقت F8) لخدمة العميل التالي فوراً ثم استرجع السند المعلق بضغطة واحدة.');
                    parkBtn.innerHTML = `<span class="btn-icon">⏸️</span> <span>تعليق مؤقت</span> <kbd class="shortcut-kbd">F8</kbd>`;
                    parkBtn.onclick = () => this.parkCurrentVoucher();
                    if (btnNew && btnNew.nextSibling) {
                        footerBar.insertBefore(parkBtn, btnNew.nextSibling);
                    } else {
                        footerBar.appendChild(parkBtn);
                    }
                }

                // 3. زر سريع في الشريط العلوي (#btn-mcp-park-top) + زر نفق التركيز (#mcpC8FocusTunnelBtn)
                const undoBtn = document.getElementById('mcpC7UndoBtn') || document.getElementById('mcp-2g-resilience-badge');
                if (undoBtn && undoBtn.parentElement && !document.getElementById('btn-mcp-park-top')) {
                    const topParkBtn = document.createElement('button');
                    topParkBtn.type = 'button';
                    topParkBtn.id = 'btn-mcp-park-top';
                    topParkBtn.title = 'تعليق السند الحالي مؤقتاً بضغطة واحدة (F8 / Alt+P)';
                    topParkBtn.innerHTML = `<span>⏸️ تعليق</span><span id="mcpC8ParkedCountBadge" style="background:#d97706;color:#fff;padding:0 6px;border-radius:999px;font-size:0.7rem;">0</span>`;
                    topParkBtn.onclick = () => this.parkCurrentVoucher();
                    undoBtn.insertAdjacentElement('afterend', topParkBtn);

                    const tunnelBtn = document.createElement('button');
                    tunnelBtn.type = 'button';
                    tunnelBtn.id = 'mcpC8FocusTunnelBtn';
                    tunnelBtn.title = 'تفعيل/إيقاف نفق التركيز البصري لتهدئة البطاقات غير النشطة (Alt+F)';
                    tunnelBtn.innerHTML = `<span>🎯 نفق التركيز</span>`;
                    tunnelBtn.onclick = () => this.toggleFocusTunnel();
                    topParkBtn.insertAdjacentElement('afterend', tunnelBtn);
                }
            },

            parkCurrentVoucher(silentIfSwap = false) {
                if (!window.McpDesktopConstitution7 || typeof window.McpDesktopConstitution7.captureFullMultiVoucherState !== 'function') {
                    return false;
                }
                const snap = window.McpDesktopConstitution7.captureFullMultiVoucherState('سند معلق مؤقتاً');
                const totalLocal = this.cleanNumber(document.getElementById('amount-local-hdr')?.value || 0);
                const totalForeign = this.cleanNumber(document.getElementById('amount-foreign')?.value || 0);
                const curr = document.getElementById('currency')?.value || 'SDG';
                const displayTotal = (curr === 'SDG') ? totalLocal : totalForeign;

                // التحقق من وجود بيانات فعلية لتعليقها
                const hasAccounts = snap.blocks.some(b => (b.accountName && b.accountName.trim()) || this.cleanNumber(b.cashRaw) > 0 || (b.bankRows && b.bankRows.some(r => this.cleanNumber(r.amountRaw) > 0)) || (b.chequeRows && b.chequeRows.some(r => this.cleanNumber(r.amountRaw) > 0)));
                if (!hasAccounts && !snap.header.desc.trim() && displayTotal <= 0) {
                    if (!silentIfSwap && typeof window.showToast === 'function') {
                        window.showToast('ℹ️ الشاشة فارغة حالياً؛ أدخل حساباً أو مبلغاً أولاً لتعليقه مؤقتاً.', 'info');
                    }
                    return false;
                }

                const partyNames = snap.blocks
                    .map(b => (b.accountName || '').trim())
                    .filter(Boolean);
                const summaryLabel = partyNames.length > 0
                    ? (partyNames[0] + (partyNames.length > 1 ? ` + ${partyNames.length - 1} جهات` : ''))
                    : (snap.header.mainAccountName || 'سند قيد الإدخال');

                const parkedItem = {
                    parkId: 'PARK-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6),
                    parkedAt: new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' }),
                    type: snap.header.type || 'payment',
                    summaryLabel: summaryLabel,
                    blocksCount: snap.blocks.length,
                    totalFormatted: this.formatCleanNumber(displayTotal) + ' ' + curr,
                    snapshot: snap
                };

                const list = this.getParkedVouchersList();
                list.unshift(parkedItem);
                if (list.length > 12) list.pop();
                this.saveParkedVouchersList(list);
                this.renderParkedVouchersBar();

                if (!silentIfSwap) {
                    // تفريغ الشاشة فوراً في 0ms لخدمة العميل المستعجل التالي بدون رسائل تأكيد معطلة
                    this.clearScreenForNextCustomer();
                    if (typeof window.showToast === 'function') {
                        window.showToast(`⏸️ تم تعليق السند (${summaryLabel}) في الشريط العلوي وتفريغ الشاشة فوراً لخدمة العميل التالي!`, 'success', 2600);
                    }
                }
                return true;
            },

            clearScreenForNextCustomer() {
                const container = document.getElementById('accounts-blocks-container');
                if (container && typeof window.addAccountBlock === 'function') {
                    container.innerHTML = '';
                    if (typeof window.blockCounter !== 'undefined') window.blockCounter = 0;
                    window.addAccountBlock();
                }
                const descEl = document.getElementById('voucher-desc');
                if (descEl) descEl.value = '';
                const refEl = document.getElementById('voucher-ref');
                if (refEl) refEl.value = '';
                if (typeof window.loadNextMultiVoucherNumber === 'function') {
                    try { window.loadNextMultiVoucherNumber(); } catch (_) {}
                }
                if (typeof window.calcTotal === 'function') {
                    try { window.calcTotal(); } catch (_) {}
                }
                if (typeof window.formDirty !== 'undefined') window.formDirty = false;
                const firstSearch = document.querySelector('.account-block .block-account-search');
                if (firstSearch) {
                    setTimeout(() => { try { firstSearch.focus(); } catch (_) {} }, 30);
                }
            },

            resumeParkedVoucher(parkId) {
                const list = this.getParkedVouchersList();
                const idx = list.findIndex(item => item && item.parkId === parkId);
                if (idx === -1) return;

                const targetItem = list[idx];
                // إذا كانت الشاشة الحالية تحتوي على بيانات غير محفوظة، نعلقها تلقائياً حتى لا يضيع حرف واحد (Smart Swap)
                if (window.McpDesktopConstitution7 && typeof window.McpDesktopConstitution7.captureFullMultiVoucherState === 'function') {
                    const curSnap = window.McpDesktopConstitution7.captureFullMultiVoucherState('Current');
                    const curHasData = curSnap.blocks.some(b => (b.accountName && b.accountName.trim()) || this.cleanNumber(b.cashRaw) > 0 || (b.bankRows && b.bankRows.some(r => this.cleanNumber(r.amountRaw) > 0)));
                    if (curHasData && curSnap.signature !== targetItem.snapshot?.signature) {
                        this.parkCurrentVoucher(true);
                    }
                }

                // إزالة السند المسترجع من قائمة المعلقات وتطبيقه فوراً في الشاشة
                const updatedList = this.getParkedVouchersList().filter(item => item && item.parkId !== parkId);
                this.saveParkedVouchersList(updatedList);
                this.renderParkedVouchersBar();

                if (window.McpDesktopConstitution7 && typeof window.McpDesktopConstitution7.applyMultiVoucherSnapshot === 'function') {
                    window.McpDesktopConstitution7.applyMultiVoucherSnapshot(targetItem.snapshot);
                }
                if (typeof window.showToast === 'function') {
                    window.showToast(`▶️ تم استرجاع السند المعلق (${targetItem.summaryLabel}) بكامل سطوره وبياناته بنجاح!`, 'success', 2200);
                }
            },

            deleteParkedVoucher(parkId, ev) {
                if (ev) {
                    ev.preventDefault();
                    ev.stopPropagation();
                }
                const list = this.getParkedVouchersList().filter(item => item && item.parkId !== parkId);
                this.saveParkedVouchersList(list);
                this.renderParkedVouchersBar();
                if (typeof window.showToast === 'function') {
                    window.showToast('🗑️ تم إزالة المسودة المعلقة من الشريط العلوي.', 'info', 1400);
                }
            },

            renderParkedVouchersBar() {
                this.ensureParkedBarAndButtons();
                const bar = document.getElementById('mcpC8ParkedVouchersBar');
                const countBadge = document.getElementById('mcpC8ParkedCountBadge');
                const list = this.getParkedVouchersList();

                if (countBadge) countBadge.textContent = String(list.length);
                if (!bar) return;

                if (list.length === 0) {
                    bar.style.display = 'none';
                    bar.innerHTML = '';
                    return;
                }

                bar.style.display = 'flex';
                const pillsHtml = list.map((item, i) => {
                    const typeBadge = item.type === 'receipt'
                        ? `<span style="background:rgba(16,185,129,0.22);color:#34d399;padding:1px 6px;border-radius:5px;font-size:0.72rem;">قبض</span>`
                        : `<span style="background:rgba(244,63,94,0.22);color:#fda4af;padding:1px 6px;border-radius:5px;font-size:0.72rem;">صرف</span>`;
                    return `
                        <div class="mcp-c8-parked-pill" data-park-id="${item.parkId}" title="اضغط لاسترجاع هذا السند المعلق بكامل بياناته فوراً">
                            <span>⏸️ #${i + 1}</span>
                            ${typeBadge}
                            <span style="max-width:170px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${item.summaryLabel}</span>
                            <b style="color:#fbbf24;font-family:monospace;">${item.totalFormatted}</b>
                            <span style="color:#94a3b8;font-size:0.72rem;">🕒 ${item.parkedAt}</span>
                            <button type="button" class="mcp-c8-parked-resume-btn" data-resume-id="${item.parkId}">▶️ استرجاع</button>
                            <button type="button" class="mcp-c8-parked-del-btn" data-del-id="${item.parkId}" title="حذف من المعلقات">✕</button>
                        </div>
                    `;
                }).join('');

                bar.innerHTML = `
                    <div style="display:flex;align-items:center;gap:8px;font-weight:900;font-size:0.88rem;color:#fbbf24;flex-shrink:0;">
                        <span>⏸️ سندات معلقة بانتظار الاستكمال (${list.length}):</span>
                    </div>
                    <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;flex:1;">
                        ${pillsHtml}
                    </div>
                `;

                bar.querySelectorAll('.mcp-c8-parked-pill').forEach(pill => {
                    const pid = pill.getAttribute('data-park-id');
                    pill.onclick = (e) => {
                        if (e.target && e.target.getAttribute('data-del-id')) return;
                        this.resumeParkedVoucher(pid);
                    };
                });
                bar.querySelectorAll('.mcp-c8-parked-del-btn').forEach(btn => {
                    const pid = btn.getAttribute('data-del-id');
                    btn.onclick = (e) => this.deleteParkedVoucher(pid, e);
                });
            },

            initOneClickParkAndResumeSystem() {
                const self = this;
                this.ensureParkedBarAndButtons();
                this.renderParkedVouchersBar();

                window.parkCurrentMultiVoucher = () => self.parkCurrentVoucher(false);
                window.resumeParkedMultiVoucher = (id) => self.resumeParkedVoucher(id);

                document.addEventListener('keydown', (e) => {
                    if (e.key === 'F8' || (e.altKey && (e.key === 'p' || e.key === 'P' || e.key === 'ح'))) {
                        e.preventDefault();
                        self.parkCurrentVoucher(false);
                    }
                }, true);
            },

            // ═══════════════════════════════════════════════════════════════════════════
            // 5. رادار منع "تكرار نفس الفاتورة أو السند بالخطأ" في نفس اليوم (Anti-Duplicate Transaction Guard — Directive 5)
            // ═══════════════════════════════════════════════════════════════════════════
            findMatchingSameDayTransaction() {
                const type = document.getElementById('voucher-type')?.value || 'payment';
                const today = document.getElementById('voucher-date')?.value || new Date().toISOString().split('T')[0];
                const currentVNo = (document.getElementById('voucher-no-display')?.value || '').trim();

                // إذا كنا في وضع تعديل سند محفوظ مسبقاً، نتجاهل السند نفسه
                let isEditingExisting = false;
                try {
                    if (typeof currentVoucherIndex !== 'undefined' && currentVoucherIndex !== -1) {
                        isEditingExisting = true;
                    }
                } catch (_) {}

                const activePairs = [];
                document.querySelectorAll('.account-block').forEach(block => {
                    const bid = block.getAttribute('data-block-id');
                    const accName = (document.getElementById(`account-${bid}-search`)?.value || '').trim();
                    const accId = (document.getElementById(`account-${bid}-id`)?.value || '').trim();
                    const amt = this.cleanNumber(document.getElementById(`amount-${bid}`)?.value || 0);
                    if ((accName || accId) && amt > 0) {
                        activePairs.push({ accId: accId.toLowerCase(), accName: accName.toLowerCase(), displayAcc: accName || accId, amount: amt });
                    }
                });

                if (activePairs.length === 0) return null;

                const storageKey = (type === 'receipt') ? 'erp_receipts_v1' : 'erp_payments_v1';
                const tKey = this.getTenantStorageKey(storageKey);
                let list = [];
                try {
                    list = JSON.parse(localStorage.getItem(tKey) || localStorage.getItem(storageKey) || '[]');
                } catch (_) { list = []; }
                if (!Array.isArray(list)) return null;

                for (let i = list.length - 1; i >= 0; i--) {
                    const v = list[i];
                    if (!v || v.deleted) continue;
                    const vNo = String(v.voucherNo || v.id || '').trim();
                    if (isEditingExisting && vNo === currentVNo) continue;
                    if (String(v.date || '').slice(0, 10) !== today) continue;

                    const vItems = Array.isArray(v.items) ? v.items : [];
                    for (const pair of activePairs) {
                        const matchedItem = vItems.find(it => {
                            if (!it) return false;
                            const itAmt = this.cleanNumber(it.amount || 0);
                            if (Math.abs(itAmt - pair.amount) > 0.01) return false;
                            const itId = String(it.accountId || it.account || '').trim().toLowerCase();
                            const itName = String(it.accountName || '').trim().toLowerCase();
                            return (pair.accId && itId === pair.accId) || (pair.accName && (itName === pair.accName || itId === pair.accName));
                        });

                        if (matchedItem) {
                            const sig = `${today}|${type}|${vNo}|${pair.displayAcc}|${pair.amount}`;
                            if (this.dismissedDuplicates.has(sig)) continue;
                            return {
                                signature: sig,
                                voucherNo: vNo,
                                accountName: pair.displayAcc,
                                amount: pair.amount,
                                time: v.time || 'قبل قليل',
                                voucher: v
                            };
                        }
                    }
                }
                return null;
            },

            ensureDuplicateRadarBanner() {
                let banner = document.getElementById('mcpC8DuplicateRadarBanner');
                if (!banner) {
                    banner = document.createElement('div');
                    banner.id = 'mcpC8DuplicateRadarBanner';
                    const primaryContainer = document.getElementById('primary-inputs-container');
                    if (primaryContainer && primaryContainer.parentElement) {
                        primaryContainer.insertAdjacentElement('afterend', banner);
                    }
                }
                return banner;
            },

            checkAndRenderDuplicateRadar() {
                const banner = this.ensureDuplicateRadarBanner();
                if (!banner) return null;
                const match = this.findMatchingSameDayTransaction();
                if (!match) {
                    banner.style.display = 'none';
                    banner.innerHTML = '';
                    return null;
                }

                const curr = document.getElementById('currency')?.value || 'SDG';
                banner.style.display = 'flex';
                banner.innerHTML = `
                    <div style="display:flex;align-items:center;gap:10px;flex:1;min-width:240px;">
                        <span style="font-size:1.4rem;">🔔</span>
                        <div style="font-size:0.9rem;font-weight:800;line-height:1.45;">
                            <b style="color:#fbbf24;">تنبيه تركيز:</b> توجد حركة مطابقة تماماً تم حفظها لهذا العميل/الحساب (<b style="color:#38bdf8;">${match.accountName}</b>) اليوم (${match.time}) برقم (<b style="color:#fef08a;font-family:monospace;">${match.voucherNo}</b>) وبنفس المبلغ (<b style="color:#34d399;font-family:monospace;">${this.formatCleanNumber(match.amount)} ${curr}</b>)، هل أنت متأكد من تكرارها؟
                        </div>
                    </div>
                    <div style="display:flex;align-items:center;gap:8px;flex-shrink:0;">
                        <button type="button" id="mcpC8OpenPrevDupBtn" style="background:rgba(56,189,248,0.2);border:1.5px solid #38bdf8;color:#e0f2fe;padding:5px 12px;border-radius:8px;font-weight:900;font-size:0.8rem;cursor:pointer;">👁️ عرض السند (${match.voucherNo})</button>
                        <button type="button" id="mcpC8DismissDupBtn" style="background:rgba(16,185,129,0.25);border:1.5px solid #10b981;color:#d1fae5;padding:5px 12px;border-radius:8px;font-weight:900;font-size:0.8rem;cursor:pointer;">✓ نعم، متأكد (تجاهل)</button>
                    </div>
                `;

                const openBtn = banner.querySelector('#mcpC8OpenPrevDupBtn');
                if (openBtn) {
                    openBtn.onclick = () => {
                        if (typeof window.loadVoucherIntoForm === 'function' && match.voucher) {
                            window.loadVoucherIntoForm(match.voucher);
                            banner.style.display = 'none';
                        }
                    };
                }
                const dismissBtn = banner.querySelector('#mcpC8DismissDupBtn');
                if (dismissBtn) {
                    dismissBtn.onclick = () => {
                        this.dismissedDuplicates.add(match.signature);
                        banner.style.display = 'none';
                    };
                }
                return match;
            },

            showPreSaveDuplicateConfirmModal(match, onConfirmProceed) {
                let modal = document.getElementById('mcpC8DuplicateConfirmModal');
                if (modal) modal.remove();

                const curr = document.getElementById('currency')?.value || 'SDG';
                modal = document.createElement('div');
                modal.id = 'mcpC8DuplicateConfirmModal';
                modal.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,0.88);backdrop-filter:blur(10px);z-index:1000050;display:flex;align-items:center;justify-content:center;direction:rtl;';
                modal.innerHTML = `
                    <div style="background:linear-gradient(145deg,#0f172a,#1e293b);border:2.5px solid #f59e0b;border-radius:18px;padding:26px 28px;width:92%;max-width:540px;color:#fff;box-shadow:0 25px 60px rgba(0,0,0,0.85),0 0 30px rgba(245,158,11,0.3);text-align:center;font-family:'Tajawal',sans-serif;">
                        <div style="font-size:3.4rem;margin-bottom:10px;">🔔</div>
                        <h3 style="margin:0 0 12px 0;color:#fbbf24;font-size:1.45rem;font-weight:900;">تنبيه تركيز: احتمال تكرار حركة في نفس اليوم</h3>
                        <p style="color:#e2e8f0;font-size:1.05rem;line-height:1.7;margin:0 0 22px 0;font-weight:700;">
                            تنبيه تركيز: توجد حركة مطابقة تماماً تم حفظها لهذا العميل (<b style="color:#38bdf8;">${match.accountName}</b>) قبل قليل برقم (<b style="color:#fef08a;font-family:monospace;">${match.voucherNo}</b>) وبمبلغ (<b style="color:#34d399;font-family:monospace;">${this.formatCleanNumber(match.amount)} ${curr}</b>)، هل أنت متأكد من تكرارها؟
                        </p>
                        <div style="display:flex;gap:12px;justify-content:center;flex-wrap:wrap;">
                            <button type="button" id="mcpC8DupCancelSaveBtn" style="flex:1;min-width:190px;height:46px;border-radius:11px;border:2px solid #38bdf8;background:#0284c7;color:#fff;font-weight:900;font-size:1rem;cursor:pointer;">🛡️ لا، أوقف الحفظ وراجع السند</button>
                            <button type="button" id="mcpC8DupConfirmSaveBtn" style="flex:1;min-width:190px;height:46px;border-radius:11px;border:2px solid #f59e0b;background:rgba(245,158,11,0.2);color:#fef08a;font-weight:900;font-size:0.96rem;cursor:pointer;">✅ نعم، أنا متأكد — اعتمد الحفظ</button>
                        </div>
                    </div>
                `;
                document.body.appendChild(modal);

                const cancelBtn = modal.querySelector('#mcpC8DupCancelSaveBtn');
                const confirmBtn = modal.querySelector('#mcpC8DupConfirmSaveBtn');
                if (cancelBtn) {
                    setTimeout(() => cancelBtn.focus(), 30);
                    cancelBtn.onclick = () => modal.remove();
                }
                if (confirmBtn) {
                    confirmBtn.onclick = () => {
                        this.dismissedDuplicates.add(match.signature);
                        modal.remove();
                        onConfirmProceed();
                    };
                }
            },

            initAntiDuplicateTransactionGuard() {
                const self = this;
                let radarTimer = null;

                const scheduleRadar = () => {
                    clearTimeout(radarTimer);
                    radarTimer = setTimeout(() => self.checkAndRenderDuplicateRadar(), 220);
                };

                document.addEventListener('input', (e) => {
                    if (e.target && e.target.closest && e.target.closest('#accounts-blocks-container')) {
                        scheduleRadar();
                    }
                }, true);

                document.addEventListener('change', (e) => {
                    if (e.target && e.target.closest && e.target.closest('#main-form-panel')) {
                        scheduleRadar();
                    }
                }, true);

                // اعتراض لطيف قبل حفظ السند إذا وُجدت حركة مطابقة تماماً في نفس اليوم ولم يؤكدها المحاسب بعد
                const wrapSaveWithDuplicateGuard = () => {
                    if (typeof window.saveVoucher === 'function' && !window.saveVoucher.__mcpC8DupWrapped) {
                        const origSave = window.saveVoucher;
                        const wrappedSave = function (...args) {
                            if (!self.bypassDuplicateCheckOnce) {
                                const match = self.findMatchingSameDayTransaction();
                                if (match) {
                                    self.showPreSaveDuplicateConfirmModal(match, () => {
                                        self.bypassDuplicateCheckOnce = true;
                                        try {
                                            window.saveVoucher(...args);
                                        } finally {
                                            setTimeout(() => { self.bypassDuplicateCheckOnce = false; }, 400);
                                        }
                                    });
                                    return;
                                }
                            }
                            return origSave.apply(this, args);
                        };
                        wrappedSave.__mcpC8DupWrapped = true;
                        window.saveVoucher = wrappedSave;
                    }
                };

                wrapSaveWithDuplicateGuard();
                window.addEventListener('DOMContentLoaded', () => setTimeout(wrapSaveWithDuplicateGuard, 80));
            },

            // ═══════════════════════════════════════════════════════════════════════════
            // 6. الذاكرة العضلية الموحدة، الفحص الذاتي للتوازن، ونفق التركيز البصري (Directive 6 & Addition 5)
            // ═══════════════════════════════════════════════════════════════════════════
            runSilentDoubleEntryBalanceCheck() {
                const summaryBar = document.getElementById('mcp-world-summary-bar');
                if (!summaryBar) return;

                let badge = document.getElementById('mcpC8BalanceCheckBadge');
                if (!badge) {
                    badge = document.createElement('div');
                    badge.id = 'mcpC8BalanceCheckBadge';
                    badge.setAttribute('data-guide-title', '⚖️ الفحص الذاتي الصامت لتوازن طرفي القيد وتطابق السطور');
                    badge.setAttribute('data-golden-rule', 'القاعدة الذهبية: اطمئن طالما شارة (⚖️ القيد متوازن 100%) خضراء؛ فمجموع السطور الفرعية يطابق الإجمالي العام وطرفي القيد بالقرش.');
                    const firstGroup = summaryBar.querySelector('div');
                    if (firstGroup) firstGroup.appendChild(badge);
                    else summaryBar.appendChild(badge);
                }

                let blocksSum = 0;
                let subMethodsSum = 0;
                let mismatchBlockId = null;

                document.querySelectorAll('.account-block').forEach(block => {
                    const bid = block.getAttribute('data-block-id');
                    const blockAmt = this.cleanNumber(document.getElementById(`amount-${bid}`)?.value || 0);
                    blocksSum += blockAmt;

                    let blockSub = 0;
                    if (document.getElementById(`pm-cash-${bid}`)?.classList.contains('active')) {
                        blockSub += this.cleanNumber(block.querySelector('.block-cash-amount')?.value || 0);
                    }
                    if (document.getElementById(`pm-bank-${bid}`)?.classList.contains('active')) {
                        block.querySelectorAll('.bank-row .block-bank-amount').forEach(inp => {
                            blockSub += this.cleanNumber(inp.value);
                        });
                    }
                    if (document.getElementById(`pm-cheque-${bid}`)?.classList.contains('active')) {
                        block.querySelectorAll('.cheque-row .block-cheque-amount').forEach(inp => {
                            blockSub += this.cleanNumber(inp.value);
                        });
                    }
                    subMethodsSum += blockSub;
                    if (Math.abs(blockSub - blockAmt) > 0.01 && !mismatchBlockId) {
                        mismatchBlockId = bid;
                    }
                });

                const curr = document.getElementById('currency')?.value || 'SDG';
                const hdrTotal = curr === 'SDG'
                    ? this.cleanNumber(document.getElementById('amount-local-hdr')?.value || 0)
                    : this.cleanNumber(document.getElementById('amount-foreign')?.value || 0);

                const diff = Math.abs(blocksSum - hdrTotal) + Math.abs(blocksSum - subMethodsSum);
                if (diff <= 0.02) {
                    badge.classList.remove('unbalanced');
                    badge.innerHTML = `<span>⚖️ القيد متوازن 100% (المدين = الدائن)</span>`;
                } else {
                    badge.classList.add('unbalanced');
                    badge.innerHTML = `<span>⚠️ فرق توازن قيد المراجعة</span> <button type="button" id="mcpC8AutoFixBalanceBtn" style="background:#f59e0b;color:#0f172a;border:none;border-radius:5px;padding:1px 7px;font-size:0.75rem;font-weight:900;cursor:pointer;">إصلاح فوري ⚡</button>`;
                    const fixBtn = badge.querySelector('#mcpC8AutoFixBalanceBtn');
                    if (fixBtn) {
                        fixBtn.onclick = () => {
                            document.querySelectorAll('.account-block').forEach(b => {
                                const id = b.getAttribute('data-block-id');
                                if (typeof window.recalcBlockTotal === 'function') window.recalcBlockTotal(id);
                            });
                            if (typeof window.calcTotal === 'function') window.calcTotal();
                        };
                    }
                }
            },

            toggleFocusTunnel(forceState) {
                const cur = document.body.classList.contains('mcp-c8-focus-tunnel-enabled');
                const next = (typeof forceState === 'boolean') ? forceState : !cur;
                document.body.classList.toggle('mcp-c8-focus-tunnel-enabled', next);
                const btn = document.getElementById('mcpC8FocusTunnelBtn');
                if (btn) btn.classList.toggle('active', next);
                try {
                    localStorage.setItem(this.FOCUS_TUNNEL_KEY, next ? '1' : '0');
                } catch (_) {}
            },

            initMuscleMemoryBalanceAndFocusTunnel() {
                const self = this;
                const savedTunnel = localStorage.getItem(this.FOCUS_TUNNEL_KEY);
                const enableTunnel = (savedTunnel === null) ? true : (savedTunnel === '1');
                this.toggleFocusTunnel(enableTunnel);

                document.addEventListener('focusin', (e) => {
                    const inBlock = e.target && e.target.closest && e.target.closest('#accounts-blocks-container .account-block');
                    const totalBlocks = document.querySelectorAll('#accounts-blocks-container .account-block').length;
                    document.body.classList.toggle('mcp-c8-user-typing-in-block', Boolean(inBlock && totalBlocks > 1));
                }, true);

                document.addEventListener('focusout', () => {
                    setTimeout(() => {
                        const active = document.activeElement;
                        const inBlock = active && active.closest && active.closest('#accounts-blocks-container .account-block');
                        const totalBlocks = document.querySelectorAll('#accounts-blocks-container .account-block').length;
                        document.body.classList.toggle('mcp-c8-user-typing-in-block', Boolean(inBlock && totalBlocks > 1));
                    }, 80);
                }, true);

                document.addEventListener('keydown', (e) => {
                    if (e.altKey && (e.key === 'f' || e.key === 'F' || e.key === 'ب')) {
                        e.preventDefault();
                        self.toggleFocusTunnel();
                        if (typeof window.showToast === 'function') {
                            const isOn = document.body.classList.contains('mcp-c8-focus-tunnel-enabled');
                            window.showToast(isOn ? '🎯 تم تفعيل نفق التركيز البصري لراحة العين' : '🎯 تم إيقاف نفق التركيز البصري', 'info', 1400);
                        }
                    }
                }, true);

                setTimeout(() => this.runSilentDoubleEntryBalanceCheck(), 200);
            },

            // ═══════════════════════════════════════════════════════════════════════════
            // 7. التحديث الذاتي للمرشد الذكي (Directives 6 & 7)
            // ═══════════════════════════════════════════════════════════════════════════
            registerWithSmartGuide() {
                window.MCP_DESKTOP_CONSTITUTION8_GUIDE = {
                    constitutionNumber: 8,
                    title: 'الدستور الثامن: علم النفس المعرفي، راحة المحاسب تحت الزحام، الآلة الحاسبة المدمجة، التفقيط، حارس الإرهاق، تعليق السند، ومنع التكرار',
                    goldenRule: 'القاعدة الذهبية لعلم النفس المعرفي: اكتب معادلاتك الحسابية مباشرة داخل خانة المبلغ واضغط Enter، وراقب شارة عدد الأصفار والتفقيط بالحروف، واستخدم زر (⏸️ تعليق مؤقت F8) عند الزحام لخدمة العميل المستعجل فوراً دون ضياع أي سطر.'
                };

                const c4 = window.McpDesktopConstitution4;
                const selectEl = document.getElementById('mcpC4StageJumpSelect');
                if (c4 && Array.isArray(c4.steps) && !c4.steps.some(s => s.id === 'step-c8-cognitive-ergonomics')) {
                    const stepIdx = c4.steps.length;
                    const c8Step = {
                        id: 'step-c8-cognitive-ergonomics',
                        title: '2️⃣2️⃣ علم النفس المعرفي: الحاسبة المدمجة، التفقيط، حارس الإرهاق، تعليق السند (F8)، ومنع التكرار',
                        svgStage: 'process',
                        showMap: false,
                        selector: '#btn-mcp-park-voucher, #grand-tafqeet-container, #mcpC8BalanceCheckBadge',
                        goldenRule: 'القاعدة الذهبية لراحة المحاسب تحت الزحام: اكتب المعادلة الحسابية داخل خانة المبلغ نفسها واضغط Enter، وراجع التفقيط وعدد الأصفار، واستخدم (⏸️ تعليق مؤقت F8) لركن السند في الشريط العلوي وخدمة العميل المستعجل فوراً.',
                        action: () => {
                            if (typeof window.cleanupMultiCashGuidePopups === 'function') window.cleanupMultiCashGuidePopups();
                        },
                        text: 'ولدعم راحة المحاسب الذهنية والنفسية تحت ضغط العمل والزحام، تعمل في هذه الشاشة منظومة علم النفس المعرفي المتكاملة: أولاً، الآلة الحاسبة المدمجة داخل الخانات الرقمية؛ اكتب مثلاً اثنا عشر ضرب أربعة وعشرين أو خمسة آلاف زائد ألف وخمسمائة واضغط إنتر ليحسبها النظام في صفر ثانية مع شريط معاينة حي. ثانياً، التفقيط العربي اللحظي بالحروف مع شارة مقياس الأصفار لمنع الخلط بين مائة ألف ومليون. ثالثاً، حارس الإرهاق الذكي الذي يحيط الخانة بإطار كهرماني نابض إذا قفز الرقم لأضعاف المعدل التاريخي للحساب مع زر تصحيح الصفر الزائد بضغطة واحدة. رابعاً، زر تعليق مؤقت واختصاره إف ثمانية لركن السند في الشريط العلوي المصغر وتفريغ الشاشة فوراً لخدمة العميل المستعجل ثم استرجاعه بضغطة واحدة. خامساً، رادار منع تكرار نفس السند في نفس اليوم وشارة الفحص الذاتي الصامت لتوازن طرفي القيد ونفق التركيز البصري. القاعدة الذهبية: دع النظام يحمل عنك العبء الذهني في الحساب ومراجعة الأصفار والتوازن وتبديل العملاء في الزحام.'
                    };
                    c4.steps.push(c8Step);
                    if (selectEl) {
                        const opt = document.createElement('option');
                        opt.value = String(stepIdx);
                        opt.textContent = '2️⃣2️⃣ علم النفس المعرفي، الحاسبة، التفقيط، وتعليق السند (F8)';
                        selectEl.appendChild(opt);
                    }
                    const counterEl = document.getElementById('mcpC4StepCounterBadge');
                    if (counterEl) {
                        counterEl.textContent = (c4.currentStepIndex + 1) + ' / ' + c4.steps.length;
                    }
                }
            }
        };

        window.McpDesktopConstitution8 = McpDesktopConstitution8;
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => McpDesktopConstitution8.init());
        } else {
            McpDesktopConstitution8.init();
        }
    })();
    </script>

