            /* ─── 1. محرك الدقة الكسرية الميكروية لمنع أخطاء التقريب العشري (Zero Rounding Drift) ─── */
            toMicro(val) {
                const n = Number(val);
                if (!Number.isFinite(n)) return 0;
                return Math.round(n * 1e6);
            },
            fromMicro(microVal, decimals = 4) {
                const raw = microVal / 1e6;
                const p = Math.pow(10, decimals);
                return Math.round((raw + Number.EPSILON) * p) / p;
            },
            exactMul(a, b, decimals = 4) {
                const na = Number(a) || 0;
                const nb = Number(b) || 0;
                const p = Math.pow(10, decimals);
                return Math.round(((na * nb) + Number.EPSILON) * p) / p;
            },
            exactDiv(a, b, decimals = 4) {
                const na = Number(a) || 0;
                const nb = Number(b) || 1;
                if (nb === 0) return 0;
                const p = Math.pow(10, decimals);
                return Math.round(((na / nb) + Number.EPSILON) * p) / p;
            },

            /* ─── 2. تحميل وحفظ كتالوج الأصناف والأرصدة وسجل الدفعات الجزئية ─── */
            loadCatalog() {
                try {
                    const saved = localStorage.getItem(STORAGE_KEY_CUSTOM_ITEMS);
                    if (saved) {
                        const parsed = JSON.parse(saved);
                        if (Array.isArray(parsed) && parsed.length > 0) {
                            this.catalog = parsed;
                            return;
                        }
                    }
                } catch (e) {}
                this.catalog = JSON.parse(JSON.stringify(DEFAULT_ITEMS_CATALOG));
                this.saveCatalog();
            },

            saveCatalog() {
                try {
                    localStorage.setItem(STORAGE_KEY_CUSTOM_ITEMS, JSON.stringify(this.catalog));
                } catch (e) {}
            },

            getStagedOrdersMap() {
                try {
                    return JSON.parse(localStorage.getItem(STORAGE_KEY_STAGED_ORDERS) || '{}');
                } catch (e) {
                    return {};
                }
            },

            saveStagedOrdersMap(map) {
                try {
                    localStorage.setItem(STORAGE_KEY_STAGED_ORDERS, JSON.stringify(map));
                } catch (e) {}
            },

            /* ─── 3. بناء زر الشريط العلوي وأزرار الكتل والنافذة الوليدة (فحص واستلام + تعدد الوحدات) ─── */
            injectTopBarButton() {
                if (document.getElementById('mcpC9OpenInspectionBtn')) return;
                const c8HoldBtn = document.getElementById('mcpC8HoldVoucherBtn');
                const btn = document.createElement('button');
                btn.type = 'button';
