                btn.title = 'فتح شاشة فحص واستلام وفرز البضاعة وتعدد الوحدات والاستلام الجزئي (اختصار F7)';
                btn.innerHTML = `<span class="c9-radar-dot"></span><span>📦 فحص واستلام مخزني (F7)</span><span id="mcpC9RadarWarningBadge" style="background:rgba(245,158,11,0.22);border:1.5px solid #fbbf24;color:#fde68a;padding:1px 6px;border-radius:999px;font-size:0.72rem;font-weight:900;">جاهز</span>`;
                btn.addEventListener('click', () => this.openInspectionModal());

                if (c8HoldBtn && c8HoldBtn.parentElement) {
                    c8HoldBtn.parentElement.insertBefore(btn, c8HoldBtn);
                } else {
                    const topActionRow = document.querySelector('.header-actions-group') || document.querySelector('.voucher-type-toggle');
                    if (topActionRow && topActionRow.parentElement) {
                        topActionRow.parentElement.insertBefore(btn, topActionRow.nextSibling);
                    }
                }
            },

            ensureBlockInspectButtons() {
                document.querySelectorAll('.account-block').forEach((blk) => {
                    const bid = blk.getAttribute('data-block-id');
                    if (!bid) return;
                    if (blk.querySelector('.btn-block-c9-inspect')) return;
                    const dupBtn = blk.querySelector('.btn-duplicate-block');
                    if (dupBtn && dupBtn.parentElement) {
                        const btn = document.createElement('button');
                        btn.type = 'button';
                        btn.className = 'btn-block-c9-inspect';
                        btn.setAttribute('data-block', bid);
                        btn.style.cssText = 'background: rgba(16, 185, 129, 0.15); border: 2px solid #10b981; color: #6ee7b7; border-radius: 8px; height: 30px; padding: 0 10px; display: inline-flex; align-items: center; gap: 4px; cursor: pointer; font-size: 0.82rem; font-weight: 900; transition: all 0.18s;';
                        btn.title = 'فتح شاشة فحص واستلام وفرز البضاعة وتعدد الوحدات لهذا السطر المخزني (F7)';
                        btn.innerHTML = '<span>📦</span> <span>فحص واستلام</span>';
                        btn.addEventListener('click', () => this.openInspectionModal(bid));
