        .mcp-c10-field label {
            display: block;
            font-size: 0.8rem;
            font-weight: 800;
            color: #e9d5ff;
            margin-bottom: 4px;
        }
        /* تثبيت لون خلفية منطقة الكتابة + زيادة سُمك الحواف بمقدار (+2) */
        #mcpC10CommercialHubModal input:not([type="checkbox"]),
        #mcpC10CommercialHubModal select {
            width: 100%;
