            transition: border-color 0.15s ease, box-shadow 0.15s ease;
        }
        #mcpC10CommercialHubModal input:not([type="checkbox"]):focus,
        #mcpC10CommercialHubModal select:focus {
            background-color: rgba(15, 23, 42, 0.94) !important;
            border-color: #c084fc !important;
            box-shadow: 0 0 0 3px rgba(192, 132, 252, 0.28) !important;
        }
        .mcp-c10-num-input {
            font-family: 'Consolas', 'Monaco', monospace !important;
            font-variant-numeric: tabular-nums !important;
            direction: ltr !important;
            text-align: center !important;
            font-size: 1.02rem !important;
        }
        .mcp-c10-table {
            width: 100%;
            border-collapse: collapse;
            font-size: 0.84rem;
            font-variant-numeric: tabular-nums;
            margin-top: 8px;
        }
        .mcp-c10-table th,
        .mcp-c10-table td {
            padding: 7px 9px;
            border: 2px solid rgba(148, 163, 184, 0.35);
            text-align: right;
        }
        .mcp-c10-table th {
            background: rgba(88, 28, 135, 0.42);
            color: #f3e8ff;
            font-weight: 900;
        }
        .mcp-c10-btn-primary {
            height: 40px;
            padding: 0 15px;
            border-radius: 10px;
            border: 2.5px solid #c084fc;
            background: linear-gradient(135deg, #7e22ce, #581c87);
            color: #ffffff;
            font-family: 'Tajawal', sans-serif;
            font-weight: 900;
            font-size: 0.86rem;
            cursor: pointer;
        }
        .mcp-c10-btn-emerald {
            height: 40px;
            padding: 0 16px;
            border-radius: 10px;
            border: 2.5px solid #6ee7b7;
            background: linear-gradient(135deg, #059669, #047857);
            color: #ffffff;
            font-family: 'Tajawal', sans-serif;
            font-weight: 900;
            font-size: 0.88rem;
            cursor: pointer;
        }
        .mcp-c10-btn-rose {
            height: 40px;
            padding: 0 16px;
            border-radius: 10px;
            border: 2.5px solid #fda4af;
            background: linear-gradient(135deg, #e11d48, #9f1239);
            color: #ffffff;
            font-family: 'Tajawal', sans-serif;
            font-weight: 900;
            font-size: 0.88rem;
            cursor: pointer;
        }

        /* دعم الثيمات الـ 7 بما فيها الثيم الفاتح */
        body.light-theme #mcpC10OpenCommercialBtn {
            background: #581c87 !important;
            color: #ffffff !important;
            border-color: #9333ea !important;
        }
    </style>

    <script id="mcp-constitution-10-commercial-depth-engine">
    (function() {
        'use strict';
        if (window.__MCP_CONSTITUTION_10_COMMERCIAL_DEPTH_ACTIVE__) return;
        window.__MCP_CONSTITUTION_10_COMMERCIAL_DEPTH_ACTIVE__ = true;

        const LANDED_COST_KEY = 'erp_landed_cost_allocations_v1';
        const LIFECYCLE_DOCS_KEY = 'erp_lifecycle_documents_v1';
        const COMMERCIAL_INVOICES_KEY = 'erp_commercial_invoices_v1';
        const RETURNS_KEY = 'erp_returns_reverse_entries_v1';

        const PRICING_TIERS = [
            { code: 'wholesale', label: 'شريحة الجملة الكبرى (-8%)', multiplier: 0.92 },
            { code: 'semi_wholesale', label: 'شريحة نصف الجملة (-4%)', multiplier: 0.96 },
            { code: 'retail', label: 'شريحة القطاعي القياسية (100%)', multiplier: 1.00 },
            { code: 'vip_custom', label: 'سعر خاص تفضيلي للعميل/المورد (-10%)', multiplier: 0.90 },
            { code: 'last_party_price', label: 'آخر سعر تعامل مسجل لهذا الطرف (-5%)', multiplier: 0.95 }
        ];

        const DEFAULT_LIFECYCLE_DOCS = [
            {
                docId: 'PO-2026-101',
                docType: 'أمر شراء وتوريد (Purchase Order)',
                partyId: 'sup-1',
                partyName: 'شركة مصانع الحديد والصلب الوطنية',
                tierCode: 'wholesale',
                creditLimit: 50000000,
                currentDebt: 12500000,
                dueDate: '2026-12-30',
                items: [
                    { id: 'ITM_STEEL_16', name: 'حديد تسليح عز الدخيلة 16 مم', qty: 200, weightKg: 2350, baseUnitPrice: 12500, baseUnitCost: 11800 },
                    { id: 'ITM_CEMENT_50', name: 'أسمنت بورتلاندي عادي رتبة 42.5N', qty: 100, weightKg: 5000, baseUnitPrice: 18000, baseUnitCost: 16500 }
                ]
            },
            {
                docId: 'QT-2026-502',
                docType: 'عرض سعر معتمد للتوريد (Quotation)',
                partyId: 'sup-2',
                partyName: 'مؤسسة الكوابل والتوريدات الكهربائية',
                tierCode: 'semi_wholesale',
                creditLimit: 25000000,
                currentDebt: 4200000,
                dueDate: '2026-12-20',
                items: [
                    { id: 'ITM_CABLE_NYM', name: 'كابل كهرباء نحاس معزول 3×2.5 مم معتمد', qty: 300, weightKg: 450, baseUnitPrice: 4200, baseUnitCost: 3800 }
                ]
            },
            {
                docId: 'PINV-2026-309',
                docType: 'فاتورة مشتريات ومصروفات شحن (Purchase Invoice)',
                partyId: 'sup-3',
                partyName: 'الشركة العالمية للزيوت والمحركات',
                tierCode: 'vip_custom',
                creditLimit: 18000000,
                currentDebt: 19500000, /* متجاوز لسقف الائتمان لاختبار الرقابة الصارمة */
                dueDate: '2026-10-15',
                items: [
                    { id: 'ITM_LED_PANEL', name: 'كشاف ليد سقف 60×60 سم 48 وات', qty: 120, weightKg: 140, baseUnitPrice: 9500, baseUnitCost: 8700 }
                ]
            }
        ];

        const McpDesktopConstitution10 = {
            activeTargetBlockId: null,
            lastReverseSignature: '',
            lastReverseTime: 0,

            parseNum(val) {
                if (val === null || val === undefined) return 0;
                const clean = String(val)
                    .replace(/[٠-٩]/g, d => String(d.charCodeAt(0) - 1632))
                    .replace(/[۰-۹]/g, d => String(d.charCodeAt(0) - 1776))
                    .replace(/,/g, '')
                    .trim();
                const n = parseFloat(clean);
                return Number.isFinite(n) ? n : 0;
            },

            ensureSeedData() {
                try {
                    const existing = localStorage.getItem(LIFECYCLE_DOCS_KEY);
                    if (!existing) {
                        localStorage.setItem(LIFECYCLE_DOCS_KEY, JSON.stringify(DEFAULT_LIFECYCLE_DOCS));
                    }
                } catch (e) {}
            },

            getLifecycleDocs() {
                try {
                    const raw = localStorage.getItem(LIFECYCLE_DOCS_KEY);
                    const parsed = raw ? JSON.parse(raw) : null;
                    return Array.isArray(parsed) && parsed.length > 0 ? parsed : DEFAULT_LIFECYCLE_DOCS;
                } catch (e) {
                    return DEFAULT_LIFECYCLE_DOCS;
                }
            },

            saveLifecycleDocs(docs) {
                try {
                    localStorage.setItem(LIFECYCLE_DOCS_KEY, JSON.stringify(docs));
                } catch (e) {}
            },

            canUserSeeProfitMargin() {
                try {
                    if (window.USER_PERMISSIONS && window.USER_PERMISSIONS.hideProfitMargin === true) return false;
                    const role = String(window.CURRENT_USER_ROLE || localStorage.getItem('erp_user_role') || 'admin').toLowerCase();
                    return role !== 'restricted_cashier';
                } catch (e) {
                    return true;
                }
            },

            injectTopBarButton() {
                if (document.getElementById('mcpC10OpenCommercialBtn')) return;
                const anchor = document.getElementById('mcpC9OpenInspectionBtn') || document.getElementById('mcpC8HoldVoucherBtn');
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.id = 'mcpC10OpenCommercialBtn';
                btn.title = 'فتح شاشة العمق التجاري، شرائح الأسعار، توزيع المصروفات المضافة (Landed Cost)، الدورة المستندية، والمرتجعات (اختصار F6)';
                btn.innerHTML = `<span>💼 العمق التجاري & Landed Cost (F6)</span>`;
                btn.addEventListener('click', () => this.openCommercialModal());

                if (anchor && anchor.parentElement) {
                    anchor.parentElement.insertBefore(btn, anchor);
                } else {
                    const topActionRow = document.querySelector('.header-actions-group') || document.querySelector('.voucher-type-toggle');
                    if (topActionRow && topActionRow.parentElement) {
                        topActionRow.parentElement.insertBefore(btn, topActionRow.nextSibling);
                    }
                }
            },

            ensureBlockCommercialButtons() {
                document.querySelectorAll('.account-block').forEach((blk) => {
                    const bid = blk.getAttribute('data-block-id');
                    if (!bid) return;
                    if (blk.querySelector('.btn-block-c10-commercial')) return;
                    const c9Btn = blk.querySelector('.btn-block-c9-inspect') || blk.querySelector('.btn-duplicate-block');
                    if (c9Btn && c9Btn.parentElement) {
                        const btn = document.createElement('button');
                        btn.type = 'button';
                        btn.className = 'btn-block-c10-commercial';
                        btn.setAttribute('data-block', bid);
                        btn.style.cssText = 'background: rgba(168, 85, 247, 0.16); border: 2px solid #a855f7; color: #e9d5ff; border-radius: 8px; height: 30px; padding: 0 10px; display: inline-flex; align-items: center; gap: 4px; cursor: pointer; font-size: 0.82rem; font-weight: 900; transition: all 0.18s;';
                        btn.title = 'فتح شاشة العمق التجاري، شرائح الأسعار، توزيع المصروفات المضافة Landed Cost، الدورة المستندية، والمرتجعات (F6)';
                        btn.innerHTML = '<span>💼</span> <span>تسعير و Landed Cost</span>';
                        btn.addEventListener('click', () => this.openCommercialModal(bid));
                        c9Btn.parentElement.insertBefore(btn, c9Btn);
                    }
                });
            },

            populateTargetBlockSelect(preferredBlockId) {
                const sel = document.getElementById('mcpC10TargetBlockSelect');
                if (!sel) return;
                sel.innerHTML = '';
                const blocks = Array.from(document.querySelectorAll('.account-block'));
                blocks.forEach((blk, idx) => {
                    const bid = blk.getAttribute('data-block-id');
                    const accInput = document.getElementById(`account-${bid}-search`);
                    const accName = (accInput && accInput.value.trim()) ? accInput.value.trim() : `حساب غير مسمى`;
                    const opt = document.createElement('option');
                    opt.value = String(bid);
                    opt.textContent = `📋 بطاقة الحساب رقم (${idx + 1}) — ${accName}`;
                    sel.appendChild(opt);
                });
                const newOpt = document.createElement('option');
                newOpt.value = 'NEW_BLOCK';
                newOpt.textContent = '➕ إنشاء بطاقة حساب جديدة مستقلة في السند المجمع';
                sel.appendChild(newOpt);

                if (preferredBlockId && sel.querySelector(`option[value="${preferredBlockId}"]`)) {
                    sel.value = String(preferredBlockId);
                    this.activeTargetBlockId = String(preferredBlockId);
                } else if (blocks.length > 0) {
                    const firstBid = blocks[0].getAttribute('data-block-id');
                    sel.value = String(firstBid);
                    this.activeTargetBlockId = String(firstBid);
                } else {
                    sel.value = 'NEW_BLOCK';
                    this.activeTargetBlockId = 'NEW_BLOCK';
                }
            },

            injectCommercialModal() {
                if (document.getElementById('mcpC10CommercialHubModal')) return;
                const docs = this.getLifecycleDocs();
                const modal = document.createElement('div');
                modal.id = 'mcpC10CommercialHubModal';
                modal.setAttribute('role', 'dialog');
                modal.setAttribute('aria-label', 'منظومة العمق التجاري، شرائح التسعير، توزيع المصروفات المضافة Landed Cost، الدورة المستندية، والمرتجعات');
                modal.innerHTML = `
                    <div class="mcp-c10-modal-card" onclick="event.stopPropagation()">
                        <div class="mcp-c10-modal-header">
                            <div>
                                <div style="font-size:1.15rem;font-weight:900;color:#e9d5ff;display:flex;align-items:center;gap:8px;">
                                    <span>💼</span>
                                    <span>منظومة العمق التجاري: شرائح التسعير، توزيع المصروفات المضافة (Landed Cost)، الدورة المستندية، والمرتجعات (Constitution 10)</span>
                                </div>
                                <div style="font-size:0.78rem;color:#cbd5e1;margin-top:3px;">تحديد التكلفة الفعلية للوحدة + رقابة سقف الائتمان والربحية + تحويل المستندات بضغطة زر للسند المجمع + القيود العكسية للمرتجعات (0ms)</div>
                            </div>
                            <div style="display:flex;align-items:center;gap:8px;">
                                <button type="button" id="mcpC10ToggleAddDocBtn" style="height:34px;padding:0 11px;border-radius:8px;background:rgba(56,189,248,0.18);border:2.5px solid #38bdf8;color:#e0f2fe;font-family:'Tajawal',sans-serif;font-size:0.8rem;font-weight:900;cursor:pointer;">➕ إنشاء عرض سعر / أمر شراء</button>
                                <button type="button" id="mcpC10CloseModalBtn" style="height:34px;padding:0 12px;border-radius:8px;background:rgba(239,68,68,0.2);border:2.5px solid #ef4444;color:#fecaca;font-family:'Tajawal',sans-serif;font-size:0.84rem;font-weight:900;cursor:pointer;">✖ إغلاق (Esc)</button>
                            </div>
                        </div>

                        <!-- شريط اختيار بطاقة الحساب المستهدفة في السند المجمع + خيار فصل بطاقات المصروفات المضافة -->
                        <div class="mcp-c10-section-box" style="border-color:rgba(251,191,36,0.65);background:rgba(30,27,75,0.55);padding:10px 14px;">
                            <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;">
                                <div style="display:flex;align-items:center;gap:8px;font-size:0.88rem;font-weight:900;color:#fde68a;">
                                    <span>🎯 بطاقة الحساب المستهدفة في السند المجمع:</span>
                                </div>
                                <div style="flex:1;min-width:240px;">
                                    <select id="mcpC10TargetBlockSelect"></select>
                                </div>
                                <label style="display:inline-flex;align-items:center;gap:6px;font-size:0.8rem;font-weight:900;color:#6ee7b7;cursor:pointer;">
                                    <input type="checkbox" id="mcpC10SplitLandedBlocksCheck" style="width:16px;height:16px;accent-color:#10b981;cursor:pointer;" />
                                    <span>✨ توزيع ذكي بالسند المجمع: بطاقة للمورد الأساسي + بطاقة مستقلة لمصاريف النقل والعتالة والتخليص</span>
                                </label>
                            </div>
                        </div>

                        <!-- شريط إضافة عرض سعر أو أمر شراء جديد للدورة المستندية -->
                        <div id="mcpC10QuickAddDocBar" class="mcp-c10-section-box" style="display:none;border-color:#38bdf8;background:rgba(15,23,42,0.96);">
                            <div style="font-size:0.88rem;font-weight:900;color:#38bdf8;margin-bottom:8px;">➕ إضافة مستند مصدر جديد (عرض سعر / أمر شراء) للدورة المستندية:</div>
                            <div class="mcp-c10-grid-4">
                                <div class="mcp-c10-field">
                                    <label>رقم المستند (مثال: QT-2026-900)</label>
                                    <input type="text" id="mcpC10NewDocId" value="QT-2026-880" />
                                </div>
                                <div class="mcp-c10-field">
                                    <label>اسم العميل / المورد</label>
                                    <input type="text" id="mcpC10NewPartyName" placeholder="اسم الشركة أو المورد" value="شركة الإمداد والتوريدات الهندسية" />
                                </div>
                                <div class="mcp-c10-field">
                                    <label>اسم الصنف الرئيسي + الكمية</label>
                                    <div style="display:flex;gap:6px;">
                                        <input type="text" id="mcpC10NewItemName" value="مواسير صلب مجلفن 4 بوصة" />
                                        <input type="text" id="mcpC10NewItemQty" class="mcp-c10-num-input" value="150" style="width:90px;" />
                                    </div>
                                </div>
                                <div class="mcp-c10-field">
                                    <label>تكلفة الوحدة + سعر البيع</label>
                                    <div style="display:flex;gap:6px;">
                                        <input type="text" id="mcpC10NewItemCost" class="mcp-c10-num-input" value="8000" />
                                        <input type="text" id="mcpC10NewItemPrice" class="mcp-c10-num-input" value="9500" />
                                        <button type="button" id="mcpC10SaveNewDocBtn" class="mcp-c10-btn-primary" style="padding:0 12px;">حفظ</button>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <!-- شريط الرقابة الصارمة على سقف الائتمان وتاريخ الاستحقاق والربحية اللحظية -->
                        <div id="mcpC10CreditControlBanner" style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;padding:9px 13px;border-radius:11px;border:2.5px solid #a855f7;background:rgba(88,28,135,0.28);font-size:0.85rem;font-weight:800;margin-bottom:12px;">
                            <span id="mcpC10CreditStatusText">🛡️ رقابة الائتمان: السقف متاح والمديونية ضمن الحدود الآمنة</span>
                            <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
                                <label style="display:inline-flex;align-items:center;gap:5px;font-size:0.78rem;color:#fde047;cursor:pointer;">
                                    <input type="checkbox" id="mcpC10OfficialCreditOverrideCheck" style="width:15px;height:15px;accent-color:#f59e0b;cursor:pointer;" />
                                    <span>تعميد إداري بتجاوز سقف الائتمان</span>
                                </label>
                                <span id="mcpC10LiveProfitMarginBadge" style="padding:3px 11px;border-radius:999px;background:rgba(16,185,129,0.25);border:2px solid #34d399;color:#a7f3d0;">📈 هامش الربح اللحظي: 0%</span>
                            </div>
                        </div>

                        <!-- القسم 1 و 3: الدورة المستندية المترابطة بضغطة زر + شرائح الأسعار وسقف الائتمان -->
                        <div class="mcp-c10-grid-4" style="margin-bottom:12px;">
                            <div class="mcp-c10-section-box" style="margin-bottom:0;">
                                <div class="mcp-c10-field">
                                    <label for="mcpC10LifecycleSourceSelect">1️⃣ المستند المصدر (عرض سعر / أمر شراء / فاتورة)</label>
                                    <select id="mcpC10LifecycleSourceSelect">
                                        ${docs.map((d) => `<option value="${d.docId}">${d.docId} — ${d.partyName}</option>`).join('')}
                                    </select>
                                </div>
                            </div>
                            <div class="mcp-c10-section-box" style="margin-bottom:0;">
                                <div class="mcp-c10-field">
                                    <label for="mcpC10PricingTierSelect">2️⃣ شريحة التسعير الذكية للعميل/المورد</label>
                                    <select id="mcpC10PricingTierSelect">
                                        ${PRICING_TIERS.map((t) => `<option value="${t.code}">${t.label}</option>`).join('')}
                                    </select>
                                </div>
                            </div>
                            <div class="mcp-c10-section-box" style="margin-bottom:0;">
                                <div class="mcp-c10-field">
                                    <label for="mcpC10CreditCeilingInput">3️⃣ سقف الائتمان المسموح (Credit Limit)</label>
                                    <input type="text" id="mcpC10CreditCeilingInput" class="mcp-c10-num-input" value="50000000" />
                                </div>
                            </div>
                            <div class="mcp-c10-section-box" style="margin-bottom:0;">
                                <div class="mcp-c10-field">
                                    <label for="mcpC10MaturityDueDate">4️⃣ تاريخ استحقاق المديونية</label>
                                    <input type="date" id="mcpC10MaturityDueDate" value="2026-12-30" />
                                </div>
                            </div>
                        </div>

                        <!-- القسم 2: توزيع المصروفات المضافة وتحديد التكلفة الفعلية للوحدة (Landed Cost Allocation) -->
                        <div class="mcp-c10-section-box" style="border-color:rgba(56,189,248,0.6);">
                            <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:10px;">
                                <span style="font-size:0.92rem;font-weight:900;color:#38bdf8;">🚚 توزيع المصروفات المضافة على المشتريات (Landed Cost Allocation) وتحديد التكلفة الفعلية الحقيقية للوحدة:</span>
                                <div style="display:flex;align-items:center;gap:8px;">
                                    <label for="mcpC10AllocationMethod" style="font-size:0.82rem;font-weight:800;color:#e0f2fe;">معيار التوزيع المحاسبي:</label>
                                    <select id="mcpC10AllocationMethod" style="width:210px;height:36px;">
                                        <option value="by_value">حسب القيمة المالية للصنف (%)</option>
                                        <option value="by_weight">حسب الوزن الإجمالي بالكيلوجرام</option>
                                        <option value="by_qty">حسب عدد الوحدات (الكمية)</option>
                                    </select>
                                </div>
                            </div>

                            <div class="mcp-c10-grid-4">
                                <div class="mcp-c10-field">
                                    <label for="mcpC10ExpTransport">🚛 مصروفات النقل والشحن</label>
                                    <input type="text" id="mcpC10ExpTransport" class="mcp-c10-num-input" value="150000" />
                                </div>
                                <div class="mcp-c10-field">
                                    <label for="mcpC10ExpLoading">🏗️ مصروفات العتالة والتنزيل</label>
                                    <input type="text" id="mcpC10ExpLoading" class="mcp-c10-num-input" value="45000" />
                                </div>
                                <div class="mcp-c10-field">
                                    <label for="mcpC10ExpCustoms">🛃 رسوم جمركية وتخليص وأخرى</label>
                                    <input type="text" id="mcpC10ExpCustoms" class="mcp-c10-num-input" value="55000" />
                                </div>
                                <div class="mcp-c10-field">
                                    <label for="mcpC10ExpTotalDisplay">💰 إجمالي المصروفات المضافة الموزعة</label>
                                    <input type="text" id="mcpC10ExpTotalDisplay" class="mcp-c10-num-input" readonly value="250,000" style="color:#fbbf24 !important;border-color:#fbbf24 !important;" />
                                </div>
                            </div>

                            <table class="mcp-c10-table">
                                <thead>
                                    <tr>
                                        <th>الصنف</th>
                                        <th>الكمية</th>
                                        <th>الوزن (كجم)</th>
                                        <th>التكلفة الأصلية للوحدة</th>
                                        <th>سعر الشريحة المختارة</th>
                                        <th>نصيب الصنف من المصروفات</th>
                                        <th>التكلفة الفعلية للوحدة (Landed Cost)</th>
                                    </tr>
                                </thead>
                                <tbody id="mcpC10LandedCostTableBody"></tbody>
                            </table>

                            <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-top:12px;">
                                <span id="mcpC10LifecycleSummaryText" style="font-size:0.86rem;font-weight:800;color:#fde047;"></span>
                                <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
                                    <button type="button" id="mcpC10ApplyLandedOnlyBtn" class="mcp-c10-btn-primary" title="ترحيل مصروفات النقل والعتالة والشحن فقط إلى السند المجمع مع تحديث متوسط تكلفة المخزون">🚛 ترحيل مصروفات الشحن والعتالة فقط</button>
                                    <button type="button" id="mcpC10ConvertLifecycleBtn" class="mcp-c10-btn-emerald" title="تحويل المستند المصدر بضغطة زر إلى فاتورة + إذن مخزني + ترحيل مالي للسند المجمع بالتكلفة الفعلية">⚡ تحويل للدورة المستندية الكاملة وترحيل السند المجمع</button>
                                </div>
                            </div>
                        </div>

                        <!-- القسم 4: إدارة المرتجعات والتسويات والقيود العكسية الدقيقة (Returns & Reverse Accounting) -->
                        <div id="mcpC10ReturnsReverseBox" class="mcp-c10-section-box" style="border-color:rgba(244,63,94,0.6);margin-bottom:0;">
                            <div style="font-size:0.92rem;font-weight:900;color:#fb7185;margin-bottom:8px;">↩️ إدارة المرتجعات والتسويات وتوليد القيد العكسي الآلي الدقيق (كلي / جزئي — منع تجاوز الفاتورة الأصلية):</div>
                            <div class="mcp-c10-grid-4" style="margin-bottom:8px;">
                                <div class="mcp-c10-field">
                                    <label for="mcpC10ReturnOrigDocSelect">📄 جلب الفاتورة / السند الأصلي بضغطة</label>
                                    <select id="mcpC10ReturnOrigDocSelect"></select>
                                </div>
                                <div class="mcp-c10-field">
                                    <label for="mcpC10ReturnMaxQty">📦 الكمية / القيمة الأصلية القصوى</label>
                                    <input type="text" id="mcpC10ReturnMaxQty" class="mcp-c10-num-input" readonly value="0" />
                                </div>
                                <div class="mcp-c10-field">
                                    <label for="mcpC10ReturnWantedQty">🔢 الكمية / القيمة المراد إرجاعها</label>
                                    <input type="text" id="mcpC10ReturnWantedQty" class="mcp-c10-num-input" value="0" />
                                </div>
                                <div class="mcp-c10-field">
                                    <label for="mcpC10ReturnReasonInput">📝 سبب المرتجع والتسوية</label>
                                    <input type="text" id="mcpC10ReturnReasonInput" placeholder="مرتجع تسوية / استبدال" value="مرتجع جزئي على الفاتورة الأصلية" />
                                </div>
                            </div>
                            <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;">
                                <span id="mcpC10ReturnReversePreview" style="font-size:0.84rem;font-weight:800;color:#fecdd3;">⚡ القيد العكسي جاهز لضبط المخزن وكشف الحساب والنقدية في 0ms.</span>
                                <button type="button" id="mcpC10ExecReturnReverseBtn" class="mcp-c10-btn-rose">↩️ اعتماد المرتجع وتوليد القيد العكسي وضبط الأرصدة فوراً</button>
                            </div>
                        </div>
                    </div>
                `;
                modal.addEventListener('click', (ev) => {
                    if (ev.target === modal) this.closeCommercialModal();
                });
                document.body.appendChild(modal);
                this.bindCommercialEvents();
            },

            getSelectedLifecycleDoc() {
                const docId = document.getElementById('mcpC10LifecycleSourceSelect')?.value;
                const docs = this.getLifecycleDocs();
                return docs.find((d) => d.docId === docId) || docs[0];
            },

            populateSourceDocDropdown() {
                const sel = document.getElementById('mcpC10LifecycleSourceSelect');
                if (!sel) return;
                const docs = this.getLifecycleDocs();
                const currentVal = sel.value;
                sel.innerHTML = docs.map((d) => `<option value="${d.docId}">${d.docId} — ${d.partyName}</option>`).join('');
                if (currentVal && docs.some(d => d.docId === currentVal)) {
                    sel.value = currentVal;
                }
            },

            populateReturnDocDropdown() {
                const sel = document.getElementById('mcpC10ReturnOrigDocSelect');
                if (!sel) return;
                const docs = this.getLifecycleDocs();
                let html = '';
                docs.forEach((d) => {
                    const totalQty = (d.items || []).reduce((acc, it) => acc + (Number(it.qty) || 0), 0);
                    html += `<option value="DOC:${d.docId}" data-max="${totalQty}" data-type="doc">${d.docId} — ${d.partyName} (إجمالي كمية: ${totalQty})</option>`;
                });

                /* إضافة الفواتير المحولة أو السندات المجمعة المحفوظة */
                try {
                    const savedInvs = JSON.parse(localStorage.getItem(COMMERCIAL_INVOICES_KEY) || '[]');
                    savedInvs.slice(0, 10).forEach((inv) => {
                        if (!inv || !inv.invoiceId) return;
                        html += `<option value="INV:${inv.invoiceId}" data-max="${inv.totalAmount || 0}" data-type="invoice" data-party="${inv.partyName || ''}">فاتورة ${inv.invoiceId} — ${inv.partyName} (${Number(inv.totalAmount || 0).toLocaleString('en-US')})</option>`;
                    });
                } catch (e) {}

                sel.innerHTML = html;
                this.handleReturnSourceSelection();
            },

            handleReturnSourceSelection() {
                const sel = document.getElementById('mcpC10ReturnOrigDocSelect');
                if (!sel || sel.selectedIndex < 0) return;
                const opt = sel.options[sel.selectedIndex];
                const maxVal = this.parseNum(opt?.getAttribute('data-max'));
                const maxEl = document.getElementById('mcpC10ReturnMaxQty');
                const wantEl = document.getElementById('mcpC10ReturnWantedQty');
                if (maxEl) maxEl.value = String(maxVal);
                if (wantEl) {
                    const cur = this.parseNum(wantEl.value);
                    if (cur <= 0 || cur > maxVal) {
                        wantEl.value = String(Math.max(1, Math.round(maxVal * 0.25)));
                    }
                }
                this.updateReturnPreviewText();
            },

            updateReturnPreviewText() {
                const sel = document.getElementById('mcpC10ReturnOrigDocSelect');
                const opt = sel && sel.selectedIndex >= 0 ? sel.options[sel.selectedIndex] : null;
                const maxVal = this.parseNum(opt?.getAttribute('data-max'));
                const wantVal = this.parseNum(document.getElementById('mcpC10ReturnWantedQty')?.value);
                const previewEl = document.getElementById('mcpC10ReturnReversePreview');
                if (!previewEl) return;

                if (wantVal > maxVal) {
                    previewEl.style.color = '#fda4af';
                    previewEl.textContent = `🚨 ممنوع محاسبياً: الكمية/القيمة المرتجعة (${wantVal.toLocaleString('en-US')}) أكبر من أصل المستند (${maxVal.toLocaleString('en-US')})!`;
                } else if (wantVal <= 0) {
                    previewEl.style.color = '#fde047';
                    previewEl.textContent = 'ℹ️ أدخل الكمية أو القيمة المراد إرجاعها لتوليد القيد العكسي الآلي.';
                } else {
                    previewEl.style.color = '#a7f3d0';
                    previewEl.textContent = `✅ جاهز لتوليد القيد العكسي الدقيق لـ (${wantVal.toLocaleString('en-US')} من أصل ${maxVal.toLocaleString('en-US')}) وضبط المخزن وكشف الحساب والنقدية في 0ms.`;
                }
            },

            recalculateCommercialAndLandedCost(syncFromSourceDoc = false) {
                const doc = this.getSelectedLifecycleDoc();
                if (!doc) return null;

                if (syncFromSourceDoc) {
                    const tierSel = document.getElementById('mcpC10PricingTierSelect');
                    if (tierSel && doc.tierCode) tierSel.value = doc.tierCode;
                    const ceilEl = document.getElementById('mcpC10CreditCeilingInput');
                    if (ceilEl && doc.creditLimit) ceilEl.value = String(doc.creditLimit);
                    const dueEl = document.getElementById('mcpC10MaturityDueDate');
                    if (dueEl && doc.dueDate) dueEl.value = doc.dueDate;
                }

                const tierCode = document.getElementById('mcpC10PricingTierSelect')?.value || 'wholesale';
                const tierObj = PRICING_TIERS.find((t) => t.code === tierCode) || PRICING_TIERS[0];
                const allocMethod = document.getElementById('mcpC10AllocationMethod')?.value || 'by_value';

                const expTrans = this.parseNum(document.getElementById('mcpC10ExpTransport')?.value);
                const expLoad = this.parseNum(document.getElementById('mcpC10ExpLoading')?.value);
                const expCust = this.parseNum(document.getElementById('mcpC10ExpCustoms')?.value);
                const totalAddedExpenses = Math.round((expTrans + expLoad + expCust) * 100) / 100;

                const expTotEl = document.getElementById('mcpC10ExpTotalDisplay');
                if (expTotEl) expTotEl.value = totalAddedExpenses.toLocaleString('en-US');

                const items = Array.isArray(doc.items) ? doc.items : [];
                let totalBaseCostValue = 0;
                let totalWeightKg = 0;
                let totalQtyUnits = 0;

                items.forEach((it) => {
                    const q = Number(it.qty) || 0;
                    const c = Number(it.baseUnitCost) || 0;
                    const w = Number(it.weightKg) || 0;
                    totalBaseCostValue += q * c;
                    totalWeightKg += w;
                    totalQtyUnits += q;
                });

                const tbody = document.getElementById('mcpC10LandedCostTableBody');
                let rowsHtml = '';
                let totalTierRevenue = 0;
                let totalTrueLandedCost = 0;
                const computedItems = [];

                items.forEach((it) => {
                    const q = Number(it.qty) || 1;
                    const w = Number(it.weightKg) || 0;
                    const origCost = Number(it.baseUnitCost) || 0;
                    const origLineCost = q * origCost;
                    const tierUnitPrice = Math.round((Number(it.baseUnitPrice) || 0) * tierObj.multiplier * 100) / 100;

                    let weightRatio = 0;
                    if (allocMethod === 'by_weight' && totalWeightKg > 0) {
                        weightRatio = w / totalWeightKg;
                    } else if (allocMethod === 'by_qty' && totalQtyUnits > 0) {
                        weightRatio = q / totalQtyUnits;
                    } else if (totalBaseCostValue > 0) {
                        weightRatio = origLineCost / totalBaseCostValue;
                    }

                    const allocatedExpenseForLine = Math.round(totalAddedExpenses * weightRatio * 100) / 100;
                    const addedCostPerUnit = q > 0 ? (allocatedExpenseForLine / q) : 0;
                    const trueLandedUnitCost = Math.round((origCost + addedCostPerUnit) * 100) / 100;

                    totalTierRevenue += q * tierUnitPrice;
                    totalTrueLandedCost += origLineCost + allocatedExpenseForLine;

                    computedItems.push({
                        ...it,
                        tierUnitPrice,
                        allocatedExpenseForLine,
                        trueLandedUnitCost
                    });

                    rowsHtml += `
                        <tr>
                            <td style="font-weight:900;">${it.name}</td>
                            <td style="font-family:Consolas,monospace;">${q.toLocaleString('en-US')}</td>
                            <td style="font-family:Consolas,monospace;">${w.toLocaleString('en-US')}</td>
                            <td style="font-family:Consolas,monospace;">${origCost.toLocaleString('en-US')}</td>
                            <td style="color:#38bdf8;font-weight:900;font-family:Consolas,monospace;">${tierUnitPrice.toLocaleString('en-US')}</td>
                            <td style="color:#fbbf24;font-weight:800;font-family:Consolas,monospace;">+ ${allocatedExpenseForLine.toLocaleString('en-US')}</td>
                            <td style="color:#34d399;font-weight:900;font-family:Consolas,monospace;">${trueLandedUnitCost.toLocaleString('en-US')}</td>
                        </tr>
                    `;
                });

                if (tbody) tbody.innerHTML = rowsHtml;

                /* حساب هامش الربح اللحظي (حسب صلاحية المستخدم) */
                const profitBadge = document.getElementById('mcpC10LiveProfitMarginBadge');
                if (profitBadge) {
                    if (!this.canUserSeeProfitMargin()) {
                        profitBadge.textContent = '🔒 هامش الربح محمي بصلاحية الإدارة';
                    } else {
                        const netProfit = Math.round((totalTierRevenue - totalTrueLandedCost) * 100) / 100;
                        const marginPct = totalTierRevenue > 0 ? Math.round((netProfit / totalTierRevenue) * 1000) / 10 : 0;
                        profitBadge.textContent = `📈 صافي الربح بعد المصروفات المضافة: ${netProfit.toLocaleString('en-US')} (${marginPct}%)`;
                    }
                }

                /* الرقابة الصارمة على سقف الائتمان وتاريخ الاستحقاق */
                const creditLimit = this.parseNum(document.getElementById('mcpC10CreditCeilingInput')?.value);
                const dueDateStr = document.getElementById('mcpC10MaturityDueDate')?.value || '';
                const currentDebt = Number(doc.currentDebt) || 0;
                const projectedExposure = currentDebt + totalTrueLandedCost;
                const isOverdue = Boolean(dueDateStr && new Date(dueDateStr).getTime() < Date.now());
                const isCreditExceeded = Boolean(creditLimit > 0 && projectedExposure > creditLimit);
                const isOverrideChecked = Boolean(document.getElementById('mcpC10OfficialCreditOverrideCheck')?.checked);

                const creditTxt = document.getElementById('mcpC10CreditStatusText');
                const creditBanner = document.getElementById('mcpC10CreditControlBanner');
                if (creditTxt && creditBanner) {
                    if (isCreditExceeded && !isOverrideChecked) {
                        creditBanner.style.borderColor = '#ef4444';
                        creditBanner.style.background = 'rgba(127, 29, 29, 0.42)';
                        creditTxt.textContent = `🚨 قفل سقف الائتمان: إجمالي المديونية (${projectedExposure.toLocaleString('en-US')}) يتجاوز السقف المعتمد (${creditLimit.toLocaleString('en-US')})! فعّل "تعميد إداري" للمتابعة.${isOverdue ? ' [تاريخ الاستحقاق متأخر!]' : ''}`;
                    } else if (isCreditExceeded && isOverrideChecked) {
                        creditBanner.style.borderColor = '#f59e0b';
                        creditBanner.style.background = 'rgba(120, 53, 15, 0.42)';
                        creditTxt.textContent = `🛡️ تجاوز ائتماني معمد إدارياً: المديونية (${projectedExposure.toLocaleString('en-US')}) فوق السقف (${creditLimit.toLocaleString('en-US')}).`;
                    } else if (isOverdue) {
                        creditBanner.style.borderColor = '#f59e0b';
                        creditBanner.style.background = 'rgba(120, 53, 15, 0.36)';
                        creditTxt.textContent = `⚠️ تنبيه استحقاق المديونية: تاريخ استحقاق هذا الطرف (${dueDateStr}) قد حلّ — يرجى التحصيل أو التسوية.`;
                    } else {
                        creditBanner.style.borderColor = '#10b981';
                        creditBanner.style.background = 'rgba(6, 78, 59, 0.32)';
                        creditTxt.textContent = `🛡️ رقابة الائتمان آمنة: المديونية بعد الحركة (${projectedExposure.toLocaleString('en-US')}) ضمن سقف الائتمان (${creditLimit.toLocaleString('en-US')}).`;
                    }
                }

                const summaryEl = document.getElementById('mcpC10LifecycleSummaryText');
                if (summaryEl) {
                    summaryEl.textContent = `📊 تكلفة الأصناف الأصلية: ${totalBaseCostValue.toLocaleString('en-US')} + المصروفات المضافة (${totalAddedExpenses.toLocaleString('en-US')}) = الإجمالي الفعلي (Landed Total): ${Math.round(totalTrueLandedCost).toLocaleString('en-US')}`;
                }

                return {
                    doc,
                    tierObj,
                    allocMethod,
                    expTrans,
                    expLoad,
                    expCust,
                    totalBaseCostValue: Math.round(totalBaseCostValue * 100) / 100,
                    totalAddedExpenses,
                    totalTrueLandedCost: Math.round(totalTrueLandedCost * 100) / 100,
                    computedItems,
                    blockedByCredit: isCreditExceeded && !isOverrideChecked
                };
            },

            applyBlockPosting(bid, accountName, amountVal, statementText) {
                const accSearch = document.getElementById(`account-${bid}-search`);
                const accHidden = document.getElementById(`account-${bid}`);
                if (accountName && accSearch) {
                    accSearch.value = accountName;
                    if (accHidden) accHidden.value = accountName;
                }
                if (window.McpDesktopConstitution9 && typeof window.McpDesktopConstitution9.applyAmountAndStatementToBlock === 'function') {
                    window.McpDesktopConstitution9.applyAmountAndStatementToBlock(bid, amountVal, statementText);
                    return;
                }
                const formatted = Number(amountVal || 0).toFixed(2);
                const cashDetails = document.getElementById(`cash-details-${bid}`);
                const cashInput = document.getElementById(`cash-amount-${bid}`);
                if (cashDetails && cashDetails.style.display === 'none') {
                    const cashToggle = document.getElementById(`pm-cash-${bid}`);
                    if (cashToggle) cashToggle.click();
                    else cashDetails.style.display = 'block';
                }
                if (cashInput) {
                    cashInput.value = formatted;
                    cashInput.dispatchEvent(new Event('input', { bubbles: true }));
                    cashInput.dispatchEvent(new Event('change', { bubbles: true }));
                }
                const stmtEl = document.getElementById(`statement-${bid}`);
                if (stmtEl) {
                    stmtEl.value = statementText;
                    stmtEl.dispatchEvent(new Event('input', { bubbles: true }));
                }
                if (typeof window.recalcBlockTotal === 'function') window.recalcBlockTotal(bid);
                if (typeof window.calcTotal === 'function') window.calcTotal();
            },

            resolveOrCreateBlockId(preferredValue) {
                if (preferredValue && preferredValue !== 'NEW_BLOCK' && document.querySelector(`.account-block[data-block-id="${preferredValue}"]`)) {
                    return preferredValue;
                }
                if (typeof window.addAccountBlock === 'function') {
                    window.addAccountBlock();
                }
                const allBlocks = Array.from(document.querySelectorAll('.account-block'));
                const lastBlk = allBlocks[allBlocks.length - 1];
                return lastBlk ? lastBlk.getAttribute('data-block-id') : '1';
            },

            commitLandedCostOrFullLifecycle(expensesOnly = false) {
                const calc = this.recalculateCommercialAndLandedCost(false);
                if (!calc || !calc.doc) return false;

                if (!expensesOnly && calc.blockedByCredit) {
                    if (typeof window.showToast === 'function') {
                        window.showToast('⛔ مرفوض ائتمانياً: الطرف متجاوز لسقف الائتمان المسموح! يرجى تفعيل "تعميد إداري بتجاوز سقف الائتمان" للمتابعة.', 'error');
                    }
                    return false;
                }

                const { doc, tierObj, allocMethod, expTrans, expLoad, expCust, totalBaseCostValue, totalAddedExpenses, totalTrueLandedCost, computedItems } = calc;

                /* 1. تحديث متوسط تكلفة الوحدة والأرصدة المخزنية في الدستور التاسع (Moving Weighted Average Cost & Stock) */
                try {
                    if (window.McpDesktopConstitution9 && Array.isArray(window.McpDesktopConstitution9.catalog)) {
                        const cat = window.McpDesktopConstitution9.catalog;
                        computedItems.forEach((it) => {
                            const target = cat.find((c) => c.id === it.id || c.name.includes(it.name.split(' ')[0]));
                            if (target) {
                                if (Array.isArray(target.units) && target.units[0]) {
                                    target.units[0].defaultPrice = it.trueLandedUnitCost;
                                }
                                if (!expensesOnly && target.stockByWarehouseBase && target.stockByWarehouseBase.WH_MAIN) {
                                    target.stockByWarehouseBase.WH_MAIN.available += Number(it.qty) || 0;
                                }
                            }
                        });
                        window.McpDesktopConstitution9.saveCatalog();
                    }
                } catch (e) {}

                /* 2. توليد الفاتورة التجارية وإذن الاستلام/الصرف المخزني المرتبط في الدورة المستندية */
                const generatedInvoiceId = 'INV-' + Date.now().toString().slice(-6);
                const generatedPermitId = 'WH-PERM-' + Date.now().toString().slice(-6);
                try {
                    const invList = JSON.parse(localStorage.getItem(COMMERCIAL_INVOICES_KEY) || '[]');
                    invList.unshift({
                        invoiceId: generatedInvoiceId,
                        permitId: generatedPermitId,
                        sourceDocId: doc.docId,
                        partyName: doc.partyName,
                        tierCode: tierObj.code,
                        allocMethod,
                        baseAmount: totalBaseCostValue,
                        landedExpenses: totalAddedExpenses,
                        totalAmount: expensesOnly ? totalAddedExpenses : totalTrueLandedCost,
                        createdAt: new Date().toISOString()
                    });
                    localStorage.setItem(COMMERCIAL_INVOICES_KEY, JSON.stringify(invList.slice(0, 40)));

                    const lcHistory = JSON.parse(localStorage.getItem(LANDED_COST_KEY) || '[]');
                    lcHistory.unshift({
                        id: 'LC-' + Date.now(),
                        sourceDocId: doc.docId,
                        invoiceId: generatedInvoiceId,
                        permitId: generatedPermitId,
                        partyName: doc.partyName,
                        tierCode: tierObj.code,
                        allocMethod,
                        totalAddedExpenses,
                        totalTrueLandedCost,
                        mode: expensesOnly ? 'LANDED_EXPENSES_ONLY' : 'FULL_DOCUMENT_LIFECYCLE',
                        createdAt: new Date().toISOString()
                    });
                    localStorage.setItem(LANDED_COST_KEY, JSON.stringify(lcHistory.slice(0, 40)));
                } catch (e) {}

                /* 3. ترحيل المبالغ والبيانات إلى بطاقة/بطاقات السند المجمع */
                const splitBlocks = Boolean(document.getElementById('mcpC10SplitLandedBlocksCheck')?.checked);
                const selectedTarget = document.getElementById('mcpC10TargetBlockSelect')?.value || this.activeTargetBlockId;
                const allocLabel = allocMethod === 'by_weight' ? 'بالوزن' : allocMethod === 'by_qty' ? 'بالكمية' : 'بالقيمة';

                if (expensesOnly) {
                    const bid = this.resolveOrCreateBlockId(selectedTarget);
                    const stmt = `[مصروفات مضافة Landed Cost — ${doc.docId}] موزعة (${allocLabel}) على أصناف (${doc.partyName}): نقل وشحن (${expTrans.toLocaleString('en-US')}) + عتالة (${expLoad.toLocaleString('en-US')}) + جمارك وتخليص (${expCust.toLocaleString('en-US')})`;
                    this.applyBlockPosting(bid, 'مصاريف نقل وشحن وتخليص مشتريات (Landed Cost)', totalAddedExpenses, stmt);
                } else if (splitBlocks && totalAddedExpenses > 0) {
                    /* توزيع ذكي في السند المجمع: بطاقة للمورد الأساسي + بطاقة لمصاريف النقل والعتالة والتخليص */
                    const mainBid = this.resolveOrCreateBlockId(selectedTarget);
                    const mainStmt = `[دورة مستندية كاملة: ${doc.docId} ⬅️ فاتورة ${generatedInvoiceId} + إذن مخزني ${generatedPermitId}] صافي قيمة البضاعة للمورد (${doc.partyName}) — شريحة: ${tierObj.label}`;
                    this.applyBlockPosting(mainBid, doc.partyName, totalBaseCostValue, mainStmt);

                    const expBid = this.resolveOrCreateBlockId('NEW_BLOCK');
                    const expStmt = `[توزيع مصروفات مضافة Landed Cost على فاتورة ${generatedInvoiceId}] موزعة (${allocLabel}): نقل (${expTrans.toLocaleString('en-US')}) + عتالة (${expLoad.toLocaleString('en-US')}) + رسوم (${expCust.toLocaleString('en-US')})`;
                    this.applyBlockPosting(expBid, 'متعهد النقل والشحن والتخليص الجمركي (Landed Cost)', totalAddedExpenses, expStmt);
                } else {
                    const bid = this.resolveOrCreateBlockId(selectedTarget);
                    const fullStmt = `[تحويل آلي للدورة المستندية: ${doc.docId} ⬅️ فاتورة ${generatedInvoiceId} + إذن مخزني ${generatedPermitId}] الطرف: ${doc.partyName} — شريحة: ${tierObj.label} — شامل المصروفات المضافة الموزعة ${allocLabel} (${totalAddedExpenses.toLocaleString('en-US')})`;
                    this.applyBlockPosting(bid, doc.partyName, totalTrueLandedCost, fullStmt);
                }

                this.closeCommercialModal();
                if (typeof window.showToast === 'function') {
                    window.showToast(
                        expensesOnly
                            ? `🚛 تم توزيع المصروفات المضافة (${totalAddedExpenses.toLocaleString('en-US')}) وتحديث التكلفة الفعلية للوحدة وترحيل السند فوراً!`
                            : `⚡ اكتمل تحويل الدورة المستندية (${doc.docId} ⬅️ ${generatedInvoiceId} + ${generatedPermitId}) وترحيل السند المجمع بنسبة خطأ 0%!`,
                        'success'
                    );
                }
                return true;
            },

            executeReturnAndReverseAccounting() {
                const sel = document.getElementById('mcpC10ReturnOrigDocSelect');
                if (!sel || sel.selectedIndex < 0) return false;
                const opt = sel.options[sel.selectedIndex];
                const rawVal = opt.value || '';
                const maxVal = this.parseNum(opt.getAttribute('data-max'));
                const wantVal = this.parseNum(document.getElementById('mcpC10ReturnWantedQty')?.value);
                const reason = (document.getElementById('mcpC10ReturnReasonInput')?.value || 'مرتجع وتسوية عكسية').trim();

                if (wantVal <= 0) {
                    if (typeof window.showToast === 'function') {
                        window.showToast('⚠️ يرجى إدخال كمية أو قيمة مرتجع صحيحة أكبر من الصفر.', 'warning');
                    }
                    return false;
                }
                if (wantVal > maxVal) {
                    if (typeof window.showToast === 'function') {
                        window.showToast(`🚨 مرفوض محاسبياً: لا يمكن إرجاع (${wantVal.toLocaleString('en-US')}) لأنها أكبر من أصل المستند (${maxVal.toLocaleString('en-US')})!`, 'error');
                    }
                    return false;
                }

                /* قفل عدم مضاعفة القيود العكسية عند الضغط المتكرر */
                const sig = `${rawVal}__${wantVal}__${reason}`;
                if (this.lastReverseSignature === sig && (Date.now() - this.lastReverseTime) < 2500) {
                    return false;
                }
                this.lastReverseSignature = sig;
                this.lastReverseTime = Date.now();

                let reverseAmount = wantVal;
                let partyName = opt.getAttribute('data-party') || opt.textContent.split('(')[0].trim();

                if (rawVal.startsWith('DOC:')) {
                    const docId = rawVal.replace('DOC:', '');
                    const doc = this.getLifecycleDocs().find((d) => d.docId === docId);
                    if (doc && Array.isArray(doc.items) && doc.items[0]) {
                        reverseAmount = Math.round(wantVal * (Number(doc.items[0].baseUnitCost) || 10000) * 100) / 100;
                        partyName = doc.partyName;
                    }
                }

                const revEntry = {
                    returnId: 'RET-REV-' + Date.now().toString().slice(-6),
                    sourceRef: rawVal,
                    partyLabel: partyName,
                    returnedQtyOrVal: wantVal,
                    maxOrigQtyOrVal: maxVal,
                    reverseAmount,
                    reason,
                    debitAccount: 'حساب المورد / الذمم أو الخزينة (قيد عكسي)',
                    creditAccount: 'حساب المخزون / مرتجعات المشتريات والتسويات',
                    createdAt: new Date().toISOString()
                };

                try {
                    const rets = JSON.parse(localStorage.getItem(RETURNS_KEY) || '[]');
                    rets.unshift(revEntry);
                    localStorage.setItem(RETURNS_KEY, JSON.stringify(rets.slice(0, 40)));

                    const journals = JSON.parse(localStorage.getItem('erp_journal_entries_v1') || '[]');
                    journals.unshift({
                        id: revEntry.returnId,
                        date: new Date().toISOString().slice(0, 10),
                        description: `قيد عكسي آلي لمرتجع (${partyName} - ${rawVal}) — السبب: ${reason}`,
                        debit: reverseAmount,
                        credit: reverseAmount,
                        isReverseEntry: true
                    });
                    localStorage.setItem('erp_journal_entries_v1', JSON.stringify(journals.slice(0, 100)));
                } catch (e) {}

                const selectedTarget = document.getElementById('mcpC10TargetBlockSelect')?.value || this.activeTargetBlockId;
                const bid = this.resolveOrCreateBlockId(selectedTarget);
                const revStmt = `[قيد تسوية ومرتجع عكسي آلي رقم ${revEntry.returnId}] على (${rawVal} — ${partyName}) — المرتجع: (${wantVal} من أصل ${maxVal}) — السبب: ${reason}`;
                this.applyBlockPosting(bid, partyName, reverseAmount, revStmt);

                this.closeCommercialModal();
                if (typeof window.showToast === 'function') {
                    window.showToast(`↩️ تم توليد القيد العكسي الآلي (${revEntry.returnId} بمبلغ ${reverseAmount.toLocaleString('en-US')}) وضبط المخزن وكشف الحساب في 0ms!`, 'success');
                }
                return true;
            },

            handleQuickAddSourceDoc() {
                const docId = (document.getElementById('mcpC10NewDocId')?.value || ('QT-' + Date.now().toString().slice(-4))).trim();
                const partyName = (document.getElementById('mcpC10NewPartyName')?.value || 'طرف تجاري جديد').trim();
                const itemName = (document.getElementById('mcpC10NewItemName')?.value || 'صنف تجاري').trim();
                const qty = Math.max(1, this.parseNum(document.getElementById('mcpC10NewItemQty')?.value));
                const cost = Math.max(1, this.parseNum(document.getElementById('mcpC10NewItemCost')?.value));
                const price = Math.max(cost, this.parseNum(document.getElementById('mcpC10NewItemPrice')?.value));

                const docs = this.getLifecycleDocs();
                const newDoc = {
                    docId,
                    docType: 'عرض سعر / أمر توريد مضاف فورياً',
                    partyId: 'party-' + Date.now(),
                    partyName,
                    tierCode: 'wholesale',
                    creditLimit: 50000000,
                    currentDebt: 0,
                    dueDate: '2026-12-31',
                    items: [
                        { id: 'ITM_' + Date.now(), name: itemName, qty, weightKg: qty * 10, baseUnitPrice: price, baseUnitCost: cost }
                    ]
                };
                docs.unshift(newDoc);
                this.saveLifecycleDocs(docs);
                this.populateSourceDocDropdown();
                const sel = document.getElementById('mcpC10LifecycleSourceSelect');
                if (sel) sel.value = docId;
                this.populateReturnDocDropdown();
                this.recalculateCommercialAndLandedCost(true);

                const addBar = document.getElementById('mcpC10QuickAddDocBar');
                if (addBar) addBar.style.display = 'none';

                if (typeof window.showToast === 'function') {
                    window.showToast(`✅ تم إنشاء المستند المصدر (${docId} — ${partyName}) وتفعيله في الدورة المستندية فوراً!`, 'success');
                }
            },

            bindCommercialEvents() {
                document.getElementById('mcpC10CloseModalBtn')?.addEventListener('click', () => this.closeCommercialModal());
                document.getElementById('mcpC10ToggleAddDocBtn')?.addEventListener('click', () => {
                    const bar = document.getElementById('mcpC10QuickAddDocBar');
                    if (bar) bar.style.display = bar.style.display === 'none' ? 'block' : 'none';
                });
                document.getElementById('mcpC10SaveNewDocBtn')?.addEventListener('click', () => this.handleQuickAddSourceDoc());
                document.getElementById('mcpC10TargetBlockSelect')?.addEventListener('change', (e) => {
                    this.activeTargetBlockId = e.target.value;
                });

                document.getElementById('mcpC10LifecycleSourceSelect')?.addEventListener('change', () => this.recalculateCommercialAndLandedCost(true));

                [
                    'mcpC10PricingTierSelect',
                    'mcpC10AllocationMethod',
                    'mcpC10CreditCeilingInput',
                    'mcpC10MaturityDueDate',
                    'mcpC10ExpTransport',
                    'mcpC10ExpLoading',
                    'mcpC10ExpCustoms',
                    'mcpC10OfficialCreditOverrideCheck'
                ].forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) {
                        el.addEventListener('input', () => this.recalculateCommercialAndLandedCost(false));
                        el.addEventListener('change', () => this.recalculateCommercialAndLandedCost(false));
                    }
                });

                document.getElementById('mcpC10ApplyLandedOnlyBtn')?.addEventListener('click', () => this.commitLandedCostOrFullLifecycle(true));
                document.getElementById('mcpC10ConvertLifecycleBtn')?.addEventListener('click', () => this.commitLandedCostOrFullLifecycle(false));

                document.getElementById('mcpC10ReturnOrigDocSelect')?.addEventListener('change', () => this.handleReturnSourceSelection());
                document.getElementById('mcpC10ReturnWantedQty')?.addEventListener('input', () => this.updateReturnPreviewText());
                document.getElementById('mcpC10ExecReturnReverseBtn')?.addEventListener('click', () => this.executeReturnAndReverseAccounting());
            },

            initMainScreenCreditAndTierMonitor() {
                document.addEventListener('change', (e) => {
                    const t = e.target;
                    if (!t || !t.classList || !t.classList.contains('block-account-search')) return;
                    const val = (t.value || '').trim();
                    if (!val) return;
                    const matchedDoc = this.getLifecycleDocs().find((d) => val.includes(d.partyName) || d.partyName.includes(val));
                    if (matchedDoc && matchedDoc.currentDebt > matchedDoc.creditLimit && typeof window.showToast === 'function') {
                        window.showToast(`🚨 رقابة الائتمان (الدستور 10): الطرف (${matchedDoc.partyName}) متجاوز لسقف الائتمان المسموح (${matchedDoc.creditLimit.toLocaleString('en-US')})!`, 'warning');
                    }
                });
            },

            openCommercialModal(preferredBlockId) {
                this.injectCommercialModal();
                this.populateTargetBlockSelect(preferredBlockId);
                this.populateSourceDocDropdown();
                this.populateReturnDocDropdown();
                this.recalculateCommercialAndLandedCost(true);
                const modal = document.getElementById('mcpC10CommercialHubModal');
                if (modal) modal.classList.add('c10-modal-open');
            },

            closeCommercialModal() {
                const modal = document.getElementById('mcpC10CommercialHubModal');
                if (modal) modal.classList.remove('c10-modal-open');
            },

            registerWithSmartGuide() {
                const c4 = window.McpDesktopConstitution4;
                if (!c4 || !Array.isArray(c4.steps)) return;
                const alreadyExists = c4.steps.some(s => s && s.id === 'c10_commercial_landed_lifecycle_returns');
                if (!alreadyExists) {
                    const stepIdx = c4.steps.length;
                    const c10Step = {
                        id: 'c10_commercial_landed_lifecycle_returns',
                        title: '2️⃣4️⃣ العمق التجاري: شرائح التسعير، توزيع المصروفات المضافة (Landed Cost)، الدورة المستندية، والمرتجعات (F6)',
                        selector: '#mcpC10OpenCommercialBtn',
                        badge: 'الدستور 10 — العمق التجاري & Landed Cost',
                        purpose: 'تطبيق شرائح الأسعار الذكية (جملة، نصف جملة، قطاعي، سعر خاص، آخر سعر) مع رقابة سقف الائتمان والربحية اللحظية، وتوزيع مصروفات النقل والشحن والعتالة والجمارك آلياً على تكلفة الوحدة (Landed Cost)، وتحويل المستندات بضغطة زر إلى فاتورة وإذن مخزني وسند مالي مجمع، وإدارة المرتجعات والقيود العكسية.',
                        goldenRule: 'القاعدة الذهبية: لا تسجل مصروفات النقل والشحن والعتالة بمعزل عن البضاعة؛ افتح شاشة (العمق التجاري F6) لتوزيع المصروفات المضافة آلياً على تكلفة الوحدة، أو تحويل عرض السعر/أمر الشراء بضغطة زر إلى فاتورة وإذن مخزني وسند مجمع، أو توليد قيد عكسي فوري للمرتجعات.',
                        simAction: () => {
                            this.openCommercialModal();
                            setTimeout(() => {
                                const tierSel = document.getElementById('mcpC10PricingTierSelect');
                                if (tierSel) {
                                    tierSel.value = 'vip_custom';
                                    this.recalculateCommercialAndLandedCost(false);
                                }
                            }, 350);
                        }
                    };
                    c4.steps.push(c10Step);
                    const selectEl = document.getElementById('mcpC4JumpSelect');
                    if (selectEl) {
                        const opt = document.createElement('option');
                        opt.value = String(stepIdx);
                        opt.textContent = '2️⃣4️⃣ العمق التجاري، Landed Cost، الدورة المستندية، والمرتجعات (F6)';
                        selectEl.appendChild(opt);
                    }
                    const counterEl = document.getElementById('mcpC4StepCounterBadge');
                    if (counterEl) {
                        counterEl.textContent = (c4.currentStepIndex + 1) + ' / ' + c4.steps.length;
                    }
                }
            },

            init() {
                this.ensureSeedData();
                this.injectTopBarButton();
                this.ensureBlockCommercialButtons();
                this.injectCommercialModal();
                this.initMainScreenCreditAndTierMonitor();
                this.registerWithSmartGuide();

                const container = document.getElementById('accounts-container');
                if (container && typeof MutationObserver !== 'undefined') {
                    const obs = new MutationObserver(() => this.ensureBlockCommercialButtons());
                    obs.observe(container, { childList: true });
                }

                document.addEventListener('keydown', (ev) => {
                    if (ev.key === 'F6' || (ev.altKey && (ev.key === 'l' || ev.key === 'L'))) {
                        ev.preventDefault();
                        const modal = document.getElementById('mcpC10CommercialHubModal');
                        if (modal && modal.classList.contains('c10-modal-open')) {
                            this.closeCommercialModal();
                        } else {
                            this.openCommercialModal();
                        }
                    } else if (ev.key === 'Escape') {
                        const modal = document.getElementById('mcpC10CommercialHubModal');
                        if (modal && modal.classList.contains('c10-modal-open')) {
                            this.closeCommercialModal();
                        }
                    }
                });

                setTimeout(() => this.registerWithSmartGuide(), 850);
            }
        };

        window.McpDesktopConstitution10 = McpDesktopConstitution10;
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => McpDesktopConstitution10.init());
        } else {
            McpDesktopConstitution10.init();
        }
    })();
    </script>

    <!-- ═══════════════════════════════════════════════════════════════════════════════
         🏦 الدستور الحادي عشر (11 من 14): دستور دورة الشيكات الكاملة من الألف للياء،
            رقابة التحويلات البنكية ومنع تكرار الإشعار للاختلاس، وإقفال الفترات المالية
         ═══════════════════════════════════════════════════════════════════════════════ -->
    <style id="mcp-constitution-11-banking-cheques-styles">
