            color: #ffffff;
            font-size: 0.74rem;
            font-weight: 900;
            font-family: 'Consolas', monospace;
        }
        .btn-block-c11-cheque:hover {
            background: rgba(59, 130, 246, 0.3) !important;
            border-color: #60a5fa !important;
            color: #ffffff !important;
            transform: translateY(-1px);
        }

        /* نافذة حافظة الشيكات الكاملة، التحصيل، الارتداد، التظهير، وإقفال الفترات المالية */
        #mcpC11ChequePortfolioModal {
            position: fixed;
            inset: 0;
            z-index: 2147483590;
            background: rgba(2, 6, 23, 0.86);
            backdrop-filter: blur(8px);
            display: none;
            align-items: center;
            justify-content: center;
            padding: 14px;
            direction: rtl;
            font-family: 'Tajawal', sans-serif;
        }
        #mcpC11ChequePortfolioModal.c11-modal-open {
            display: flex !important;
        }
        .mcp-c11-modal-card {
            width: 100%;
            max-width: 1180px;
            max-height: 92vh;
            overflow-y: auto;
            background: linear-gradient(165deg, #0f172a 0%, #0a1931 100%);
            border: 3.5px solid #3b82f6 !important;
            border-radius: 18px;
            box-shadow: 0 24px 60px rgba(0, 0, 0, 0.92), 0 0 0 1px rgba(59, 130, 246, 0.35);
            padding: 18px 20px;
            color: #f8fafc;
        }
        .mcp-c11-modal-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 10px;
            padding-bottom: 12px;
            margin-bottom: 12px;
            border-bottom: 2.5px solid rgba(59, 130, 246, 0.45);
            flex-wrap: wrap;
        }
        .mcp-c11-section-box {
            background: rgba(15, 23, 42, 0.88);
            border: 2.5px solid rgba(59, 130, 246, 0.48);
            border-radius: 13px;
            padding: 12px 14px;
