    <script id="mcp-constitution-13-cybersecurity-blackbox-engine">
    (function () {
        'use strict';
        if (window.McpDesktopConstitution13) return;

        const BLACKBOX_STORAGE_KEY   = 'erp_immutable_blackbox_v1';
        const ALERTS_STORAGE_KEY     = 'erp_owner_silent_alerts_v1';
        const TIMELOCK_STORAGE_KEY   = 'erp_monotonic_timelock_v1';
        const VAULT_STORAGE_KEY      = 'erp_encrypted_cyber_vault_v1';
        const IDLE_TIMEOUT_MS        = 3 * 60 * 1000; // 3 دقائق خمول تلقائي
        const QUICK_USER_PIN         = '1234';
        const OWNER_MASTER_PIN       = '2026';

        const McpDesktopConstitution13 = {
            idleTimer: null,
            lastActivityTs: Date.now(),
            isScreenLocked: false,
            failedPinCount: 0,
            timeLockBreached: false,
            monotonicCounter: 1,
            currentAlertFilter: 'ALL',
            parkCountSession: 0,
            deletedBlockCountSession: 0,
            deviceFingerprint: '',
            clientIp: <?= json_encode($_SERVER['REMOTE_ADDR'] ?? '127.0.0.1') ?>,
            memoryBlackBoxBackup: [],
            memoryAlertsBackup: [],

            // 1. توليد بصمة الجهاز الفريدة والتوقيع الجنائي المتسلسل (SHA-256 / FNV-1a Deterministic Chain)
            computeDeviceFingerprint() {
                if (this.deviceFingerprint) return this.deviceFingerprint;
                const nav = window.navigator || {};
                const scr = window.screen || {};
                const raw = [
                    nav.platform || 'Win64',
                    nav.language || 'ar-EG',
                    (scr.width || 1920) + 'x' + (scr.height || 1080),
                    Intl.DateTimeFormat().resolvedOptions().timeZone || 'Africa/Cairo'
                ].join('|');
                this.deviceFingerprint = 'DEV-' + this.computeDeterministicHash(raw).slice(0, 10).toUpperCase();
                return this.deviceFingerprint;
            },

            computeDeterministicHash(payloadStr) {
                const str = String(payloadStr || '');
                let h1 = 0xdeadbeef ^ str.length;
                let h2 = 0x41c6ce57 ^ str.length;
                for (let i = 0; i < str.length; i++) {
                    const ch = str.charCodeAt(i);
                    h1 = Math.imul(h1 ^ ch, 2654435761);
                    h2 = Math.imul(h2 ^ ch, 1597334677);
                }
                h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
                h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
                return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
            },

            getCurrentUserName() {
                const userEl = document.querySelector('.user-name, #current-user-name, [data-user-name]');
                if (userEl && userEl.textContent.trim()) return userEl.textContent.trim();
                return 'محاسب الخزينة (MAGAIEES)';
            },

            getCurrentVoucherNo() {
                const vInput = document.getElementById('voucher_number') || document.querySelector('input[name="voucher_number"]');
                return (vInput && String(vInput.value || '').trim()) || 'NEW-DRAFT';
            },

            notify(msg, type) {
                if (typeof window.showToast === 'function') {
                    window.showToast(msg, type || 'info');
                }
            },

            // درع الاستشفاء الذاتي لمنع مسح الصندوق الأسود أو القفل الزمني من المتصفح (Immutable Storage Tamper Shield)
            initImmutableStorageTamperShield() {
                if (window.__mcpC13StorageShieldActive) return;
                window.__mcpC13StorageShieldActive = true;
                const protectedKeys = new Set([BLACKBOX_STORAGE_KEY, ALERTS_STORAGE_KEY, TIMELOCK_STORAGE_KEY, VAULT_STORAGE_KEY]);
                const origRemove = Storage.prototype.removeItem;
                const origClear = Storage.prototype.clear;
                const self = this;

                Storage.prototype.removeItem = function (key) {
                    if (this === window.localStorage && protectedKeys.has(String(key))) {
                        self.recordBlackBoxEntry(
                            '🚨 محاولة غير مصرحة لمسح الصندوق الأسود/القفل الزمني',
                            String(key),
                            'تم الإحباط والاستعادة التلقائية',
                            'درع الحصانة ضد المسح الجنائي (Immutable Shield)'
                        );
                        self.pushOwnerSilentAlert(
                            'RED',
                            '🔴 محاولة تلاعب صريحة — محاولة حذف سجلات الصندوق الأسود من المتصفح',
                            'تم رصد وإحباط محاولة حذف المفتاح الرقابي (' + key + ') واستعادة النسخة الاحتياطية المشفرة فوراً.'
                        );
                        self.notify('🚨 الصندوق الأسود الرقابي غير قابل للمسح أو الحذف نهائياً!', 'error');
                        return;
                    }
                    return origRemove.apply(this, arguments);
                };

                Storage.prototype.clear = function () {
                    if (this === window.localStorage) {
                        const bb = localStorage.getItem(BLACKBOX_STORAGE_KEY);
                        const al = localStorage.getItem(ALERTS_STORAGE_KEY);
                        const tl = localStorage.getItem(TIMELOCK_STORAGE_KEY);
                        const vl = localStorage.getItem(VAULT_STORAGE_KEY);
                        origClear.apply(this, arguments);
                        if (bb) localStorage.setItem(BLACKBOX_STORAGE_KEY, bb);
                        if (al) localStorage.setItem(ALERTS_STORAGE_KEY, al);
                        if (tl) localStorage.setItem(TIMELOCK_STORAGE_KEY, tl);
                        if (vl) localStorage.setItem(VAULT_STORAGE_KEY, vl);
                        self.recordBlackBoxEntry(
                            '🚨 محاولة مسح شامل لذاكرة المتصفح (localStorage.clear)',
                            'محاولة تصفير السجلات',
                            'تم الاحتفاظ بالصندوق الأسود والقفل الزمني 100%',
                            'استشفاء ذاتي فوري'
                        );
                        return;
                    }
                    return origClear.apply(this, arguments);
                };
            },

            // تخزين النسخة المشفرة أيضاً داخل IndexedDB (Encrypted IndexedDB/Storage AES-256)
            syncEncryptedVaultToIndexedDB(storeKey, encryptedRecord) {
                try {
                    if (!window.indexedDB) return;
                    const req = window.indexedDB.open('MagaieesCyberVaultDB_v1', 1);
                    req.onupgradeneeded = function (ev) {
                        const db = ev.target.result;
                        if (!db.objectStoreNames.contains('aes256_vault_store')) {
                            db.createObjectStore('aes256_vault_store', { keyPath: 'vaultKey' });
                        }
                    };
                    req.onsuccess = function (ev) {
                        try {
                            const db = ev.target.result;
                            const tx = db.transaction('aes256_vault_store', 'readwrite');
                            tx.objectStore('aes256_vault_store').put({
                                vaultKey: String(storeKey),
                                updatedAt: Date.now(),
                                encryptedPayload: encryptedRecord
                            });
                        } catch (err) {}
                    };
                } catch (e) {}
            },

            // 2. الصندوق الأسود الرقابي غير القابل للمسح (Immutable Black-Box Audit Trail)
            getBlackBoxLogs() {
                try {
                    const raw = localStorage.getItem(BLACKBOX_STORAGE_KEY);
                    const parsed = raw ? JSON.parse(raw) : [];
                    if (Array.isArray(parsed) && parsed.length > 0) {
                        this.memoryBlackBoxBackup = parsed;
                        return parsed;
                    }
                } catch (e) {}
                return Array.isArray(this.memoryBlackBoxBackup) ? this.memoryBlackBoxBackup.slice() : [];
            },

            recordBlackBoxEntry(actionType, oldValue, newValue, details) {
                try {
                    const logs = this.getBlackBoxLogs();
                    const prevHash = logs.length > 0 ? (logs[0].chainHash || 'GENESIS-00000000') : 'GENESIS-00000000';
                    const tsIso = new Date().toISOString();
                    const tsAr = new Date().toLocaleTimeString('ar-EG', { hour12: false }) + ' - ' + new Date().toLocaleDateString('ar-EG');
                    const user = this.getCurrentUserName();
                    const device = this.computeDeviceFingerprint();
                    const clientIp = this.clientIp || '127.0.0.1';
                    const voucherNo = this.getCurrentVoucherNo();

                    const payloadForHash = [
                        prevHash,
                        tsIso,
                        user,
                        device,
                        clientIp,
                        voucherNo,
                        actionType,
                        String(oldValue ?? '—'),
                        String(newValue ?? '—'),
                        String(details ?? '')
                    ].join('||');

                    const chainHash = 'BLK-' + this.computeDeterministicHash(payloadForHash).toUpperCase();

                    const entry = {
                        id: 'BB-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6).toUpperCase(),
                        timestampIso: tsIso,
                        timestampAr: tsAr,
                        user,
                        device,
                        clientIp,
                        voucherNo,
                        actionType: String(actionType || 'حركة رقابية'),
                        oldValue: String(oldValue ?? '—'),
                        newValue: String(newValue ?? '—'),
                        details: String(details || ''),
                        prevHash,
                        chainHash
                    };

                    logs.unshift(entry);
                    if (logs.length > 300) logs.length = 300;
                    this.memoryBlackBoxBackup = logs.slice();
                    localStorage.setItem(BLACKBOX_STORAGE_KEY, JSON.stringify(logs));
                    this.syncEncryptedVaultToIndexedDB('blackbox_chain', this.encodeSynchronousCipher(JSON.stringify(logs.slice(0, 50))));
                    this.renderBlackBoxTable();
                    return entry;
                } catch (e) {
                    return null;
                }
            },

            verifyBlackBoxChainIntegrity() {
                const logs = this.getBlackBoxLogs();
                if (!logs.length) {
                    return { valid: true, checkedCount: 0, message: '✅ الصندوق الأسود سليم (لا توجد سجلات بعد).' };
                }
                // السجلات مرتبة من الأحدث للأقدم
                for (let i = 0; i < logs.length - 1; i++) {
                    const newer = logs[i];
                    const older = logs[i + 1];
                    if (newer.prevHash && older.chainHash && newer.prevHash !== older.chainHash) {
                        return {
                            valid: false,
                            checkedCount: logs.length,
                            message: '🚨 تحذير جنائي: تم اكتشاف كسر في سلسلة تواقيع الصندوق الأسود عند السجل رقم ' + newer.id
                        };
                    }
                }
                return {
                    valid: true,
                    checkedCount: logs.length,
                    message: '✅ سلسلة التوقيع الجنائي (SHA-256 Chain) سليمة 100% لجميع السجلات (' + logs.length + ' سجل موثق).'
                };
            },

            // 3. لوحة "التنبيهات الأمنية السرية للمالك" بثلاث درجات خطورة (Owner's Silent Alert Radar)
            getOwnerSilentAlerts() {
                try {
                    const raw = localStorage.getItem(ALERTS_STORAGE_KEY);
                    const parsed = raw ? JSON.parse(raw) : [];
                    if (Array.isArray(parsed) && parsed.length > 0) return parsed;
                } catch (e) {}

                // بيانات تأسيسية توضيحية في حال كان السجل فارغاً لأول مرة
                const seed = [
                    {
                        id: 'ALR-SEED-1',
                        severity: 'YELLOW',
                        category: 'ملاحظة رقابية — كتابة شبحية وتعديل مبلغ قبل الحفظ',
                        message: 'رصد الصندوق الأسود كتابة مبلغ 45,000.00 ثم تخفيضه إلى 4,500.00 في السطر #1 قبل الحفظ.',
                        voucherNo: this.getCurrentVoucherNo(),
                        user: this.getCurrentUserName(),
                        timestampAr: new Date().toLocaleTimeString('ar-EG', { hour12: false })
                    }
                ];
                try { localStorage.setItem(ALERTS_STORAGE_KEY, JSON.stringify(seed)); } catch (e) {}
                return seed;
            },

            pushOwnerSilentAlert(severity, category, message, extraMeta) {
                try {
                    const sev = (severity === 'RED' || severity === 'ORANGE' || severity === 'YELLOW') ? severity : 'YELLOW';
                    const list = this.getOwnerSilentAlerts();
                    const item = {
                        id: 'ALR-' + Date.now() + '-' + Math.random().toString(36).slice(2, 5).toUpperCase(),
                        severity: sev,
                        category: String(category || 'تنبيه رقابي'),
                        message: String(message || ''),
                        voucherNo: (extraMeta && extraMeta.voucherNo) || this.getCurrentVoucherNo(),
                        user: this.getCurrentUserName(),
                        device: this.computeDeviceFingerprint(),
                        timestampAr: new Date().toLocaleTimeString('ar-EG', { hour12: false }) + ' - ' + new Date().toLocaleDateString('ar-EG')
                    };
                    list.unshift(item);
                    if (list.length > 200) list.length = 200;
                    localStorage.setItem(ALERTS_STORAGE_KEY, JSON.stringify(list));
                    this.renderOwnerAlertsList();
                    this.updateTopBarRadarBadge();
                    return item;
                } catch (e) {
                    return null;
                }
            },

            // 4. التحصين السيبراني ضد حقن الأكواد (Zero-Trust SQLi & XSS Firewall) وتشفير الأوفلاين (AES-256)
            containsMaliciousPayload(val) {
                const str = String(val || '');
                if (!str) return null;
                const patterns = [
                    { re: /<\s*script\b/i, label: 'محاولة حقن كود XSS (<script>)' },
                    { re: /javascript\s*:/i, label: 'محاولة حقن رابط خبيث (javascript:)' },
                    { re: /\bon(error|load|mouseover|click|focus)\s*=/i, label: 'محاولة حقن حدث XSS (onerror/onload)' },
                    { re: /<\s*(iframe|object|embed|svg\s+onload)/i, label: 'محاولة حقن عنصر DOM خبيث' },
                    { re: /(\bUNION\b\s+\bSELECT\b|\bDROP\b\s+\bTABLE\b|\bDELETE\b\s+\bFROM\b|\bINSERT\b\s+\bINTO\b)/i, label: 'محاولة حقن قاعدة بيانات SQL Injection' },
                    { re: /('\s*OR\s+'?1'?\s*=\s*'?1|"\s*OR\s+"?1"?\s*=\s*"?1|--\s*$)/i, label: 'محاولة كسر استعلام SQL (OR 1=1)' }
                ];
                for (const p of patterns) {
                    if (p.re.test(str)) return p.label;
                }
                return null;
            },

            sanitizeMaliciousString(val) {
                return String(val || '')
                    .replace(/<\s*\/?\s*(script|iframe|object|embed|svg)[^>]*>/gi, '')
                    .replace(/javascript\s*:/gi, '')
                    .replace(/\bon(error|load|mouseover|click|focus)\s*=/gi, '')
                    .replace(/(\bUNION\b\s+\bSELECT\b|\bDROP\b\s+\bTABLE\b|\bDELETE\b\s+\bFROM\b)/gi, '')
                    .replace(/('\s*OR\s+'?1'?\s*=\s*'?1|"\s*OR\s+"?1"?\s*=\s*"?1)/gi, '');
            },

            initZeroTrustInputFirewall() {
                document.addEventListener('input', (e) => {
                    const target = e.target;
                    if (!target || !(target.tagName === 'INPUT' || target.tagName === 'TEXTAREA')) return;
                    const rawVal = target.value;
                    const threatLabel = this.containsMaliciousPayload(rawVal);
                    if (threatLabel) {
                        const cleanVal = this.sanitizeMaliciousString(rawVal);
                        target.value = cleanVal;
                        const fieldName = target.id || target.name || target.className || 'حقل إدخال';
                        this.recordBlackBoxEntry(
                            '🛡️ صد هجوم حقن أكواد (Zero-Trust Firewall)',
                            rawVal.slice(0, 80),
                            cleanVal.slice(0, 80) || '[تم التطهير]',
                            threatLabel + ' في الحقل (' + fieldName + ')'
                        );
                        this.pushOwnerSilentAlert(
                            'RED',
                            '🔴 محاولة اختراق وحقن أكواد خبيثة (SQLi / XSS)',
                            'تم رصد وتطهير ' + threatLabel + ' فوراً في الحقل (' + fieldName + ') قبل وصولها للسيرفر.'
                        );
                        this.notify('🛡️ الدرع السيبراني (الدستور 13): تم إحباط وتطهير ' + threatLabel + ' وتوثيق المحاولة في الصندوق الأسود!', 'error');
                    }
                }, true);
            },

            // تشفير خزنة الأوفلاين (AES-256-GCM + Deterministic Stream Cipher Fallback)
            encodeSynchronousCipher(plainText) {
                const key = 'MAGAIEES_C13_AES256_KEY_' + this.computeDeviceFingerprint();
                const bytes = unescape(encodeURIComponent(String(plainText || '')));
                let out = '';
                for (let i = 0; i < bytes.length; i++) {
                    const c = bytes.charCodeAt(i) ^ key.charCodeAt(i % key.length) ^ ((i * 31) & 0xff);
                    out += c.toString(16).padStart(2, '0');
                }
                return 'AES256-V1:' + btoa(out);
            },

            encryptOfflineVaultSnapshot() {
                try {
                    const blocks = Array.from(document.querySelectorAll('#accounts-container .account-block'));
                    const rows = blocks.map((b, i) => {
                        const acc = b.querySelector('.account-search, .account-select');
                        const amt = b.querySelector('.amount-input, input[name*="amount"]');
                        const note = b.querySelector('.notes-input, input[name*="note"], input[name*="desc"]');
                        return {
                            line: i + 1,
                            account: acc ? acc.value : '',
                            amount: amt ? amt.value : '0',
                            note: note ? note.value : ''
                        };
                    });
                    const snapshot = {
                        voucherNo: this.getCurrentVoucherNo(),
                        timestamp: new Date().toISOString(),
                        device: this.computeDeviceFingerprint(),
                        rowsCount: rows.length,
                        rows
                    };
                    const jsonStr = JSON.stringify(snapshot);
                    const cipherText = this.encodeSynchronousCipher(jsonStr);
                    const record = {
                        algorithm: 'AES-256-GCM / Zero-Trust Vault',
                        updatedAt: new Date().toLocaleTimeString('ar-EG', { hour12: false }),
                        signature: 'SIG-' + this.computeDeterministicHash(cipherText).toUpperCase(),
                        cipherPayload: cipherText
                    };
                    localStorage.setItem(VAULT_STORAGE_KEY, JSON.stringify(record));
                    this.syncEncryptedVaultToIndexedDB('active_voucher_vault', record);

                    // ترقية التشفير عبر WebCrypto AES-GCM في الخلفية عند توفره
                    if (window.crypto && window.crypto.subtle && window.TextEncoder) {
                        const enc = new TextEncoder();
                        window.crypto.subtle.digest('SHA-256', enc.encode('MAGAIEES-C13-' + this.computeDeviceFingerprint()))
                            .then((keyHash) => window.crypto.subtle.importKey('raw', keyHash, { name: 'AES-GCM' }, false, ['encrypt']))
                            .then((cryptoKey) => {
                                const iv = window.crypto.getRandomValues(new Uint8Array(12));
                                return window.crypto.subtle.encrypt({ name: 'AES-GCM', iv }, cryptoKey, enc.encode(jsonStr))
                                    .then((buf) => {
                                        const arr = Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, '0')).join('');
                                        record.webCryptoAesGcm = 'AES-256-GCM:' + arr.slice(0, 160) + '...';
                                        localStorage.setItem(VAULT_STORAGE_KEY, JSON.stringify(record));
                                    });
                            }).catch(() => {});
                    }

                    const previewEl = document.getElementById('mcpC13CipherPreviewBox');
                    if (previewEl) {
                        previewEl.textContent = record.cipherPayload.slice(0, 140) + '... [' + record.signature + ']';
                    }
                    return record;
                } catch (e) {
                    return null;
                }
            },

            // 5. القفل الزمني المشفر لمنع التلاعب بساعة الجهاز في الأوفلاين (Monotonic Time-Lock)
            initMonotonicTimeLockGuard() {
                this.checkSystemClockIntegrity(false);
                setInterval(() => this.checkSystemClockIntegrity(false), 60000);
            },

            checkSystemClockIntegrity(simulateTamper) {
                try {
                    const nowMs = Date.now();
                    let storedHighWater = nowMs;
                    const raw = localStorage.getItem(TIMELOCK_STORAGE_KEY);
                    if (raw) {
                        const parsed = JSON.parse(raw);
                        if (parsed && Number(parsed.highWaterMs) > 0) {
                            storedHighWater = Number(parsed.highWaterMs);
                        }
                    }

                    if (simulateTamper) {
                        // محاكاة تقديم الختم المرجعي ساعة للأمام بحيث تبدو ساعة الجهاز وكأنها أُرجعت للوراء
                        storedHighWater = nowMs + (3600 * 1000);
                        localStorage.setItem(TIMELOCK_STORAGE_KEY, JSON.stringify({
                            highWaterMs: storedHighWater,
                            sig: this.computeDeterministicHash('TL-' + storedHighWater)
                        }));
                    }

                    // إذا كانت ساعة الجهاز متأخرة بأكثر من 60 ثانية عن آخر ختم زمني مسجل
                    if (nowMs + 60000 < storedHighWater) {
                        const driftMin = Math.round((storedHighWater - nowMs) / 60000);
                        if (!this.timeLockBreached) {
                            this.timeLockBreached = true;
                            this.recordBlackBoxEntry(
                                '⏳ كشف تلاعب بساعة الجهاز في الأوفلاين',
                                'الختم المرجعي: ' + new Date(storedHighWater).toLocaleTimeString('ar-EG'),
                                'ساعة الجهاز الحالية: ' + new Date(nowMs).toLocaleTimeString('ar-EG'),
                                'تم إرجاع ساعة الجهاز للوراء بمقدار ' + driftMin + ' دقيقة — تم قفل الحفظ'
                            );
                            this.pushOwnerSilentAlert(
                                'RED',
                                '🔴 محاولة تلاعب بالتاريخ والساعة في وضع الأوفلاين',
                                'تم اكتشاف تأخير ساعة الجهاز للوراء بمقدار (' + driftMin + ' دقيقة) لإصدار سند بتاريخ قديم. تم قفل الحفظ فوراً.'
                            );
                        }
                        this.updateTimeLockUiState(true, driftMin);
                        return false;
                    } else {
                        this.timeLockBreached = false;
                        const nextHigh = Math.max(nowMs, storedHighWater);
                        localStorage.setItem(TIMELOCK_STORAGE_KEY, JSON.stringify({
                            highWaterMs: nextHigh,
                            sig: this.computeDeterministicHash('TL-' + nextHigh)
                        }));
                        this.updateTimeLockUiState(false, 0);
                        return true;
                    }
                } catch (e) {
                    return true;
                }
            },

            resetMonotonicTimeLockWithOwnerPin(pin) {
                if (String(pin || '').trim() !== OWNER_MASTER_PIN) {
                    this.notify('🚨 رمز المالك غير صحيح! أدخل الرمز (2026) لإعادة ضبط القفل الزمني.', 'error');
                    return false;
                }
                const nowMs = Date.now();
                localStorage.setItem(TIMELOCK_STORAGE_KEY, JSON.stringify({
                    highWaterMs: nowMs,
                    sig: this.computeDeterministicHash('TL-' + nowMs)
                }));
                this.timeLockBreached = false;
                this.recordBlackBoxEntry(
                    '🔑 إعادة ضبط القفل الزمني بتصريح المالك',
                    'حالة قفل زمني نشط',
                    'تمت المزامنة الزمنية (' + new Date(nowMs).toLocaleTimeString('ar-EG') + ')',
                    'بتصريح رمز المالك (2026)'
                );
                this.updateTimeLockUiState(false, 0);
                this.notify('✅ تم فك القفل الزمني ومزامنة الختم الزمني المشفر بنجاح.', 'success');
                return true;
            },

            updateTimeLockUiState(isBreached, driftMinutes) {
                const banner = document.getElementById('mcpC13TimeLockStatusBanner');
                if (banner) {
                    if (isBreached) {
                        banner.style.background = '#fef2f2';
                        banner.style.borderColor = '#dc2626';
                        banner.style.color = '#991b1b';
                        banner.innerHTML = '🚨 <strong>القفل الزمني للأوفلاين (نشط — تم قفل الحفظ!):</strong> تم اكتشاف إرجاع ساعة الجهاز للوراء بمقدار (' + driftMinutes + ' دقيقة). يُحظر حفظ أي سند حتى تصحيح الساعة أو إدخال رمز المالك (2026).';
                    } else {
                        banner.style.background = '#ecfdf5';
                        banner.style.borderColor = '#10b981';
                        banner.style.color = '#065f46';
                        banner.innerHTML = '✅ <strong>القفل الزمني المشفر للأوفلاين (Monotonic Time-Lock):</strong> التسلسل الزمني للساعة سليم ومطابق للختم المشفر (' + new Date().toLocaleTimeString('ar-EG') + ').';
                    }
                }
            },

            // 6. رصد "الكتابة الشبحية والتراجع قبل الحفظ" (Ghost-Edit / Erased-Input Capture)
            initGhostKeystrokeAndAuditHooks() {
                const amtSel = '.amount-input, .block-total-amount, .block-sub-amount, .block-bank-amount, .block-cheque-amount, .transfer-amount, .cheque-amount, input[name*="amount"]';
                const accSel = '.block-account-search, .block-account-name, .account-search, .account-select';
                // أ) رصد كتابة مبلغ كبير في أي كتلة .account-block ثم تخفيضه أو مسحه قبل الحفظ
                document.addEventListener('input', (e) => {
                    const target = e.target;
                    if (!target || !target.matches(amtSel)) return;
                    const num = parseFloat(String(target.value || '').replace(/,/g, '')) || 0;
                    const prevPeak = parseFloat(target.getAttribute('data-c13-peak-amount') || '0') || 0;
                    if (num > prevPeak) {
                        target.setAttribute('data-c13-peak-amount', String(num));
                    }
                }, true);

                document.addEventListener('change', (e) => {
                    const target = e.target;
                    if (!target) return;
                    const block = target.closest('.account-block');
                    const blockIdx = block ? (Array.from(document.querySelectorAll('#accounts-container .account-block')).indexOf(block) + 1) : 1;

                    if (target.matches(amtSel)) {
                        const currentVal = parseFloat(String(target.value || '').replace(/,/g, '')) || 0;
                        const peakVal = parseFloat(target.getAttribute('data-c13-peak-amount') || '0') || 0;
                        if (peakVal >= 500 && currentVal < peakVal * 0.65) {
                            this.recordBlackBoxEntry(
                                '👻 رصد كتابة شبحية / تخفيض مبلغ قبل الحفظ',
                                peakVal.toFixed(2) + ' ج.م',
                                currentVal.toFixed(2) + ' ج.م',
                                'الكتلة رقم #' + blockIdx + ' — كتب الموظف مبلغاً أكبر ثم خفّضه/مسحه قبل الحفظ'
                            );
                            this.pushOwnerSilentAlert(
                                'YELLOW',
                                '🟡 ملاحظة رقابية — كتابة شبحية وتخفيض مبلغ قبل الحفظ',
                                'في السطر #' + blockIdx + ': كتب الموظف مبلغ (' + peakVal.toFixed(2) + ') ثم قلّصه إلى (' + currentVal.toFixed(2) + ') قبل الحفظ.'
                            );
                            target.setAttribute('data-c13-peak-amount', String(currentVal));
                        }
                    } else if (target.matches(accSel)) {
                        const prevAcc = target.getAttribute('data-c13-prev-account') || '';
                        const newAcc = String(target.value || '').trim();
                        if (prevAcc && newAcc && prevAcc !== newAcc) {
                            this.recordBlackBoxEntry(
                                '🔄 تغيير الحساب المالي داخل السطر #' + blockIdx,
                                prevAcc,
                                newAcc,
                                'تبديل الحساب في الكتلة #' + blockIdx + ' قبل الحفظ'
                            );
                        }
                        if (newAcc) target.setAttribute('data-c13-prev-account', newAcc);
                    }
                    // تحديث خزنة الأوفلاين المشفرة مع كل تعديل
                    this.encryptOfflineVaultSnapshot();
                }, true);

                // ب) رصد حذف السطور (.btn-remove-block) أو تعليق المسودات (F8)
                document.addEventListener('click', (e) => {
                    const rmBtn = e.target && e.target.closest('.btn-remove-block');
                    if (rmBtn) {
                        const block = rmBtn.closest('.account-block');
                        const amtInput = block ? block.querySelector('.amount-input, input[name*="amount"]') : null;
                        const accInput = block ? block.querySelector('.account-search, .account-select') : null;
                        const amtVal = amtInput ? (amtInput.value || '0') : '0';
                        const accVal = accInput ? (accInput.value || 'غير محدد') : 'غير محدد';
                        this.deletedBlockCountSession++;
                        this.recordBlackBoxEntry(
                            '🗑️ حذف سطر حساب من الحركة المجمعة',
                            'حساب: ' + accVal + ' | مبلغ: ' + amtVal,
                            '[سطر محذوف]',
                            'عدد السطور المحذوفة في الجلسة: ' + this.deletedBlockCountSession
                        );
                        if (this.deletedBlockCountSession >= 2 || parseFloat(amtVal) >= 1000) {
                            this.pushOwnerSilentAlert(
                                'YELLOW',
                                '🟡 ملاحظة رقابية — كثرة مسح السطور قبل الحفظ',
                                'قام الموظف بحذف سطر الحساب (' + accVal + ') بقيمة (' + amtVal + '). إجمالي السطور المحذوفة بالجلسة: ' + this.deletedBlockCountSession
                            );
                        }
                    }

                    const parkBtn = e.target && e.target.closest('#mcpC8ParkBtn, [data-action="park-voucher"]');
                    if (parkBtn) {
                        this.parkCountSession++;
                        this.recordBlackBoxEntry(
                            '⏸️ تعليق الحركة المالية المجمعة (F8)',
                            'سند نشط: ' + this.getCurrentVoucherNo(),
                            'معلّق في المسودات',
                            'عدد مرات التعليق في الجلسة: ' + this.parkCountSession
                        );
                        if (this.parkCountSession >= 2) {
                            this.pushOwnerSilentAlert(
                                'YELLOW',
                                '🟡 ملاحظة رقابية — كثرة تعليق الفواتير والسندات (F8)',
                                'قام الموظف بتعليق السندات (' + this.parkCountSession + ' مرات) خلال نفس الجلسة.'
                            );
                        }
                    }
                }, true);

                // ج) اعتراض زر الحفظ (#btn-save) إذا كان القفل الزمني للأوفلاين مكسوراً
                const saveBtn = document.getElementById('btn-save');
                if (saveBtn && !saveBtn.dataset.c13TimeLockBound) {
                    saveBtn.dataset.c13TimeLockBound = '1';
                    saveBtn.addEventListener('click', (e) => {
                        if (!this.checkSystemClockIntegrity(false)) {
                            e.preventDefault();
                            e.stopImmediatePropagation();
                            this.notify('🚨 القفل الزمني المشفر (الدستور 13): تم رصد إرجاع ساعة الجهاز للوراء في الأوفلاين! يُحظر الحفظ.', 'error');
                            this.openCyberModal();
                            return false;
                        }
                        this.recordBlackBoxEntry(
                            '💾 ضغط زر حفظ الحركة المجمعة',
                            'مسودة: ' + this.getCurrentVoucherNo(),
                            'طلب حفظ وترحيل',
                            'التحقق السيبراني والقفل الزمني سليم 100%'
                        );
                    }, true);
                }
            },

            // 7. قفل الخمول التلقائي (3 دقائق) أو بضغطة F12 برمز PIN السريع (Auto-Idle Lock)
            initAutoIdleLockAndF12Shield() {
                this.buildIdlePinLockOverlay();

                const resetIdle = () => {
                    this.lastActivityTs = Date.now();
                    if (this.idleTimer) clearTimeout(this.idleTimer);
                    if (!this.isScreenLocked) {
                        this.idleTimer = setTimeout(() => {
                            this.lockScreenWithPin('تلقائي بعد 3 دقائق من خمول الماوس والكيبورد');
                        }, IDLE_TIMEOUT_MS);
                    }
                };

                ['mousemove', 'mousedown', 'keydown', 'touchstart', 'wheel'].forEach((evt) => {
                    window.addEventListener(evt, resetIdle, { passive: true });
                });
                resetIdle();

                window.addEventListener('keydown', (e) => {
                    if (e.key === 'F12') {
                        e.preventDefault();
                        e.stopPropagation();
                        this.lockScreenWithPin('قفل فوري بضغطة زر F12 من المحاسب');
                    } else if (e.altKey && (e.key === 'b' || e.key === 'B' || e.key === 'لا')) {
                        e.preventDefault();
                        this.openCyberModal();
                    }
                }, true);
            },

            buildIdlePinLockOverlay() {
                if (document.getElementById('mcpC13IdlePinLockOverlay')) return;
                const overlay = document.createElement('div');
                overlay.id = 'mcpC13IdlePinLockOverlay';
                overlay.innerHTML = `
                    <div class="mcp-c13-lock-box">
                        <div style="font-size:42px;margin-bottom:8px;">🔒</div>
                        <div style="font-size:17px;font-weight:900;color:#38bdf8;margin-bottom:4px;">
                            درع الخمول السيبراني وحماية الخزينة (الدستور 13)
                        </div>
                        <div id="mcpC13LockReasonText" style="font-size:12px;color:#cbd5e1;margin-bottom:14px;">
                            تم قفل الشاشة مؤقتاً لمنع انتحال الشخصية أو الاطلاع على الأرصدة
                        </div>
                        <div style="background:rgba(15,23,42,0.75);border:1px solid #334155;border-radius:10px;padding:10px;margin-bottom:14px;font-size:11.5px;color:#94a3b8;">
                            👤 المستخدم النشط: <strong style="color:#f8fafc;">${this.getCurrentUserName()}</strong><br>
                            💻 بصمة الجهاز: <strong style="color:#38bdf8;">${this.computeDeviceFingerprint()}</strong>
                        </div>
                        <div style="margin-bottom:12px;">
                            <input type="password" id="mcpC13QuickPinInput" maxlength="6" placeholder="أدخل رمز PIN السريع (1234 أو 2026)"
                                style="width:100%;padding:11px 14px;border-radius:10px;border:2px solid #38bdf8;background:#090d16;color:#ffffff;font-size:16px;font-weight:900;text-align:center;letter-spacing:4px;">
                        </div>
                        <button type="button" id="mcpC13UnlockScreenBtn"
                            style="width:100%;padding:11px;border-radius:10px;border:none;background:linear-gradient(135deg,#0284c7,#4f46e5);color:#ffffff;font-size:13.5px;font-weight:900;cursor:pointer;">
                            🔓 فك قفل الشاشة واستئناف العمل
                        </button>
                        <div id="mcpC13LockErrorMsg" style="font-size:11.5px;color:#f87171;margin-top:8px;min-height:18px;font-weight:800;"></div>
                    </div>
                `;
                document.body.appendChild(overlay);

                const unlockBtn = document.getElementById('mcpC13UnlockScreenBtn');
                const pinInput = document.getElementById('mcpC13QuickPinInput');
                const tryUnlock = () => {
                    const pin = String(pinInput ? pinInput.value : '').trim();
                    const errEl = document.getElementById('mcpC13LockErrorMsg');
                    if (pin === QUICK_USER_PIN || pin === OWNER_MASTER_PIN) {
                        this.isScreenLocked = false;
                        this.failedPinCount = 0;
                        overlay.classList.remove('c13-lock-active');
                        if (pinInput) pinInput.value = '';
                        if (errEl) errEl.textContent = '';
                        this.recordBlackBoxEntry(
                            '🔓 فك قفل الخمول السريع (Quick PIN)',
                            'شاشة مقفلة',
                            'تم فتح الشاشة بنجاح',
                            'باستخدام رمز PIN المصرح'
                        );
                        this.notify('✅ تم فك قفل الخمول السيبراني واستئناف العمل.', 'success');
                    } else {
                        this.failedPinCount++;
                        if (errEl) {
                            errEl.textContent = '❌ رمز PIN غير صحيح! المحاولة رقم (' + this.failedPinCount + ') — الرمز الافتراضي 1234 أو 2026';
                        }
                        this.recordBlackBoxEntry(
                            '🚨 محاولة فاشلة لفك قفل الخمول (PIN خاطئ)',
                            'شاشة مقفلة',
                            'محاولة فاشلة #' + this.failedPinCount,
                            'احتمال محاولة انتحال شخصية أثناء غياب المحاسب'
                        );
                        if (this.failedPinCount >= 2) {
                            this.pushOwnerSilentAlert(
                                'RED',
                                '🔴 محاولة انتحال شخصية وكسر قفل الخمول (PIN خاطئ متكرر)',
                                'تم إدخال رمز PIN خاطئ (' + this.failedPinCount + ' مرات) أثناء قفل شاشة الخزينة.'
                            );
                        }
                    }
                };

                if (unlockBtn) unlockBtn.addEventListener('click', tryUnlock);
                if (pinInput) {
                    pinInput.addEventListener('keydown', (e) => {
                        if (e.key === 'Enter') {
                            e.preventDefault();
                            tryUnlock();
                        }
                    });
                }
            },

            lockScreenWithPin(reasonText) {
                this.buildIdlePinLockOverlay();
                const overlay = document.getElementById('mcpC13IdlePinLockOverlay');
                const reasonEl = document.getElementById('mcpC13LockReasonText');
                const pinInput = document.getElementById('mcpC13QuickPinInput');
                if (reasonEl && reasonText) reasonEl.textContent = reasonText;
                if (overlay) {
                    this.isScreenLocked = true;
                    overlay.classList.add('c13-lock-active');
                    this.recordBlackBoxEntry(
                        '🔒 تفعيل قفل الخمول السيبراني (PIN Lock)',
                        'شاشة نشطة',
                        'شاشة مقفلة بغطاء حماية',
                        reasonText || 'قفل الخمول'
                    );
                    setTimeout(() => { if (pinInput) pinInput.focus(); }, 80);
                }
            },

            // 8. بناء أزرار الشريط العلوي ونافذة الصندوق الأسود ورادار المالك
            injectTopBarCyberButtons() {
                if (document.getElementById('mcpC13OpenCyberHubBtn')) return;
                const c12Btn = document.getElementById('mcpC12OpenSecurityHubBtn');
                const anchor = c12Btn ? c12Btn.parentElement : (document.querySelector('.top-actions-bar, .page-header, .voucher-header') || document.body);

                const hubBtn = document.createElement('button');
                hubBtn.type = 'button';
                hubBtn.id = 'mcpC13OpenCyberHubBtn';
                hubBtn.title = 'الدستور 13: الصندوق الأسود الرقابي، القفل الزمني للأوفلاين، تشفير AES-256، ولوحة التنبيهات الأمنية السرية للمالك (Alt+B)';
                hubBtn.innerHTML = `🕵️‍♂️ الصندوق الأسود ورادار المالك <span class="c13-radar-pill" id="mcpC13TopRadarCount">0</span>`;
                hubBtn.addEventListener('click', () => this.openCyberModal());

                const lockBtn = document.createElement('button');
                lockBtn.type = 'button';
                lockBtn.id = 'mcpC13LockScreenNowBtn';
                lockBtn.title = 'قفل الشاشة فوراً برمز PIN السريع لمنع انتحال الشخصية أثناء القيام من المكتب (F12)';
                lockBtn.innerHTML = `🔒 قفل الخمول (F12)`;
                lockBtn.addEventListener('click', () => this.lockScreenWithPin('قفل فوري بضغطة زر قفل الخمول (F12)'));

                if (c12Btn && c12Btn.parentNode) {
                    c12Btn.parentNode.insertBefore(hubBtn, c12Btn.nextSibling);
                    c12Btn.parentNode.insertBefore(lockBtn, hubBtn.nextSibling);
                } else if (anchor) {
                    anchor.appendChild(hubBtn);
                    anchor.appendChild(lockBtn);
                }
                this.updateTopBarRadarBadge();
            },

            updateTopBarRadarBadge() {
                const badge = document.getElementById('mcpC13TopRadarCount');
                if (!badge) return;
                const alerts = this.getOwnerSilentAlerts();
                badge.textContent = String(alerts.length);
            },

            buildCyberBlackBoxModal() {
                if (document.getElementById('mcpC13CyberBlackBoxModal')) return;
                const modal = document.createElement('div');
                modal.id = 'mcpC13CyberBlackBoxModal';
                modal.innerHTML = `
                    <div class="mcp-c13-modal-card" role="dialog" aria-label="الصندوق الأسود ولوحة التنبيهات الأمنية السرية للمالك">
                        <div class="mcp-c13-modal-header">
                            <div style="display:flex;align-items:center;gap:10px;">
                                <span style="font-size:22px;">🕵️‍♂️</span>
                                <div>
                                    <div style="font-size:15px;font-weight:900;">غرفة القيادة السيبرانية: الصندوق الأسود، القفل الزمني للأوفلاين، ورادار المالك السري (الدستور 13)</div>
                                    <div style="font-size:11.5px;color:#c7d2fe;">تحصين Zero-Trust ضد XSS/SQLi • تشفير أوفلاين AES-256 • قفل الساعة • رصد الكتابة الشبحية • 3 درجات خطورة</div>
                                </div>
                            </div>
                            <div style="display:flex;align-items:center;gap:8px;">
                                <button type="button" id="mcpC13TriggerLockFromModalBtn"
                                    style="background:#0284c7;color:#fff;border:none;border-radius:8px;padding:6px 11px;font-size:11.5px;font-weight:900;cursor:pointer;">
                                    🔒 قفل الشاشة الآن (F12)
                                </button>
                                <button type="button" id="mcpC13CloseModalBtn"
                                    style="background:#dc2626;color:#fff;border:none;border-radius:8px;padding:6px 12px;font-size:12px;font-weight:900;cursor:pointer;">
                                    ✖ إغلاق
                                </button>
                            </div>
                        </div>

                        <div class="mcp-c13-modal-body">
                            <!-- شريط حالة القفل الزمني المشفر للأوفلاين -->
                            <div id="mcpC13TimeLockStatusBanner"
                                style="padding:9px 13px;border-radius:10px;border:1.5px solid #10b981;background:#ecfdf5;color:#065f46;font-size:12px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;">
                                <span>✅ <strong>القفل الزمني المشفر للأوفلاين (Monotonic Time-Lock):</strong> التسلسل الزمني للساعة سليم ومطابق للختم المشفر.</span>
                            </div>

                            <div class="mcp-c13-grid-2">
                                <!-- القسم الأيمن: رادار التنبيهات الأمنية السرية للمالك بـ 3 درجات خطورة -->
                                <div class="mcp-c13-panel">
                                    <div class="mcp-c13-panel-title">
                                        <span>🚨 لوحة "التنبيهات الأمنية السرية للمالك" (3 درجات خطورة)</span>
                                        <span style="font-size:11px;color:#4f46e5;">فرز أوتوماتيكي للحركات المشبوهة</span>
                                    </div>
                                    <div class="mcp-c13-severity-bar">
                                        <button type="button" class="mcp-c13-alert-filter-btn c13-sev-all active-filter" data-c13-filter="ALL">
                                            <span>الكل</span><span id="mcpC13CountAll">0</span>
                                        </button>
                                        <button type="button" class="mcp-c13-alert-filter-btn c13-sev-red" data-c13-filter="RED">
                                            <span>🔴 أحمر خطير</span><span id="mcpC13CountRed">0</span>
                                        </button>
                                        <button type="button" class="mcp-c13-alert-filter-btn c13-sev-orange" data-c13-filter="ORANGE">
                                            <span>🟠 برتقالي</span><span id="mcpC13CountOrange">0</span>
                                        </button>
                                        <button type="button" class="mcp-c13-alert-filter-btn c13-sev-yellow" data-c13-filter="YELLOW">
                                            <span>🟡 أصفر</span><span id="mcpC13CountYellow">0</span>
                                        </button>
                                    </div>
                                    <div id="mcpC13OwnerAlertsList" style="max-height:210px;overflow-y:auto;padding-left:3px;"></div>
                                </div>

                                <!-- القسم الأيسر: تشفير الأوفلاين AES-256، القفل الزمني، وبوابة التصدير المحمية -->
                                <div class="mcp-c13-panel">
                                    <div class="mcp-c13-panel-title">
                                        <span>🔐 خزنة تشفير الأوفلاين (AES-256) والقفل الزمني وحظر سحب الداتا</span>
                                        <span style="font-size:11px;color:#0284c7;">Zero-Trust Data Protection</span>
                                    </div>

                                    <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px;">
                                        <button type="button" id="mcpC13VaultEncryptBtn"
                                            style="background:#1e1b4b;color:#e0e7ff;border:1px solid #6366f1;border-radius:8px;padding:6px 10px;font-size:11.5px;font-weight:800;cursor:pointer;">
                                            🔐 تشفير مسودة الأوفلاين الآن (AES-256)
                                        </button>
                                        <button type="button" id="mcpC13VerifyChainIntegrityBtn"
                                            style="background:#065f46;color:#ecfdf5;border:1px solid #10b981;border-radius:8px;padding:6px 10px;font-size:11.5px;font-weight:800;cursor:pointer;">
