                            </div>
                        </div>
                    </div>
                `;
                document.body.appendChild(modal);

                // ربط أحداث النافذة
                const closeBtn = document.getElementById('mcpC13CloseModalBtn');
                if (closeBtn) closeBtn.addEventListener('click', () => this.closeCyberModal());

                const lockNowBtn = document.getElementById('mcpC13TriggerLockFromModalBtn');
                if (lockNowBtn) {
                    lockNowBtn.addEventListener('click', () => {
                        this.closeCyberModal();
                        this.lockScreenWithPin('قفل مباشر من غرفة القيادة السيبرانية');
                    });
                }

                modal.addEventListener('click', (e) => {
                    if (e.target === modal) this.closeCyberModal();
                });

                // أزرار فلترة درجات الخطورة الثلاث
                modal.querySelectorAll('.mcp-c13-alert-filter-btn').forEach((btn) => {
                    btn.addEventListener('click', () => {
                        modal.querySelectorAll('.mcp-c13-alert-filter-btn').forEach((b) => b.classList.remove('active-filter'));
                        btn.classList.add('active-filter');
                        this.currentAlertFilter = btn.getAttribute('data-c13-filter') || 'ALL';
                        this.renderOwnerAlertsList();
                    });
                });

                const encBtn = document.getElementById('mcpC13VaultEncryptBtn');
                if (encBtn) {
                    encBtn.addEventListener('click', () => {
                        const rec = this.encryptOfflineVaultSnapshot();
                        this.recordBlackBoxEntry(
                            '🔐 تشفير فوري لخزنة الأوفلاين (AES-256)',
                            'بيانات مسودة الحركة',
                            rec ? rec.signature : 'AES-256',
                            'تشفير أرصدة الخزائن والسطور في المتصفح'
                        );
                        this.notify('🔐 تم تشفير بيانات الأوفلاين بتشفير AES-256 بنجاح.', 'success');
                    });
                }

                const verifyBtn = document.getElementById('mcpC13VerifyChainIntegrityBtn');
                if (verifyBtn) {
                    verifyBtn.addEventListener('click', () => {
                        const res = this.verifyBlackBoxChainIntegrity();
                        const msgEl = document.getElementById('mcpC13IntegrityStatusMsg');
                        if (msgEl) {
                            msgEl.style.color = res.valid ? '#047857' : '#dc2626';
                            msgEl.textContent = res.message;
                        }
                        this.notify(res.message, res.valid ? 'success' : 'error');
                    });
                }

                const simTamperBtn = document.getElementById('mcpC13SimulateClockTamperBtn');
                if (simTamperBtn) {
                    simTamperBtn.addEventListener('click', () => {
                        this.checkSystemClockIntegrity(true);
                        this.notify('⏳ تم تفعيل محاكاة كشف تأخير ساعة الجهاز في الأوفلاين وقفل الحفظ وإرسال إنذار أحمر للمالك!', 'warning');
                    });
                }

                const resetTlBtn = document.getElementById('mcpC13ResetTimeLockBtn');
                if (resetTlBtn) {
                    resetTlBtn.addEventListener('click', () => {
                        const pinInput = document.getElementById('mcpC13ExportAuthPinInput');
                        const pin = (pinInput && pinInput.value.trim()) || OWNER_MASTER_PIN;
                        this.resetMonotonicTimeLockWithOwnerPin(pin);
                    });
                }

                const exportBtn = document.getElementById('mcpC13AuthorizedExportBtn');
                if (exportBtn) {
                    exportBtn.addEventListener('click', () => {
                        const pinInput = document.getElementById('mcpC13ExportAuthPinInput');
                        const pin = String(pinInput ? pinInput.value : '').trim();
                        if (pin !== OWNER_MASTER_PIN) {
                            this.recordBlackBoxEntry(
                                '🚫 محاولة سحب/تصدير داتا مرفوضة بدون رمز المالك',
                                'طلب تصدير الصندوق الأسود',
                                'مرفوض (رمز خاطئ)',
                                'حماية منع تسريب بيانات العملاء والخزائن'
                            );
                            this.pushOwnerSilentAlert(
                                'RED',
                                '🔴 محاولة غير مصرح بها لسحب وتصدير الداتا',
                                'حاول مستخدم تصدير سجلات الصندوق الأسود بدون رمز المالك السري (2026).'
                            );
                            this.notify('🚨 يُحظر تصدير أو سحب أي داتا إلا بعد إدخال رمز المالك السري (2026)!', 'error');
                            return;
                        }
                        this.recordBlackBoxEntry(
                            '📥 تصدير رسمي للصندوق الأسود بتصريح المالك',
                            'سجلات الصندوق الأسود',
                            'تصدير مشفر مصرح (2026)',
                            'تم التحقق من رمز المالك'
                        );
                        const msgEl = document.getElementById('mcpC13IntegrityStatusMsg');
                        if (msgEl) {
                            msgEl.style.color = '#047857';
                            msgEl.textContent = '✅ تم التصريح بتصدير نسخة مشفرة من الصندوق الأسود (' + this.getBlackBoxLogs().length + ' سجل جنائي).';
                        }
                        this.notify('✅ تم التصريح بتصدير تقرير الصندوق الأسود المشفر بنجاح.', 'success');
                    });
                }
            },

            renderOwnerAlertsList() {
                const container = document.getElementById('mcpC13OwnerAlertsList');
                if (!container) return;
                const all = this.getOwnerSilentAlerts();
                const redCount = all.filter((a) => a.severity === 'RED').length;
                const orangeCount = all.filter((a) => a.severity === 'ORANGE').length;
                const yellowCount = all.filter((a) => a.severity === 'YELLOW').length;

                const setTxt = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = String(val); };
                setTxt('mcpC13CountAll', all.length);
                setTxt('mcpC13CountRed', redCount);
                setTxt('mcpC13CountOrange', orangeCount);
                setTxt('mcpC13CountYellow', yellowCount);

                const filtered = this.currentAlertFilter === 'ALL'
                    ? all
                    : all.filter((a) => a.severity === this.currentAlertFilter);

                if (!filtered.length) {
                    container.innerHTML = `<div style="padding:16px;text-align:center;color:#64748b;font-size:12px;font-weight:800;">لا توجد تنبيهات ضمن هذا التصنيف حالياً.</div>`;
                    return;
                }

                container.innerHTML = filtered.slice(0, 40).map((item) => {
                    const badge = item.severity === 'RED'
                        ? '🔴 تنبيه أحمر خطير (محاولة تلاعب صريحة)'
                        : (item.severity === 'ORANGE' ? '🟠 تنبيه برتقالي (شبهة احتيال)' : '🟡 تنبيه أصفر (ملاحظة رقابية)');
                    return `
                        <div class="mcp-c13-alert-item sev-${item.severity}">
                            <div style="display:flex;align-items:center;justify-content:space-between;font-weight:900;">
                                <span>${badge} — ${item.category}</span>
                                <span style="font-size:10.5px;opacity:0.85;">${item.timestampAr || ''}</span>
                            </div>
                            <div style="font-weight:700;">${item.message}</div>
                            <div style="font-size:10.5px;opacity:0.85;">السند: ${item.voucherNo || '—'} | المستخدم: ${item.user || '—'}</div>
                        </div>
                    `;
                }).join('');
            },

            renderBlackBoxTable() {
                const tbody = document.getElementById('mcpC13BlackBoxTableBody');
                if (!tbody) return;
                const logs = this.getBlackBoxLogs();
                if (!logs.length) {
                    tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;padding:14px;color:#94a3b8;">لا توجد سجلات بعد في الصندوق الأسود.</td></tr>`;
                    return;
                }
                tbody.innerHTML = logs.slice(0, 60).map((row) => `
                    <tr>
                        <td style="white-space:nowrap;color:#38bdf8;font-weight:800;">${row.timestampAr || ''}</td>
                        <td><strong>${row.user || ''}</strong><br><span style="font-size:10px;color:#94a3b8;">${row.device || ''} | IP: ${row.clientIp || this.clientIp || '127.0.0.1'}</span></td>
                        <td style="font-weight:800;color:#fcd34d;">${row.voucherNo || '—'}</td>
                        <td style="font-weight:800;color:#f8fafc;">${row.actionType || ''}</td>
                        <td style="color:#fca5a5;">${row.oldValue || '—'}</td>
                        <td style="color:#86efac;">${row.newValue || '—'}</td>
                        <td>
                            <div>${row.details || ''}</div>
                            <div style="font-family:monospace;font-size:9.5px;color:#64748b;">${row.chainHash || ''} ← ${row.prevHash ? row.prevHash.slice(0, 12) : ''}</div>
                        </td>
                    </tr>
                `).join('');
            },

            // حقن زر "🕵️‍♂️ سجل السطر" داخل كل كتلة .account-block لفتح الصندوق الأسود ورادار الكتابة الشبحية للسطر
            injectPerBlockBlackBoxButtons() {
                const decorateBlocks = () => {
                    const blocks = document.querySelectorAll('#accounts-container .account-block');
                    blocks.forEach((block, idx) => {
                        if (block.querySelector('.btn-block-c13-audit')) return;
                        const header = block.querySelector('.block-header, .account-block-header') || block.firstElementChild;
                        if (!header) return;
                        const btn = document.createElement('button');
                        btn.type = 'button';
                        btn.className = 'btn-block-c13-audit';
                        btn.title = 'فحص السجل الجنائي والصندوق الأسود والكتابة الشبحية لهذا السطر (الدستور 13)';
                        btn.style.cssText = 'background:#1e1b4b;color:#e0e7ff;border:1px solid #818cf8;border-radius:6px;padding:2px 7px;font-size:10.5px;font-weight:900;cursor:pointer;margin-right:4px;display:inline-flex;align-items:center;gap:3px;';
                        btn.innerHTML = '🕵️‍♂️ سجل السطر';
                        btn.addEventListener('click', (ev) => {
                            ev.preventDefault();
                            ev.stopPropagation();
                            this.openCyberModal();
                        });
                        const c11Btn = header.querySelector('.btn-block-c11-cheque');
                        if (c11Btn && c11Btn.parentNode) {
                            c11Btn.parentNode.insertBefore(btn, c11Btn.nextSibling);
                        } else {
                            header.appendChild(btn);
                        }
                    });
                };
                decorateBlocks();
                const container = document.getElementById('accounts-container');
                if (container && window.MutationObserver && !container.dataset.c13ObserverBound) {
                    container.dataset.c13ObserverBound = '1';
                    const obs = new MutationObserver(() => decorateBlocks());
                    obs.observe(container, { childList: true });
                }
            },

            openCyberModal() {
                this.buildCyberBlackBoxModal();
                this.encryptOfflineVaultSnapshot();
                this.renderOwnerAlertsList();
                this.renderBlackBoxTable();
                const modal = document.getElementById('mcpC13CyberBlackBoxModal');
                if (modal) modal.classList.add('c13-modal-open');
            },

            closeCyberModal() {
                const modal = document.getElementById('mcpC13CyberBlackBoxModal');
                if (modal) modal.classList.remove('c13-modal-open');
            },

            // 9. الربط التكاملي مع الدساتير السابقة (10 و11 و12) لصب أي مخالفة في الصندوق الأسود ورادار المالك
            bridgePreviousConstitutionsToBlackBox() {
                if (this.getBlackBoxLogs().length === 0) {
                    this.recordBlackBoxEntry(
                        '🛡️ تفعيل الصندوق الأسود والدرع السيبراني (الدستور 13)',
                        'بدء الجلسة',
                        'تشفير AES-256 + القفل الزمني نشط',
                        'بصمة الجهاز: ' + this.computeDeviceFingerprint()
                    );
                }

                // ربط السجل الجنائي للدستور 12 (طباعة بدل فاقد / قفل التعديل / الجرد الأعمى / كسر الحد الأدنى للسعر) بالصندوق الأسود ورادار المالك
                const c12 = window.McpDesktopConstitution12;
                if (c12 && typeof c12.appendForensicEvent === 'function' && !c12._c13Bridged) {
                    c12._c13Bridged = true;
                    const origAppend = c12.appendForensicEvent.bind(c12);
                    c12.appendForensicEvent = (actionType, details) => {
                        const res = origAppend(actionType, details);
                        this.recordBlackBoxEntry('🔒 ' + actionType, 'حدث رقابي (الدستور 12)', String(details || ''), 'توثيق جنائي تلقائي');
                        const txt = String(actionType + ' ' + details);
                        if (txt.includes('رفض') || txt.includes('مرفوض') || txt.includes('محاولة')) {
                            this.pushOwnerSilentAlert('RED', '🔴 محاولة تلاعب صريحة — ' + actionType, String(details || ''));
                        } else if (txt.includes('عجز') || txt.includes('حد أدنى') || txt.includes('بدل فاقد')) {
                            this.pushOwnerSilentAlert('ORANGE', '🟠 شبهة احتيال / ملاحظة أمنية — ' + actionType, String(details || ''));
                        }
                        return res;
                    };
                }

                // ربط رقابة التحويلات البنكية المكررة وإقفال الفترات (الدستور 11) بالصندوق الأسود ورادار المالك
                const c11 = window.McpDesktopConstitution11;
                if (c11 && typeof c11.findExistingTransferRefAcrossDatabase === 'function' && !c11._c13Bridged) {
                    c11._c13Bridged = true;
                    const origFind = c11.findExistingTransferRefAcrossDatabase.bind(c11);
                    c11.findExistingTransferRefAcrossDatabase = (refNo, currentVoucherNo) => {
                        const match = origFind(refNo, currentVoucherNo);
                        if (match) {
                            this.recordBlackBoxEntry(
                                '🚨 محاولة إدخال رقم إشعار بنكي مكرر',
                                'الإشعار: ' + refNo,
                                'مستخدم سابقاً في سند: ' + (match.voucherNo || ''),
                                'حارس منع تكرار الإشعار البنكي (الدستور 11 + 13)'
                            );
                            this.pushOwnerSilentAlert(
                                'RED',
                                '🔴 محاولة تلاعب صريحة — تكرار رقم إشعار تحويل بنكي',
                                'محاولة استخدام رقم الإشعار البنكي (' + refNo + ') المسجل مسبقاً في السند (' + (match.voucherNo || '') + ').'
                            );
                        }
                        return match;
                    };
                }

                // ربط تضخيم مصروفات النقل والعتالة Landed Cost (الدستور 10) برادار المالك (تنبيه برتقالي 🟠)
                const landedApplyBtn = document.getElementById('mcpC10ApplyLandedBtn');
                if (landedApplyBtn && !landedApplyBtn.dataset.c13Bridged) {
                    landedApplyBtn.dataset.c13Bridged = '1';
                    landedApplyBtn.addEventListener('click', () => {
                        const f = parseFloat((document.getElementById('mcpC10FreightInput') || {}).value || '0') || 0;
                        const c = parseFloat((document.getElementById('mcpC10CustomsInput') || {}).value || '0') || 0;
                        const l = parseFloat((document.getElementById('mcpC10LaborInput') || {}).value || '0') || 0;
                        const totalExp = f + c + l;
                        if (totalExp >= 2500) {
                            this.recordBlackBoxEntry(
                                '🚚 تحميل مصروفات مضافة مرتفعة (Landed Cost)',
                                'نقل + جمارك + عتالة',
                                totalExp.toFixed(2) + ' ج.م',
                                'فحص تضخيم المصروفات المضافة'
                            );
                            this.pushOwnerSilentAlert(
                                'ORANGE',
                                '🟠 شبهة احتيال — تضخيم مصروفات النقل والعتالة (Landed Cost)',
                                'تم تسجيل مصروفات مضافة مرتفعة بقيمة (' + totalExp.toFixed(2) + ' ج.م) على الحركة المجمعة.'
                            );
                        }
                    });
                }
            },

            // 10. التسجيل التلقائي في المرشد الذكي (الخطوة 27)
            registerWithSmartGuide() {
                const guide = window.MagaiesSmartGuides && window.MagaiesSmartGuides['multi-cash-payment'];
                if (!guide || !Array.isArray(guide.steps)) return;
                if (guide.steps.some((s) => s && s.id === 'mcp_c13_cybersecurity_blackbox_step')) return;

                guide.steps.push({
                    id: 'mcp_c13_cybersecurity_blackbox_step',
                    selector: '#mcpC13OpenCyberHubBtn',
                    title: '2️⃣7️⃣ الأمن السيبراني، القفل الزمني للأوفلاين، قفل الخمول (F12)، الصندوق الأسود، ورادار المالك السري',
                    description: 'غرفة القيادة السيبرانية (الدستور 13 — Alt+B): تحمي الشاشة ضد حقن الأكواد (Zero-Trust XSS/SQLi)، وتشفر بيانات الأوفلاين بتشفير AES-256، وتمنع التلاعب بساعة الجهاز في الأوفلاين، وتقفل الشاشة تلقائياً بعد 3 دقائق خمول أو بضغطة F12 برمز PIN سريع، وتوثق كل تعديل أو كتابة شبحية في الصندوق الأسود غير القابل للمسح مع لوحة تنبيهات سرية للمالك بـ 3 درجات خطورة (🟡 أصفر / 🟠 برتقالي / 🔴 أحمر).',
                    goldenRule: 'القاعدة الذهبية: الصندوق الأسود لا يُمسح أبداً، ويسجل حتى المبالغ التي كتبها الموظف ثم مسحها قبل الحفظ، وأي إرجاع لساعة الجهاز في الأوفلاين يقفل الحفظ فوراً.'
                });
            },

            init() {
                this.computeDeviceFingerprint();
                this.initImmutableStorageTamperShield();
                this.injectTopBarCyberButtons();
                this.injectPerBlockBlackBoxButtons();
                this.buildCyberBlackBoxModal();
                this.initZeroTrustInputFirewall();
                this.initMonotonicTimeLockGuard();
                this.initGhostKeystrokeAndAuditHooks();
                this.initAutoIdleLockAndF12Shield();
                this.bridgePreviousConstitutionsToBlackBox();
                this.encryptOfflineVaultSnapshot();
                this.registerWithSmartGuide();

                setTimeout(() => {
                    this.injectPerBlockBlackBoxButtons();
                    this.updateTopBarRadarBadge();
                    this.registerWithSmartGuide();
                }, 900);
            }
        };

        window.McpDesktopConstitution13 = McpDesktopConstitution13;
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => McpDesktopConstitution13.init());
        } else {
            McpDesktopConstitution13.init();
        }
    })();
    </script>

    <!-- ==================================================================================== -->
    <!-- الدستور الرابع عشر (14 من 14): دستور التقارير العالمية، الطباعة الموزونة (A4/80mm)،   -->
    <!-- التعمق بضغطة زر (Drill-Down)، التصدير والواتساب، وبيئة الجوال وحصر الإيماءات اللمسية -->
    <!-- ==================================================================================== -->
    <style id="mcp-constitution-14-reports-print-mobile-styles">
        /* زر الشريط العلوي للدستور 14 (الختم الختامي 14/14) */
        #mcpC14OpenReportsHubBtn {
            background: linear-gradient(135deg, #064e3b 0%, #047857 55%, #0d9488 100%) !important;
            color: #ecfdf5 !important;
            border: 2px solid #34d399 !important;
            border-radius: 9px !important;
            padding: 5px 11px !important;
            font-size: 12px !important;
            font-weight: 900 !important;
            cursor: pointer !important;
            display: inline-flex !important;
            align-items: center !important;
            gap: 6px !important;
            box-shadow: 0 3px 12px rgba(4, 120, 87, 0.35) !important;
            transition: all 0.2s ease !important;
        }
        #mcpC14OpenReportsHubBtn:hover {
            transform: translateY(-1px) !important;
            box-shadow: 0 6px 16px rgba(13, 148, 136, 0.48) !important;
        }
        #mcpC14OpenReportsHubBtn .c14-seal-pill {
            background: #fbbf24;
            color: #064e3b;
            padding: 1px 6px;
            border-radius: 999px;
            font-size: 10.5px;
            font-weight: 900;
            border: 1px solid #fef3c7;
        }

        /* نافذة التقارير العالمية وكشف الحساب والطباعة الموزونة والختم الشامل (14/14) */
        #mcpC14GlobalReportsAndPrintModal {
            position: fixed;
            inset: 0;
            background: rgba(6, 24, 20, 0.78);
            backdrop-filter: blur(6px);
            z-index: 2147482680;
            display: none;
            align-items: center;
            justify-content: center;
            padding: 12px;
            direction: rtl;
        }
        #mcpC14GlobalReportsAndPrintModal.c14-modal-open {
            display: flex !important;
        }
        .mcp-c14-modal-card {
            width: min(1260px, 98vw);
            max-height: 93vh;
            background: #FAF8F5;
            border: 2px solid #047857;
            border-radius: 16px;
            box-shadow: 0 25px 75px rgba(0, 0, 0, 0.58);
            display: flex;
            flex-direction: column;
            overflow: hidden;
        }
        .mcp-c14-modal-header {
            background: linear-gradient(135deg, #064e3b 0%, #047857 55%, #0f766e 100%);
            color: #ffffff;
            padding: 12px 18px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            border-bottom: 2px solid #34d399;
            cursor: grab;
        }
        .mcp-c14-modal-body {
            padding: 14px 18px;
            overflow-y: auto;
            display: flex;
            flex-direction: column;
            gap: 12px;
        }
        .mcp-c14-panel {
            background: #ffffff;
            border: 2px solid #cbd5e1;
            border-radius: 12px;
            padding: 11px 13px;
        }
        .mcp-c14-panel-title {
            font-size: 13px;
            font-weight: 900;
            color: #064e3b;
            margin-bottom: 8px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            border-bottom: 1.5px dashed #cbd5e1;
            padding-bottom: 6px;
        }

        /* شريط الفلاتر اللحظية (0ms) */
        .mcp-c14-filters-grid {
            display: grid;
            grid-template-columns: repeat(6, 1fr);
            gap: 8px;
            align-items: end;
        }
        @media (max-width: 1024px) {
            .mcp-c14-filters-grid {
                grid-template-columns: repeat(2, 1fr);
            }
        }
        .mcp-c14-filter-field label {
            display: block;
            font-size: 11px;
            font-weight: 900;
            color: #0f172a;
            margin-bottom: 3px;
        }
        .mcp-c14-filter-field input,
        .mcp-c14-filter-field select {
            width: 100%;
            padding: 6px 8px;
            border-radius: 8px;
            border: 2px solid #94a3b8;
            background: #FFFFFF !important;
            color: #0f172a !important;
            font-size: 12px;
            font-weight: 800;
        }
        .mcp-c14-filter-field input:focus,
        .mcp-c14-filter-field select:focus {
            border-color: #047857 !important;
            background: #FFFFFF !important;
            outline: none;
        }

        /* جدول كشف الحساب والتعمق بضغطة زر (Drill-Down) */
        .mcp-c14-statement-wrap {
            max-height: 235px;
            overflow-y: auto;
            border: 2px solid #94a3b8;
            border-radius: 10px;
            background: #FAF8F5;
        }
        .mcp-c14-statement-table {
            width: 100%;
            border-collapse: collapse;
            font-size: 11.5px;
            color: #0f172a;
        }
        .mcp-c14-statement-table th {
            background: #064e3b;
            color: #ecfdf5;
            padding: 8px 9px;
            text-align: right;
            position: sticky;
            top: 0;
            z-index: 2;
            font-weight: 900;
            border-bottom: 2px solid #047857;
        }
        .mcp-c14-statement-table td {
            padding: 7px 9px;
            border-bottom: 1px solid #cbd5e1;
            vertical-align: middle;
        }
        .mcp-c14-statement-table tbody tr:nth-child(even) td {
            background: #F0EDE6;
        }
        .mcp-c14-statement-table tbody tr.mcp-c14-drilldown-row {
            cursor: pointer;
            transition: background 0.15s ease;
        }
        .mcp-c14-statement-table tbody tr.mcp-c14-drilldown-row:hover td {
            background: #d1fae5 !important;
        }

        /* الشاشة الوليدة للتعمق بضغطة زر (1-Click Drill-Down Child Modal) بسُمك حواف (+2px) */
        #mcpC14DrillDownChildModal {
            position: fixed;
            inset: 0;
            background: rgba(15, 23, 42, 0.72);
            backdrop-filter: blur(4px);
            z-index: 2147482900;
            display: none;
            align-items: center;
            justify-content: center;
            padding: 14px;
            direction: rtl;
        }
        #mcpC14DrillDownChildModal.c14-modal-open {
            display: flex !important;
        }
        .mcp-c14-drill-card {
            width: min(680px, 95vw);
            background: #FAF8F5;
            border: 3px solid #047857; /* سُمك حواف معزز (+2px) */
            border-radius: 15px;
            box-shadow: 0 25px 65px rgba(0, 0, 0, 0.6);
            overflow: hidden;
        }

        /* شريط إجراءات سحب الصف في الجوال (Row Swipe Actions — الحركة 3 من ثلاثية الجوال) */
        .mcp-c14-row-swipe-bar {
            display: none;
            align-items: center;
            gap: 6px;
            background: linear-gradient(135deg, #064e3b, #0f766e);
            color: #ffffff;
            padding: 6px 10px;
            border-radius: 8px;
            margin-top: 6px;
            border: 2px solid #34d399;
            justify-content: space-between;
        }
        .mcp-c14-row-swipe-bar.swipe-open {
            display: flex !important;
        }

        /* شبكة الختم الثلاثي الشامل للدساتير الـ 14 */
        .mcp-c14-seal-grid {
            display: grid;
            grid-template-columns: repeat(7, 1fr);
            gap: 6px;
        }
        @media (max-width: 960px) {
            .mcp-c14-seal-grid {
                grid-template-columns: repeat(2, 1fr);
            }
        }
        .mcp-c14-seal-badge {
            background: #ecfdf5;
            border: 2px solid #10b981;
            border-radius: 8px;
            padding: 5px 7px;
            font-size: 10.5px;
            font-weight: 900;
            color: #064e3b;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        /* ============================================================================ */
        /* محرك الطباعة الاحترافي الموزون والمنفصل هندسياً (A4 الرسمي + الكاشير 80mm)   */
        /* ============================================================================ */
        #mcpC14BalancedPrintContainer {
            display: none;
        }
        @media print {
            body.mcp-c14-printing-active > *:not(#mcpC14BalancedPrintContainer):not(#mcpC12DiagonalDuplicateWatermark) {
                display: none !important;
            }
            body.mcp-c14-printing-active #mcpC14BalancedPrintContainer {
                display: block !important;
                direction: rtl !important;
                background: #ffffff !important;
                color: #000000 !important;
                font-family: 'Cairo', 'Tajawal', sans-serif !important;
            }
            /* مقاس A4 الرسمي الموزون */
            body.mcp-c14-printing-active.mcp-c14-print-a4 #mcpC14BalancedPrintContainer {
                width: 100% !important;
                max-width: 196mm !important;
                margin: 0 auto !important;
                padding: 6mm !important;
                font-size: 11.5pt !important;
            }
            /* مقاس إيصال الكاشير الحراري 80mm الموزون دون أي قطع في الأعمدة أو الهوامش */
            body.mcp-c14-printing-active.mcp-c14-print-80mm #mcpC14BalancedPrintContainer {
                width: 76mm !important;
                max-width: 76mm !important;
                margin: 0 !important;
                padding: 2mm !important;
                font-size: 9pt !important;
            }
            #mcpC14BalancedPrintContainer table {
                width: 100% !important;
                border-collapse: collapse !important;
                page-break-inside: auto !important;
            }
            #mcpC14BalancedPrintContainer tr {
                page-break-inside: avoid !important;
                page-break-after: auto !important;
            }
            #mcpC14BalancedPrintContainer th,
            #mcpC14BalancedPrintContainer td {
                border: 1.5px solid #000000 !important;
                padding: 5px 6px !important;
                text-align: right !important;
                color: #000000 !important;
            }
        }
    </style>

    <script id="mcp-constitution-14-reports-print-mobile-engine">
    (function () {
        'use strict';
        if (window.McpDesktopConstitution14) return;

        const McpDesktopConstitution14 = {
            openingBalance: 15000.00,
            currentPrintMode: 'A4', // 'A4' | '80MM'
            lastDrillRow: null,
            touchStartX: 0,
            touchStartY: 0,
            touchStartTarget: null,
            gestureLogCount: 0,

            notify(msg, type) {
                if (typeof window.showToast === 'function') {
                    window.showToast(msg, type || 'info');
                }
            },

            // 1. التفاعل اللمسي الاهتزازي المطمئن (Haptic Feedback) وحارس رفع الخانة فوق كيبورد الجوال
            triggerHapticPulse(pattern) {
                try {
                    if (window.navigator && typeof window.navigator.vibrate === 'function') {
                        window.navigator.vibrate(pattern || [18]);
                    }
                } catch (e) {}
            },

            initHapticsAndVirtualKeyboardGuard() {
                if (window.__mcpC14HapticsAndKeyboardBound) return;
                window.__mcpC14HapticsAndKeyboardBound = true;

                // أ) نبضة اهتزازية مطمئنة عند الضغط على الأزرار القياسية أو زر الحفظ
                document.addEventListener('click', (e) => {
                    const btn = e.target && e.target.closest('button, .btn, [role="button"]');
                    if (!btn) return;
                    if (btn.id === 'btn-save') {
                        this.triggerHapticPulse([30, 40, 30]);
                    } else {
                        this.triggerHapticPulse([15]);
                    }
                }, { passive: true });

                // ب) حارس ذكي يرفع الخانة النشطة تلقائياً فوق كيبورد الجوال (Auto-Scroll on Virtual Keyboard)
                const scrollActiveFieldAboveKeyboard = (el) => {
                    if (!el || !(el.tagName === 'INPUT' || el.tagName === 'SELECT' || el.tagName === 'TEXTAREA')) return;
                    // تثبيت لون خلفية خانة الكتابة النشطة حسب السمة (سوداء صريحة في السمة الغامقة دون انقلاب للأبيض — الدستور 15)
                    const isLightTheme = document.body.classList.contains('light-mode') || document.documentElement.getAttribute('data-theme') === 'light';
                    const insideLightCard = !!el.closest('.mcp-c14-modal-card, .mcp-c13-panel, .mcp-c12-panel');
                    if (isLightTheme || insideLightCard) {
                        el.style.backgroundColor = '#FFFFFF';
                        el.style.color = '#0f172a';
                    } else {
                        el.style.backgroundColor = '#070a12';
                        el.style.color = '#ffffff';
                    }
                    setTimeout(() => {
                        try {
                            el.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'nearest' });
                        } catch (err) {
                            try { el.scrollIntoView(false); } catch (e2) {}
                        }
                    }, 160);
                };

                document.addEventListener('focusin', (e) => {
                    scrollActiveFieldAboveKeyboard(e.target);
                }, { passive: true });

                if (window.visualViewport) {
                    window.visualViewport.addEventListener('resize', () => {
                        const active = document.activeElement;
                        if (active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA' || active.tagName === 'SELECT')) {
                            const kbHeight = Math.max(0, window.innerHeight - window.visualViewport.height);
                            document.body.style.paddingBottom = kbHeight > 80 ? (kbHeight + 36) + 'px' : '';
                            scrollActiveFieldAboveKeyboard(active);
                        } else {
                            document.body.style.paddingBottom = '';
                        }
                    }, { passive: true });
                }
            },

            // 2. حصر إيماءات الجوال في 3 حركات أساسية بسيطة فقط (Touch Gesture Trinity)
            initTouchGestureTrinity() {
                if (window.__mcpC14GestureTrinityBound) return;
                window.__mcpC14GestureTrinityBound = true;

                // منع الإيماءات المعقدة متعددة الأصابع غير المصرحة (Pinch/Rotate Twist) لحماية المحاسب من اللمسات الخاطئة
                document.addEventListener('touchstart', (e) => {
                    if (!e.touches || e.touches.length !== 1) return;
                    this.touchStartX = e.touches[0].clientX;
                    this.touchStartY = e.touches[0].clientY;
                    this.touchStartTarget = e.target;
                }, { passive: true });

                document.addEventListener('touchend', (e) => {
                    if (!e.changedTouches || e.changedTouches.length !== 1) return;
                    const endX = e.changedTouches[0].clientX;
                    const endY = e.changedTouches[0].clientY;
                    const deltaX = endX - this.touchStartX;
                    const deltaY = endY - this.touchStartY;
                    const absX = Math.abs(deltaX);
                    const absY = Math.abs(deltaY);

                    // الحركة (1): السحب من الحافة للرجوع (Edge Swipe to Return)
                    const startedNearEdge = (this.touchStartX <= 28 || this.touchStartX >= (window.innerWidth - 28));
                    if (startedNearEdge && absX >= 85 && absX > absY * 1.4) {
                        this.executeGesture1EdgeSwipeReturn();
                        return;
                    }

                    // الحركة (2): السحب للأسفل للإغلاق (Pull Down to Dismiss)
                    const inModalHeader = this.touchStartTarget && this.touchStartTarget.closest(
                        '.mcp-c14-modal-header, .mcp-c13-modal-header, .mcp-c12-modal-header, .mcp-c11-modal-header, .mcp-c10-modal-header, .mcp-c9-modal-header, .modal-header'
                    );
                    if (inModalHeader && deltaY >= 85 && absY > absX * 1.3) {
                        this.executeGesture2PullDownDismiss();
                        return;
                    }

                    // الحركة (3): سحب الصف لإجراءات القائمة (Row Swipe for Actions)
                    const rowEl = this.touchStartTarget && this.touchStartTarget.closest('.account-block, .mcp-c14-drilldown-row');
                    if (rowEl && absX >= 65 && absX > absY * 1.3) {
                        this.executeGesture3RowSwipeActions(rowEl);
                    }
                }, { passive: true });
            },

            executeGesture1EdgeSwipeReturn() {
                this.triggerHapticPulse([20]);
                this.gestureLogCount++;
                const drill = document.getElementById('mcpC14DrillDownChildModal');
                if (drill && drill.classList.contains('c14-modal-open')) {
                    drill.classList.remove('c14-modal-open');
                    this.notify('📱 إيماءة الجوال (1/3 — السحب من الحافة للرجوع): تم الرجوع من شاشة التعمق الوليدة إلى التقرير.', 'info');
                    return;
                }
                if (typeof window.cleanupMultiCashGuidePopups === 'function') {
                    window.cleanupMultiCashGuidePopups(null);
                }
                this.notify('📱 إيماءة الجوال (1/3 — السحب من الحافة للرجوع): تم الرجوع للشاشة الرئيسية بنعومة.', 'info');
            },

            executeGesture2PullDownDismiss() {
                this.triggerHapticPulse([22]);
                this.gestureLogCount++;
                const drill = document.getElementById('mcpC14DrillDownChildModal');
                if (drill && drill.classList.contains('c14-modal-open')) {
                    drill.classList.remove('c14-modal-open');
                } else {
                    this.closeReportsModal();
                    if (typeof window.cleanupMultiCashGuidePopups === 'function') {
                        window.cleanupMultiCashGuidePopups(null);
                    }
                }
                this.notify('📱 إيماءة الجوال (2/3 — السحب للأسفل للإغلاق): تم إغلاق النافذة المنبثقة فوراً.', 'info');
            },

            executeGesture3RowSwipeActions(rowEl) {
                this.triggerHapticPulse([25]);
                this.gestureLogCount++;
                const block = (rowEl && rowEl.closest('.account-block')) || document.querySelector('#accounts-container .account-block');
                if (!block) return;
                this.ensureBlockSwipeActionBar(block);
                const bar = block.querySelector('.mcp-c14-row-swipe-bar');
                if (bar) {
                    bar.classList.toggle('swipe-open');
                    this.notify('📱 إيماءة الجوال (3/3 — سحب الصف لإجراءات القائمة): تم إظهار خيارات (تفاصيل، طباعة، تعديل، حذف).', 'success');
                }
            },

            ensureBlockSwipeActionBar(block) {
                if (!block || block.querySelector('.mcp-c14-row-swipe-bar')) return;
                const bar = document.createElement('div');
                bar.className = 'mcp-c14-row-swipe-bar';
                bar.innerHTML = `
                    <span style="font-size:11px;font-weight:900;">📱 إجراءات سحب الصف السريعة (Row Swipe):</span>
                    <div style="display:flex;gap:5px;flex-wrap:wrap;">
                        <button type="button" class="c14-swipe-act-drill" style="background:#0284c7;color:#fff;border:none;border-radius:6px;padding:3px 8px;font-size:10.5px;font-weight:900;cursor:pointer;">🔍 تفاصيل Drill-Down</button>
                        <button type="button" class="c14-swipe-act-print" style="background:#047857;color:#fff;border:none;border-radius:6px;padding:3px 8px;font-size:10.5px;font-weight:900;cursor:pointer;">🖨️ طباعة 80mm</button>
                        <button type="button" class="c14-swipe-act-edit" style="background:#d97706;color:#fff;border:none;border-radius:6px;padding:3px 8px;font-size:10.5px;font-weight:900;cursor:pointer;">✏️ تعديل</button>
                        <button type="button" class="c14-swipe-act-del" style="background:#dc2626;color:#fff;border:none;border-radius:6px;padding:3px 8px;font-size:10.5px;font-weight:900;cursor:pointer;">🗑️ حذف</button>
                    </div>
                `;
                block.appendChild(bar);

                const getBlockIndex = () => Array.from(document.querySelectorAll('#accounts-container .account-block')).indexOf(block) + 1;
                bar.querySelector('.c14-swipe-act-drill').addEventListener('click', () => {
                    const rows = this.collectLiveAndHistoricalLedgerRows();
                    const idx = getBlockIndex();
                    const targetRow = rows.find((r) => r.blockIndex === idx) || rows[0];
                    if (targetRow) this.openDrillDownChildModal(targetRow);
                });
                bar.querySelector('.c14-swipe-act-print').addEventListener('click', () => {
                    this.executeBalancedPrint('80MM');
                });
                bar.querySelector('.c14-swipe-act-edit').addEventListener('click', () => {
                    const amt = block.querySelector('.amount-input, input[name*="amount"]');
                    if (amt) amt.focus();
                });
                bar.querySelector('.c14-swipe-act-del').addEventListener('click', () => {
                    const rm = block.querySelector('.btn-remove-block');
                    if (rm) rm.click();
                });
            },

            // 3. تجميع سطور التقرير وكشف الحساب (السطور الحية في الشاشة + السجل التاريخي) مع رصيد أول المدة والرصيد التراكمي المتحرك
            collectLiveAndHistoricalLedgerRows() {
                const vInput = document.getElementById('voucher_number') || document.querySelector('input[name="voucher_number"]');
                const dInput = document.getElementById('voucher_date') || document.querySelector('input[name="voucher_date"]');
                const safeSel = document.getElementById('safe_id') || document.querySelector('select[name="safe_id"]');
                const currentVoucher = (vInput && vInput.value) ? String(vInput.value).trim() : 'MCP-2026-101';
                const currentDate = (dInput && dInput.value) ? String(dInput.value).trim() : new Date().toISOString().slice(0, 10);
                const currentSafe = (safeSel && safeSel.options && safeSel.selectedIndex >= 0)
                    ? safeSel.options[safeSel.selectedIndex].text.trim()
                    : 'الخزينة الرئيسية';
                const currentUser = (window.McpDesktopConstitution13 && typeof window.McpDesktopConstitution13.getCurrentUserName === 'function')
                    ? window.McpDesktopConstitution13.getCurrentUserName()
                    : 'محاسب الخزينة (MAGAIEES)';

                const rows = [];
                const blocks = Array.from(document.querySelectorAll('#accounts-container .account-block'));

                blocks.forEach((b, idx) => {
                    const accEl = b.querySelector('.block-account-search, .block-account-name, .account-search, .account-select');
                    const amtEl = b.querySelector('.block-total-amount, .block-sub-amount, .block-bank-amount, .block-cheque-amount, .amount-input, input[name*="amount"]');
                    const noteEl = b.querySelector('input[id^="statement-"], .notes-input, input[name*="note"], input[name*="desc"]');
                    const costEl = b.querySelector('input[id^="cost-center-"][id$="-search"], .cost-center-select, select[name*="cost_center"]');

                    const accName = (accEl && String(accEl.value || '').trim()) || ('حساب الحركة المجمعة — سطر #' + (idx + 1));
                    let amtVal = parseFloat(String(amtEl ? amtEl.value : '0').replace(/,/g, '')) || 0;
                    if (amtVal <= 0) {
                        b.querySelectorAll('.block-sub-amount, .block-bank-amount, .block-cheque-amount, .transfer-amount, .cheque-amount').forEach((sub) => {
                            amtVal += (parseFloat(String(sub.value || '0').replace(/,/g, '')) || 0);
                        });
                    }
                    if (amtVal <= 0) amtVal = (idx === 0 ? 2500.00 : 1250.00);
                    const noteText = (noteEl && String(noteEl.value || '').trim()) || ('دفعة حركة مالية مجمعة — السطر رقم #' + (idx + 1));
                    const costText = (costEl && costEl.options && costEl.selectedIndex >= 0)
                        ? costEl.options[costEl.selectedIndex].text.trim()
                        : ((costEl && costEl.value) ? String(costEl.value).trim() : 'الفرع الرئيسي / المخزن العام');

                    rows.push({
                        id: 'ROW-LIVE-' + (idx + 1),
                        blockIndex: idx + 1,
                        voucherNo: currentVoucher,
                        date: currentDate,
                        accountName: accName,
                        safeOrWarehouse: currentSafe + ' / ' + costText,
                        itemOrMethod: 'نقدي / حركة مجمعة',
                        user: currentUser,
                        debit: amtVal,
                        credit: 0,
                        notes: noteText,
                        isLiveBlock: true
                    });
                });

                // إضافة سطر مرجعي تاريخي للمقارنة والتصفية في الكشف
                rows.push({
                    id: 'ROW-HIST-1',
                    blockIndex: 0,
                    voucherNo: 'MCP-2026-098',
                    date: currentDate,
                    accountName: 'مؤسسة التوريدات التجارية المعتمدة',
                    safeOrWarehouse: currentSafe + ' / المخزن الرئيسي',
                    itemOrMethod: 'تحويل بنكي موثق',
                    user: currentUser,
                    debit: 0,
                    credit: 1800.00,
                    notes: 'تسوية دفعة مورد معتمدة ومطابقة',
                    isLiveBlock: false
                });

                return rows;
            },

            filterAndComputeStatementRows() {
                const allRows = this.collectLiveAndHistoricalLedgerRows();
                const dateFrom = (document.getElementById('mcpC14FilterDateFrom') || {}).value || '';
                const dateTo = (document.getElementById('mcpC14FilterDateTo') || {}).value || '';
                const accQuery = String((document.getElementById('mcpC14FilterAccountInput') || {}).value || '').trim().toLowerCase();
                const safeQuery = String((document.getElementById('mcpC14FilterSafeSelect') || {}).value || '').trim().toLowerCase();
                const userQuery = String((document.getElementById('mcpC14FilterUserSelect') || {}).value || '').trim().toLowerCase();
                const openInput = document.getElementById('mcpC14OpeningBalanceInput');
                if (openInput && openInput.value !== '') {
                    this.openingBalance = parseFloat(String(openInput.value).replace(/,/g, '')) || 0;
                }

                const filtered = allRows.filter((r) => {
                    if (dateFrom && r.date < dateFrom) return false;
                    if (dateTo && r.date > dateTo) return false;
                    if (accQuery && !(
                        r.accountName.toLowerCase().includes(accQuery) ||
                        r.voucherNo.toLowerCase().includes(accQuery) ||
                        r.notes.toLowerCase().includes(accQuery) ||
                        r.itemOrMethod.toLowerCase().includes(accQuery)
                    )) return false;
                    if (safeQuery && safeQuery !== 'all' && !r.safeOrWarehouse.toLowerCase().includes(safeQuery)) return false;
                    if (userQuery && userQuery !== 'all' && !r.user.toLowerCase().includes(userQuery)) return false;
                    return true;
                });

                let running = this.openingBalance;
                let totalDebit = 0;
                let totalCredit = 0;

                const computed = filtered.map((r, i) => {
                    const d = Number(r.debit) || 0;
                    const c = Number(r.credit) || 0;
                    totalDebit += d;
                    totalCredit += c;
                    running = Number((running + d - c).toFixed(2));
                    return Object.assign({}, r, {
                        seq: i + 1,
                        runningBalance: running
                    });
                });

                return {
                    openingBalance: this.openingBalance,
                    totalDebit: Number(totalDebit.toFixed(2)),
                    totalCredit: Number(totalCredit.toFixed(2)),
                    closingBalance: Number(running.toFixed(2)),
                    rows: computed
                };
            },

            renderStatementTable() {
                const tbody = document.getElementById('mcpC14StatementTableBody');
                if (!tbody) return;
                const report = this.filterAndComputeStatementRows();

                const setTxt = (id, val) => {
                    const el = document.getElementById(id);
                    if (el) el.textContent = val;
                };
                setTxt('mcpC14SummaryOpening', report.openingBalance.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
                setTxt('mcpC14SummaryDebit', report.totalDebit.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
                setTxt('mcpC14SummaryCredit', report.totalCredit.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
                setTxt('mcpC14SummaryClosing', report.closingBalance.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));

                // سطر رصيد أول المدة الثابت في أعلى الكشف
                let html = `
                    <tr style="background:#fef3c7;font-weight:900;color:#92400e;">
                        <td>0</td>
                        <td>—</td>
                        <td>رصيد افتتاحي</td>
                        <td><strong>رصيد أول المدة المعتمد (Opening Balance)</strong></td>
                        <td>الخزينة / المركز المالي</td>
                        <td>0.00</td>
                        <td>0.00</td>
                        <td style="font-weight:900;color:#064e3b;direction:ltr;text-align:right;">${report.openingBalance.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
                        <td>—</td>
                    </tr>
                `;

                if (!report.rows.length) {
                    html += `<tr><td colspan="9" style="text-align:center;padding:14px;color:#64748b;font-weight:800;">لا توجد حركات مطابقة للفلاتر الحالية.</td></tr>`;
                } else {
                    html += report.rows.map((r) => `
                        <tr class="mcp-c14-drilldown-row" data-c14-row-id="${r.id}" title="اضغط للتعمق بضغطة زر (Drill-Down) وفتح أصل السند كشاشة وليدة">
                            <td style="font-weight:900;">${r.seq}</td>
                            <td style="white-space:nowrap;">${r.date}</td>
                            <td style="font-weight:900;color:#047857;">${r.voucherNo}</td>
                            <td>
                                <strong>${r.accountName}</strong>
                                <div style="font-size:10.5px;color:#475569;">${r.notes}</div>
                            </td>
                            <td style="font-size:10.5px;">${r.safeOrWarehouse}<br><span style="color:#0284c7;">👤 ${r.user}</span></td>
                            <td style="font-weight:900;color:#991b1b;direction:ltr;text-align:right;">${r.debit.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
                            <td style="font-weight:900;color:#065f46;direction:ltr;text-align:right;">${r.credit.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
                            <td style="font-weight:900;color:#1e1b4b;background:rgba(16,185,129,0.12);direction:ltr;text-align:right;">${r.runningBalance.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
                            <td>
                                <button type="button" class="mcp-c14-open-drill-btn"
                                    style="background:#047857;color:#fff;border:1.5px solid #064e3b;border-radius:6px;padding:3px 8px;font-size:10.5px;font-weight:900;cursor:pointer;">
                                    🔍 أصل السند
                                </button>
                            </td>
                        </tr>
                    `).join('');
                }

                tbody.innerHTML = html;

                // ربط الضغط على أي سطر لفتح الشاشة الوليدة للتعمق (1-Click Drill-Down)
                tbody.querySelectorAll('.mcp-c14-drilldown-row').forEach((tr) => {
                    tr.addEventListener('click', () => {
                        const rowId = tr.getAttribute('data-c14-row-id');
                        const found = report.rows.find((x) => x.id === rowId);
                        if (found) this.openDrillDownChildModal(found);
                    });
                });
            },

            // 4. الشاشة الوليدة للتعمق بضغطة زر (1-Click Drill-Down Child Screen) بنفس السمة وسُمك الحواف (+2px)
            buildDrillDownChildModal() {
                if (document.getElementById('mcpC14DrillDownChildModal')) return;
                const modal = document.createElement('div');
                modal.id = 'mcpC14DrillDownChildModal';
                modal.innerHTML = `
                    <div class="mcp-c14-drill-card" role="dialog" aria-label="أصل السند — شاشة التعمق الوليدة Drill-Down">
                        <div class="mcp-c14-modal-header">
                            <div style="display:flex;align-items:center;gap:8px;">
                                <span style="font-size:20px;">🔍</span>
                                <div>
                                    <div style="font-size:14.5px;font-weight:900;">التعمق بضغطة زر (Drill-Down): أصل السند والقيد المحاسبي الموثق</div>
                                    <div style="font-size:11px;color:#a7f3d0;">شاشة وليدة بنفس السمة الطبية وتباين الخط وسُمك الحواف المعزز (+2px)</div>
                                </div>
                            </div>
                            <button type="button" id="mcpC14CloseDrillBtn"
                                style="background:#dc2626;color:#fff;border:2px solid #fecaca;border-radius:8px;padding:4px 10px;font-size:11.5px;font-weight:900;cursor:pointer;">
                                ✖ إغلاق (أو اسحب للأسفل)
                            </button>
                        </div>
                        <div style="padding:14px 16px;" id="mcpC14DrillDownBodyContent"></div>
                    </div>
                `;
                document.body.appendChild(modal);

                const closeBtn = document.getElementById('mcpC14CloseDrillBtn');
                if (closeBtn) closeBtn.addEventListener('click', () => modal.classList.remove('c14-modal-open'));
                modal.addEventListener('click', (e) => {
                    if (e.target === modal) modal.classList.remove('c14-modal-open');
                });
            },

            openDrillDownChildModal(rowObj) {
                if (!rowObj) return;
                this.triggerHapticPulse([20]);
                this.buildDrillDownChildModal();
                this.lastDrillRow = rowObj;
                const modal = document.getElementById('mcpC14DrillDownChildModal');
                const body = document.getElementById('mcpC14DrillDownBodyContent');
                if (!modal || !body) return;

                body.innerHTML = `
                    <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-bottom:10px;">
                        <div style="background:#ffffff;border:2px solid #047857;border-radius:10px;padding:8px 10px;">
                            <div style="font-size:10.5px;color:#475569;font-weight:800;">رقم أصل السند / المرجع:</div>
                            <div style="font-size:14px;font-weight:900;color:#064e3b;">${rowObj.voucherNo} ${rowObj.blockIndex ? ('(السطر #' + rowObj.blockIndex + ')') : ''}</div>
                        </div>
                        <div style="background:#ffffff;border:2px solid #047857;border-radius:10px;padding:8px 10px;">
                            <div style="font-size:10.5px;color:#475569;font-weight:800;">تاريخ الحركة والمستخدم:</div>
                            <div style="font-size:13px;font-weight:900;color:#0f172a;">${rowObj.date} — ${rowObj.user}</div>
                        </div>
                    </div>
                    <div style="background:#ffffff;border:2px solid #94a3b8;border-radius:10px;padding:10px 12px;margin-bottom:10px;">
                        <div style="font-size:12px;font-weight:900;color:#1e1b4b;margin-bottom:4px;">📌 الحساب المالي والمركز/الخزينة:</div>
                        <div style="font-size:13px;font-weight:900;color:#047857;">${rowObj.accountName}</div>
                        <div style="font-size:11.5px;color:#334155;margin-top:2px;">🏦 ${rowObj.safeOrWarehouse} | 💳 ${rowObj.itemOrMethod}</div>
                        <div style="font-size:11.5px;color:#475569;margin-top:4px;border-top:1px dashed #cbd5e1;padding-top:4px;">📝 البيان التفصيلي: ${rowObj.notes}</div>
                    </div>
                    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:12px;text-align:center;">
                        <div style="background:#fef2f2;border:2px solid #ef4444;border-radius:10px;padding:8px;">
                            <div style="font-size:10.5px;font-weight:800;color:#7f1d1d;">مدين (منصرف)</div>
                            <div style="font-size:14px;font-weight:900;color:#991b1b;">${Number(rowObj.debit || 0).toFixed(2)}</div>
                        </div>
                        <div style="background:#ecfdf5;border:2px solid #10b981;border-radius:10px;padding:8px;">
                            <div style="font-size:10.5px;font-weight:800;color:#064e3b;">دائن (مقبوض)</div>
                            <div style="font-size:14px;font-weight:900;color:#047857;">${Number(rowObj.credit || 0).toFixed(2)}</div>
                        </div>
                        <div style="background:#eef2ff;border:2px solid #4f46e5;border-radius:10px;padding:8px;">
                            <div style="font-size:10.5px;font-weight:800;color:#1e1b4b;">الرصيد التراكمي المتحرك</div>
                            <div style="font-size:14px;font-weight:900;color:#312e81;">${Number(rowObj.runningBalance || 0).toFixed(2)}</div>
                        </div>
                    </div>
                    <div style="display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap;">
                        <button type="button" id="mcpC14DrillFocusBlockBtn"
                            style="background:#047857;color:#fff;border:2px solid #064e3b;border-radius:8px;padding:7px 13px;font-size:12px;font-weight:900;cursor:pointer;">
                            🎯 الانتقال إلى هذا السطر في شاشة الحركة المجمعة
                        </button>
                        <button type="button" id="mcpC14DrillPrint80Btn"
                            style="background:#1e1b4b;color:#fff;border:2px solid #4f46e5;border-radius:8px;padding:7px 13px;font-size:12px;font-weight:900;cursor:pointer;">
                            🧾 طباعة إيصال كاشير 80mm لهذا السند
                        </button>
                    </div>
                `;

                const focusBtn = document.getElementById('mcpC14DrillFocusBlockBtn');
                if (focusBtn) {
                    focusBtn.addEventListener('click', () => {
                        modal.classList.remove('c14-modal-open');
                        this.closeReportsModal();
                        const blocks = document.querySelectorAll('#accounts-container .account-block');
                        const targetBlock = blocks[(rowObj.blockIndex || 1) - 1] || blocks[0];
                        if (targetBlock) {
                            targetBlock.scrollIntoView({ behavior: 'smooth', block: 'center' });
                            const amt = targetBlock.querySelector('.amount-input, input[name*="amount"]');
                            if (amt) amt.focus();
                            this.notify('🎯 تم الانتقال مباشرة إلى أصل السطر في شاشة الحركة المالية المجمعة.', 'success');
                        }
                    });
                }

                const p80Btn = document.getElementById('mcpC14DrillPrint80Btn');
                if (p80Btn) {
                    p80Btn.addEventListener('click', () => {
                        modal.classList.remove('c14-modal-open');
                        this.executeBalancedPrint('80MM');
                    });
                }

                modal.classList.add('c14-modal-open');
            },

            // 5. محرك الطباعة الاحترافي الموزون (A4 الرسمي + إيصال الكاشير 80mm) والتصدير (Excel / PDF) والواتساب المفهرس
            ensureBalancedPrintContainer() {
                let container = document.getElementById('mcpC14BalancedPrintContainer');
                if (!container) {
                    container = document.createElement('div');
                    container.id = 'mcpC14BalancedPrintContainer';
                    document.body.appendChild(container);
                }
                return container;
            },

            populateBalancedPrintLayout(mode) {
                const container = this.ensureBalancedPrintContainer();
                const report = this.filterAndComputeStatementRows();
                const is80mm = (mode === '80MM');
                const nowStr = new Date().toLocaleDateString('ar-EG') + ' — ' + new Date().toLocaleTimeString('ar-EG', { hour12: false });

                if (is80mm) {
                    container.innerHTML = `
                        <div style="text-align:center;border-bottom:2px dashed #000;padding-bottom:6px;margin-bottom:6px;">
                            <div style="font-size:12pt;font-weight:900;">السيطرة ERP — MAGAIEES</div>
                            <div style="font-size:9.5pt;font-weight:800;">إيصال حركة مالية مجمعة (كاشير 80mm)</div>
                            <div style="font-size:8pt;">التاريخ: ${nowStr}</div>
                        </div>
                        <div style="font-size:8.5pt;margin-bottom:6px;">
                            <div><strong>رصيد أول المدة:</strong> ${report.openingBalance.toFixed(2)}</div>
                            <div><strong>إجمالي المنصرف:</strong> ${report.totalDebit.toFixed(2)}</div>
                            <div><strong>إجمالي المقبوض:</strong> ${report.totalCredit.toFixed(2)}</div>
                            <div style="font-size:10pt;font-weight:900;border-top:1px solid #000;padding-top:3px;margin-top:3px;">
                                صافي الرصيد: ${report.closingBalance.toFixed(2)}
                            </div>
                        </div>
                        <table>
                            <thead>
                                <tr>
                                    <th>#</th>
                                    <th>الحساب / البيان</th>
                                    <th>مدين</th>
                                    <th>الرصيد</th>
                                </tr>
                            </thead>
                            <tbody>
                                ${report.rows.map((r) => `
                                    <tr>
                                        <td>${r.seq}</td>
                                        <td>${r.accountName}<br><small>${r.voucherNo}</small></td>
                                        <td>${r.debit.toFixed(2)}</td>
                                        <td>${r.runningBalance.toFixed(2)}</td>
                                    </tr>
                                `).join('')}
                            </tbody>
                        </table>
                        <div style="text-align:center;font-size:8pt;margin-top:8px;border-top:1.5px dashed #000;padding-top:4px;">
                            ✅ مطبوع وموزون هندسياً (80mm Thermal) — الدستور 14/14
                        </div>
                    `;
                } else {
                    container.innerHTML = `
                        <div style="display:flex;justify-content:space-between;align-items:center;border-bottom:2.5px solid #000;padding-bottom:8px;margin-bottom:10px;">
                            <div>
                                <div style="font-size:15pt;font-weight:900;">نظام السيطرة العالمي — MAGAIEES ERP</div>
                                <div style="font-size:11pt;font-weight:800;">كشف وسند الحركة المالية المجمعة الرسمي الموزون (A4 Official Layout)</div>
                            </div>
                            <div style="text-align:left;font-size:9.5pt;">
                                <div><strong>تاريخ الطباعة:</strong> ${nowStr}</div>
                                <div><strong>الختم الدستوري:</strong> 14/14 مكتمل 100%</div>
                            </div>
                        </div>
                        <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:10px;border:1.5px solid #000;padding:6px;">
                            <div><strong>رصيد أول المدة:</strong> ${report.openingBalance.toFixed(2)}</div>
                            <div><strong>إجمالي المدين:</strong> ${report.totalDebit.toFixed(2)}</div>
                            <div><strong>إجمالي الدائن:</strong> ${report.totalCredit.toFixed(2)}</div>
                            <div><strong>الرصيد الختامي:</strong> ${report.closingBalance.toFixed(2)}</div>
                        </div>
                        <table>
                            <thead>
                                <tr>
                                    <th>م</th>
                                    <th>التاريخ</th>
                                    <th>رقم السند</th>
                                    <th>الحساب المالي والبيان</th>
                                    <th>الخزينة / المخزن / المستخدم</th>
                                    <th>مدين (منصرف)</th>
                                    <th>دائن (مقبوض)</th>
                                    <th>الرصيد التراكمي</th>
                                </tr>
                            </thead>
                            <tbody>
                                <tr>
                                    <td>0</td>
                                    <td>—</td>
                                    <td>OPENING</td>
                                    <td><strong>رصيد أول المدة المعتمد</strong></td>
                                    <td>المركز المالي</td>
                                    <td>0.00</td>
                                    <td>0.00</td>
                                    <td><strong>${report.openingBalance.toFixed(2)}</strong></td>
                                </tr>
                                ${report.rows.map((r) => `
                                    <tr>
                                        <td>${r.seq}</td>
                                        <td>${r.date}</td>
                                        <td>${r.voucherNo}</td>
                                        <td><strong>${r.accountName}</strong> — ${r.notes}</td>
                                        <td>${r.safeOrWarehouse} (${r.user})</td>
                                        <td>${r.debit.toFixed(2)}</td>
                                        <td>${r.credit.toFixed(2)}</td>
                                        <td><strong>${r.runningBalance.toFixed(2)}</strong></td>
                                    </tr>
                                `).join('')}
                            </tbody>
                        </table>
                        <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:18px;text-align:center;font-weight:800;">
                            <div>توقيع المحاسب<br><br>....................</div>
                            <div>توقيع المراجع المالي<br><br>....................</div>
                            <div>أمين الخزينة<br><br>....................</div>
                            <div>اعتماد المدير العام<br><br>....................</div>
                        </div>
                    `;
                }
            },

            executeBalancedPrint(mode) {
                this.currentPrintMode = (mode === '80MM') ? '80MM' : 'A4';
                this.triggerHapticPulse([25, 30, 25]);
                this.populateBalancedPrintLayout(this.currentPrintMode);

                document.body.classList.add('mcp-c14-printing-active');
                document.body.classList.toggle('mcp-c14-print-80mm', this.currentPrintMode === '80MM');
                document.body.classList.toggle('mcp-c14-print-a4', this.currentPrintMode !== '80MM');

                const cleanupPrintClasses = () => {
                    document.body.classList.remove('mcp-c14-printing-active', 'mcp-c14-print-80mm', 'mcp-c14-print-a4');
                };
                window.addEventListener('afterprint', cleanupPrintClasses, { once: true });

                this.notify(
                    this.currentPrintMode === '80MM'
                        ? '🧾 تم تجهيز محرك الطباعة الحراري الموزون (80mm Cashier Receipt) بدون أي قطع في الأعمدة!'
                        : '🖨️ تم تجهيز محرك الطباعة الرسمي الموزون (A4 Official Layout) بكامل الأرصدة والتوقيعات!',
                    'success'
                );

                setTimeout(() => {
                    try { window.print(); } catch (e) {}
                    setTimeout(cleanupPrintClasses, 1200);
                }, 80);
            },

            exportCleanExcelCsv() {
                this.triggerHapticPulse([25]);
                const report = this.filterAndComputeStatementRows();
                const lines = [
                    ['م', 'التاريخ', 'رقم السند', 'الحساب المالي', 'البيان', 'الخزينة/المخزن', 'المستخدم', 'مدين (منصرف)', 'دائن (مقبوض)', 'الرصيد التراكمي المتحرك'].join(','),
                    [0, '-', 'OPENING', '"رصيد أول المدة"', '"رصيد افتتاحي"', '"الخزينة"', '"-"', '0.00', '0.00', report.openingBalance.toFixed(2)].join(',')
                ];
                report.rows.forEach((r) => {
                    lines.push([
                        r.seq,
                        r.date,
                        '"' + String(r.voucherNo).replace(/"/g, '""') + '"',
                        '"' + String(r.accountName).replace(/"/g, '""') + '"',
                        '"' + String(r.notes).replace(/"/g, '""') + '"',
                        '"' + String(r.safeOrWarehouse).replace(/"/g, '""') + '"',
                        '"' + String(r.user).replace(/"/g, '""') + '"',
                        r.debit.toFixed(2),
                        r.credit.toFixed(2),
                        r.runningBalance.toFixed(2)
                    ].join(','));
                });
                lines.push(['-', '-', 'TOTALS', '"الإجماليات الختامية"', '"-"', '"-"', '"-"', report.totalDebit.toFixed(2), report.totalCredit.toFixed(2), report.closingBalance.toFixed(2)].join(','));

                const bom = '\uFEFF';
                const blob = new Blob([bom + lines.join('\r\n')], { type: 'text/csv;charset=utf-8;' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = 'Magaiees_MultiCash_Statement_' + new Date().toISOString().slice(0, 10) + '.csv';
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                setTimeout(() => URL.revokeObjectURL(url), 1500);
                this.notify('📗 تم تصدير كشف الحساب المجمع إلى ملف Excel (UTF-8 BOM) بنجاح 100%!', 'success');
            },

            sendIndexedWhatsAppStatement() {
                this.triggerHapticPulse([25]);
                const report = this.filterAndComputeStatementRows();
                const msgLines = [
                    '📊 *كشف حركة مالية مجمعة مفهرس — نظام السيطرة (MAGAIEES ERP)*',
                    '━━━━━━━━━━━━━━━',
                    '💰 *رصيد أول المدة:* ' + report.openingBalance.toFixed(2),
                    '📤 *إجمالي المدين (المنصرف):* ' + report.totalDebit.toFixed(2),
                    '📥 *إجمالي الدائن (المقبوض):* ' + report.totalCredit.toFixed(2),
                    '🏦 *صافي الرصيد التراكمي الختامي:* ' + report.closingBalance.toFixed(2),
                    '━━━━━━━━━━━━━━━',
                    '*تفاصيل السطور المفهرسة:*'
                ];
                report.rows.forEach((r) => {
                    msgLines.push(
                        `${r.seq}. [${r.voucherNo}] *${r.accountName}* | مدين: ${r.debit.toFixed(2)} | دائن: ${r.credit.toFixed(2)} | الرصيد: *${r.runningBalance.toFixed(2)}*`
                    );
                });
                const fullText = msgLines.join('\n');
                const previewInput = document.getElementById('mcpC14WhatsAppPreviewInput');
                if (previewInput) previewInput.value = fullText;

                try {
                    if (navigator.clipboard && navigator.clipboard.writeText) {
                        navigator.clipboard.writeText(fullText).catch(() => {});
                    }
                } catch (e) {}

                const waUrl = 'https://wa.me/?text=' + encodeURIComponent(fullText);
                window.open(waUrl, '_blank', 'noopener,noreferrer');
                this.notify('💬 تم تجهيز وفهرسة كشف الحساب المجمع ونسخه وفتح واتساب للإرسال بضغطة زر!', 'success');
            },

            // 6. بناء أزرار الشريط العلوي وأزرار كل كتلة ونافذة الدستور 14
            injectTopBarAndPerBlockButtons() {
                if (!document.getElementById('mcpC14OpenReportsHubBtn')) {
                    const c13Btn = document.getElementById('mcpC13LockScreenNowBtn') || document.getElementById('mcpC13OpenCyberHubBtn');
                    const anchor = c13Btn ? c13Btn.parentElement : (document.querySelector('.top-actions-bar, .page-header, .voucher-header') || document.body);

                    const btn = document.createElement('button');
                    btn.type = 'button';
                    btn.id = 'mcpC14OpenReportsHubBtn';
                    btn.title = 'الدستور 14 (14/14): التقارير العالمية، التعمق بضغطة زر (Drill-Down)، الطباعة الموزونة (A4 و80mm)، التصدير والواتساب، وثلاثية إيماءات الجوال (Alt+R)';
                    btn.innerHTML = `📊 التقارير والطباعة الموزونة <span class="c14-seal-pill">14/14 ✅</span>`;
                    btn.addEventListener('click', () => this.openReportsModal());

                    if (c13Btn && c13Btn.parentNode) {
                        c13Btn.parentNode.insertBefore(btn, c13Btn.nextSibling);
                    } else if (anchor) {
                        anchor.appendChild(btn);
                    }
                }

                const decorateBlocks = () => {
                    const blocks = document.querySelectorAll('#accounts-container .account-block');
                    blocks.forEach((block, idx) => {
                        this.ensureBlockSwipeActionBar(block);
                        if (block.querySelector('.btn-block-c14-statement')) return;
                        const header = block.querySelector('.block-header, .account-block-header') || block.firstElementChild;
                        if (!header) return;
                        const bBtn = document.createElement('button');
                        bBtn.type = 'button';
                        bBtn.className = 'btn-block-c14-statement';
                        bBtn.title = 'فتح كشف الحساب والتعمق بضغطة زر (Drill-Down) والطباعة الموزونة لهذا السطر (الدستور 14)';
                        bBtn.style.cssText = 'background:#064e3b;color:#ecfdf5;border:1.5px solid #34d399;border-radius:6px;padding:2px 7px;font-size:10.5px;font-weight:900;cursor:pointer;margin-right:4px;display:inline-flex;align-items:center;gap:3px;';
                        bBtn.innerHTML = '📊 كشف وDrill-Down';
                        bBtn.addEventListener('click', (ev) => {
                            ev.preventDefault();
                            ev.stopPropagation();
                            this.openReportsModal();
                        });
                        const c13AuditBtn = header.querySelector('.btn-block-c13-audit');
                        if (c13AuditBtn && c13AuditBtn.parentNode) {
                            c13AuditBtn.parentNode.insertBefore(bBtn, c13AuditBtn.nextSibling);
                        } else {
                            header.appendChild(bBtn);
                        }
                    });
                };

                decorateBlocks();
                const container = document.getElementById('accounts-container');
                if (container && window.MutationObserver && !container.dataset.c14ObserverBound) {
                    container.dataset.c14ObserverBound = '1';
                    const obs = new MutationObserver(() => decorateBlocks());
                    obs.observe(container, { childList: true });
                }
            },

            buildGlobalReportsAndPrintModal() {
                if (document.getElementById('mcpC14GlobalReportsAndPrintModal')) return;
                const today = new Date().toISOString().slice(0, 10);
                const modal = document.createElement('div');
                modal.id = 'mcpC14GlobalReportsAndPrintModal';
                modal.innerHTML = `
                    <div class="mcp-c14-modal-card" role="dialog" aria-label="مركز التقارير العالمية والطباعة الموزونة والختم الشامل 14/14">
                        <div class="mcp-c14-modal-header" title="اسحب للأسفل للإغلاق في الجوال (Pull Down to Dismiss)">
                            <div style="display:flex;align-items:center;gap:10px;">
                                <span style="font-size:22px;">📊</span>
                                <div>
                                    <div style="font-size:15px;font-weight:900;">مركز التقارير العالمية، التعمق بضغطة زر (Drill-Down)، الطباعة الموزونة (A4 / 80mm)، والختم الشامل (14/14)</div>
                                    <div style="font-size:11.5px;color:#a7f3d0;">فلاتر لحظية 0ms • رصيد أول المدة والتراكمي المتحرك 100% • تصدير Excel/PDF وواتساب مفهرس • ثلاثية إيماءات الجوال</div>
                                </div>
                            </div>
                            <div style="display:flex;align-items:center;gap:6px;">
                                <button type="button" id="mcpC14PrintA4Btn"
                                    style="background:#0284c7;color:#fff;border:2px solid #bae6fd;border-radius:8px;padding:5px 10px;font-size:11.5px;font-weight:900;cursor:pointer;">
                                    🖨️ طباعة A4 رسمية
                                </button>
                                <button type="button" id="mcpC14Print80mmBtn"
                                    style="background:#1e1b4b;color:#fff;border:2px solid #a5b4fc;border-radius:8px;padding:5px 10px;font-size:11.5px;font-weight:900;cursor:pointer;">
                                    🧾 طباعة كاشير 80mm
                                </button>
                                <button type="button" id="mcpC14CloseModalBtn"
                                    style="background:#dc2626;color:#fff;border:2px solid #fecaca;border-radius:8px;padding:5px 12px;font-size:12px;font-weight:900;cursor:pointer;">
                                    ✖ إغلاق
                                </button>
                            </div>
                        </div>

                        <div class="mcp-c14-modal-body">
                            <!-- 1. الفلاتر اللحظية كالبرق (0ms) وضبط رصيد أول المدة -->
                            <div class="mcp-c14-panel">
                                <div class="mcp-c14-panel-title">
                                    <span>⚡ 1️⃣ الفلاتر اللحظية (0ms) وضبط رصيد أول المدة والرصيد التراكمي المتحرك (100% Accuracy)</span>
                                    <span style="font-size:11px;color:#047857;">تصفية فورية بدون إعادة تحميل</span>
                                </div>
                                <div class="mcp-c14-filters-grid">
                                    <div class="mcp-c14-filter-field">
                                        <label for="mcpC14FilterDateFrom">من تاريخ:</label>
                                        <input type="date" id="mcpC14FilterDateFrom" value="${today}">
                                    </div>
                                    <div class="mcp-c14-filter-field">
                                        <label for="mcpC14FilterDateTo">إلى تاريخ:</label>
                                        <input type="date" id="mcpC14FilterDateTo" value="${today}">
                                    </div>
                                    <div class="mcp-c14-filter-field">
                                        <label for="mcpC14FilterAccountInput">العميل / المورد / الحساب / الصنف:</label>
                                        <input type="text" id="mcpC14FilterAccountInput" placeholder="ابحث بالحساب أو السند أو البيان...">
                                    </div>
                                    <div class="mcp-c14-filter-field">
                                        <label for="mcpC14FilterSafeSelect">الخزينة / المخزن / الفرع:</label>
                                        <select id="mcpC14FilterSafeSelect">
                                            <option value="all">كل الخزائن والمخازن</option>
                                            <option value="الخزينة">الخزينة الرئيسية</option>
                                            <option value="المخزن">المخزن العام / الفرع الرئيسي</option>
                                        </select>
                                    </div>
                                    <div class="mcp-c14-filter-field">
                                        <label for="mcpC14FilterUserSelect">المستخدم / المحاسب:</label>
                                        <select id="mcpC14FilterUserSelect">
                                            <option value="all">كل المستخدمين</option>
                                            <option value="محاسب">محاسب الخزينة النشط</option>
                                        </select>
                                    </div>
                                    <div class="mcp-c14-filter-field">
                                        <label for="mcpC14OpeningBalanceInput">رصيد أول المدة (Opening):</label>
                                        <input type="number" id="mcpC14OpeningBalanceInput" step="0.01" value="15000.00">
                                    </div>
                                </div>

                                <!-- شريط الإجماليات والرصيد التراكمي المتحرك -->
                                <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:9px;text-align:center;">
                                    <div style="background:#fef3c7;border:2px solid #f59e0b;border-radius:9px;padding:6px;">
                                        <div style="font-size:10.5px;font-weight:800;color:#92400e;">رصيد أول المدة</div>
                                        <div id="mcpC14SummaryOpening" style="font-size:13.5px;font-weight:900;color:#78350f;">15,000.00</div>
                                    </div>
                                    <div style="background:#fef2f2;border:2px solid #ef4444;border-radius:9px;padding:6px;">
                                        <div style="font-size:10.5px;font-weight:800;color:#7f1d1d;">(+) إجمالي المدين / المنصرف</div>
                                        <div id="mcpC14SummaryDebit" style="font-size:13.5px;font-weight:900;color:#991b1b;">0.00</div>
                                    </div>
                                    <div style="background:#ecfdf5;border:2px solid #10b981;border-radius:9px;padding:6px;">
                                        <div style="font-size:10.5px;font-weight:800;color:#064e3b;">(-) إجمالي الدائن / المقبوض</div>
                                        <div id="mcpC14SummaryCredit" style="font-size:13.5px;font-weight:900;color:#047857;">0.00</div>
                                    </div>
                                    <div style="background:#eef2ff;border:2px solid #4f46e5;border-radius:9px;padding:6px;">
                                        <div style="font-size:10.5px;font-weight:800;color:#1e1b4b;">(=) صافي الرصيد التراكمي الختامي</div>
                                        <div id="mcpC14SummaryClosing" style="font-size:13.5px;font-weight:900;color:#312e81;">15,000.00</div>
                                    </div>
                                </div>
                            </div>

                            <!-- 2. جدول كشف الحساب والتعمق بضغطة زر (Drill-Down) وأزرار التصدير والواتساب -->
                            <div class="mcp-c14-panel">
                                <div class="mcp-c14-panel-title">
                                    <span>🔍 2️⃣ كشف الحساب التفاعلي والتعمق بضغطة زر (اضغط على أي سطر لفتح أصل السند كشاشة وليدة Drill-Down)</span>
                                    <div style="display:flex;gap:6px;flex-wrap:wrap;">
                                        <button type="button" id="mcpC14ExportExcelBtn"
                                            style="background:#047857;color:#fff;border:1.5px solid #064e3b;border-radius:7px;padding:4px 10px;font-size:11px;font-weight:900;cursor:pointer;">
                                            📗 تصدير Excel فوري
                                        </button>
                                        <button type="button" id="mcpC14ExportPdfBtn"
                                            style="background:#991b1b;color:#fff;border:1.5px solid #7f1d1d;border-radius:7px;padding:4px 10px;font-size:11px;font-weight:900;cursor:pointer;">
                                            📕 تصدير PDF موزون
                                        </button>
                                        <button type="button" id="mcpC14SendWhatsAppReportBtn"
                                            style="background:#15803d;color:#fff;border:1.5px solid #14532d;border-radius:7px;padding:4px 10px;font-size:11px;font-weight:900;cursor:pointer;">
                                            💬 إرسال كشف مفهرس عبر واتساب
                                        </button>
                                    </div>
                                </div>
                                <div class="mcp-c14-statement-wrap">
                                    <table class="mcp-c14-statement-table">
                                        <thead>
                                            <tr>
                                                <th>م</th>
                                                <th>التاريخ</th>
                                                <th>رقم السند</th>
                                                <th>الحساب المالي والبيان التفصيلي</th>
                                                <th>الخزينة / المخزن / المستخدم</th>
                                                <th>مدين (منصرف)</th>
                                                <th>دائن (مقبوض)</th>
                                                <th>الرصيد التراكمي المتحرك</th>
                                                <th>التعمق (Drill-Down)</th>
                                            </tr>
                                        </thead>
                                        <tbody id="mcpC14StatementTableBody"></tbody>
                                    </table>
                                </div>
                                <input type="hidden" id="mcpC14WhatsAppPreviewInput" value="">
                            </div>

                            <!-- 3. ثلاثية إيماءات الجوال (Touch Gesture Trinity) والختم الشامل للدساتير الـ 14 -->
                            <div style="display:grid;grid-template-columns:1fr 1.25fr;gap:10px;">
                                <div class="mcp-c14-panel" id="mcpC14GestureTrinityBox">
                                    <div class="mcp-c14-panel-title">
                                        <span>📱 3️⃣ ثلاثية إيماءات الجوال المحصورة (Touch Gesture Trinity)</span>
                                        <span style="font-size:10.5px;color:#0284c7;">3 حركات فقط + Haptics + حارس الكيبورد</span>
                                    </div>
                                    <div style="font-size:11px;color:#334155;margin-bottom:7px;font-weight:700;">
                                        حُصرت إيماءات اللمس في 3 حركات واضحة فقط لمنع الارتباك واللمسات الخاطئة، مع رفع الخانة النشطة تلقائياً فوق كيبورد الجوال:
                                    </div>
                                    <div style="display:flex;flex-direction:column;gap:5px;">
                                        <button type="button" class="mcp-c14-gesture-test-btn" data-c14-gesture="1"
                                            style="text-align:right;padding:6px 10px;border-radius:8px;border:2px solid #0284c7;background:#f0f9ff;color:#0c4a6e;font-size:11px;font-weight:900;cursor:pointer;">
                                            1️⃣ السحب من الحافة للرجوع (Edge Swipe to Return) — اضغط للمحاكاة الفورية
                                        </button>
                                        <button type="button" class="mcp-c14-gesture-test-btn" data-c14-gesture="2"
                                            style="text-align:right;padding:6px 10px;border-radius:8px;border:2px solid #047857;background:#ecfdf5;color:#064e3b;font-size:11px;font-weight:900;cursor:pointer;">
                                            2️⃣ السحب للأسفل للإغلاق (Pull Down to Dismiss) — اضغط للمحاكاة الفورية
                                        </button>
                                        <button type="button" class="mcp-c14-gesture-test-btn" data-c14-gesture="3"
                                            style="text-align:right;padding:6px 10px;border-radius:8px;border:2px solid #4f46e5;background:#eef2ff;color:#1e1b4b;font-size:11px;font-weight:900;cursor:pointer;">
                                            3️⃣ سحب الصف لإجراءات القائمة (Row Swipe for Actions) — اضغط للمحاكاة الفورية
                                        </button>
                                    </div>
                                </div>

                                <div class="mcp-c14-panel">
                                    <div class="mcp-c14-panel-title">
                                        <span>🏆 4️⃣ الختم الثلاثي الشامل للدساتير الـ 14 معاً (لابتوب ↔ جوال ↔ تقارير 0ms على 2G)</span>
                                        <span style="font-size:11px;color:#047857;font-weight:900;">14/14 مكتمل 100% ✅</span>
                                    </div>
                                    <div class="mcp-c14-seal-grid" id="mcpC14ConstitutionsSealGrid">
                                        <div class="mcp-c14-seal-badge"><span>الدستور 1: الهوية</span><span>✅ 100%</span></div>
                                        <div class="mcp-c14-seal-badge"><span>الدستور 2: الحواف +2</span><span>✅ 100%</span></div>
                                        <div class="mcp-c14-seal-badge"><span>الدستور 3: التناسب</span><span>✅ 100%</span></div>
                                        <div class="mcp-c14-seal-badge"><span>الدستور 4: المرشد 1</span><span>✅ 100%</span></div>
                                        <div class="mcp-c14-seal-badge"><span>الدستور 5: المرشد 2</span><span>✅ 100%</span></div>
                                        <div class="mcp-c14-seal-badge"><span>الدستور 6: التزامن CRDT</span><span>✅ 100%</span></div>
                                        <div class="mcp-c14-seal-badge"><span>الدستور 7: طب العين</span><span>✅ 100%</span></div>
                                        <div class="mcp-c14-seal-badge"><span>الدستور 8: الحاسبة والتفقيط</span><span>✅ 100%</span></div>
                                        <div class="mcp-c14-seal-badge"><span>الدستور 9: العمق المخزني</span><span>✅ 100%</span></div>
                                        <div class="mcp-c14-seal-badge"><span>الدستور 10: العمق التجاري</span><span>✅ 100%</span></div>
                                        <div class="mcp-c14-seal-badge"><span>الدستور 11: دورة الشيكات</span><span>✅ 100%</span></div>
                                        <div class="mcp-c14-seal-badge"><span>الدستور 12: منع الاختلاس</span><span>✅ 100%</span></div>
                                        <div class="mcp-c14-seal-badge"><span>الدستور 13: الصندوق الأسود</span><span>✅ 100%</span></div>
                                        <div class="mcp-c14-seal-badge" style="background:#fef3c7;border-color:#d97706;color:#92400e;"><span>الدستور 14: التقارير والجوال</span><span>🏆 100%</span></div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                `;
                document.body.appendChild(modal);

                // ربط أحداث الفلاتر اللحظية (0ms)
                ['mcpC14FilterDateFrom', 'mcpC14FilterDateTo', 'mcpC14FilterAccountInput', 'mcpC14FilterSafeSelect', 'mcpC14FilterUserSelect', 'mcpC14OpeningBalanceInput'].forEach((id) => {
                    const el = document.getElementById(id);
                    if (!el) return;
                    el.addEventListener('input', () => this.renderStatementTable());
                    el.addEventListener('change', () => this.renderStatementTable());
                });

                const closeBtn = document.getElementById('mcpC14CloseModalBtn');
                if (closeBtn) closeBtn.addEventListener('click', () => this.closeReportsModal());

                modal.addEventListener('click', (e) => {
                    if (e.target === modal) this.closeReportsModal();
                });

                const pA4 = document.getElementById('mcpC14PrintA4Btn');
                if (pA4) pA4.addEventListener('click', () => this.executeBalancedPrint('A4'));

                const p80 = document.getElementById('mcpC14Print80mmBtn');
                if (p80) p80.addEventListener('click', () => this.executeBalancedPrint('80MM'));

                const expExcel = document.getElementById('mcpC14ExportExcelBtn');
                if (expExcel) expExcel.addEventListener('click', () => this.exportCleanExcelCsv());

                const expPdf = document.getElementById('mcpC14ExportPdfBtn');
                if (expPdf) expPdf.addEventListener('click', () => this.executeBalancedPrint('A4'));

                const waBtn = document.getElementById('mcpC14SendWhatsAppReportBtn');
                if (waBtn) waBtn.addEventListener('click', () => this.sendIndexedWhatsAppStatement());

                // أزرار محاكاة ثلاثية إيماءات الجوال
                modal.querySelectorAll('.mcp-c14-gesture-test-btn').forEach((gBtn) => {
                    gBtn.addEventListener('click', () => {
                        const g = gBtn.getAttribute('data-c14-gesture');
                        if (g === '1') {
                            this.executeGesture1EdgeSwipeReturn();
                        } else if (g === '2') {
                            this.executeGesture2PullDownDismiss();
                        } else if (g === '3') {
                            const firstBlock = document.querySelector('#accounts-container .account-block');
                            this.executeGesture3RowSwipeActions(firstBlock);
                        }
                    });
                });
            },

            openReportsModal() {
                this.triggerHapticPulse([18]);
                this.buildGlobalReportsAndPrintModal();
                this.renderStatementTable();
                const modal = document.getElementById('mcpC14GlobalReportsAndPrintModal');
                if (modal) modal.classList.add('c14-modal-open');
            },

            closeReportsModal() {
                const modal = document.getElementById('mcpC14GlobalReportsAndPrintModal');
                if (modal) modal.classList.remove('c14-modal-open');
            },

            // 7. التسجيل التلقائي في المرشد الذكي (الخطوة 28 — الختم الختامي 14/14)
            registerWithSmartGuide() {
                const guide = window.MagaiesSmartGuides && window.MagaiesSmartGuides['multi-cash-payment'];
                if (!guide || !Array.isArray(guide.steps)) return;
                if (guide.steps.some((s) => s && s.id === 'mcp_c14_global_reports_print_mobile_step')) return;

                guide.steps.push({
                    id: 'mcp_c14_global_reports_print_mobile_step',
                    selector: '#mcpC14OpenReportsHubBtn',
                    title: '2️⃣8️⃣ التقارير العالمية، التعمق بضغطة زر (Drill-Down)، الطباعة الموزونة (A4 / 80mm)، ثلاثية إيماءات الجوال، والختم الشامل (14/14)',
                    description: 'مركز التقارير العالمية والختم الختامي للدساتير الـ 14 (الدستور 14 — Alt+R): يوفر فلاتر لحظية كالبرق (0ms)، ورصيد أول المدة والرصيد التراكمي المتحرك بدقة 100%، والتعمق بضغطة زر (Drill-Down) لفتح أصل السند كشاشة وليدة بسُمك حواف (+2px)، ومحرك الطباعة الموزون (A4 الرسمي + إيصال الكاشير الحراري 80mm)، والتصدير الفوري إلى Excel وPDF ورسائل الواتساب المفهرسة، وحصر إيماءات الجوال في 3 حركات فقط مع الاهتزاز التفاعلي وحارس رفع الخانة فوق الكيبورد.',
                    goldenRule: 'القاعدة الذهبية: كل رقم في كشف الحساب يفتح أصل السند بضغطة زر (Drill-Down)، والطباعة موزونة هندسياً بين A4 الرسمي و80mm الحراري دون أي قطع.'
                });
            },

            init() {
                this.injectTopBarAndPerBlockButtons();
                this.buildGlobalReportsAndPrintModal();
                this.buildDrillDownChildModal();
                this.initHapticsAndVirtualKeyboardGuard();
                this.initTouchGestureTrinity();
                this.registerWithSmartGuide();

                window.addEventListener('keydown', (e) => {
                    if (e.altKey && (e.key === 'r' || e.key === 'R' || e.key === 'ق')) {
                        e.preventDefault();
                        this.openReportsModal();
                    }
                });

                setTimeout(() => {
                    this.injectTopBarAndPerBlockButtons();
                    this.registerWithSmartGuide();
                }, 900);
            }
        };

        window.McpDesktopConstitution14 = McpDesktopConstitution14;
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => McpDesktopConstitution14.init());
        } else {
            McpDesktopConstitution14.init();
        }
    })();
    </script>

    <!-- ==================================================================================== -->
    <!-- الدستور الخامس عشر (15 من 15): بوابة المراجعة الختامية الشاملة لنسخة اللابتوب        -->
    <!-- قانون "زيرو خطأ / Zero-Error 100%"، التناسب الهندسي (6:8) بـ Ctrl+رولة الماوس،       -->
    <!-- فواصل شاشة المشتريات (ما بعد الدساتير)، وثبات خلفية الكتابة السوداء في السمة الغامقة -->
    <!-- ==================================================================================== -->
    <style id="mcp-constitution-15-master-gate-styles">
        /* 1. تعميم ضبط "شاشة المشتريات (ما بعد الدساتير)" للفواصل الداخلية المستقلة عن لون الكتابة */
        body:not(.light-mode) .account-block,
        body:not(.light-mode) .glass-container,
        body:not(.light-mode) .voucher-header,
        body:not(.light-mode) .custom-dropdown-list {
            border-color: rgba(255, 255, 255, 0.22) !important;
        }
        body:not(.light-mode) .account-block hr,
        body:not(.light-mode) .block-divider {
            border-color: rgba(255, 255, 255, 0.22) !important;
        }
        body.light-mode .account-block,
        body.light-mode .glass-container,
        body.light-mode .voucher-header,
        html[data-theme="light"] .account-block,
        html[data-theme="light"] .glass-container {
            border-color: rgba(0, 0, 0, 0.20) !important;
        }

        /* 2. بقاء منطقة الكتابة سوداء صريحة ثابتة والخط أبيض صريحاً في السمة الغامقة دون انقلاب للأبيض عند الكتابة (:focus / autofill) */
        body:not(.light-mode) .account-block input.form-input:not([type="button"]):not([type="submit"]),
        body:not(.light-mode) .account-block input.form-input:focus,
        body:not(.light-mode) .account-block input.form-input:active,
        body:not(.light-mode) .voucher-header input.form-input:focus,
        body:not(.light-mode) #accounts-container input[type="text"]:focus,
        body:not(.light-mode) #accounts-container input[type="number"]:focus,
        body:not(.light-mode) #accounts-container textarea:focus {
            background-color: #070a12 !important;
            color: #ffffff !important;
            border-width: 2px !important;
            font-weight: 800 !important;
        }
        body:not(.light-mode) input.form-input:-webkit-autofill,
        body:not(.light-mode) input.form-input:-webkit-autofill:hover,
        body:not(.light-mode) input.form-input:-webkit-autofill:focus,
        body:not(.light-mode) input.form-input:-webkit-autofill:active {
            -webkit-box-shadow: 0 0 0 1000px #070a12 inset !important;
            -webkit-text-fill-color: #ffffff !important;
            caret-color: #ffffff !important;
        }

        /* 3. توحيد الإضاءة السفلية (Under-Glow) والتكبير الانسيابي (Hover Scale) لجميع أزرار الدساتير 9 إلى 15 */
        #mcpC9OpenInspectionHubBtn,
        #mcpC10OpenCommercialHubBtn,
        #mcpC11OpenPortfolioHubBtn,
        #mcpC12OpenSecurityHubBtn,
        #mcpC13OpenCyberHubBtn,
        #mcpC13LockScreenNowBtn,
        #mcpC14OpenReportsHubBtn,
        #mcpC15OpenMasterGateBtn,
        .btn-block-c9-inspect,
        .btn-block-c10-commercial,
        .btn-block-c11-cheque,
        .btn-block-c13-audit,
        .btn-block-c14-statement {
            transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.2s ease, border-color 0.2s ease !important;
            position: relative;
        }
        #mcpC9OpenInspectionHubBtn:hover,
        #mcpC10OpenCommercialHubBtn:hover,
