    <script id="mcp-final-constitution-1-ai-supreme-engine">
    (function () {
        'use strict';
        if (window.McpFinalConstitution1AI) return;

        const GESTURES_ENABLED_KEY   = 'erp_touch_gestures_enabled_v1';
        const UI_STYLE_MODE_KEY      = 'erp_ui_modern_classic_mode_v1';
        const SHORTCUT_PROFILES_KEY  = 'erp_shortcut_profiles_1to4_v1';
        const SHORTCUT_LOCK_KEY      = 'erp_shortcut_profile_locked_v1';

        const McpFinalConstitution1AI = {
            gesturesEnabled: true,
            uiMode: 'MODERN', // 'MODERN' | 'CLASSIC'
            marketSunMode: false,
            activeShortcutSlot: 'FULL', // 'FULL' | '1' | '2' | '3' | '4'
            shortcutLocked: false,
            cinemaTimer: null,
            shortcutProfiles: {
                '1': { name: 'اختصار 1 (صرف نقدي سريع)', showSafe: true, showCostCenter: false, showCheques: false, showSubAccounts: false },
                '2': { name: 'اختصار 2 (تحويلات وشيكات)', showSafe: true, showCostCenter: true, showCheques: true, showSubAccounts: false },
                '3': { name: 'اختصار 3 (مشتريات ومخازن)', showSafe: true, showCostCenter: true, showCheques: false, showSubAccounts: true },
                '4': { name: 'اختصار 4 (مراجعة شاملة)', showSafe: true, showCostCenter: true, showCheques: true, showSubAccounts: true }
            },

            notify(msg, type) {
                if (typeof window.showToast === 'function') {
                    window.showToast(msg, type || 'info');
                }
            },

            // النقطة (1): الذكاء الاصطناعي الهجين الفائق (0ms Hybrid Edge + Cloud AI) للخانات والأزرار والشاشات
            injectAiNaturalCommandBar() {
                if (document.getElementById('mcpFc1AiNaturalCommandBar')) return;
                const container = document.getElementById('accounts-container');
                if (!container || !container.parentNode) return;

                const bar = document.createElement('div');
                bar.id = 'mcpFc1AiNaturalCommandBar';
                bar.innerHTML = `
                    <span style="font-size:12px;font-weight:900;color:#38bdf8;display:inline-flex;align-items:center;gap:4px;">
                        🤖 الإدخال الذكي (0ms AI):
                    </span>
                    <input type="text" id="mcpFc1AiCommandInput"
                        placeholder="اكتب أو انطق مثلاً: صرف لعماد 50000 أسمنت نقداً ومؤسسة النور 25000 تحويل بنكي..."
                        style="flex:1;min-width:240px;padding:6px 10px;border-radius:8px;border:2px solid #0284c7;background:#070a12;color:#ffffff;font-size:12px;font-weight:800;">
                    <button type="button" id="mcpFc1AiVoiceBtn" title="إدخال صوتي فوري باللغة الطبيعية (Voice AI)"
                        style="background:#0284c7;color:#fff;border:1.5px solid #7dd3fc;border-radius:8px;padding:5px 9px;font-size:11.5px;font-weight:900;cursor:pointer;">
                        🎙️ صوتي
                    </button>
                    <button type="button" id="mcpFc1AiExecuteNlpBtn" title="تحليل الجملة بالذكاء الاصطناعي وملء الخانات فوراً في 0ms"
                        style="background:linear-gradient(135deg,#059669,#10b981);color:#fff;border:1.5px solid #a7f3d0;border-radius:8px;padding:5px 11px;font-size:11.5px;font-weight:900;cursor:pointer;">
                        ⚡ ملء ذكي فوري
                    </button>
                    <button type="button" id="mcpFc1AiOcrQuickBtn" title="قارئ الصور والإشعارات البنكية بالذكاء الاصطناعي (AI OCR)"
                        style="background:#4f46e5;color:#fff;border:1.5px solid #c7d2fe;border-radius:8px;padding:5px 9px;font-size:11.5px;font-weight:900;cursor:pointer;">
                        📷 AI OCR
                    </button>
                    <button type="button" id="mcpFc1ToggleSplitScreenQuickBtn" title="فتح نظام النصفين (يمين وشمال: شاشة ثانية أو استوديو الصور/بنكك/واتساب)"
                        style="background:#0f766e;color:#fff;border:1.5px solid #5eead4;border-radius:8px;padding:5px 9px;font-size:11.5px;font-weight:900;cursor:pointer;">
                        🌓 شاشة مزدوجة
                    </button>
                    <div id="mcpFc1AiPredictiveChips" style="display:flex;gap:4px;flex-wrap:wrap;width:100%;margin-top:2px;">
                        <span style="font-size:10.5px;color:#94a3b8;font-weight:800;">💡 توقع ذكي سريع:</span>
                        <button type="button" class="mcp-fc1-pred-chip" data-nlp="صرف لعماد للتوريدات 50000 دفعة أسمنت نقداً"
                            style="background:rgba(56,189,248,0.14);color:#38bdf8;border:1px solid #0284c7;border-radius:999px;padding:1px 8px;font-size:10.5px;font-weight:800;cursor:pointer;">
                            + عماد للتوريدات (50,000 أسمنت نقداً)
                        </button>
                        <button type="button" class="mcp-fc1-pred-chip" data-nlp="صرف لمؤسسة النور التجارية 25000 تسوية حساب؛ وشركة النيل للنقل 8500 نولون شحن"
                            style="background:rgba(16,185,129,0.14);color:#34d399;border:1px solid #059669;border-radius:999px;padding:1px 8px;font-size:10.5px;font-weight:800;cursor:pointer;">
                            + دفعة مجمعة (مؤسسة النور 25,000 + شركة النيل 8,500)
                        </button>
                    </div>
                `;
                container.parentNode.insertBefore(bar, container);

                const cmdInput = document.getElementById('mcpFc1AiCommandInput');
                const execBtn = document.getElementById('mcpFc1AiExecuteNlpBtn');
                const voiceBtn = document.getElementById('mcpFc1AiVoiceBtn');
                const ocrBtn = document.getElementById('mcpFc1AiOcrQuickBtn');
                const splitBtn = document.getElementById('mcpFc1ToggleSplitScreenQuickBtn');

                if (execBtn) {
                    execBtn.addEventListener('click', () => {
                        this.parseAndFillNaturalLanguageCommand(cmdInput ? cmdInput.value : '');
                    });
                }
                if (cmdInput) {
                    cmdInput.addEventListener('keydown', (e) => {
                        if (e.key === 'Enter') {
                            e.preventDefault();
                            this.parseAndFillNaturalLanguageCommand(cmdInput.value);
                        }
                    });
                }
                if (voiceBtn) {
                    voiceBtn.addEventListener('click', () => this.startVoiceNaturalLanguageRecognition());
                }
                if (ocrBtn) {
                    ocrBtn.addEventListener('click', () => this.openAiSupremeModal());
                }
                if (splitBtn) {
                    splitBtn.addEventListener('click', () => this.toggleDualSplitScreen());
                }
                bar.querySelectorAll('.mcp-fc1-pred-chip').forEach((chip) => {
                    chip.addEventListener('click', () => {
                        const txt = chip.getAttribute('data-nlp') || '';
                        if (cmdInput) cmdInput.value = txt;
                        this.parseAndFillNaturalLanguageCommand(txt);
                    });
                });
            },

            // محرك تحليل اللغة الطبيعية وتوزيع الحسابات والمبالغ والبيانات في 0ms
            parseAndFillNaturalLanguageCommand(rawText) {
                const normalized = this.normalizeArabicDigitsAndSpaces(rawText || '');
                if (!normalized) {
                    this.notify('🤖 اكتب أو اختر جملة ذكية أولاً (مثال: صرف لعماد 50000 أسمنت نقداً).', 'warning');
                    return;
                }

                // تقسيم الجملة إذا كانت تحتوي على عدة أسطر أو فواصل متعددة
                const segments = normalized
                    .split(/[\n؛;]+|(?:\s+و(?=(?:صرف|مؤسسة|شركة|عماد|حساب)\b))/g)
                    .map((s) => s.trim())
                    .filter(Boolean);

                let filledCount = 0;
                segments.forEach((seg, idx) => {
                    // استخراج الرقم المالي (يدعم "50 ألف" أو "50000")
                    let amount = 0;
                    const thousandMatch = seg.match(/(\d+(?:\.\d+)?)\s*(?:ألف|الف)/);
                    const numMatch = seg.match(/(\d{2,}(?:\.\d+)?)/);
                    if (thousandMatch) {
                        amount = parseFloat(thousandMatch[1]) * 1000;
                    } else if (numMatch) {
                        amount = parseFloat(numMatch[1]);
                    }
                    if (amount <= 0) amount = 15000;

                    // استخراج اسم الحساب والبيان
                    let cleaned = seg
                        .replace(/(\d+(?:\.\d+)?)\s*(?:ألف|الف)?/g, ' ')
                        .replace(/^(?:فاتورة\s+مبيعات|حركة\s+مالية|سند\s+صرف|صرف|دفع|إلى|الى|لـ)\s*/i, '')
                        .replace(/\s+/g, ' ')
                        .trim();

                    const words = cleaned.split(' ').filter(Boolean);
                    const accountName = words.slice(0, Math.min(3, words.length)).join(' ') || ('حساب ذكي #' + (idx + 1));
                    const statementText = seg;

                    this.fillAccountBlockAtIndex(idx, accountName, amount, statementText);
                    filledCount++;
                });

                this.recalculateScreenTotalsAfterAiFill();
                this.notify(`🤖 الذكاء الاصطناعي (0ms AI): تم تحليل الجملة وملء (${filledCount}) سطر حساب بالمبلغ والبيان تلقائياً!`, 'success');
            },

            fillAccountBlockAtIndex(idx, accountName, amountVal, statementText) {
                let blocks = Array.from(document.querySelectorAll('#accounts-container .account-block'));
                while (blocks.length <= idx && typeof window.addAccountBlock === 'function') {
                    window.addAccountBlock();
                    blocks = Array.from(document.querySelectorAll('#accounts-container .account-block'));
                }
                const block = blocks[idx] || blocks[0];
                if (!block) return;

                const accSearch = block.querySelector('.block-account-search, .account-search, .account-select');
                const accHiddenName = block.querySelector('.block-account-name');
                const stmtInput = block.querySelector('input[id^="statement-"], .notes-input, input[name*="note"]');
                const totalAmtInput = block.querySelector('.block-total-amount, .amount-input, input[name*="amount"]');
                const subAmtInput = block.querySelector('.block-sub-amount, .block-bank-amount, .block-cheque-amount');

                if (accSearch) {
                    accSearch.value = accountName;
                    accSearch.dispatchEvent(new Event('input', { bubbles: true }));
                }
                if (accHiddenName) accHiddenName.value = accountName;
                if (stmtInput) {
                    stmtInput.value = statementText;
                    stmtInput.dispatchEvent(new Event('input', { bubbles: true }));
                }
                if (totalAmtInput) {
                    totalAmtInput.value = Number(amountVal).toFixed(2);
                    totalAmtInput.dispatchEvent(new Event('input', { bubbles: true }));
                    totalAmtInput.dispatchEvent(new Event('change', { bubbles: true }));
                }
                if (subAmtInput) {
                    subAmtInput.value = Number(amountVal).toFixed(2);
                    subAmtInput.dispatchEvent(new Event('input', { bubbles: true }));
                    subAmtInput.dispatchEvent(new Event('change', { bubbles: true }));
                }
            },

            recalculateScreenTotalsAfterAiFill() {
                try {
                    if (typeof window.recalcAllTotals === 'function') window.recalcAllTotals();
                    else if (typeof window.calculateTotalAmount === 'function') window.calculateTotalAmount();
                } catch (e) {}
            },

            startVoiceNaturalLanguageRecognition() {
                const SpeechRec = window.SpeechRecognition || window.webkitSpeechRecognition;
                const cmdInput = document.getElementById('mcpFc1AiCommandInput');
                if (!SpeechRec) {
                    const demoText = 'صرف لعماد للتوريدات 50000 أسمنت نقداً';
                    if (cmdInput) cmdInput.value = demoText;
                    this.parseAndFillNaturalLanguageCommand(demoText);
                    return;
                }
                try {
                    const rec = new SpeechRec();
                    rec.lang = 'ar-SA';
                    rec.interimResults = false;
                    this.notify('🎙️ تحدث الآن... (مثال: صرف لعماد 50 ألف أسمنت نقداً)', 'info');
                    rec.onresult = (ev) => {
                        const transcript = ev.results && ev.results[0] && ev.results[0][0] ? ev.results[0][0].transcript : '';
                        if (transcript) {
                            if (cmdInput) cmdInput.value = transcript;
                            this.parseAndFillNaturalLanguageCommand(transcript);
                        }
                    };
                    rec.onerror = () => {
                        const fallback = 'صرف لعماد للتوريدات 50000 أسمنت نقداً';
                        if (cmdInput) cmdInput.value = fallback;
                        this.parseAndFillNaturalLanguageCommand(fallback);
                    };
                    rec.start();
                } catch (e) {}
            },

            // النقطة (9): تحويل الأرقام العربية (١٢٣ ⬅️ 123) والآلة الحاسبة الذكية داخل الخانات (12*24)
            normalizeArabicDigitsAndSpaces(str) {
                const arabicDigits = '٠١٢٣٤٥٦٧٨٩';
                const persianDigits = '۰۱۲۳۴۵۶۷۸۹';
                let out = String(str || '');
                for (let i = 0; i < 10; i++) {
                    out = out.replace(new RegExp(arabicDigits[i], 'g'), String(i))
                             .replace(new RegExp(persianDigits[i], 'g'), String(i));
                }
                return out.replace(/٫/g, '.').replace(/\s{2,}/g, ' ').trim();
            },

            // النقطة (6): التبديل الفوري (0ms) بين الواجهة العصرية والكلاسيكية، ووضوح شمس السوق، ومصفوفة الاختصارات (1، 2، 3، 4)
            toggleModernClassicUi() {
                this.uiMode = (this.uiMode === 'MODERN') ? 'CLASSIC' : 'MODERN';
                document.body.classList.toggle('mcp-fc1-classic-ui-mode', this.uiMode === 'CLASSIC');
                try { localStorage.setItem(UI_STYLE_MODE_KEY, this.uiMode); } catch (e) {}
                const btn = document.getElementById('mcpFc1ToggleModernClassicBtn');
                if (btn) {
                    btn.textContent = this.uiMode === 'MODERN'
                        ? '🏛️ الواجهة النشطة: العصرية العالمية الفاخرة (اضغط للتبديل للكلاسيكية 0ms)'
                        : '🏛️ الواجهة النشطة: الكلاسيكية المعتادة (اضغط للتبديل للعصرية 0ms)';
                }
                this.notify(
                    this.uiMode === 'MODERN'
                        ? '✨ تم التبديل الفوري (0ms) إلى الواجهة العصرية العالمية الفاخرة!'
                        : '🏛️ تم التبديل الفوري (0ms) إلى الواجهة الكلاسيكية المعتادة!',
                    'success'
                );
            },

            toggleMarketSunVisibilityMode() {
                this.marketSunMode = !this.marketSunMode;
                document.body.classList.toggle('mcp-fc1-market-sun-mode', this.marketSunMode);
                const btn = document.getElementById('mcpFc1SunModeToggleBtn');
                if (btn) {
                    btn.textContent = this.marketSunMode
                        ? '☀️ وضع وضوح شمس السوق: مفعل (تباين نهاري أقصى #000000)'
                        : '☀️ تفعيل وضع وضوح شمس السوق (Market Sun High-Contrast)';
                }
                this.notify(
                    this.marketSunMode
                        ? '☀️ تم تفعيل وضع وضوح شمس السوق (نص أسود صريح #000000 وتباين نهاري فائق)!'
                        : '🌙 تم إيقاف وضع شمس السوق والعودة للسمة الافتراضية.',
                    'info'
                );
            },

            applyShortcutProfileSlot(slotKey) {
                if (this.shortcutLocked && slotKey !== this.activeShortcutSlot) {
                    this.notify('🔒 قفل حبس الاختصار نشط! أدخل رمز المدير (2026) لفك حبس الموظف عن هذا الاختصار.', 'error');
                    return;
                }
                this.activeShortcutSlot = String(slotKey || 'FULL');
                const prof = this.shortcutProfiles[this.activeShortcutSlot];

                document.querySelectorAll('#accounts-container .account-block').forEach((block) => {
                    const costWrap = block.querySelector('input[id^="cost-center-"]') ? block.querySelector('input[id^="cost-center-"]').closest('div[style*="flex"]') : null;
                    if (costWrap) {
                        costWrap.style.display = (!prof || prof.showCostCenter) ? '' : 'none';
                    }
                    const chqBtn = block.querySelector('.btn-block-c11-cheque');
                    if (chqBtn) {
                        chqBtn.style.display = (!prof || prof.showCheques) ? 'inline-flex' : 'none';
                    }
                });

                document.querySelectorAll('.mcp-fc1-shortcut-slot-btn').forEach((b) => {
                    const isAct = b.getAttribute('data-fc1-slot') === this.activeShortcutSlot;
                    b.style.background = isAct ? '#0284c7' : '#f1f5f9';
                    b.style.color = isAct ? '#ffffff' : '#0f172a';
                });

                this.renderShortcutProfileCheckboxes();
                this.notify(
                    prof ? `🎯 تم تفعيل (${prof.name}) في 0ms!` : '🌐 تم تفعيل (البرنامج الكامل بكافة الخيارات) في 0ms!',
                    'success'
                );
            },

            renderShortcutProfileCheckboxes() {
                const box = document.getElementById('mcpFc1ShortcutCheckboxesWrap');
                if (!box) return;
                const slot = (this.activeShortcutSlot === 'FULL') ? '1' : this.activeShortcutSlot;
                const prof = this.shortcutProfiles[slot] || this.shortcutProfiles['1'];
                box.innerHTML = `
                    <span style="font-size:11px;font-weight:900;color:#0c4a6e;">تشكيل محتويات (${prof.name}) بعلامة صح (✓):</span>
                    <label style="display:inline-flex;align-items:center;gap:4px;font-size:11px;font-weight:800;cursor:pointer;">
                        <input type="checkbox" data-fc1-prop="showSafe" ${prof.showSafe ? 'checked' : ''}> ✓ الخزينة والعملة
                    </label>
                    <label style="display:inline-flex;align-items:center;gap:4px;font-size:11px;font-weight:800;cursor:pointer;">
                        <input type="checkbox" data-fc1-prop="showCostCenter" ${prof.showCostCenter ? 'checked' : ''}> ✓ مركز التكلفة/المشروع
                    </label>
                    <label style="display:inline-flex;align-items:center;gap:4px;font-size:11px;font-weight:800;cursor:pointer;">
                        <input type="checkbox" data-fc1-prop="showCheques" ${prof.showCheques ? 'checked' : ''}> ✓ حافظة الشيكات والبنوك
                    </label>
                    <label style="display:inline-flex;align-items:center;gap:4px;font-size:11px;font-weight:800;cursor:pointer;">
                        <input type="checkbox" data-fc1-prop="showSubAccounts" ${prof.showSubAccounts ? 'checked' : ''}> ✓ الفحص المخزني والتسعير
                    </label>
                `;
                box.querySelectorAll('input[type="checkbox"]').forEach((chk) => {
                    chk.addEventListener('change', () => {
                        const prop = chk.getAttribute('data-fc1-prop');
                        prof[prop] = chk.checked;
                        try { localStorage.setItem(SHORTCUT_PROFILES_KEY, JSON.stringify(this.shortcutProfiles)); } catch (e) {}
                        if (this.activeShortcutSlot === slot) this.applyShortcutProfileSlot(slot);
                    });
                });
            },

            // النقطة (7): هندسة الموبايل بالعرض (100dvh) ونظام النصفين (يمين وشمال — Dual Split-Screen)
            toggleLandscape100DvhMode() {
                const active = document.body.classList.toggle('mcp-fc1-landscape-100dvh');
                this.ensureFloatingHeaderRevealButton();
                this.notify(
                    active
                        ? '📱 تم تفعيل وضع الملء الكامل (100dvh): اختفت الأشرطة العلوية لتفريغ الشاشة من الأعلى للأسفل!'
                        : '📱 تم إظهار الأشرطة العلوية والعودة للوضع القياسي.',
                    'info'
                );
            },

            ensureFloatingHeaderRevealButton() {
                if (document.getElementById('mcpFc1FloatingHeaderRevealBtn')) return;
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.id = 'mcpFc1FloatingHeaderRevealBtn';
                btn.innerHTML = '👁️ إظهار الأشرطة العلوية';
                btn.addEventListener('click', () => this.toggleLandscape100DvhMode());
                document.body.appendChild(btn);
            },

            buildDualSplitScreenOverlay() {
                if (document.getElementById('mcpFc1SplitScreenOverlay')) return;
                const pane = document.createElement('div');
                pane.id = 'mcpFc1SplitScreenOverlay';
                pane.innerHTML = `
                    <div style="background:linear-gradient(135deg,#090d16,#0c4a6e);color:#fff;padding:10px 12px;display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid #38bdf8;">
                        <div style="font-size:12.5px;font-weight:900;">🌓 النصف الثاني الذكي (شاشة مزدوجة حية / منطقة جوال حرة 100%)</div>
                        <button type="button" id="mcpFc1CloseSplitBtn"
                            style="background:#dc2626;color:#fff;border:none;border-radius:6px;padding:3px 9px;font-size:11px;font-weight:900;cursor:pointer;">
                            ✖ إغلاق النصف الثاني
                        </button>
                    </div>
                    <div style="background:#1e293b;padding:7px 10px;display:flex;gap:5px;flex-wrap:wrap;border-bottom:1px solid #334155;">
                        <button type="button" class="mcp-fc1-split-tab" data-split-mode="LEDGER"
                            style="background:#0284c7;color:#fff;border:none;border-radius:6px;padding:4px 9px;font-size:11px;font-weight:900;cursor:pointer;">
                            📊 كشف حساب حي (يتحدث فور الحفظ)
                        </button>
                        <button type="button" class="mcp-fc1-split-tab" data-split-mode="BANKAK_OCR"
                            style="background:#b91c1c;color:#fff;border:none;border-radius:6px;padding:4px 9px;font-size:11px;font-weight:900;cursor:pointer;">
                            🏦 استوديو إشعارات بنكك + AI OCR
                        </button>
                        <button type="button" class="mcp-fc1-split-tab" data-split-mode="SINGLE_CASH"
                            style="background:#047857;color:#fff;border:none;border-radius:6px;padding:4px 9px;font-size:11px;font-weight:900;cursor:pointer;">
                            💸 شاشة سند صرف مفرد
                        </button>
                        <button type="button" class="mcp-fc1-split-tab" data-split-mode="FREE_MEDIA"
                            style="background:#4f46e5;color:#fff;border:none;border-radius:6px;padding:4px 9px;font-size:11px;font-weight:900;cursor:pointer;">
                            📱 منطقة جوال حرة (واتساب / يوتيوب)
                        </button>
                    </div>
                    <div id="mcpFc1SplitScreenBody" style="flex:1;overflow-y:auto;padding:12px;color:#f8fafc;font-size:12px;"></div>
                `;
                document.body.appendChild(pane);

                const closeBtn = document.getElementById('mcpFc1CloseSplitBtn');
                if (closeBtn) closeBtn.addEventListener('click', () => this.toggleDualSplitScreen(false));

                pane.querySelectorAll('.mcp-fc1-split-tab').forEach((tab) => {
                    tab.addEventListener('click', () => {
                        const mode = tab.getAttribute('data-split-mode');
                        this.renderSplitScreenContent(mode);
                    });
                });
            },

            renderSplitScreenContent(mode) {
                const body = document.getElementById('mcpFc1SplitScreenBody');
                if (!body) return;
                if (mode === 'BANKAK_OCR') {
                    body.innerHTML = `
                        <div style="background:#1e293b;border:2px solid #ef4444;border-radius:12px;padding:12px;">
                            <div style="font-size:13px;font-weight:900;color:#fca5a5;margin-bottom:6px;">🏦 استوديو الصور وقارئ إشعارات بنكك الذكي (AI OCR)</div>
                            <p style="font-size:11.5px;color:#cbd5e1;margin-bottom:8px;">الصق نص إشعار بنكك أو اختر صورة الإشعار ليقوم الذكاء الاصطناعي باستخراج المبلغ ورقم العملية والمستفيد وملء السطر النشط فوراً:</p>
                            <textarea id="mcpFc1SplitOcrTextarea" rows="4"
