            toggleDualSplitScreen(forceState) {
                this.buildDualSplitScreenOverlay();
                const pane = document.getElementById('mcpFc1SplitScreenOverlay');
                if (!pane) return;
                const next = typeof forceState === 'boolean' ? forceState : !pane.classList.contains('fc1-split-open');
                pane.classList.toggle('fc1-split-open', next);
                document.body.classList.toggle('mcp-fc1-split-active', next);
                if (next) {
                    this.renderSplitScreenContent('LEDGER');
                    this.notify('🌓 تم فتح نظام النصفين (الشاشة المزدوجة: الحركة المجمعة يميناً + الكشف الحي واستوديو AI OCR يساراً)!', 'success');
                }
            },

            // النقطة (8): مفتاح التحكم في إيماءات الأصابع (تفعيل/إيقاف للشاشات المرتجة) وإخفاء الأرصدة بالإصبعين (****)
            initFingerGesturesAndPrivacyMask() {
                try {
                    const saved = localStorage.getItem(GESTURES_ENABLED_KEY);
                    if (saved === '0') this.gesturesEnabled = false;
                } catch (e) {}

                document.addEventListener('touchstart', (e) => {
                    if (!this.gesturesEnabled || !e.touches) return;
                    if (e.touches.length === 2) {
                        // إصبعين: إخفاء/إظهار الأرصدة السرية (****)
                        this.togglePrivacyMaskBalances();
                    } else if (e.touches.length === 3) {
                        // 3 أصابع: تعليق مؤقت / استرجاع المسودة
                        const parkBtn = document.getElementById('mcpC8ParkBtn') || document.querySelector('[data-action="park-voucher"]');
                        if (parkBtn) parkBtn.click();
                    }
                }, { passive: true });
            },

            togglePrivacyMaskBalances() {
                const masked = document.body.classList.toggle('mcp-fc1-privacy-masked');
                this.notify(
                    masked
                        ? '🙈 تم إخفاء الأرصدة السرية (****) بحركة الإصبعين لحماية الخصوصية!'
                        : '👁️ تم إظهار الأرصدة المالية.',
                    'info'
                );
            },

            // النقطة (10): المحاورة الذكية مع "المرشد الذكي" بالذكاء الاصطناعي التوليدي + استوديو التصوير (4K Auto-Cinema)
            answerSmartGuideQuestionWithAi(questionText) {
                const q = String(questionText || '').trim();
                const ansBox = document.getElementById('mcpFc1SmartGuideAiAnswerBox');
                if (!q) {
                    if (ansBox) ansBox.textContent = '🎙️ اكتب سؤالك عن الشاشة أو الخانات أو التقارير ليجيبك المرشد الذكي فوراً بالصوت والنص.';
                    return;
                }

                let response = '';
                if (q.includes('توزيع') || q.includes('نسخ') || q.includes('لصق')) {
                    response = '💡 لتوزيع نص منسوخ على عدة سطور: الصق النص في شريط الإدخال الذكي (0ms AI) أعلى الحسابات أو داخل نافذة AI واضغط (ملء ذكي فوري)، فيقوم النظام بإنشاء السطور وملء الحساب والمبلغ والبيان تلقائياً. القاعدة الذهبية: افصل بين كل عملية وأخرى بسطر جديد أو فاصلة منقوطة.';
                } else if (q.includes('تسمع') || q.includes('تؤثر') || q.includes('تقرير')) {
                    response = '📊 هذه الشاشة (الحركة المالية المجمعة) تستمد أرصدتها من دليل الحسابات والخزائن والبنوك، وفور الضغط على حفظ (F10) تُسمّع ذرياً في: 1) كشف حساب الخزينة/البنك، 2) كشوفات حسابات العملاء والموردين والمصروفات، 3) ميزان المراجعة والأستاذ العام، 4) حافظة الشيكات والصندوق الأسود.';
                } else if (q.includes('مزدوج') || q.includes('نصفين') || q.includes('بنكك')) {
                    response = '🌓 لفتح الشاشة المزدوجة (نصفين يمين وشمال): اضغط زر (🌓 شاشة مزدوجة) في شريط الإدخال الذكي، فتعمل على الحركة المجمعة يميناً وتفتح كشف الحساب الحي أو استوديو إشعارات بنكك (AI OCR) يساراً في نفس اللحظة.';
                } else {
                    response = `🎙️ إجابة المرشد الذكي عن (${q}): هذه الشاشة مجهزة بـ 15 دستوراً + الذكاء الاصطناعي الشامل (0ms AI)؛ يمكنك الإدخال صوتاً أو كتابةً باللغة الطبيعية، أو الضغط على أي سطر في التقارير للتعمق (Drill-Down)، أو الضغط على (Ctrl+رولة الماوس) لضبط التناسب الهندسي (6:8). القاعدة الذهبية: تأكد دائماً من مطابقة إجمالي السند مع التفقيط اللحظي قبل الضغط على F10.`;
                }

                if (ansBox) ansBox.textContent = response;
                if (window.McpDesktopConstitution4 && typeof window.McpDesktopConstitution4.speakText === 'function') {
                    window.McpDesktopConstitution4.speakText(response);
                }
                this.notify('🎙️ المرشد الذكي (AI): تم توليد الإجابة ونطقها بالصوت الرجالي الفخيم!', 'success');
            },

            start4KAutoCinemaTour() {
                this.closeAiSupremeModal();
                this.notify('🎬 تم بدء وضع التصوير السينمائي التلقائي (4K Auto-Cinema Tour) لعرض إمكانيات الشاشة والمرشد الذكي!', 'success');
                if (window.McpDesktopConstitution4 && typeof window.McpDesktopConstitution4.startGuide === 'function') {
                    window.McpDesktopConstitution4.startGuide();
