                const btn = document.createElement('button');
                btn.type = 'button';
                btn.id = 'mcpFc1OpenAiHubBtn';
                btn.title = 'الدستور الختامي الأول (1 من 2): الذكاء الاصطناعي الشامل (0ms AI)، الإدخال الصوتي/النصي، AI OCR، الواجهة المزدوجة، الشاشة المزدوجة (نصفين)، والمرشد الذكي التوليدي (Alt+A)';
                btn.innerHTML = `🤖 الذكاء الاصطناعي الشامل (1/2)`;
                btn.addEventListener('click', () => this.openAiSupremeModal());

                if (c15Btn && c15Btn.parentNode) {
                    c15Btn.parentNode.insertBefore(btn, c15Btn.nextSibling);
                } else if (anchor) {
                    anchor.appendChild(btn);
                }
            },

