                        </div>
                    </div>
                `;
                document.body.appendChild(modal);

                const closeBtn = document.getElementById('mcpFc1CloseModalBtn');
                if (closeBtn) closeBtn.addEventListener('click', () => this.closeAiSupremeModal());
                modal.addEventListener('click', (e) => {
                    if (e.target === modal) this.closeAiSupremeModal();
                });

                const distBtn = document.getElementById('mcpFc1AiSmartPasteDistributeBtn');
                if (distBtn) {
                    distBtn.addEventListener('click', () => {
                        const txt = (document.getElementById('mcpFc1ModalBatchPasteInput') || {}).value || '';
                        this.parseAndFillNaturalLanguageCommand(txt || 'عماد للتوريدات 50000 أسمنت نقداً ؛ مؤسسة النور التجارية 25000 تسوية حساب');
                    });
                }

                const ocrModalBtn = document.getElementById('mcpFc1AiOcrBtn');
                if (ocrModalBtn) {
                    ocrModalBtn.addEventListener('click', () => {
                        this.closeAiSupremeModal();
                        this.toggleDualSplitScreen(true);
                        this.renderSplitScreenContent('BANKAK_OCR');
                    });
                }

                const copilotBtn = document.getElementById('mcpFc1AiCopilotSuggestBtn');
                if (copilotBtn) {
                    copilotBtn.addEventListener('click', () => {
                        document.querySelectorAll('#accounts-container input[type="text"]').forEach((inp) => {
                            if (inp.value) inp.value = this.normalizeArabicDigitsAndSpaces(inp.value);
                        });
                        this.recalculateScreenTotalsAfterAiFill();
                        this.notify('🛠️ AI Copilot: تم تطهير الأرقام العربية والمسافات الزائدة ومراجعة توازن الأسطر في 0ms! الخطوة التالية المقترحة: اضغط F10 للحفظ أو Alt+R لمعاينة كشف الحساب.', 'success');
                    });
                }

                const uiBtn = document.getElementById('mcpFc1ToggleModernClassicBtn');
                if (uiBtn) uiBtn.addEventListener('click', () => this.toggleModernClassicUi());

                const sunBtn = document.getElementById('mcpFc1SunModeToggleBtn');
                if (sunBtn) sunBtn.addEventListener('click', () => this.toggleMarketSunVisibilityMode());

                modal.querySelectorAll('.mcp-fc1-shortcut-slot-btn').forEach((sBtn) => {
                    sBtn.addEventListener('click', () => {
                        this.applyShortcutProfileSlot(sBtn.getAttribute('data-fc1-slot'));
                    });
                });

                const lockProfBtn = document.getElementById('mcpFc1LockShortcutProfileBtn');
                if (lockProfBtn) {
                    lockProfBtn.addEventListener('click', () => {
                        this.shortcutLocked = !this.shortcutLocked;
                        try { localStorage.setItem(SHORTCUT_LOCK_KEY, this.shortcutLocked ? '1' : '0'); } catch (e) {}
                        lockProfBtn.textContent = this.shortcutLocked
                            ? '🔓 فك حبس الاختصار (مقفل حالياً للموظف)'
                            : '🔒 قفل حبس الاختصار للموظف';
                        this.notify(
                            this.shortcutLocked
                                ? '🔒 تم قفل وحبس الموظف داخل الاختصار النشط لمنع تغيير الخانات!'
                                : '🔓 تم فك قفل الاختصار.',
                            'info'
                        );
                    });
                }

                const splitModalBtn = document.getElementById('mcpFc1ToggleSplitScreenBtn');
                if (splitModalBtn) {
                    splitModalBtn.addEventListener('click', () => {
                        this.closeAiSupremeModal();
                        this.toggleDualSplitScreen(true);
                    });
                }

                const landBtn = document.getElementById('mcpFc1LandscapeFullDvhBtn');
                if (landBtn) {
                    landBtn.addEventListener('click', () => {
                        this.closeAiSupremeModal();
                        this.toggleLandscape100DvhMode();
                    });
                }

                const gestBtn = document.getElementById('mcpFc1GestureMasterToggleBtn');
                if (gestBtn) {
                    gestBtn.addEventListener('click', () => {
                        this.gesturesEnabled = !this.gesturesEnabled;
                        try { localStorage.setItem(GESTURES_ENABLED_KEY, this.gesturesEnabled ? '1' : '0'); } catch (e) {}
                        gestBtn.textContent = this.gesturesEnabled
                            ? '✋ إيماءات الأصابع: مفعلة (اضغط للإيقاف للشاشات المرتجة)'
                            : '🚫 إيماءات الأصابع: متوقفة لحماية الشاشة المرتجة (اضغط للتفعيل)';
                        this.notify(
                            this.gesturesEnabled ? '✋ تم تفعيل إيماءات الأصابع.' : '🚫 تم إيقاف إيماءات الأصابع لحماية الشاشة المرتجة.',
                            'info'
                        );
                    });
                }

                const maskBtn = document.getElementById('mcpFc1MaskBalancesNowBtn');
                if (maskBtn) maskBtn.addEventListener('click', () => this.togglePrivacyMaskBalances());

                const askBtn = document.getElementById('mcpFc1AskSmartGuideBtn');
                const askInp = document.getElementById('mcpFc1AskSmartGuideInput');
                if (askBtn) {
                    askBtn.addEventListener('click', () => this.answerSmartGuideQuestionWithAi(askInp ? askInp.value : ''));
                }
                if (askInp) {
                    askInp.addEventListener('keydown', (e) => {
                        if (e.key === 'Enter') {
                            e.preventDefault();
                            this.answerSmartGuideQuestionWithAi(askInp.value);
                        }
                    });
                }

                const cinemaBtn = document.getElementById('mcpFc1Start4KCinemaBtn');
                if (cinemaBtn) cinemaBtn.addEventListener('click', () => this.start4KAutoCinemaTour());

                this.renderShortcutProfileCheckboxes();
            },

            openAiSupremeModal() {
                this.buildAiSupremeModal();
                this.renderShortcutProfileCheckboxes();
                const modal = document.getElementById('mcpFc1AiSupremeHubModal');
                if (modal) modal.classList.add('fc1-modal-open');
            },

            closeAiSupremeModal() {
                const modal = document.getElementById('mcpFc1AiSupremeHubModal');
                if (modal) modal.classList.remove('fc1-modal-open');
            },

            // التسجيل التلقائي في المرشد الذكي (الخطوة 30 — الدستور الختامي الأول 1 من 2)
            registerWithSmartGuide() {
                const guide = window.MagaiesSmartGuides && window.MagaiesSmartGuides['multi-cash-payment'];
                if (!guide || !Array.isArray(guide.steps)) return;
                if (guide.steps.some((s) => s && s.id === 'mcp_fc1_ai_supreme_step')) return;

                guide.steps.push({
                    id: 'mcp_fc1_ai_supreme_step',
                    selector: '#mcpFc1OpenAiHubBtn',
                    title: '3️⃣0️⃣ الدستور الختامي الأول (1 من 2): الذكاء الاصطناعي الشامل (0ms AI)، الشاشة المزدوجة، والواجهة المزدوجة',
                    description: 'غرفة الذكاء الاصطناعي الشامل (Alt+A): تتيح الإدخال باللغة الطبيعية صوتاً أو كتابةً، وقراءة إشعارات بنكك والفواتير بـ AI OCR، وتوزيع النصوص المنسوخة على عدة سطور في 0ms، والتبديل الفوري بين الواجهة العصرية والكلاسيكية ووضع شمس السوق، وتشكيل أزرار الاختصارات (1، 2، 3، 4) بعلامة صح (✓)، وفتح نظام النصفين (شاشة مزدوجة يمين وشمال)، ومحاورة المرشد الذكي بالذكاء الاصطناعي التوليدي + استوديو 4K.',
                    goldenRule: 'القاعدة الذهبية: استثمر شريط الإدخال الذكي (0ms AI) والشاشة المزدوجة لإنجاز الحركات المجمعة ومطابقتها مع إشعارات بنكك وكشف الحساب في ثانية واحدة.'
                });
            },

            init() {
                this.injectTopBarAiSupremeButton();
                this.injectAiNaturalCommandBar();
                this.buildAiSupremeModal();
                this.initFingerGesturesAndPrivacyMask();
                this.registerWithSmartGuide();

                window.addEventListener('keydown', (e) => {
                    if (e.altKey && (e.key === 'a' || e.key === 'A' || e.key === 'ش')) {
                        e.preventDefault();
                        this.openAiSupremeModal();
                    }
                });

                // تحديث النصف الثاني من الشاشة المزدوجة حياً مع كل إدخال في النصف الأيمن
                document.addEventListener('input', () => {
                    const pane = document.getElementById('mcpFc1SplitScreenOverlay');
                    if (pane && pane.classList.contains('fc1-split-open')) {
                        this.renderSplitScreenContent('LEDGER');
                    }
                }, { passive: true });

                setTimeout(() => {
                    this.injectTopBarAiSupremeButton();
                    this.injectAiNaturalCommandBar();
                    this.registerWithSmartGuide();
                }, 900);
            }
        };

        window.McpFinalConstitution1AI = McpFinalConstitution1AI;
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => McpFinalConstitution1AI.init());
        } else {
            McpFinalConstitution1AI.init();
        }
    })();
    </script>

