            getBankakFawryRegistry() {
                try {
                    const raw = localStorage.getItem(BANKAK_FAWRY_REGISTRY_KEY);
                    const parsed = raw ? JSON.parse(raw) : [];
                    if (Array.isArray(parsed) && parsed.length > 0) return parsed;
                } catch (e) {}
                const seed = [
                    { trxId: 'BNK-2026-884120', amount: 18500, sender: 'مؤسسة التوريدات', voucherNo: 'MCP-2026-091', date: '2026-11-01' }
                ];
